                if (fo && fo->type == JSON_BOOL) free_only = fo->bool_val;
                json_t *mv = json_obj_get(aux, "openrouter_model");
                if (mv && mv->type == JSON_STRING && mv->str_val && mv->str_val[0])
                    model = mv->str_val;
            }
