        runtime, true, ghe_profile(), ghe_install_id(config_json),
        ghe_version(), ghe_supervision_mode());
    if (runtime) json_free(runtime);
    if (!snap) return NULL;

    /* Serialize snapshot to JSON. */
    json_t *out = json_object();
