    ns->keys = (char **)calloc(n ? n : 1, sizeof(char *));
    ns->vals = (void **)calloc(n ? n : 1, sizeof(void *));
    if (!ns->keys || !ns->vals) {
        free(ns->keys); free(ns->vals); free(ns);
        return NULL;
    }
    ns->count = n;
    for (size_t i = 0; i < n; i++) {
        ns->keys[i] = rl_strdup(value->c.keys[i]);
        ns->vals[i] = json_copy(value->c.items[i]);
    }
    return ns;

if (!error_kind) return false;
    return strcmp(error_kind, "CancelledError") == 0 ||
           strcmp(error_kind, "InterruptedError") == 0 ||
           strcmp(error_kind, "KeyboardInterrupt") == 0;

/* The C analogue of a thread with a running asyncio loop is a thread
     * inside an async session callback (the runtime's worker thread). */
    return relay_runtime_in_async_worker();

/* C has no awaitables: the runtime's run_in_session_async already runs
     * the operation on a worker thread and joins, which IS the awaited
     * result. */
    return value;

/* Python: codecs = getattr(relay, "codecs", None); None -> None. The C
     * analogue of a missing codec registry is an absent backend. */
    if (!relay_runtime_backend_available()) return NULL;
    const char *api_mode = metadata ? json_get_str(metadata, "api_mode", "") : "";
    for (int i = 0; i < CODE_MODES_N; i++)
        if (strcmp(api_mode, CODE_MODES[i]) == 0)
            return rl_strdup(CODE_CODECS[i]);
    return NULL;

json_t *body = json_copy(content);
    if (!body || body->type != JSON_OBJECT) return body;
    const char *api_mode = metadata ? json_get_str(metadata, "api_mode", "") : "";
    if (strcmp(api_mode, "codex_responses") != 0) return body;

    json_t *tools = json_obj_get(body, "tools");
    if (!tools || tools->type != JSON_ARRAY) return body;

    json_t *out = json_array();
    if (!out) return body;
    size_t n = tools->c.count;
    for (size_t i = 0; i < n; i++) {
        json_t *tool = tools->c.items[i];
        if (tool && tool->type == JSON_OBJECT &&
            json_get_str(tool, "type", "") && strcmp(json_get_str(tool, "type", ""), "function") == 0) {
            json_t *fn = json_obj_get(tool, "function");
            if (fn && fn->type == JSON_OBJECT) {
                /* {"type": "function", **dict(tool["function"])} */
                json_t *flat = json_object();
                json_set(flat, "type", json_string("function"));
                for (size_t k = 0; k < fn->c.count; k++)
                    json_set(flat, fn->c.keys[k], json_copy(fn->c.items[k]));
                json_append(out, flat);
                continue;
            }
        }
        json_append(out, json_copy(tool));
    }
    json_set(body, "tools", out);
    return body;

json_t *body = json_copy(request);
    if (!body || body->type != JSON_OBJECT) {
        if (body) json_free(body);
        return json_object();
    }
    const char *api_mode = metadata ? json_get_str(metadata, "api_mode", "") : "";
    if (strcmp(api_mode, "codex_responses") == 0) {
        json_t *tools = json_obj_get(body, "tools");
        if (tools && tools->type == JSON_NULL) {
            /* tools=None -> pop (the Responses codec expects absent, not null). */
            json_obj_del(body, "tools");
        } else if (tools && tools->type == JSON_ARRAY) {
            json_t *out = json_array();
            size_t n = tools->c.count;
            for (size_t i = 0; i < n; i++) {
                json_t *tool = tools->c.items[i];
                if (tool && tool->type == JSON_OBJECT &&
                    strcmp(json_get_str(tool, "type", ""), "function") == 0 &&
                    !json_obj_get(tool, "function")) {
                    /* {"type":"function","function":{k:v for k != "type"}} */
                    json_t *fn = json_object();
                    for (size_t k = 0; k < tool->c.count; k++) {
                        if (strcmp(tool->c.keys[k], "type") == 0) continue;
                        json_set(fn, tool->c.keys[k], json_copy(tool->c.items[k]));
                    }
                    json_t *wrapped = json_object();
                    json_set(wrapped, "type", json_string("function"));
                    json_set(wrapped, "function", fn);
                    json_append(out, wrapped);
                } else {
                    json_append(out, json_copy(tool));
                }
            }
            json_set(body, "tools", out);
        }
    } else if (strcmp(api_mode, "chat_completions") == 0) {
        json_t *tools = json_obj_get(body, "tools");
        if (tools && tools->type == JSON_ARRAY) {
            json_t *out = json_array();
            size_t n = tools->c.count;
            for (size_t i = 0; i < n; i++) {
                json_t *tool = tools->c.items[i];
                if (tool && tool->type == JSON_OBJECT &&
                    json_obj_get(tool, "function") &&
                    !json_obj_get(tool, "type")) {
                    /* {"type": "function", **tool} */
                    json_t *flat = json_object();
                    json_set(flat, "type", json_string("function"));
                    for (size_t k = 0; k < tool->c.count; k++)
                        json_set(flat, tool->c.keys[k], json_copy(tool->c.items[k]));
                    json_append(out, flat);
                } else {
                    json_append(out, json_copy(tool));
                }
            }
            json_set(body, "tools", out);
        }
    }
    return body;

if (!original || !final || !baseline || !intercepted) return final;
    json_t *om = json_obj_get(original, "messages");
    json_t *fm = json_obj_get(final, "messages");
    json_t *bm = json_obj_get(baseline, "messages");
    json_t *im = json_obj_get(intercepted, "messages");
    if (!om || !fm || !bm || !im) return final;
    if (om->type != JSON_ARRAY || fm->type != JSON_ARRAY ||
        bm->type != JSON_ARRAY || im->type != JSON_ARRAY)
        return final;
    size_t n = om->c.count;
    if (fm->c.count != n || bm->c.count != n || im->c.count != n)
        return final;
    for (size_t i = 0; i < n; i++) {
        json_t *o = om->c.items[i];
        json_t *f = fm->c.items[i];
        json_t *b = bm->c.items[i];
        json_t *ic = im->c.items[i];
        if (!o || !f || !b || !ic) continue;
        if (o->type != JSON_OBJECT || f->type != JSON_OBJECT ||
            b->type != JSON_OBJECT || ic->type != JSON_OBJECT)
            continue;
        for (int k = 0; k < RELAY_PROVIDER_EXTENSION_KEYS_N; k++) {
            const char *key = RELAY_PROVIDER_EXTENSION_KEYS[k];
            if (json_obj_get(o, key) &&
                !json_obj_get(b, key) &&
                !json_obj_get(ic, key) &&
                !json_obj_get(f, key)) {
                json_set(f, key, json_copy(json_obj_get(o, key)));
            }
        }
    }
    return final;

/* content = getattr(request, "content", request); C requests are json
     * objects: when the object carries a "content" member (the relay LLM
     * request shape), that member is the content; otherwise the request IS
     * its content. A non-dict content falls back to the relay body, mirroring
     * the isinstance check. */
    const json_t *content = NULL;
    if (next_request && next_request->type == JSON_OBJECT) {
        json_t *c = json_obj_get(next_request, "content");
        content = (c && c->type == JSON_OBJECT) ? c : next_request;
    } else {
        content = relay_request_body;
    }
    if (!content || content->type != JSON_OBJECT)
        content = relay_request_body;

    json_t *final = json_copy(original);
    if (!final) return NULL;

    if (!codec_baseline_body ||
        relay_llm_json_equal(content, relay_request_body)) {
        /* Plain copy path. */
    } else {
        const json_t *baseline = codec_baseline_body;
        json_t *intercepted = relay_llm_provider_request_body(content, metadata);
        if (intercepted) {
            /* Union of baseline and intercepted keys; overlay only changed
             * values (typed codecs may not represent provider fields). */
            for (size_t i = 0; i < baseline->c.count; i++) {
                const char *key = baseline->c.keys[i];
                if (!json_obj_get(intercepted, key))
                    json_obj_del(final, key);
            }
            for (size_t i = 0; i < intercepted->c.count; i++) {
                const char *key = intercepted->c.keys[i];
                json_t *bv = json_obj_get(baseline, key);
                json_t *iv = intercepted->c.items[i];
                if (!bv || !relay_llm_json_equal(iv, bv))
                    json_set(final, key, json_copy(iv));
            }
            relay_llm_restore_provider_message_extensions(original, final,
                                                          baseline, intercepted);
            json_free(intercepted);
        }
    }

    /* headers = getattr(request, "headers", None); C requests may carry a
     * "headers" member; internal relay headers are dropped, the rest merge
     * into extra_headers. */
    json_t *headers = NULL;
    if (next_request && next_request->type == JSON_OBJECT)
        headers = json_obj_get(next_request, "headers");
    if (headers && headers->type == JSON_OBJECT) {
        json_t *filtered = json_object();
        for (size_t i = 0; i < headers->c.count; i++) {
            const char *key = headers->c.keys[i];
            char lower[256];
            size_t n = strlen(key);
            if (n >= sizeof lower) n = sizeof lower - 1;
            for (size_t j = 0; j < n; j++)
                lower[j] = (char)tolower((unsigned char)key[j]);
            lower[n] = '\0';
            bool internal = false;
            for (int j = 0; j < RELAY_INTERNAL_PROVIDER_HEADERS_N; j++)
                if (strcmp(lower, RELAY_INTERNAL_PROVIDER_HEADERS[j]) == 0) { internal = true; break; }
            if (internal) continue;
            json_set(filtered, key, json_copy(headers->c.items[i]));
        }
        if (filtered->c.count > 0) {
            json_t *extra = json_obj_get(final, "extra_headers");
            json_t *merged = json_object();
            if (extra && extra->type == JSON_OBJECT)
                for (size_t i = 0; i < extra->c.count; i++)
                    json_set(merged, extra->c.keys[i], json_copy(extra->c.items[i]));
            for (size_t i = 0; i < filtered->c.count; i++)
                json_set(merged, filtered->c.keys[i], json_copy(filtered->c.items[i]));
            json_set(final, "extra_headers", merged);
        }
        json_free(filtered);
    }
    return final;

(void)backend_codec;
    (void)relay_request;
    /* Python: codec is None -> the body itself is the baseline. When a codec
     * exists, the decode/encode round trip yields the codec-only shape — or
     * NULL when the round trip fails. The C port has no codec library, so a
     * real codec name means the baseline cannot be computed: return NULL
     * (Python's codec-failure path), which makes _provider_request treat the
     * request as unchanged. */
    char *codec = relay_llm_codec(metadata);
    if (!codec) {
        json_t *baseline = relay_llm_provider_request_body(relay_request_body, metadata);
        return baseline;
    }
    free(codec);
    hermes_log(LOG_WARNING, "relay_llm",
               "NeMo Relay request codec baseline unavailable in the C port; ignoring request rewrites");
    return NULL;

if (!runtime || !session || !out_turn || !out_handle || !out_request_id)
        return false;
    *out_turn = NULL; *out_handle = NULL; *out_request_id = NULL;

    relay_turn_t *turn = relay_active_turn(relay_session_id(session));
    const char *request_id = metadata ? json_get_str(metadata, "api_request_id", "") : "";
    if (!turn || !request_id[0]) return false;

    /* turn.lease.host is not runtime -> None */
    relay_lease_t *lease = relay_turn_lease(turn);
    relay_host_t *host = lease ? relay_lease_host(lease) : NULL;
    if (!host || relay_host_runtime(host) != runtime) return false;

    if (relay_turn_closed(turn)) return false;

    relay_handle_t handle = relay_turn_get_logical_call(turn, request_id);
    if (!handle) {
        /* scope.push(LOGICAL_LLM_SCOPE, Function, handle=parent, input={},
         * metadata={schema, instance, hermes.call_role}) inside the session. */
        relay_backend_t be;
        if (!relay_runtime_backend_snapshot(&be) || !be.scope_push) return false;
        const char *call_role = metadata ? json_get_str(metadata, "call_role", "primary") : "primary";
        char meta[1024];
        snprintf(meta, sizeof meta,
                 "{\"%s\":\"%s\",\"%s\":\"%s\",\"hermes.call_role\":\"%s\"}",
                 RELAY_RUNTIME_SCHEMA_KEY, RELAY_RUNTIME_SCHEMA_VERSION,
                 RELAY_RUNTIME_INSTANCE_KEY, relay_runtime_id(runtime),
                 call_role ? call_role : "primary");
        rl_push_arg_t arg = { be, RELAY_LOGICAL_LLM_SCOPE, RELAY_SCOPE_FUNCTION,
                              parent, "{}", meta, NULL };
        void *res = NULL;
        if (!relay_runtime_run_in_session(runtime, session, rl_push_cb, &arg,
                                          false, &res))
            return false;
        handle = arg.handle;
        if (!handle) return false;
        relay_turn_add_logical_call(turn, request_id, handle);
    }
    *out_turn = turn;
    *out_handle = handle;
    *out_request_id = rl_strdup(request_id);
    return true;

if (!turn || !handle || !request_id) return;
    relay_lease_t *lease = relay_turn_lease(turn);
    relay_host_t *host = lease ? relay_lease_host(lease) : NULL;
    relay_runtime_t *rt = host ? relay_host_runtime(host) : NULL;
    /* Python: not isinstance(lease.host, RelayRuntime) -> return */
    if (!rt) return;
    /* Python: with logical_llm_lock: if logical_llm_calls.get(id) is not
     * handle -> return */
    if (relay_turn_get_logical_call(turn, request_id) != handle) return;

    relay_session_t *session = lease ? relay_lease_session(lease) : NULL;
    if (!session) return;

    char output[512];
    snprintf(output, sizeof output, "{\"outcome\":\"%s\"}",
             outcome && outcome[0] ? outcome : "success");
    char meta[1024];
    snprintf(meta, sizeof meta,
             "{\"%s\":\"%s\",\"%s\":\"%s\"}",
             RELAY_RUNTIME_SCHEMA_KEY, RELAY_RUNTIME_SCHEMA_VERSION,
             RELAY_RUNTIME_INSTANCE_KEY, relay_runtime_id(rt));

    relay_backend_t be;
    if (!relay_runtime_backend_snapshot(&be) || !be.scope_pop) return;
    rl_pop_arg_t arg = { be, handle, output, meta, false };
    void *res = NULL;
    if (!relay_runtime_run_in_session(rt, session, rl_pop_cb, &arg, false, &res) ||
        !arg.ok) {
        /* Python logs a warning and retains the handle for turn finalization;
         * the provider result is authoritative. */
        hermes_log(LOG_WARNING, "relay_llm",
                   "Hermes Relay logical LLM finalization failed; retaining handle");
        return;
    }
    if (relay_turn_get_logical_call(turn, request_id) == handle)
        relay_turn_remove_logical_call(turn, request_id);

(void)relay_error_message;
    (void)callback_error_message;
    if (!raw_response || !*raw_response) return false;
    if (!relay_error_kind) return false;          /* relay_error is None */
    if (callback_error_kind) return false;        /* callback_error is not None */
    if (!json_obj_get(*raw_response, "value")) return false;

    hermes_log(LOG_WARNING, "relay_llm",
               "NeMo Relay LLM post-processing failed after provider success; returning the provider response");
    if (!defer_logical_completion)
        relay_llm_complete_logical(logical_turn, logical_handle,
                                   logical_request_id, "success");
    return true;

if (!api_request_id || !api_request_id[0]) return;
    relay_turn_t *turn = relay_current_turn();
    if (!turn) return;
    relay_handle_t handle = relay_turn_get_logical_call(turn, api_request_id);
    if (handle)
        relay_llm_complete_logical(turn, handle, api_request_id, outcome);

return rl_execute_impl(request_json, callback, cb_user, session_id,
                           name, model_name, metadata_json,
                           defer_logical_completion);

/* run_in_session_async already runs the callback on a worker thread and
     * joins — the faithful equivalent of awaiting it. */
    return rl_execute_impl(request_json, callback, cb_user, session_id,
                           name, model_name, metadata_json,
                           defer_logical_completion);

relay_turn_t *turn = relay_active_turn(NULL);
    if (!turn) {
        if (callback) return callback(cb_user);
        return NULL;
    }
    relay_lease_t *lease = relay_turn_lease(turn);
    const char *session_id = lease ? relay_lease_session_id(lease) : NULL;
    return rl_execute_impl(request_json, callback, cb_user, session_id,
                           name, model_name, metadata_json,
                           defer_logical_completion);

return relay_llm_execute_current(request_json, callback, cb_user,
                                     name, model_name, metadata_json,
                                     defer_logical_completion);

rl_stream_wrap_t *w = (rl_stream_wrap_t *)p;
    rl_stream_exec_arg_t *a = w->arg;
    if (a->be.llm_stream_execute) {
        w->ok = a->be.llm_stream_execute(a->be.ctx, a->name,
                                         a->relay_request_json,
                                         a->provider_stream_cb, a->provider_stream_user,
                                         a->observe_chunk_cb, a->observe_chunk_user,
                                         a->finalizer_cb, a->finalizer_user,
                                         a->parent, a->metadata_json,
                                         a->model_name, a->codec, a->response_codec,
                                         &w->handle);
    }
    return NULL;

relay_turn_t *turn = relay_active_turn(NULL);
    if (!turn || relay_llm_has_running_event_loop()) {
        /* Python: no turn or a running event loop -> raw factory result. */
        relay_llm_managed_stream_t *s = relay_llm_managed_stream_new(
            request_json, stream_factory, sf_user, NULL, name, model_name,
            finalizer, fin_user, NULL, NULL, NULL, NULL, NULL, NULL,
            completed_response_predicate, metadata_json, defer_logical_completion);
        if (!s) return NULL;
        void *raw = s->stream_factory ? s->stream_factory(s->sf_user) : NULL;
        json_t *rawj = (json_t *)raw;
        if (rawj && completed_response_predicate && completed_response_predicate(rawj)) {
            s->final_response = json_copy(rawj);
            json_free(rawj);
        } else if (rawj) {
            s->raw_stream_resource = json_copy(rawj);
            json_free(rawj);
        }
        return s;
    }
    relay_lease_t *lease = relay_turn_lease(turn);
    const char *session_id = lease ? relay_lease_session_id(lease) : NULL;
    return relay_llm_stream(request_json, stream_factory, sf_user,
                            session_id, name, model_name,
                            finalizer, fin_user,
                            NULL, NULL, NULL, NULL, NULL, NULL,
                            completed_response_predicate,
                            metadata_json, defer_logical_completion);

pthread_mutex_lock(&g_backend_lock);
    if (backend) {
        g_backend     = *backend;
        g_backend_set = true;
    } else {
        memset(&g_backend, 0, sizeof(g_backend));
        g_backend_set = false;
    }
    pthread_mutex_unlock(&g_backend_lock);

relay_runtime_t *rt = (relay_runtime_t *)calloc(1, sizeof(*rt));
    if (!rt) return NULL;

    rt->profile_key = rr_strdup(profile_key && *profile_key
                                ? profile_key : relay_current_profile_key());
    /* uuid.uuid4().hex — 32 hex chars, no hyphens. */
    char *u = uuid_v4();
    if (u) {
        char hex[33];
        size_t n = 0;
        for (const char *p = u; *p && n < 32; p++)
            if (*p != '-') hex[n++] = *p;
        hex[n] = '\0';
        rt->runtime_id = rr_strdup(hex);
        free(u);
    } else {
        rt->runtime_id = rr_strdup("");
    }

    rr_rlock_init(&rt->sessions_lock);
    rr_rlock_init(&rt->consumers_lock);
    rt->sessions                = omap_new(rr_session_free);
    rt->subagent_parents        = omap_new(free);
    rt->subagent_parent_handles = omap_new(NULL);   /* handles are borrowed */
    rt->execution_consumers     = omap_new(NULL);   /* a set: NULL values */

    if (!rt->profile_key || !rt->runtime_id || !rt->sessions ||
        !rt->subagent_parents || !rt->subagent_parent_handles ||
        !rt->execution_consumers) {
        relay_runtime_free(rt);
        return NULL;
    }
    return rt;

if (!rt) return false;
    /* Python raises ValueError on an empty consumer; C reports it as false. */
    if (!consumer || !*consumer) return false;
    pthread_mutex_lock(&rt->consumers_lock);
    bool ok = omap_set(rt->execution_consumers, consumer, NULL);
    pthread_mutex_unlock(&rt->consumers_lock);
    return ok;

if (!rt || !consumer) return;
    pthread_mutex_lock(&rt->consumers_lock);
    omap_pop(rt->execution_consumers, consumer);   /* set.discard: no KeyError */
    pthread_mutex_unlock(&rt->consumers_lock);

if (!rt) return false;
    pthread_mutex_lock(&rt->consumers_lock);
    bool on = omap_size(rt->execution_consumers) > 0;
    pthread_mutex_unlock(&rt->consumers_lock);
    return on;

if (!rt) return NULL;
    session_id = relay_session_id_of_event(session_id);
    if (!*session_id) return NULL;   /* Python: falsy session id -> None */

    pthread_mutex_lock(&rt->sessions_lock);
    relay_session_t *session = (relay_session_t *)omap_get(rt->sessions, session_id);
    if (!session) {
        const char *parent = (const char *)omap_get(rt->subagent_parents, session_id);
        session = rr_session_new(session_id, parent ? parent : "");
        if (!session) { pthread_mutex_unlock(&rt->sessions_lock); return NULL; }
        if (!omap_set(rt->sessions, session_id, session)) {
            rr_session_free(session);
            pthread_mutex_unlock(&rt->sessions_lock);
            return NULL;
        }
    }
    pthread_mutex_unlock(&rt->sessions_lock);

    pthread_mutex_lock(&session->lock);
    if (session->closing) {
        pthread_mutex_unlock(&session->lock);
        return NULL;
    }
    if (session->handle == NULL) {
        relay_handle_t parent_handle = NULL;
        bool subagent = session->parent_session_id[0] != '\0';
        if (subagent) {
            pthread_mutex_lock(&rt->sessions_lock);
            parent_handle = omap_get(rt->subagent_parent_handles, session_id);
            pthread_mutex_unlock(&rt->sessions_lock);
            if (parent_handle == NULL) {
                /* Recursive ensure_session for the parent — this is why the
                 * session registry lock must be recursive. */
                relay_session_t *parent =
                    relay_runtime_ensure_session(rt, session->parent_session_id, NULL, NULL);
                if (parent) parent_handle = parent->handle;
            }
        }
        char *scope_metadata = rr_scope_metadata(metadata_json, rt->runtime_id, subagent);
        relay_backend_t be;
        if (rr_backend(&be) && be.scope_push) {
            relay_handle_t h = be.scope_push(be.ctx, RELAY_SESSION_SCOPE,
                                             RELAY_SCOPE_AGENT, parent_handle,
                                             data_json, scope_metadata);
            if (h == NULL) {
                /* Python: the push raised -> context cleared and re-raised.
                 * C surfaces the failure as a NULL session. */
                session->context_ready = false;
                free(scope_metadata);
                pthread_mutex_unlock(&session->lock);
                return NULL;
            }
            session->handle        = h;
            session->context_ready = true;
        } else {
            /* No binding: nothing to push. The session object still exists so
             * bookkeeping (parents, close) stays consistent, but it carries no
             * handle — every guarded operation degrades exactly as in Python. */
            session->context_ready = false;
        }
        free(scope_metadata);
    }
    pthread_mutex_unlock(&session->lock);
    return session;

if (!rt) return NULL;
    session_id = relay_session_id_of_event(session_id);
    if (!*session_id) return NULL;   /* Python: falsy session id -> None */

    pthread_mutex_lock(&rt->sessions_lock);
    relay_session_t *session = (relay_session_t *)omap_get(rt->sessions, session_id);
    if (!session) {
        const char *parent = (const char *)omap_get(rt->subagent_parents, session_id);
        session = rr_session_new(session_id, parent ? parent : "");
        if (!session) { pthread_mutex_unlock(&rt->sessions_lock); return NULL; }
        if (!omap_set(rt->sessions, session_id, session)) {
            rr_session_free(session);
            pthread_mutex_unlock(&rt->sessions_lock);
            return NULL;
        }
    }
    pthread_mutex_unlock(&rt->sessions_lock);

    pthread_mutex_lock(&session->lock);
    if (session->closing) {
        pthread_mutex_unlock(&session->lock);
        return NULL;
    }
    if (session->handle == NULL) {
        relay_handle_t parent_handle = NULL;
        bool subagent = session->parent_session_id[0] != '\0';
        if (subagent) {
            pthread_mutex_lock(&rt->sessions_lock);
            parent_handle = omap_get(rt->subagent_parent_handles, session_id);
            pthread_mutex_unlock(&rt->sessions_lock);
            if (parent_handle == NULL) {
                /* Recursive ensure_session for the parent — this is why the
                 * session registry lock must be recursive. */
                relay_session_t *parent =
                    relay_runtime_ensure_session(rt, session->parent_session_id, NULL, NULL);
                if (parent) parent_handle = parent->handle;
            }
        }
        char *scope_metadata = rr_scope_metadata(metadata_json, rt->runtime_id, subagent);
        relay_backend_t be;
        if (rr_backend(&be) && be.scope_push) {
            relay_handle_t h = be.scope_push(be.ctx, RELAY_SESSION_SCOPE,
                                             RELAY_SCOPE_AGENT, parent_handle,
                                             data_json, scope_metadata);
            if (h == NULL) {
                /* Python: the push raised -> context cleared and re-raised.
                 * C surfaces the failure as a NULL session. */
                session->context_ready = false;
                free(scope_metadata);
                pthread_mutex_unlock(&session->lock);
                return NULL;
            }
            session->handle        = h;
            session->context_ready = true;
        } else {
            /* No binding: nothing to push. The session object still exists so
             * bookkeeping (parents, close) stays consistent, but it carries no
             * handle — every guarded operation degrades exactly as in Python. */
            session->context_ready = false;
        }
        free(scope_metadata);
    }
    pthread_mutex_unlock(&session->lock);
    return session;

if (!rt) return NULL;
    parent_session_id = rr_or_empty(parent_session_id);
    child_session_id  = rr_or_empty(child_session_id);
    if (!*parent_session_id || !*child_session_id ||
        strcmp(parent_session_id, child_session_id) == 0)
        return NULL;

    relay_session_t *parent = relay_runtime_ensure_session(rt, parent_session_id, NULL, NULL);
    relay_handle_t parent_handle = parent ? parent->handle : NULL;

    /* Python: register_subagent calls `parent = self.ensure_session(parent)`
     * and the scope push there raises OUT of register_subagent BEFORE the
     * child session is ever created. When the parent session has no handle
     * (the push failed), mirror that by returning NULL and not creating the
     * child — matching the raised-then-None contract. */
    if (parent == NULL || parent->handle == NULL)
        return NULL;

    /* Prefer the spawning TURN's handle when it belongs to this host and the
     * same parent session, so the child nests under the turn (not the session). */
    relay_turn_t *turn = relay_active_turn(parent_session_id);
    if (turn && !relay_turn_closed(turn) && relay_turn_handle(turn) != NULL) {
        relay_lease_t *lease = relay_turn_lease(turn);
        relay_session_t *lease_session = relay_lease_session(lease);
        if (relay_host_runtime(relay_lease_host(lease)) == rt &&
            lease_session != NULL &&
            strcmp(relay_session_id(lease_session), parent_session_id) == 0)
            parent_handle = relay_turn_handle(turn);
    }

    pthread_mutex_lock(&rt->sessions_lock);
    char *pdup = rr_strdup(parent_session_id);
    if (pdup && !omap_set(rt->subagent_parents, child_session_id, pdup)) free(pdup);
    if (parent_handle != NULL)
        omap_set(rt->subagent_parent_handles, child_session_id, parent_handle);
    pthread_mutex_unlock(&rt->sessions_lock);

    return relay_runtime_ensure_session(rt, child_session_id, NULL, metadata_json);

if (!rt) return;
    child_session_id = rr_or_empty(child_session_id);
    if (!*child_session_id) return;

    relay_runtime_close_session(rt, child_session_id);
    pthread_mutex_lock(&rt->sessions_lock);
    omap_erase(rt->subagent_parents, child_session_id);
    omap_pop(rt->subagent_parent_handles, child_session_id);
    pthread_mutex_unlock(&rt->sessions_lock);

if (!rt) return NULL;
    pthread_mutex_lock(&rt->sessions_lock);
    relay_session_t *s = (relay_session_t *)omap_get(rt->sessions, rr_or_empty(session_id));
    pthread_mutex_unlock(&rt->sessions_lock);
    if (!s) return NULL;
    pthread_mutex_lock(&s->lock);
    bool closing = s->closing;
    pthread_mutex_unlock(&s->lock);
    return closing ? NULL : s;

if (out_result) *out_result = NULL;
    if (!rt || !session || !callback) return false;

    pthread_mutex_lock(&session->lock);
    if (session->closing && !allow_closing) {
        /* Python: RuntimeError("Hermes Relay session is closing") */
        pthread_mutex_unlock(&session->lock);
        return false;
    }
    if (!session->context_ready || session->handle == NULL) {
        /* Python: RuntimeError("Hermes Relay session context is unavailable") */
        pthread_mutex_unlock(&session->lock);
        return false;
    }
    pthread_mutex_unlock(&session->lock);

    void *result = callback(user);
    if (out_result) *out_result = result;
    return true;

if (out_result) *out_result = NULL;
    if (!rt || !session || !callback) return false;

    pthread_mutex_lock(&session->lock);
    if (session->closing && !allow_closing) {
        pthread_mutex_unlock(&session->lock);
        return false;
    }
    if (!session->context_ready || session->handle == NULL) {
        pthread_mutex_unlock(&session->lock);
        return false;
    }
    pthread_mutex_unlock(&session->lock);

    rr_async_arg_t arg = { callback, user, NULL };
    pthread_t th;
    if (pthread_create(&th, NULL, rr_async_trampoline, &arg) != 0) {
        /* Thread exhaustion: run inline rather than dropping the operation. */
        arg.result = callback(user);
    } else {
        pthread_join(th, NULL);
    }
    if (out_result) *out_result = arg.result;
    return true;

if (!rt) return false;
    relay_session_t *session = relay_runtime_ensure_session(rt, session_id, NULL, NULL);
    if (!session) return false;

    relay_backend_t be;
    if (!rr_backend(&be)) return false;

    rr_event_arg_t arg = { be, name, session->handle, data_json, metadata_json, false };
    if (!relay_runtime_run_in_session(rt, session, rr_event_cb, &arg, false, NULL))
        return false;
    /* Python returns True once the scope event was dispatched. */
    return true;

if (!args_json) return NULL;
    /* Every early return in Python yields the ORIGINAL args unchanged. */
    if (!rt) return rr_strdup(args_json);
    if (!relay_runtime_managed_execution_enabled(rt)) return rr_strdup(args_json);

    relay_backend_t be;
    if (!rr_backend(&be) || !be.tools_request_intercepts)
        return rr_strdup(args_json);   /* Python: not callable -> args */

    relay_session_t *session = relay_runtime_ensure_session(rt, session_id, NULL, NULL);
    if (!session) return rr_strdup(args_json);

    rr_intercept_arg_t arg = { be, tool_name, args_json, NULL };
    if (!relay_runtime_run_in_session(rt, session, rr_intercept_cb, &arg, false, NULL))
        return rr_strdup(args_json);

    /* Python keeps the result only when it is a dict, else falls back. */
    if (arg.rewritten) return arg.rewritten;
    return rr_strdup(args_json);

if (!rt) return;
    session_id = relay_session_id_of_event(session_id);

    pthread_mutex_lock(&rt->sessions_lock);
    relay_session_t *session = (relay_session_t *)omap_get(rt->sessions, session_id);
    pthread_mutex_unlock(&rt->sessions_lock);

    if (!session) {
        /* Python still drops any parent bookkeeping for an unknown session. */
        pthread_mutex_lock(&rt->sessions_lock);
        omap_erase(rt->subagent_parents, session_id);
        omap_pop(rt->subagent_parent_handles, session_id);
        pthread_mutex_unlock(&rt->sessions_lock);
        return;
    }

    char failures[512];
    failures[0] = '\0';

    pthread_mutex_lock(&session->lock);
    if (session->closing) {
        pthread_mutex_unlock(&session->lock);
        return;
    }
    session->closing = true;
    if (session->handle != NULL) {
        relay_backend_t be;
        if (rr_backend(&be)) {
            char *meta = rr_close_metadata(rt->runtime_id);
            rr_pop_arg_t arg = { be, session->handle, "{}", meta, false };
            bool ran = relay_runtime_run_in_session(rt, session, rr_pop_cb, &arg,
                                                    true /* allow_closing */, NULL);
            if (!ran || !arg.ok)
                snprintf(failures, sizeof failures, "session scope close failed");
            free(meta);
        }
    }
    pthread_mutex_unlock(&session->lock);

    relay_backend_t be;
    if (rr_backend(&be) && be.subscribers_flush) {
        if (!be.subscribers_flush(be.ctx)) {
            size_t used = strlen(failures);
            snprintf(failures + used, sizeof failures - used, "%ssubscriber flush failed",
                     used ? "; " : "");
        }
    }

    pthread_mutex_lock(&rt->sessions_lock);
    /* Only drop the entry when it is still the same object (Python's identity
     * check guards against a concurrent replacement). */
    if ((relay_session_t *)omap_get(rt->sessions, session_id) == session)
        omap_erase(rt->sessions, session_id);   /* frees the session */
    omap_erase(rt->subagent_parents, session_id);
    omap_pop(rt->subagent_parent_handles, session_id);
    pthread_mutex_unlock(&rt->sessions_lock);

    if (failures[0])
        hermes_log(LOG_WARNING, "relay_runtime",
                   "Hermes Relay session %s closed with errors: %s", session_id, failures);

if (!rt) return;
    /* Snapshot the ids: close_session mutates the map (Python: list(...)). */
    pthread_mutex_lock(&rt->sessions_lock);
    size_t count = 0;
    const char **keys = omap_keys(rt->sessions, &count);
    char **ids = count ? (char **)calloc(count, sizeof(char *)) : NULL;
    for (size_t i = 0; i < count && ids; i++) ids[i] = rr_strdup(keys[i]);
    free((void *)keys);
    pthread_mutex_unlock(&rt->sessions_lock);

    for (size_t i = 0; i < count && ids; i++) {
        if (!ids[i]) continue;
        relay_runtime_close_session(rt, ids[i]);   /* _safe: never propagates */
        free(ids[i]);
    }
    free(ids);

relay_host_registry_t *reg = (relay_host_registry_t *)calloc(1, sizeof(*reg));
    if (!reg) return NULL;
    rr_rlock_init(&reg->lock);
    reg->hosts = omap_new(rr_host_free);
    if (!reg->hosts) { pthread_mutex_destroy(&reg->lock); free(reg); return NULL; }
    return reg;

if (!reg) return NULL;
    const char *key = (profile_key && *profile_key) ? profile_key
                                                    : relay_current_profile_key();
    pthread_mutex_lock(&reg->lock);
    relay_host_t *host = (relay_host_t *)omap_get(reg->hosts, key);
    if (!host && create) {
        if (relay_runtime_backend_available()) {
            relay_runtime_t *rt = relay_runtime_new(key);
            host = rt ? rr_host_new_runtime(rt, key) : NULL;
            if (!host) relay_runtime_free(rt);
        }
        if (!host) {
            /* Python falls back to NoopRelayRuntime with the import failure
             * text; the C binding is injected, so the reason is its absence. */
            host = rr_host_new_noop(key, "nemo_relay backend is not installed");
        }
        if (host && !omap_set(reg->hosts, key, host)) { rr_host_free(host); host = NULL; }
    }
    pthread_mutex_unlock(&reg->lock);
    return host;

if (!reg) return;
    const char *key = (profile_key && *profile_key) ? profile_key
                                                    : relay_current_profile_key();
    pthread_mutex_lock(&reg->lock);
    relay_host_t *host = (relay_host_t *)omap_pop(reg->hosts, key);
    pthread_mutex_unlock(&reg->lock);
    if (!host) return;
    relay_host_shutdown(host);   /* Python swallows shutdown errors here */
    rr_host_free(host);

if (!reg) return;
    pthread_mutex_lock(&reg->lock);
    size_t count = 0;
    const char **keys = omap_keys(reg->hosts, &count);
    relay_host_t **hosts = count ? (relay_host_t **)calloc(count, sizeof(*hosts)) : NULL;
    for (size_t i = 0; i < count && hosts; i++)
        hosts[i] = (relay_host_t *)omap_get(reg->hosts, keys[i]);
    free((void *)keys);
    /* Python clears the registry, then shuts the detached hosts down. */
    if (hosts) {
        for (size_t i = 0; i < count; i++) {
            /* Detach without freeing: omap_pop hands ownership back. */
            if (hosts[i]) omap_pop(reg->hosts, hosts[i]->profile_key);
        }
    }
    pthread_mutex_unlock(&reg->lock);

    for (size_t i = 0; i < count && hosts; i++) {
        if (!hosts[i]) continue;
        relay_host_shutdown(hosts[i]);
        rr_host_free(hosts[i]);
    }
    free(hosts);

relay_coordinator_t *co = (relay_coordinator_t *)calloc(1, sizeof(*co));
    if (!co) return NULL;
    rr_rlock_init(&co->lock);
    co->registry     = registry ? registry : relay_host_registry_global();
    co->active_turns  = omap_new(rr_turnset_free);
    co->conversations = omap_new(NULL);   /* key-only set */
    co->initializers  = omap_new(free);
    if (!co->active_turns || !co->conversations || !co->initializers) {
        relay_coordinator_free(co);
        return NULL;
    }
    return co;

if (!co || !name || !*name || !cb) return false;
    rr_initializer_t *init = (rr_initializer_t *)calloc(1, sizeof(*init));
    if (!init) return false;
    init->cb = cb; init->user = user;
    pthread_mutex_lock(&co->lock);
    bool ok = omap_set(co->initializers, name, init);
    pthread_mutex_unlock(&co->lock);
    if (!ok) free(init);
    return ok;

if (!co || !name) return;
    pthread_mutex_lock(&co->lock);
    omap_erase(co->initializers, name);   /* dict.pop(name, None) */
    pthread_mutex_unlock(&co->lock);

if (!co) return NULL;
    const char *pkey = (profile_key && *profile_key) ? profile_key
                                                     : relay_current_profile_key();
    session_id = relay_session_id_of_event(session_id);
    if (!*session_id) return NULL;

    relay_host_t *host = relay_host_registry_for_profile(co->registry, pkey, true);
    relay_runtime_t *rt = relay_host_runtime(host);

    /* Python ALWAYS constructs a fresh ConversationLease here — it keeps no
     * lease cache, so two acquires of the same conversation yield distinct
     * objects. The C port must not memoize or it diverges on identity. */
    char *key = rr_conv_key(pkey, session_id);
    if (!key) return NULL;

    pthread_mutex_lock(&co->lock);
    relay_lease_t *lease = (relay_lease_t *)calloc(1, sizeof(*lease));
    if (!lease) { pthread_mutex_unlock(&co->lock); free(key); return NULL; }
    lease->profile_key       = rr_strdup(pkey);
    lease->session_id        = rr_strdup(session_id);
    lease->platform          = rr_strdup(platform);
    lease->parent_session_id = rr_strdup(parent_session_id);
    lease->host              = host;
    lease->released          = false;
    /* Track the live conversation so shutdown_profile can enumerate it; the
     * lease itself stays caller-owned (Python leaves it to the GC). */
    omap_set(co->conversations, key, NULL);
    pthread_mutex_unlock(&co->lock);
    free(key);

    if (rt) {
        /* A subagent conversation nests under its parent session. */
        if (parent_session_id && *parent_session_id &&
            strcmp(parent_session_id, session_id) != 0)
            lease->session = relay_runtime_register_subagent(rt, parent_session_id,
                                                             session_id, NULL);
        else
            lease->session = relay_runtime_ensure_session(rt, session_id, NULL, NULL);
    }

    rr_run_initializers(co, rt, pkey, session_id, platform, parent_session_id, model);
    return lease;

if (!co) return NULL;
    const char *pkey = (profile_key && *profile_key) ? profile_key
                                                     : relay_current_profile_key();
    session_id = relay_session_id_of_event(session_id);
    if (!*session_id) return NULL;

    relay_host_t *host = relay_host_registry_for_profile(co->registry, pkey, true);
    relay_runtime_t *rt = relay_host_runtime(host);

    /* Python ALWAYS constructs a fresh ConversationLease here — it keeps no
     * lease cache, so two acquires of the same conversation yield distinct
     * objects. The C port must not memoize or it diverges on identity. */
    char *key = rr_conv_key(pkey, session_id);
    if (!key) return NULL;

    pthread_mutex_lock(&co->lock);
    relay_lease_t *lease = (relay_lease_t *)calloc(1, sizeof(*lease));
    if (!lease) { pthread_mutex_unlock(&co->lock); free(key); return NULL; }
    lease->profile_key       = rr_strdup(pkey);
    lease->session_id        = rr_strdup(session_id);
    lease->platform          = rr_strdup(platform);
    lease->parent_session_id = rr_strdup(parent_session_id);
    lease->host              = host;
    lease->released          = false;
    /* Track the live conversation so shutdown_profile can enumerate it; the
     * lease itself stays caller-owned (Python leaves it to the GC). */
    omap_set(co->conversations, key, NULL);
    pthread_mutex_unlock(&co->lock);
    free(key);

    if (rt) {
        /* A subagent conversation nests under its parent session. */
        if (parent_session_id && *parent_session_id &&
            strcmp(parent_session_id, session_id) != 0)
            lease->session = relay_runtime_register_subagent(rt, parent_session_id,
                                                             session_id, NULL);
        else
            lease->session = relay_runtime_ensure_session(rt, session_id, NULL, NULL);
    }

    rr_run_initializers(co, rt, pkey, session_id, platform, parent_session_id, model);
    return lease;

if (!co || !lease || lease->released) return NULL;

    relay_turn_t *turn = (relay_turn_t *)calloc(1, sizeof(*turn));
    if (!turn) return NULL;
    turn->logical_calls = omap_new(NULL);
    if (!turn->logical_calls) { free(turn); return NULL; }

    if (turn_id && *turn_id) {
        turn->turn_id = rr_strdup(turn_id);
    } else {
        char *u = uuid_v4();                      /* Python: uuid4().hex */
        if (u) {
            char hex[33]; size_t n = 0;
            for (const char *p = u; *p && n < 32; p++) if (*p != '-') hex[n++] = *p;
            hex[n] = '\0';
            turn->turn_id = rr_strdup(hex);
            free(u);
        } else {
            turn->turn_id = rr_strdup("");
        }
    }
    turn->task_id = rr_strdup(task_id);
    turn->lease   = lease;
    lease->refcount++;

    relay_runtime_t *rt = relay_host_runtime(lease->host);
    if (rt && lease->session) {
        relay_backend_t be;
        if (rr_backend(&be) && be.scope_push) {
            char *meta = rr_scope_metadata(NULL, relay_runtime_id(rt), false);
            turn->handle = be.scope_push(be.ctx, RELAY_TURN_SCOPE, RELAY_SCOPE_FUNCTION,
                                         relay_session_handle(lease->session), NULL, meta);
            free(meta);
        }
    }

    /* Register in the conversation's ACTIVE-TURN SET (Python:
     * _active_turns.setdefault(key, set()).add(id(turn))) — concurrent turns
     * on one conversation must all stay live. */
    char *key = rr_conv_key(lease->profile_key, lease->session_id);
    if (key) {
        char tk[32];
        rr_turn_key(turn, tk, sizeof tk);
        pthread_mutex_lock(&co->lock);
        omap_t *set = (omap_t *)omap_get(co->active_turns, key);
        if (!set) {
            set = omap_new(NULL);
            if (set && !omap_set(co->active_turns, key, set)) { omap_free(set); set = NULL; }
        }
        if (set) omap_set(set, tk, turn);
        turn->active_registered = set != NULL;
        pthread_mutex_unlock(&co->lock);
        free(key);
    }
    rr_set_current_turn(turn);
    turn->token_set = true;
    turn->prev_turn = relay_current_turn();
    /* begin_turn already set current_turn=turn above, so prev_turn is the
     * value that was there BEFORE this begin (exactly what ContextVar.set
     * returns as the reset token). */
    return turn;

(void)co;
    if (!turn) return;
    relay_backend_t be;
    bool have = rr_backend(&be);
    relay_runtime_t *rt = relay_host_runtime(relay_lease_host(turn->lease));
    bool is_real = rt && relay_lease_session(turn->lease) != NULL;

    size_t count = 0;
    const char **ids = omap_keys(turn->logical_calls, &count);
    for (size_t i = 0; i < count; i++) {
        relay_handle_t h = omap_get(turn->logical_calls, ids[i]);
        if (is_real && have && be.scope_pop && h != NULL) {
            char *meta = rr_scope_metadata(NULL, relay_runtime_id(rt), false);
            be.scope_pop(be.ctx, h, outcome, meta);   /* _safe: errors logged, not raised */
            free(meta);
        }
    }
    free((void *)ids);
    /* Python only clears when a real runtime owns the session; under the
     * no-wheel degradation path the calls are never popped, so the map stays. */
    if (is_real) omap_clear(turn->logical_calls);

(void)co;
    if (!turn) return;
    relay_backend_t be;
    bool have = rr_backend(&be);
    relay_runtime_t *rt = relay_host_runtime(relay_lease_host(turn->lease));
    bool is_real = rt && relay_lease_session(turn->lease) != NULL;

    size_t count = 0;
    const char **ids = omap_keys(turn->logical_calls, &count);
    for (size_t i = 0; i < count; i++) {
        relay_handle_t h = omap_get(turn->logical_calls, ids[i]);
        if (is_real && have && be.scope_pop && h != NULL) {
            char *meta = rr_scope_metadata(NULL, relay_runtime_id(rt), false);
            be.scope_pop(be.ctx, h, outcome, meta);   /* _safe: errors logged, not raised */
            free(meta);
        }
    }
    free((void *)ids);
    /* Python only clears when a real runtime owns the session; under the
     * no-wheel degradation path the calls are never popped, so the map stays. */
    if (is_real) omap_clear(turn->logical_calls);

if (!co || !turn || turn->closed) return;

    relay_coordinator_finish_logical_calls(co, turn, outcome);

    relay_runtime_t *rt = relay_host_runtime(relay_lease_host(turn->lease));
    if (turn->handle != NULL) {
        relay_backend_t be;
        if (rr_backend(&be) && be.scope_pop) {
            char *meta = rr_scope_metadata(NULL, relay_runtime_id(rt), false);
            be.scope_pop(be.ctx, turn->handle, outcome, meta);
            free(meta);
        }
    }
    turn->closed = true;
    turn->handle = NULL;

    relay_lease_t *lease = turn->lease;
    /* Delegated agents own exactly one turn: close the child conversation
     * while the active-turn guard still holds, so a parent timeout fallback
     * cannot race this terminal boundary. */
    if (lease && lease->parent_session_id && *lease->parent_session_id && rt)
        relay_runtime_unregister_subagent(rt, lease->session_id);

    rr_unregister_active_turn(co, turn);
    /* Python's _reset_turn_context: ContextVar.reset(token) restores the
     * value current_turn held BEFORE this turn's begin_turn — not NULL. A
     * turn created in a different context must not clobber the caller's
     * current-turn slot. */
    if (turn->token_set && relay_current_turn() == turn)
        rr_set_current_turn(turn->prev_turn);
    /* The turn object itself is CALLER-owned (Python hands it back and lets
     * the GC reclaim it); freeing here would dangle every caller reference. */

if (!co || !turn || turn->closed) return;

    relay_coordinator_finish_logical_calls(co, turn, outcome);

    relay_runtime_t *rt = relay_host_runtime(relay_lease_host(turn->lease));
    if (turn->handle != NULL) {
        relay_backend_t be;
        if (rr_backend(&be) && be.scope_pop) {
            char *meta = rr_scope_metadata(NULL, relay_runtime_id(rt), false);
            be.scope_pop(be.ctx, turn->handle, outcome, meta);
            free(meta);
        }
    }
    turn->closed = true;
    turn->handle = NULL;

    relay_lease_t *lease = turn->lease;
    /* Delegated agents own exactly one turn: close the child conversation
     * while the active-turn guard still holds, so a parent timeout fallback
     * cannot race this terminal boundary. */
    if (lease && lease->parent_session_id && *lease->parent_session_id && rt)
        relay_runtime_unregister_subagent(rt, lease->session_id);

    rr_unregister_active_turn(co, turn);
    /* Python's _reset_turn_context: ContextVar.reset(token) restores the
     * value current_turn held BEFORE this turn's begin_turn — not NULL. A
     * turn created in a different context must not clobber the caller's
     * current-turn slot. */
    if (turn->token_set && relay_current_turn() == turn)
        rr_set_current_turn(turn->prev_turn);
