    char resolved[PATH_MAX];
    if (!realpath(raw, resolved)) {
        if (absolute) {
            snprintf(resolved, sizeof resolved, "%s", raw);
        } else {
            char cwd[PATH_MAX];
            if (getcwd(cwd, sizeof cwd)) snprintf(resolved, sizeof resolved, "%s/%s", cwd, raw);
            else                         snprintf(resolved, sizeof resolved, "%s", raw);
        }
