    const char *out = "";
    if (stored && g_profile_key_cache) {
        void *existing = NULL;
        /* setdefault: a racing thread's value wins, exactly like Python. */
        if (omap_setdefault(g_profile_key_cache, raw, stored, &existing)) {
            out = (const char *)existing;
            if (existing != stored) free(stored);
        } else {
