                        }
                        const char *disp = rc_tool_may_have_side_effect(nm) ? "unknown" : "none";
                        const char *rec = rc_tool_may_have_side_effect(nm)
                            ? RECOVERY_INTERRUPTED_UNKNOWN : RECOVERY_INTERRUPTED_NONE;
