    for (size_t mi = 0; mi < j->c.count; mi++) {
        json_t *msg = j->c.items[mi];
        if (msg->type != JSON_OBJECT) continue;
        json_t *content = NULL;
        for (size_t ki = 0; ki < msg->c.count; ki++) {
            if (msg->c.keys && msg->c.keys[ki] && strcmp(msg->c.keys[ki], "content") == 0) {
                content = msg->c.items[ki];
