        iso[il-1] = '+';
        if (il + 5 < sizeof(iso)) {
            iso[il] = '0'; iso[il+1] = '0'; iso[il+2] = ':';
            iso[il+3] = '0'; iso[il+4] = '0'; iso[il+5] = '\0';
