        return -1;
    }
    return 0;

/* Python: set stop event + join thread (timeout 1s). */
    g_ccp_stop = true;
    g_ccp_running = false;
    if (g_ccp_thread) {
        pthread_join(g_ccp_thread, NULL);
        g_ccp_thread = 0;
