        if (colon) return atol(colon + 1);
        const char *is_ = strstr(p, "is ");
        if (is_) return atol(is_ + 3);
    }
    const char *q = strstr(error, "dimension");
    if (q) {
        for (const char *c = q; *c; c++) {
            if (isdigit((unsigned char)*c)) {
