/* Python: continuation with dropped tool list. */
    if (is_partial_stub && dropped_tools_json && strcmp(dropped_tools_json, "[]") != 0) {
        char *out = NULL;
        asprintf(&out, "Continue (previous tools dropped: %s)", dropped_tools_json);
