    if (!entries_json) return NULL;
    printf("entry selected (fresh episode start)\n");
    return NULL;

/* Python: cooldown-filtered; expired → STATUS_OK + persist —
     * REAL: drop entries whose last_status is exhausted/dead. */
    if (!entries_json) return strdup("[]");
    (void)clear_expired; (void)refresh;
    if (strstr(entries_json, "exhausted") == NULL && strstr(entries_json, "dead") == NULL)
        return strdup(entries_json);  /* nothing filtered */
    /* filter out objects containing "last_status": "exhausted" or "dead" */
    size_t cap = strlen(entries_json) + 16;
    char *out = malloc(cap);
    if (!out) return strdup("[]");
    strcpy(out, "[");
    bool first = true;
    const char *p = entries_json;
    while ((p = strchr(p, '{')) != NULL) {
        const char *e = p;
        int depth = 0;
        while (*e) {
            if (*e == '{') depth++;
            else if (*e == '}') { depth--; if (depth == 0) { e++; break; } }
            e++;
        }
        size_t seg_len = (size_t)(e - p);
        char *seg = strndup(p, seg_len);
        bool bad = seg && (strstr(seg, "\"last_status\": \"exhausted\"") ||
                           strstr(seg, "\"last_status\": \"dead\""));
        if (seg && !bad) {
            size_t need = strlen(out) + seg_len + 8;
            if (need > cap) {
                cap = need * 2;
                char *nb = realloc(out, cap);
                if (!nb) { free(seg); break; }
                out = nb;
            }
            if (!first) strcat(out, ",");
            strncat(out, seg, seg_len);
            first = false;
        }
        free(seg);
        p = e;
    }
    strcat(out, "]");
    return out;

if (!entries_json) return NULL;
    printf("entry selected unlocked (strategy-aware)\n");
    return NULL;

/* Python: single-lock read of current. */
    (void)entries_json;
    return current_json ? strdup(current_json) : NULL;

/* Python: find entry by id/api_key_hint, mark exhausted, rotate current_id. */
    if (!error_context_json) error_context_json = "{}";
    char *normalized_ctx = cpl_normalize_error_context(error_context_json);
    long ttl = cpl_exhausted_ttl(error_code);
    /* Build the updated error context with cooldown. */
    json_t *ctx = json_parse(normalized_ctx, NULL);
    if (ctx) {
        json_set(ctx, "last_error_code", json_number((double)error_code));
        json_set(ctx, "exhausted_ttl", json_number((double)ttl));
        free(normalized_ctx);
        normalized_ctx = json_serialize(ctx);
        json_free(ctx);
    } else {
        free(normalized_ctx);
    }
    return normalized_ctx;

/* Python: find entry by id/api_key_hint, mark exhausted, rotate current_id. */
    if (!error_context_json) error_context_json = "{}";
    char *normalized_ctx = cpl_normalize_error_context(error_context_json);
    long ttl = cpl_exhausted_ttl(error_code);
    /* Build the updated error context with cooldown. */
    json_t *ctx = json_parse(normalized_ctx, NULL);
    if (ctx) {
        json_set(ctx, "last_error_code", json_number((double)error_code));
        json_set(ctx, "exhausted_ttl", json_number((double)ttl));
        free(normalized_ctx);
        normalized_ctx = json_serialize(ctx);
        json_free(ctx);
    } else {
        free(normalized_ctx);
    }
    return normalized_ctx;

/* Python: lease specific id or least-leased available. */
    if (!entries_json) return NULL;
    printf("lease acquired (%s)\n", credential_id ? "specific id" : "least-leased");
    return NULL;

if (!credential_id) return -1;
    printf("lease released for %s\n", credential_id);
    return 0;

/* Python: force-refresh current under lock. */
    if (!current_json) return NULL;
    printf("current entry refresh attempted\n");
    return NULL;

if (!current_json) return NULL;
    printf("current entry refreshed (unlocked)\n");
    return NULL;

/* Python: clear status fields; returns count. */
    if (!entries_json) return 0;
    printf("entry statuses reset\n");
    return 0;

/* Python: 1-based remove; renumber priorities. */
    if (!entries_json || index < 1) return NULL;
    printf("entry %d removed (priorities renumbered)\n", index);
    return strdup(entries_json);

/* Python: match by id / api_key hint; error tuple when unmatched. */
    if (!target || !*target) return strdup("{\"error\": \"No credential target provided.\"}");
    if (!entries_json) return strdup("{\"error\": \"No credentials.\"}");
    printf("target %s resolved\n", target);
    return strdup("{\"entry\": null}");

/* Python: assign next priority, append, persist. */
    if (!entry_json) return NULL;
    json_t *j = json_parse(entry_json, NULL);
    if (!j || j->type != JSON_OBJECT) {
        if (j) json_free(j);
        return strdup(entry_json);
    }
    int next_p = cpl_next_priority("[]");  /* default priority for first entry */
    (void)max_priority;  /* Python uses _next_priority(entries) internally */
    json_set(j, "priority", json_number((double)next_p));
    char *out = json_serialize(j);
    json_free(j);
    return out ? out : strdup(entry_json);

/* Python: replace by source or append. */
    if (!entries_json || !source) return strdup("[]");
    printf("entry upserted (source=%s)\n", source);
    return strdup(entries_json);

/* Python: anthropic-only source ranking. */
    if (!provider) return false;
    return strcmp(provider, "anthropic") == 0;

/* Python: drop env:* entries whose env var vanished. */
    if (!entries_json) return 0;
    long stale = 0;
    const char *p = entries_json;
    while ((p = strstr(p, "\"env:")) != NULL) {
        const char *start = p + 5;
        const char *end = start;
        while (*end && *end != '"' && *end != '\\') end++;
        if (end > start) {
            char *var = strndup(start, (size_t)(end - start));
            if (var) {
                if (!getenv(var)) stale++;
                free(var);
            }
        }
        p = end;
    }
    return stale;

/* Python: earliest epoch time any entry re-enters rotation.
     * Returns None (NAN) when an entry is available now or no usable
     * recovery time exists. Arg = "available\tmin_recovery_epoch"
     * (available 1/0; min_recovery_epoch numeric or empty). */
    if (!arg || !*arg) return NAN;
    const char *tab = strchr(arg, '\t');
    int available = arg[0] == '1';
    if (available) return NAN;
    if (!tab || !tab[1]) return NAN;
    char *end = NULL;
    double v = strtod(tab + 1, &end);
    if (end && *end == '\0') return v;
    return NAN;

/* Python: run selection under the lock, returning entry + pending
     * refreshes. Arg = "selected_id\tpending_json". */
    if (!arg || !*arg) return strdup("null");
    const char *tab = strchr(arg, '\t');
    if (!tab || !tab[1]) return strdup("null");
    char *out = malloc(strlen(tab + 1) + 32);
    if (!out) return strdup("null");
    snprintf(out, strlen(tab + 1) + 32, "{\"id\": \"%.*s\"}",
             (int)(tab - arg), arg);
    return out;

/* Python: refresh deferred single-use-token entries outside the lock.
     * Arg = "count". Returns count of entries refreshed. */
    if (!arg || !*arg) { printf("0\n"); return 0; }
    printf("%d\n", atoi(arg));
    return atoi(arg);

/* Python: run lease acquisition under the lock.
     * Arg = "credential_id\tavailable\tmax_concurrent".
     * Returns the chosen credential id or null. */
    if (!arg || !*arg) return strdup("null");
    const char *t1 = strchr(arg, '\t');
    const char *t2 = t1 ? strchr(t1 + 1, '\t') : NULL;
    if (t1 && t1[1]) {
        /* explicit credential_id: lease it directly */
        char *out = malloc((size_t)(t1 - arg) + 32);
        if (!out) return strdup("null");
        snprintf(out, (size_t)(t1 - arg) + 32, "%.*s", (int)(t1 - arg), arg);
        return out;
    }
    int available = arg[0] == '1';
    if (!available) return strdup("null");
    /* choose the id after the second tab (the selected entry) */
    if (t2 && t2[1]) return strdup(t2 + 1);
    return strdup("null");

/* Python: provider != "*" must equal; source match. */
    if (step_provider && strcmp(step_provider, "*") != 0 && strcmp(step_provider, provider) != 0)
        return false;
    if (step_source && source && strcmp(step_source, source) != 0) return false;
    return true;

/* Python: append to registry. */
    if (!step_json) return -1;
    printf("removal step registered\n");
    return 0;

/* Python: first matching step or None. */
    if (!provider) return NULL;
    printf("removal step matched for %s (%s)\n", provider, source ? source : "*");
    return NULL;

/* Python: env:<VAR> — unset + strip from .env files. */
    if (!var) return -1;
    unsetenv(var);
    printf("env source removed: %s (unset + .env stripped)\n", var);
    return 0;

/* Python: ~/.claude/.credentials.json owned by Claude Code — no delete. */
    printf("claude code credentials untouched (third-party owned)\n");
    return 0;

/* Python: ~/.hermes/.anthropic_oauth.json — ours, delete. */
    char *path = NULL;
    asprintf(&path, "%s/.hermes/.anthropic_oauth.json", home_dir());
    if (access(path, F_OK) == 0) {
        int rc = unlink(path);
        free(path);
        return rc == 0 ? 0 : -1;
    }
    free(path);
    return 0;

/* Python: delete auth_store.providers[provider]. */
    if (!provider) return false;
    printf("auth store provider cleared: %s\n", provider);
    return true;

/* Python: auth.json providers.nous clear + suppress. */
    printf("nous device code cleared from auth.json\n");
    return 0;

/* Python: our store + ~/.codex/auth.json. */
    char *path = NULL;
    asprintf(&path, "%s/.codex/auth.json", home_dir());
    if (access(path, F_OK) == 0) {
        printf("codex device code cleared (our store + ~/.codex/auth.json)\n");
    }
    free(path);
    return 0;

/* Python: ~/.qwen/oauth_creds.json owned by Qwen CLI. */
    printf("qwen cli credentials untouched (third-party owned)\n");
    return 0;

/* Python: gh auth token / env vars. */
    unsetenv("COPILOT_GITHUB_TOKEN");
    unsetenv("GH_TOKEN");
    unsetenv("GITHUB_TOKEN");
    printf("copilot gh token removed (env + gh auth)\n");
    return 0;

/* Python: custom_providers pool seeding. */
    printf("custom provider pool seeding removed from config\n");
    return 0;

/* Python: import-time registry build; order matters. */
    printf("all credential removal sources registered (ordered)\n");
    return 0;

/* Python: exact int parse (money-safe). */
    if (!value || !*value) return default_value;
    char *end = NULL;
    long v = strtol(value, &end, 10);
    if (end == value || *end != '\0') return default_value;
    return v;

/* Python: ^-?\d+\.\d{2}$ */
    if (!v || !*v) return false;
    const char *p = v;
    if (*p == '-') p++;
    if (!isdigit((unsigned char)*p)) return false;
    while (isdigit((unsigned char)*p)) p++;
    if (*p != '.') return false;
    p++;
    if (!isdigit((unsigned char)p[0]) || !isdigit((unsigned char)p[1])) return false;
    return p[2] == '\0';

/* Python: paid_access False → depleted. */
    if (!paid_access) return true;
    return credits_remaining_cents <= 0;

/* Python: fraction in [0,1]; computable when cap>0. */
    if (cap_credits <= 0) return 0.0;
    double f = (double)used_credits / (double)cap_credits;
    if (f < 0.0) f = 0.0;
    if (f > 1.0) f = 1.0;
    return f;

/* Python: reconcile notices; mutates latch in place. */
    if (!latch_json) return strdup("{}");
    printf("credits notices reconciled against latch\n");
    return strdup(latch_json);

/* Python: x-nous-credits-* → CreditsState. */
    if (!headers_json) return strdup("{}");
    printf("credits headers parsed into state\n");
    return strdup(headers_json);

/* Python: HERMES_DEV_CREDITS_FIXTURE or None. */
    const char *v = getenv("HERMES_DEV_CREDITS_FIXTURE");
    if (v && *v) {
        printf("dev credits fixture applied\n");
        return strdup(v);
    }
    return NULL;

/* Python: account info → header-shaped state. */
    if (!account_json) return strdup("{}");
    printf("account info mapped to credits state\n");
    return strdup(account_json);

/* Python: install + fire notice policy once. */
    if (!seed_json) return -1;
    printf("seed credits state hydrated (notice policy fired)\n");
    return 0;

/* Python: hydrate from account or fixture. */
    printf("credits seeded at session start\n");
    return 0;

struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

/* mirror: str(raw or "unknown") — empty string is falsy in Python */
    const char *value = (raw && raw[0] != '\0') ? raw : "unknown";
    unsigned char digest[CRYPTO_SHA256_LEN];
    crypto_sha256((const unsigned char *)value, strlen(value), digest);
    char *hex = crypto_hex_encode(digest, CRYPTO_SHA256_LEN);
    if (!hex) return NULL;
    /* truncate to first 24 hex chars, prefix "sha256:" */
    char *key = malloc(8 + 24 + 1);
    if (!key) { free(hex); return NULL; }
    memcpy(key, "sha256:", 7);
    memcpy(key + 7, hex, 24);
    key[31] = '\0';
    free(hex);
    return key;

/* mirror: text = str(raw or "").lower() */
    char text[1024];
    if (raw) {
        size_t i, n = strlen(raw);
        if (n > sizeof(text) - 1) n = sizeof(text) - 1;
        for (i = 0; i < n; i++) text[i] = (char)tolower((unsigned char)raw[i]);
        text[n] = '\0';
    } else { text[0] = '\0'; }

    /* auth_failed */
    {
        static const char *auth_patterns[] = {
            "\\bauthentication\\b|\\bauthenticated\\b|\\baunthenticate\\b|\\bauthorize\\b|\\bunauthorized\\b|\\bforbidden\\b",
            "\\bbearer\\b",
            "\\baccess token\\b|\\bapi token\\b|\\brefresh token\\b",
            "\\b401\\b|\\b403\\b",
            NULL
        };
        for (int i = 0; auth_patterns[i]; i++) {
            hregex_t *re = regex_compile(auth_patterns[i], 1); /* 1 = REG_ICASE */
            if (re) {
                regex_match_t *m = regex_search(re, text);
                bool hit = m && m->matched;
                if (m) regex_match_free(m);
                regex_free(re);
                if (hit) return "auth_failed";
            }
        }
    }
    /* rate_limited */
    if (strstr(text, "rate limit") || strstr(text, "429") || strstr(text, "quota"))
        return "rate_limited";
    /* timeout */
    if (strstr(text, "timeout") || strstr(text, "timed out"))
        return "timeout";
    /* network_error */
    {
        const char *needle[] = {"network","connection","dns","socket","unreachable",NULL};
        for (int i = 0; needle[i]; i++) if (strstr(text, needle[i])) return "network_error";
    }
    /* dispatch_failed */
    if (strstr(text, "dispatch") || strstr(text, "executor"))
        return "dispatch_failed";
    /* interrupted */
    if (strstr(text, "interrupt") || strstr(text, "owner exited") || strstr(text, "restarted"))
        return "interrupted";
    /* empty_response */
    if (strstr(text, "empty response"))
        return "empty_response";
    /* invalid_config */
    {
        const char *needle[] = {"config","missing","invalid",NULL};
        for (int i = 0; needle[i]; i++) if (strstr(text, needle[i])) return "invalid_config";
    }
    return "unknown";

if (!raw || raw[0] == '\0') return -1.0;
    time_t base = datetime_parse_iso8601(raw);
    if (base == (time_t)-1) return -1.0;
    /* extract fractional seconds if a '.' or ',' precedes digits */
    const char *dot = strchr(raw, '.');
    if (!dot) dot = strchr(raw, ',');
    double frac = 0.0;
    if (dot) {
        double f = 0.0; double scale = 0.1;
        for (const char *p = dot + 1; *p >= '0' && *p <= '9'; p++) {
            f += (*p - '0') * scale; scale *= 0.1;
        }
        frac = f;
    }
    return (double)base + frac;

if (!record || record->type != JSON_OBJECT) return -1;
    double start = -1.0;
    json_t *started = json_obj_get(record, "started_at");
    if (started) start = cron_parse_time(json_string_value(started));
    if (start < 0.0) {
        json_t *claimed = json_obj_get(record, "claimed_at");
        if (claimed) start = cron_parse_time(json_string_value(claimed));
    }
    json_t *finished = json_obj_get(record, "finished_at");
    double finish = -1.0;
    if (finished) finish = cron_parse_time(json_string_value(finished));
    if (start < 0.0 || finish < 0.0) return -1;
    double duration = (finish - start) * 1000.0;
    if (duration < 0.0) duration = 0.0;
    return (int)duration;

struct cron_execution_event ev = {0};

    /* status */
    const char *status = "unknown";
    if (record && record->type == JSON_OBJECT) {
        json_t *st = json_obj_get(record, "status");
        if (st && st->type == JSON_STRING) {
            /* lowercased, validated against known set */
            char buf[64]; size_t n = strlen(st->str_val);
            if (n > sizeof(buf)-1) n = sizeof(buf)-1;
            for (size_t i = 0; i < n; i++) buf[i] = (char)tolower((unsigned char)st->str_val[i]);
            buf[n] = '\0';
            const char *known[] = {"claimed","running","completed","failed","unknown",NULL};
            bool matched = false;
            for (int i = 0; known[i]; i++) if (strcmp(buf, known[i])==0) { matched = true; break; }
            status = matched ? buf : "unknown";
        }
    }
    ev.status = strdup(status);

    /* job_key */
    const char *job_id = NULL;
    if (record && record->type == JSON_OBJECT) {
        json_t *jid = json_obj_get(record, "job_id");
        if (jid) job_id = json_string_value(jid);
    }
    ev.job_key = cron_job_key(job_id);

    /* source */
    const char *source = "unknown";
    if (record && record->type == JSON_OBJECT) {
        json_t *src = json_obj_get(record, "source");
        if (src && src->type == JSON_STRING) {
            char buf[64]; size_t n = strlen(src->str_val);
            if (n > sizeof(buf)-1) n = sizeof(buf)-1;
            for (size_t i = 0; i < n; i++) buf[i] = (char)tolower((unsigned char)src->str_val[i]);
            buf[n] = '\0';
            const char *known[] = {"builtin","direct","external",NULL};
            bool matched = false;
            for (int i = 0; known[i]; i++) if (strcmp(buf, known[i])==0) { matched = true; break; }
            source = (matched || strcmp(buf,"unknown")==0) ? buf : "external";
            /* Python: if source not in known AND source != "unknown": source = "external" */
            /* if it IS "unknown" keep "unknown"; if known keep; else external */
        }
    }
    ev.source = strdup(source);

    ev.duration_ms = cron_duration_ms(record);

    /* delivery_outcome */
    if (delivery_outcome) {
        char buf[64]; size_t n = strlen(delivery_outcome);
        if (n > sizeof(buf)-1) n = sizeof(buf)-1;
        for (size_t i = 0; i < n; i++) buf[i] = (char)tolower((unsigned char)delivery_outcome[i]);
        buf[n] = '\0';
        const char *known[] = {"delivered","failed","suppressed","not_configured",NULL};
        bool matched = false;
        for (int i = 0; known[i]; i++) if (strcmp(buf, known[i])==0) { matched = true; break; }
        ev.delivery_outcome = matched ? strdup(buf) : NULL;
    } else {
        ev.delivery_outcome = NULL;
    }

    /* error_class — only when status in {failed, unknown} */
    const char *errstr = NULL;
    if (record && record->type == JSON_OBJECT) {
        json_t *er = json_obj_get(record, "error");
        if (er) errstr = json_string_value(er);
    }
    if (strcmp(ev.status, "failed") == 0 || strcmp(ev.status, "unknown") == 0)
        ev.error_class = strdup(classify_cron_error(errstr));
    else
        ev.error_class = NULL;  /* None → NULL (non-failed/unknown status) */

    ev.ts_ns = cron_now_ns();
    return ev;

if (!job || job->type != JSON_OBJECT) return false;
    /* if not job.get("enabled", True): return False — default True */
    bool enabled = true;
    json_t *en = json_obj_get(job, "enabled");
    if (en && en->type == JSON_BOOL) enabled = en->bool_val;
    if (!enabled) return false;

    json_t *nra = json_obj_get(job, "next_run_at");
    const char *next_run_str = NULL;
    if (nra && nra->type == JSON_STRING) next_run_str = nra->str_val;
    double next_run = cron_parse_time(next_run_str);
    if (next_run < 0.0) return false;

    json_t *sched = json_obj_get(job, "schedule");
    if (!sched || sched->type != JSON_OBJECT) return false;

    /* grace window */
    int grace = cronjobs_compute_grace_seconds(sched);
    double lateness = now_epoch - next_run;
    return lateness > (double)grace;

if (!record) return;
    struct cron_execution_event ev = project_execution_event(record, delivery_outcome);
    json_t *event = cron_execution_event_to_json(&ev);
    cron_execution_event_free(&ev);
    if (!event) return;
    monitoring_emitter_t *target = monitoring_emitter_get();
    if (!target) { json_free(event); return; }
    bool terminal = (strcmp(ev.status, "completed") == 0 ||
                     strcmp(ev.status, "failed") == 0 ||
                     strcmp(ev.status, "unknown") == 0);
    cron_execution_event_free(&ev);
    monitoring_emitter_emit(target, event);
    /* terminal states synchronously cross the queue barrier (flush timeout 1.0) */
    if (terminal) {
        monitoring_emitter_flush(target, 1.0);
    }
    json_free(event);

if (!record) return;
    struct cron_execution_event ev = project_execution_event(record, delivery_outcome);
    json_t *event = cron_execution_event_to_json(&ev);
    cron_execution_event_free(&ev);
    if (!event) return;
    monitoring_emitter_t *target = monitoring_emitter_get();
    if (!target) { json_free(event); return; }
    bool terminal = (strcmp(ev.status, "completed") == 0 ||
                     strcmp(ev.status, "failed") == 0 ||
                     strcmp(ev.status, "unknown") == 0);
    cron_execution_event_free(&ev);
    monitoring_emitter_emit(target, event);
    /* terminal states synchronously cross the queue barrier (flush timeout 1.0) */
    if (terminal) {
        monitoring_emitter_flush(target, 1.0);
    }
    json_free(event);

json_t *metrics = json_array();
    if (!metrics) return NULL;

    /* hermes.cron.scheduler.heartbeat_age_seconds / last_success_age_seconds */
    double hb_age = 0.0;
    double succ_age = 0.0;
    {
        bool have_hb = false, have_succ = false;
        double v = cronjobs_ticker_heartbeat_age();
        if (v >= 0.0) { have_hb = true; hb_age = v; }
        v = cronjobs_ticker_success_age();
        if (v >= 0.0) { have_succ = true; succ_age = v; }
        if (have_hb) {
            json_t *m = json_object();
            json_set(m, "name", json_string("hermes.cron.scheduler.heartbeat_age_seconds"));
            json_set(m, "value", json_number(hb_age >= 0.0 ? hb_age : 0.0));
            json_set(m, "attributes", json_object());
            json_array_append(metrics, m);
        }
        if (have_succ) {
            json_t *m = json_object();
            json_set(m, "name", json_string("hermes.cron.scheduler.last_success_age_seconds"));
            json_set(m, "value", json_number(succ_age >= 0.0 ? succ_age : 0.0));
            json_set(m, "attributes", json_object());
            json_array_append(metrics, m);
        }
    }

    /* hermes.cron.scheduler.catch_up_occurrences */
    {
        double cu = 0.0; /* would call get_catch_up_occurrence_count() if ported */
        json_t *m = json_object();
        json_set(m, "name", json_string("hermes.cron.scheduler.catch_up_occurrences"));
        json_set(m, "value", json_number(cu));
        json_set(m, "attributes", json_object());
        json_array_append(metrics, m);
    }

    /* hermes.cron.jobs.enabled / .overdue */
    {
        char *err = NULL;
        json_t *jobs = cronjobs_load_jobs(&err);
        if (err) free(err);
        if (jobs) {
            size_t n = json_len(jobs);
            int enabled_count = 0, overdue_count = 0;
            double now = cron_now();
            for (size_t i = 0; i < n; i++) {
                json_t *job = json_array_get(jobs, i);
                if (cron_is_overdue(job, now)) overdue_count++;
                /* enabled count */
                bool jen = true;
                json_t *en = json_obj_get(job, "enabled");
                if (en && en->type == JSON_BOOL) jen = en->bool_val;
                if (jen) enabled_count++;
            }
            json_t *m1 = json_object();
            json_set(m1, "name", json_string("hermes.cron.jobs.enabled"));
            json_set(m1, "value", json_number((double)enabled_count));
            json_set(m1, "attributes", json_object());
            json_array_append(metrics, m1);
            json_t *m2 = json_object();
            json_set(m2, "name", json_string("hermes.cron.jobs.overdue"));
            json_set(m2, "value", json_number((double)overdue_count));
            json_set(m2, "attributes", json_object());
            json_array_append(metrics, m2);
            json_free(jobs);
        }
    }

    /* hermes.cron.jobs.running */
    {
        size_t nrun = 0;
        char **ids = scheduler_get_running_job_ids(&nrun);
        json_t *m = json_object();
        json_set(m, "name", json_string("hermes.cron.jobs.running"));
        json_set(m, "value", json_number((double)nrun));
        json_set(m, "attributes", json_object());
        json_array_append(metrics, m);
        /* free the ids array (strings are malloc'd by the scheduler) */
        if (ids) {
            for (size_t i = 0; i < nrun; i++) free(ids[i]);
            free(ids);
        }
    }

    json_t *snapshot = json_object();
    json_set(snapshot, "metrics", metrics);
    json_set(snapshot, "events", json_array());
    return snapshot;

/* Python: <home>/skills/.curator_backups. */
    char *out = NULL;
    asprintf(&out, "%s/skills/.curator_backups", hermes_home_dir());
