    for (int i = 0; i < 24 && i < CRYPTO_SHA256_LEN * 2; i++) {
        int byte_idx = i / 2;
        int nibble = (i % 2 == 0) ? (digest[byte_idx] >> 4) : (digest[byte_idx] & 0x0F);
        hex[i] = nibble < 10 ? '0' + nibble : 'a' + nibble - 10;
    }
    hex[24] = '\0';

    char *out = malloc(32);
    if (!out) return NULL;
    snprintf(out, 32, "sha256:%s", hex);
    return out;

