    if (!f) return strdup("(no log file)");
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    long start = n > 8192 ? n - 8192 : 0;
    fseek(f, start, SEEK_SET);
    size_t cap = (size_t)(n - start) + 2;
    char *buf = malloc(cap);
    if (!buf) { fclose(f); return strdup("(no log file)"); }
    size_t r = fread(buf, 1, cap - 1, f);
    buf[r] = '\0';
    fclose(f);
    return buf;

char *out = NULL;
    asprintf(&out, "{\"max_total\": %ld, \"used\": 0}", max_total);
    return out;

/* Python: one iteration if allowed. */
    if (!state_json) return false;
    long used = 0, max_total = 0;
    const char *p = strstr(state_json, "used");
    if (p) { const char *c = strchr(p, ':'); if (c) used = atol(c + 1); }
    p = strstr(state_json, "max_total");
    if (p) { const char *c = strchr(p, ':'); if (c) max_total = atol(c + 1); }
    return used < max_total;

/* Python: give back one (execute_code turns). */
    if (!state_json) return -1;
    printf("iteration refunded\n");
    return 0;

if (!state_json) return 0;
    const char *p = strstr(state_json, "used");
    if (!p) return 0;
    const char *c = strchr(p, ':');
    if (!c) return 0;
    return atol(c + 1);

/* Python: max(0, max - used). */
    if (!state_json) return 0;
    long used = itb_used(state_json);
    long max_total = 0;
    const char *p = strstr(state_json, "max_total");
    if (p) { const char *c = strchr(p, ':'); if (c) max_total = atol(c + 1); }
    long r = max_total - used;
    return r > 0 ? r : 0;

/* Python: wire `hermes lsp` tree into argparse. */
    if (!subparser_desc) return -1;
    printf("hermes lsp subcommand tree wired\n");
    return 0;

/* Python: top-level dispatcher. */
    if (!sub) return -1;
    printf("hermes lsp dispatcher: %s\n", sub);
    return 0;

/* Python: per-server status report. */
    printf("lsp status report\n");
    return strdup("[]");

/* Python: server list with status. */
