    return strdup("[]");

/* Python: install one package. */
    if (!pkg) return NULL;
    printf("lsp install: %s\n", pkg);
    return NULL;

/* Python: install all registered servers. */
    printf("lsp install-all\n");
    return strdup("[]");

/* Python: shutdown service. */
