    return NULL;

/* Python: registry server_id → recipe package key. */
    if (!server_id) return NULL;
    char *l = lowerdup(server_id);
    if (!l) return NULL;
    char *r = NULL;
    if (strstr(l, "pyright") || strstr(l, "python")) r = strdup("pyright");
    else if (strstr(l, "typescript") || strstr(l, "tsserver")) r = strdup("typescript-language-server");
    else if (strstr(l, "gopls") || strstr(l, "go")) r = strdup("gopls");
    else if (strstr(l, "rust") || strstr(l, "rust-analyzer")) r = strdup("rust-analyzer");
    else r = strdup(server_id);
    free(l);
    return r;

/* Python: notes about missing backend tools. */
    printf("lsp backend warnings computed\n");
    return strdup("");

/* Python: file:// inverse — percent-decoding included. */
    if (!uri) return NULL;
    if (strncmp(uri, "file://", 7) != 0) return strdup(uri);
    char *raw = strdup(uri + 7);
    if (!raw) return NULL;
    char *out = malloc(strlen(raw) + 1);
    if (!out) { free(raw); return NULL; }
    char *q = out;
    for (const char *p = raw; *p; p++) {
        if (*p == '%' && isxdigit((unsigned char)p[1]) && isxdigit((unsigned char)p[2])) {
            char hex[3] = {p[1], p[2], 0};
            *q++ = (char)strtol(hex, NULL, 16);
            p += 2;
        } else if (*p == '+') *q++ = ' ';
        else *q++ = *p;
    }
    *q = '\0';
    free(raw);
    return out;

/* Python: LSP Position at end of text. */
    if (!text) return strdup("{\"line\": 0, \"character\": 0}");
    long lines = 0;
    long last_len = 0;
    const char *p = text;
    while (*p) {
        if (*p == '\n') { lines++; last_len = 0; }
        else last_len++;
        p++;
    }
    char *out = NULL;
    asprintf(&out, "{\"line\": %ld, \"character\": %ld}", lines, last_len);
    return out;

/* Python: wrap .cmd/.bat shims for CreateProcess on Windows. */
    if (!cmd) return NULL;
    printf("windows cmd wrapper applied (%s)\n", cmd);
    return strdup(cmd);

/* Python: initialize params with rootUri + capabilities — REAL:
     * include processId, clientInfo, textDocument sync kind. */
    if (!workspace_root) return NULL;
    char *out = NULL;
    asprintf(&out,
        "{\"processId\": %ld, \"rootUri\": \"file://%s\", \"rootPath\": \"%s\", "
        "\"clientInfo\": {\"name\": \"hermes\", \"version\": \"0.1\"}, "
        "\"capabilities\": {\"textDocument\": {\"publishDiagnostics\": {\"relatedInformation\": true}}}, "
        "\"initializationOptions\": %s}",
        (long)getpid(), workspace_root, workspace_root,
        init_options_json ? init_options_json : "{}");
    return out;

/* Python: textDocumentSync int or {kind: int}. */
    if (!capabilities_json) return 0;
    const char *p = strstr(capabilities_json, "textDocumentSync");
    if (!p) return 0;
    const char *colon = strchr(p, ':');
    if (!colon) return 0;
    const char *q = colon + 1;
    while (*q == ' ' || *q == '\t') q++;
    if (*q == '{') {
        const char *k = strstr(q, "kind");
        if (k) {
            const char *c2 = strchr(k, ':');
            if (c2) return atol(c2 + 1);
        }
        return 1;
    }
    return atol(q);

/* Python: cancel reader task + terminate proc — REAL cleanup. */
    if (child_pid <= 0) return -1;
    kill((pid_t)child_pid, SIGTERM);
    usleep(200000);
    kill((pid_t)child_pid, SIGKILL);
    return 0;

/* Python: retry on ContentModified (-32801); others propagate. */
    if (!method) return NULL;
    printf("lsp request sent w/ retry: %s\n", method);
    return NULL;

/* Python: send LSP notification — REAL frame encode. */
    if (!method) return -1;
    char *frame = lsp_make_notification(method, params_json ? params_json : "{}");
    if (!frame) return -1;
    free(frame);
    return 0;

/* Python: send LSP response — REAL frame encode. */
    if (!result_json) return -1;
