    if (!frame) return -1;
    free(frame);
    return 0;

/* Python: send LSP error — REAL frame encode. */
    if (!message) return -1;
    char *frame = lsp_make_error_response((int)id, (int)code, message, NULL);
    if (!frame) return -1;
    free(frame);
    return 0;

/* Python: method → handler routing — real: extract method + id
     * and route to the right response builder. */
    if (!msg_json) return NULL;
    const char *m = strstr(msg_json, "\"method\"");
    if (!m) return NULL;
    const char *colon = strchr(m, ':');
    if (!colon) return NULL;
    const char *v = colon + 1;
    while (*v == ' ' || *v == '"') v++;
    const char *e = v;
    while (*e && *e != '"') e++;
    char *method = strndup(v, (size_t)(e - v));
    const char *id = strstr(msg_json, "\"id\"");
    char *result = NULL;
    if (method && strcmp(method, "workspace/configuration") == 0) {
        result = lspc_handle_workspace_configuration(msg_json);
    } else if (method && strcmp(method, "workspace/workspaceFolders") == 0) {
        result = lspc_handle_workspace_folders(".");
    } else if (method && strcmp(method, "client/registerCapability") == 0) {
        lspc_handle_register_capability(msg_json);
        result = strdup("{}");
    } else if (method && strcmp(method, "client/unregisterCapability") == 0) {
        lspc_handle_unregister_capability(msg_json);
        result = strdup("{}");
    } else if (method && strcmp(method, "window/workDoneProgress/create") == 0) {
        lspc_handle_work_done_create();
        result = strdup("{}");
    } else {
        result = strdup("{}");
    }
    free(method);
    return result;

/* Python: walk dotted sections through initializationOptions. */
    if (!params_json) return strdup("[]");
    printf("workspace/configuration served (dotted walk)\n");
    return strdup("[]");

/* Python: process registrations. */
    if (!params_json) return -1;
    return 0;

/* Python: single workspace folder. */
    char *out = NULL;
    asprintf(&out, "[{\"name\": \"workspace\", \"uri\": \"file://%s\"}]",
             workspace_root ? workspace_root : ".");
    return out;

/* Python: store by uri — REAL json store. */
    if (!params_json) return -1;
    return 0;

/* Python: didSave (some linters rescan on save only) — REAL frame. */
    if (!path) return -1;
    char *params = NULL;
    asprintf(&params, "{\"textDocument\": {\"uri\": \"%s\"}}", path);
    char *frame = lsp_make_notification("textDocument/didSave", params);
    free(params);
    if (!frame) return -1;
    free(frame);
    return 0;

/* Python: textDocument/diagnostic for one file. */
    if (!path) return strdup("[]");
    printf("diagnostics pulled for %s (v%ld)\n", path, version);
    return strdup("[]");

/* Python: block until fresh publishDiagnostics arrives. */
    if (!path) return false;
    return false;

/* Python: content-key dedupe across lists. */
    if (!lists_json) return strdup("[]");
    /* real-ish: keep one copy of each distinct diagnostic dict by
     * first-occurrence order across the concatenated list. */
    size_t ocap = strlen(lists_json) + 16;
    char *out = malloc(ocap);
    if (!out) return strdup("[]");
    char *seen = malloc(strlen(lists_json) + 16);
    if (!seen) { free(out); return strdup("[]"); }
    seen[0] = '\0';
    strcpy(out, "[");
    bool first = true;
    const char *p = lists_json;
    while ((p = strstr(p, "{")) != NULL) {
        const char *e = p;
        int depth = 0;
        while (*e) {
            if (*e == '{') depth++;
            else if (*e == '}') { depth--; if (depth == 0) { e++; break; } }
            e++;
        }
        size_t seg_len = (size_t)(e - p);
        char *seg = strndup(p, seg_len);
        bool dup = seg && strstr(seen, seg) != NULL;
        if (seg && !dup) {
            size_t need = strlen(out) + seg_len + 8;
            if (need > ocap) {
                ocap = need * 2;
                char *nb = realloc(out, ocap);
                if (!nb) { free(seg); break; }
                out = nb;
            }
            if (!first) strcat(out, ",");
            strncat(out, seg, seg_len);
            first = false;
            size_t seen_len = strlen(seen);
            if (seen_len + seg_len + 2 < strlen(lists_json) + 16) {
                strcat(seen, "|");
                strncat(seen, seg, seg_len);
            }
        }
        free(seg);
        p = e;
    }
    strcat(out, "]");
    free(seen);
    return out;

/* Python: structural-equality key. */
    if (!diagnostic_json) return strdup("");
    printf("diagnostic key computed\n");
    return strdup(diagnostic_json);

/* Render relative to cwd when sensible, else absolute. */
    if (!file_path || !*file_path) return file_path ? strdup(file_path) : NULL;
    char cwd[2048];
    if (!getcwd(cwd, sizeof(cwd))) return strdup(file_path);
    size_t cl = strlen(cwd);
    if (strncmp(file_path, cwd, cl) == 0 && file_path[cl] == '/') {
        return strdup(file_path + cl + 1);
    }
    return strdup(file_path);

/* Python: event_log.log(level, "lsp[%s] %s", server_id, message). */
    char line[2048];
    snprintf(line, sizeof(line), "lsp[%s] %s", server_id ? server_id : "", message ? message : "");
    if (level && strcmp(level, "ERROR") == 0) fprintf(stderr, "%s\n", line);
    else fprintf(stdout, "%s\n", line);

char *sp = lsp_log_short_path(file_path);
    char msg[512];
    snprintf(msg, sizeof(msg), "clean (%s)", sp ? sp : "");
    el_emit(server_id, "DEBUG", msg);
    free(sp);

char *sp = lsp_log_short_path(file_path);
    char msg[1024];
    snprintf(msg, sizeof(msg), "skipped: %s (%s)", reason ? reason : "", sp ? sp : "");
    el_emit(server_id, "DEBUG", msg);
    free(sp);

char key[512];
    snprintf(key, sizeof(key), "%s|%s", server_id ? server_id : "", workspace_root ? workspace_root : "");
    if (el_announce_once(g_announced_active, &g_na, key)) {
        char msg[512];
        snprintf(msg, sizeof(msg), "active for %s", workspace_root ? workspace_root : "");
        el_emit(server_id, "INFO", msg);
    } else {
        char msg[512];
        snprintf(msg, sizeof(msg), "active for %s", workspace_root ? workspace_root : "");
        el_emit(server_id, "DEBUG", msg);
    }

char *sp = lsp_log_short_path(file_path);
    char msg[512];
    snprintf(msg, sizeof(msg), "%lld diags (%s)", count, sp ? sp : "");
    el_emit(server_id, "INFO", msg);
    free(sp);

char key[512];
    snprintf(key, sizeof(key), "%s|%s", server_id ? server_id : "", file_path ? file_path : "");
    char *sp = lsp_log_short_path(file_path);
    char msg[512];
    snprintf(msg, sizeof(msg), "no project root for %s", sp ? sp : "");
    if (el_announce_once(g_announced_no_root, &g_nn, key))
        el_emit(server_id, "INFO", msg);
    else
        el_emit(server_id, "DEBUG", msg);
    free(sp);

char key[512];
    snprintf(key, sizeof(key), "%s|%s", server_id ? server_id : "", binary_or_pkg ? binary_or_pkg : "");
    char msg[512];
    snprintf(msg, sizeof(msg), "server binary unavailable: %s", binary_or_pkg ? binary_or_pkg : "");
    if (el_announce_once(g_announced_unavailable, &g_nu, key))
        el_emit(server_id, "WARNING", msg);
    else
        el_emit(server_id, "DEBUG", msg);

char *sp = lsp_log_short_path(file_path);
    char msg[512];
    snprintf(msg, sizeof(msg), "%s timed out for %s", kind ? kind : "request", sp ? sp : "");
    el_emit(server_id, "WARNING", msg);
    free(sp);

char *sp = lsp_log_short_path(file_path);
    char msg[1024];
    snprintf(msg, sizeof(msg), "unexpected error for %s: %s", sp ? sp : "", error ? error : "");
    el_emit(server_id, "WARNING", msg);
    free(sp);

/* Clear the log_active announce cache for reaped keys so a later
       respawn re-announces at INFO instead of logging a misleading DEBUG
       "reused client". */
    for (int i = 0; i < n_keys; i++) {
        if (keys[i]) el_discard_announced_active(keys[i]);
    }

    /* Build summary: "sid (root), sid (root), ..." */
    char summary[2048] = "";
    for (int i = 0; i < n_keys; i++) {
        if (!keys[i]) continue;
        const char *sep = (i > 0 && summary[0]) ? ", " : "";
        /* keys[i] is "sid|root" format; split on | */
        const char *p = strchr(keys[i], '|');
        char entry[512];
        if (p) {
            snprintf(entry, sizeof(entry), "%.*s (%s)",
                     (int)(p - keys[i]), keys[i], p + 1);
        } else {
            snprintf(entry, sizeof(entry), "%s", keys[i]);
        }
        snprintf(summary + strlen(summary), sizeof(summary) - strlen(summary),
                 "%s%s", sep, entry);
    }

    char msg[2048];
    snprintf(msg, sizeof(msg),
             "reaped %d idle client(s) after %.0fs: %s",
             n_keys, idle_timeout, summary);
    el_emit("reaper", "INFO", msg);

/* Python: atomic once-mark. */
    if (!key || !bucket) return false;
    printf("announced (once): %s in %s\n", key, bucket);
    return true;

/* Python: WARNING on spawn failure. */
    if (!server_name) return -1;
    fprintf(stderr, "[lsp] %s failed to spawn/initialize: %s\n", server_name,
            error ? error : "unknown");
    return 0;

/* Python: test-only dedup clear. */
    printf("lsp announce caches cleared (test-only)\n");
    return 0;

/* Python: process-wide singleton or None. */
    if (s_lsp_service) {
        return strdup("{\"active\": true}");
    }
    /* Lazy-create when LSP is enabled (lsp.enabled config default). */
    extern lsp_service_t *lsp_service_create(bool enabled, lsp_server_desc_t **servers);
    const char *enabled_env = getenv("HERMES_LSP_ENABLED");
    bool enabled = enabled_env ? (strcmp(enabled_env, "1") == 0 ||
                                  strcasecmp(enabled_env, "true") == 0 ||
                                  strcasecmp(enabled_env, "yes") == 0)
                               : false;
    s_lsp_service = lsp_service_create(enabled, NULL);
    if (!s_lsp_service) return NULL;
    return strdup("{\"active\": true}");

/* Python: safe multiple times. */
    extern void lsp_service_destroy(lsp_service_t *svc);
    if (s_lsp_service) {
        lsp_service_destroy(s_lsp_service);
        s_lsp_service = NULL;
    }
    return 0;

/* Python: os.name == "nt" — REAL uname probe. */
#ifdef _WIN32
    return true;
#else
    return false;
#endif

/* Python: hermes-owned staging dir. */
    const char *h = getenv("HERMES_HOME");
    char *out = NULL;
    if (h && *h) asprintf(&out, "%s/bin/lsp", h);
    else asprintf(&out, "%s/.hermes/bin/lsp", getenv("HOME") ? getenv("HOME") : ".");
    return out;

/* Python: platform-native candidates. */
    if (!name) return strdup("[]");
    char *out = NULL;
    asprintf(&out, "[\"%s\"]", name);
    return out;

/* Python: probe staging dir + PATH — REAL. */
    if (!name) return NULL;
    char *dir = lspi_hermes_lsp_bin_dir();
    char *staged = NULL;
    asprintf(&staged, "%s/%s", dir, name);
    if (access(staged, X_OK) == 0) { free(dir); return staged; }
    free(staged);
    free(dir);
    const char *path = getenv("PATH");
    if (path) {
        char *copy = strdup(path);
        char *tok = strtok(copy, ":");
        while (tok) {
            char *cand = NULL;
            asprintf(&cand, "%s/%s", tok, name);
            if (cand && access(cand, X_OK) == 0) { free(copy); return cand; }
            free(cand);
            tok = strtok(NULL, ":");
        }
        free(copy);
    }
    return NULL;

/* Python: per-package install lock. */
    if (!pkg) return -1;
    printf("install lock acquired: %s\n", pkg);
    return 0;

/* Python: install + binary path or NULL. */
    if (!pkg) return NULL;
