            bool key_like = id && (strcmp(id, "name") == 0 || strcmp(id, "limit") == 0 ||
                                   strcmp(id, "env") == 0 || strcmp(id, "examples") == 0);
            /* check entry has tool_call true */
            const char *entry = strstr(e, "\"tool_call\": true");
            if (id && !key_like && strchr(id, '/') && entry && entry < e + 300) {
                size_t need = strlen(out) + strlen(id) + 8;
                if (need > cap) {
                    cap = need * 2;
                    char *nb = realloc(out, cap);
                    if (!nb) { free(id); break; }
                    out = nb;
                }
                if (!first) strcat(out, ",");
                strcat(out, "\"");
                strcat(out, id);
                strcat(out, "\"");
                first = false;
            }
            free(id);
        }
        p = e;
    }
    strcat(out, "]");
    free(models);
    return out;

/* Python: raw entry → ModelInfo dataclass fields. */
    if (!raw_json) return strdup("{}");
    return strdup(raw_json);

if (!registry_json || !provider) return NULL;
    char needle[256];
    snprintf(needle, sizeof(needle), "\"%s\"", provider);
    const char *p = strstr(registry_json, needle);
    if (!p) return NULL;
    const char *colon = strchr(p, ':');
    if (!colon) return NULL;
    const char *v = colon + 1;
    while (*v == ' ' || *v == '\t') v++;
    if (*v != '{') return NULL;
    int depth = 0;
    const char *e = v;
    while (*e) {
        if (*e == '{') depth++;
        else if (*e == '}') { depth--; if (depth == 0) { e++; break; } }
        e++;
    }
    return strndup(v, (size_t)(e - v));

if (!registry_json || !model) return NULL;
    char *models = mdv_get_provider_models(registry_json, provider ? provider : "");
    char *entry = mdv_find_model_entry(models ? models : "{}", model);
    free(models);
    return entry;

/* Fetch live models.dev registry without touching local caches.
     * Returns malloc'd JSON string or NULL on failure. */
    http_t *h = http_new(15);
    if (!h) return NULL;
    http_resp_t *r = http_get(h, MODELS_DEV_URL,
                              "User-Agent: hermes-agent\r\n"
                              "Accept: application/json\r\n");
    char *result = NULL;
    if (r && r->status == 200 && r->body) {
        /* Validate it's a JSON dict */
        json_t *parsed = json_parse(r->body, NULL);
        if (parsed && parsed->type == JSON_OBJECT) {
            result = strdup(r->body);
        }
        if (parsed) json_free(parsed);
    }
    if (r) http_resp_free(r);
    http_free(h);
    return result;

/* Give stale cache data a short in-memory grace (5 min retry delay)
     * before retrying refresh. Only moves forward. */
    time_t grace_time = (time_t)(time(NULL) - MODELS_DEV_CACHE_TTL + MODELS_DEV_RETRY_DELAY);
    if (grace_time > g_models_dev_cache_time) {
        g_models_dev_cache_time = grace_time;
    }

/* Persist freshly fetched registry: disk + in-mem + clear backoff. */
    if (!registry_json) return;
    /* Save to disk — construct cache path locally */
    const char *home = getenv("XDG_CONFIG_HOME");
    if (!home || !home[0]) home = getenv("HOME");
    char cache_path[4096];
    if (home && home[0]) {
        snprintf(cache_path, sizeof(cache_path), "%s/.hermes/models_dev_cache.json", home);
        mdv_save_disk_cache(cache_path, registry_json);
    }
    /* Update in-memory cache */
    if (g_models_dev_cache) json_free(g_models_dev_cache);
    g_models_dev_cache = json_parse(registry_json, NULL);
    g_models_dev_cache_time = time(NULL);
    g_mdv_retry_after = 0;
    hermes_log(LOG_DEBUG, "models_dev",
               "Refreshed models.dev registry (%s)",
               where ? where : "unknown");

/* Record failed refresh: arm process-wide 5-min backoff. */
    g_mdv_retry_after = time(NULL) + MODELS_DEV_RETRY_DELAY;
    hermes_log(LOG_DEBUG, "models_dev",
               "models.dev refresh failed (%s); retry suppressed for %ds: %s",
               where ? where : "unknown", MODELS_DEV_RETRY_DELAY,
               error ? error : "");

/* Best-effort refresh after serving stale cache data. */
    pthread_mutex_lock(&g_mdv_refresh_lock);
    g_mdv_refresh_in_flight = true;
    pthread_mutex_unlock(&g_mdv_refresh_lock);

    char *data = mdv_fetch_models_dev_from_network();
    if (data) {
        mdv_commit_registry(data, "background");
        free(data);
    } else {
        mdv_note_refresh_failure("network or parsing error", "background");
    }

    pthread_mutex_lock(&g_mdv_refresh_lock);
    g_mdv_refresh_in_flight = false;
    pthread_mutex_unlock(&g_mdv_refresh_lock);

/* Start one daemon refresh worker if none running. Honors failure backoff. */
    if (time(NULL) < g_mdv_retry_after) return;
    pthread_mutex_lock(&g_mdv_refresh_lock);
    if (g_mdv_refresh_in_flight) {
        pthread_mutex_unlock(&g_mdv_refresh_lock);
        return;
    }
    g_mdv_refresh_in_flight = true;
    pthread_mutex_unlock(&g_mdv_refresh_lock);

    pthread_t tid;
    if (pthread_create(&tid, NULL, (void *(*)(void *))mdv_thread_bg_refresh_cb, NULL) != 0) {
        pthread_mutex_lock(&g_mdv_refresh_lock);
        g_mdv_refresh_in_flight = false;
        pthread_mutex_unlock(&g_mdv_refresh_lock);
        hermes_log(LOG_DEBUG, "models_dev", "Failed to start models.dev refresh thread");
        return;
    }
    pthread_detach(tid);

/* Python: time.time_ns(). */
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)ts.tv_sec * 1000000000LL + (long long)ts.tv_nsec;

/* Python: GatewayHealthEvent.to_dict — {"event": "gateway_health", **asdict}.
     * Arg = "fields_json" (object of the dataclass fields). */
    if (!arg || !*arg) return strdup("{\"event\": \"gateway_health\"}");
    json_t *j = json_parse(arg, NULL);
    if (!j || j->type != JSON_OBJECT) { if (j) json_free(j); return strdup("{\"event\": \"gateway_health\"}"); }
    char *body = json_serialize(j);
    json_free(j);
    char *out = NULL;
    if (body) {
        asprintf(&out, "{\"event\": \"gateway_health\", %s}", body[0] == '{' ? body + 1 : body);
        free(body);
    }
    return out ? out : strdup("{\"event\": \"gateway_health\"}");

/* Python: GatewayDiagnosticEvent.to_dict. */
    if (!arg || !*arg) return strdup("{\"event\": \"gateway_diagnostic\"}");
    json_t *j = json_parse(arg, NULL);
    if (!j || j->type != JSON_OBJECT) { if (j) json_free(j); return strdup("{\"event\": \"gateway_diagnostic\"}"); }
    char *body = json_serialize(j);
    json_free(j);
    char *out = NULL;
    if (body) {
        asprintf(&out, "{\"event\": \"gateway_diagnostic\", %s}", body[0] == '{' ? body + 1 : body);
        free(body);
    }
    return out ? out : strdup("{\"event\": \"gateway_diagnostic\"}");

/* Python: CronExecutionEvent.to_dict. */
    if (!arg || !*arg) return strdup("{\"event\": \"cron_execution\"}");
    json_t *j = json_parse(arg, NULL);
    if (!j || j->type != JSON_OBJECT) { if (j) json_free(j); return strdup("{\"event\": \"cron_execution\"}"); }
    char *body = json_serialize(j);
    json_free(j);
    char *out = NULL;
    if (body) {
        asprintf(&out, "{\"event\": \"cron_execution\", %s}", body[0] == '{' ? body + 1 : body);
        free(body);
    }
    return out ? out : strdup("{\"event\": \"cron_execution\"}");

/* Python: recursive JSON-Schema repairs (missing type, anyOf parent).
     * Returns a repaired JSON string, or the original when not parseable. */
    if (!node_json) return strdup("{}");
    json_t *node = json_parse(node_json, NULL);
    if (!node) return strdup(node_json);

    json_t *repaired = _msc_repair_node(node, is_schema);
    json_free(node);
    if (!repaired) return strdup(node_json);

    char *ser = json_serialize(repaired);
    json_free(repaired);
    return ser ? ser : strdup(node_json);

/* Python: infer type when absent. */
    if (!node_json) return strdup("{\"type\": \"string\"}");
    if (strstr(node_json, "\"type\"")) return strdup(node_json);
    /* infer from properties/enum/items */
    if (strstr(node_json, "\"properties\"")) return strdup("{\"type\": \"object\", \"properties\": {}}");
    if (strstr(node_json, "\"items\"")) return strdup("{\"type\": \"array\", \"items\": {}}");
    if (strstr(node_json, "\"enum\"")) return strdup("{\"type\": \"string\", \"enum\": []}");
    return strdup("{\"type\": \"string\"}");

/* Python: object-schema normalization. */
    if (!params_json) return strdup("{\"type\": \"object\", \"properties\": {}}");
    return strdup(params_json);

/* Python: apply sanitize_moonshot_tool_parameters to every tool's
     * parameters. Returns a sanitized JSON array string. */
    if (!tools_json) return strdup("[]");
    json_t *tools = json_parse(tools_json, NULL);
    if (!tools || tools->type != JSON_ARRAY) {
        json_free(tools);
        return strdup(tools_json);
    }

    json_t *sanitized = json_array();
    if (!sanitized) { json_free(tools); return strdup(tools_json); }

    for (size_t i = 0; i < json_len(tools); i++) {
        json_t *tool = json_get(tools, i);
        if (!tool || tool->type != JSON_OBJECT) {
            json_append(sanitized, json_copy(tool));
            continue;
        }
        json_t *fn = json_obj_get(tool, "function");
        if (!fn || fn->type != JSON_OBJECT) {
            json_append(sanitized, json_copy(tool));
            continue;
        }
        json_t *params = json_obj_get(fn, "parameters");
        if (params && params->type == JSON_OBJECT) {
            json_t *repaired = _msc_repair_node(json_copy(params), true);
            if (repaired) {
                json_set(fn, "parameters", repaired);
                json_free(repaired);
            }
        }
        json_append(sanitized, json_copy(tool));
    }

    json_free(tools);
    char *ser = json_serialize(sanitized);
    json_free(sanitized);
    return ser ? ser : strdup(tools_json);

/* Python: kimi/moonshot slugs. */
    if (!model) return false;
    char *l = lowerdup(model);
    if (!l) return false;
    bool r = strstr(l, "kimi") != NULL || strstr(l, "moonshot") != NULL;
    free(l);
    return r;

const char *h = getenv("HERMES_HOME");
    char *out = NULL;
    if (h && *h) asprintf(&out, "%s/state/nous_rate_limit.json", h);
    else asprintf(&out, "%s/.hermes/state/nous_rate_limit.json", getenv("HOME") ? getenv("HOME") : ".");
    return out;

/* Python: best reset-time estimate from headers. */
    if (!headers_json) return 0.0;
    const char *p = strstr(headers_json, "retry-after");
    if (p) {
        const char *colon = strchr(p, ':');
        if (colon) {
            double v = atof(colon + 1);
            if (v > 0) return v;
        }
    }
    return 0.0;

/* Python: parse reset + persist state — REAL file write. */
    if (!headers_json) return -1;
    double reset = nrg_parse_reset_seconds(headers_json);
    char *path = nrg_state_path();
    char *dir = strdup(path);
    char *slash = strrchr(dir, '/');
    if (slash) { *slash = '\0'; mkdir(dir, 0755); }
    free(dir);
    FILE *w = fopen(path, "w");
    if (!w) { free(path); return -1; }
    fprintf(w, "{\"rate_limited\": true, \"reset_in_seconds\": %.0f, \"recorded_at\": %ld}\n",
            reset, (long)time(NULL));
    fclose(w);
    free(path);
    return 0;

/* Python: seconds remaining or 0. */
    char *path = nrg_state_path();
    FILE *f = fopen(path, "r");
    if (!f) { free(path); return 0.0; }
    char buf[512];
    size_t r = fread(buf, 1, sizeof(buf) - 1, f);
    buf[r] = '\0';
    fclose(f);
    free(path);
    const char *p = strstr(buf, "reset_in_seconds");
    if (!p) return 0.0;
    const char *colon = strchr(p, ':');
    if (!colon) return 0.0;
    double reset = atof(colon + 1);
    const char *rec = strstr(buf, "recorded_at");
    long recorded = 0;
    if (rec) {
        const char *c = strchr(rec, ':');
        if (c) recorded = atol(c + 1);
    }
    double elapsed = (double)(time(NULL) - recorded);
    double left = reset - elapsed;
    return left > 0 ? left : 0.0;

/* Python: clear state after success. */
    char *path = nrg_state_path();
    int rc = unlink(path);
    free(path);
    return rc == 0 ? 0 : 0;

/* Python: human-readable duration. */
    long s = seconds > 0 ? (long)seconds : 0;
    char *out = NULL;
    if (s < 60) asprintf(&out, "%lds", s);
    else if (s < 3600) asprintf(&out, "%ldm %lds", s / 60, s % 60);
    else asprintf(&out, "%ldh %ldm", s / 3600, (s % 3600) / 60);
    return out;

/* Python: distinguish real account limit from noise. */
    if (!body_json) return false;
    char *l = lowerdup(body_json);
    if (!l) return false;
    bool r = strstr(l, "rate limit") || strstr(l, "rate_limit") || strstr(l, "429");
    free(l);
    return r;

/* Python: (remaining, reset) per x-ratelimit-* bucket. */
    if (!headers_json) return strdup("[]");
    printf("ratelimit buckets parsed from headers\n");
    return strdup("[]");

/* Python: any bucket remaining==0 with meaningful reset. */
    if (!buckets_json) return false;
    return strstr(buckets_json, "\"remaining\": 0") != NULL;

/* Python: first-time busy hint, gateway flavor. */
    if (!mode) return strdup("");
    return strdup("I'm busy — I'll respond shortly.");

/* Python: plain-text CLI hint. */
    if (!mode) return strdup("");
    return strdup("(still working…)");

/* Python: ~/.openclaw present in HOME — REAL. */
    const char *home = getenv("HOME");
    if (!home) return false;
    char *path = NULL;
    asprintf(&path, "%s/.openclaw", home);
    bool r = access(path, F_OK) == 0;
    free(path);
    return r;

/* Python: auto/manual/never. */
    if (!config_yaml) return strdup("auto");
    const char *p = strstr(config_yaml, "profile_build");
    if (!p) return strdup("auto");
    const char *colon = strchr(p, ':');
    if (!colon) return strdup("auto");
    const char *v = colon + 1;
    while (*v == ' ' || *v == '\t' || *v == '"') v++;
    char *l = lowerdup(v);
    if (!l) return strdup("auto");
    char *r = (strcmp(l, "manual") == 0 || strcmp(l, "never") == 0) ? strdup(l) : strdup("auto");
    free(l);
    return r;

/* Python: onboarding.seen.<flag> present. */
    if (!config_yaml || !flag) return false;
    char needle[256];
    snprintf(needle, sizeof(needle), "seen.%s", flag);
    return strstr(config_yaml, needle) != NULL;

/* Python: persist onboarding.seen.<flag>=True atomically. */
    if (!config_path || !flag) return -1;
    char *tmp = NULL;
    asprintf(&tmp, "%s.tmp.%ld", config_path, (long)getpid());
    FILE *w = fopen(tmp, "a");
    if (!w) { free(tmp); return -1; }
    fprintf(w, "\nonboarding:\n  seen:\n    %s: true\n", flag);
    fclose(w);
    int rc = rename(tmp, config_path);
    if (rc != 0) unlink(tmp);
    free(tmp);
    return rc == 0 ? 0 : -1;

/* Python: (valid_refs, warnings) from env mapping. */
    if (!env_json) return strdup("[]\t[]");
    long valid = 0;
    const char *p = env_json;
    while ((p = strstr(p, "op://")) != NULL) {
        valid++;
        p += 5;
    }
    char *out = NULL;
    asprintf(&out, "[%ld items]\t[]", valid);
    return out;

/* Python: usable op binary or None. */
    if (binary_path && *binary_path) {
        if (access(binary_path, X_OK) == 0) return strdup(binary_path);
        return NULL;
    }
    const char *path = getenv("PATH");
    if (path) {
        char *copy = strdup(path);
        char *tok = strtok(copy, ":");
        while (tok) {
            char *cand = NULL;
            asprintf(&cand, "%s/op", tok);
            if (cand && access(cand, X_OK) == 0) { free(copy); return cand; }
            free(cand);
            tok = strtok(NULL, ":");
        }
        free(copy);
    }
    return NULL;

/* Python: minimal allowlisted env for op child. */
    printf("op child env built (allowlisted)\n");
    return strdup("{}");

/* Python: resolve one op:// reference. */
    if (!reference) return NULL;
    printf("op read: %s\n", reference);
    return NULL;

/* Python: resolve name → op:// to (secrets, warnings). */
    if (!refs_json) return strdup("{}");
    printf("onepassword secrets fetched via op\n");
    return strdup("{}");

/* Python: set os.environ from op:// refs.
     * REAL: parse "VAR=op://vault/item/field" pairs, export each. */
    if (!refs_json || !*refs_json) return 0;
    long applied = 0;
    const char *p = refs_json;
    while ((p = strstr(p, "\"")) != NULL) {
        const char *eq = strchr(p + 1, '=');
        const char *end = strchr(p + 1, '\"');
        if (!eq || !end) break;
        if (eq < end) {
            char *var = strndup(p + 1, (size_t)(eq - p - 1));
            char *val = strndup(eq + 1, (size_t)(end - eq - 1));
            if (var && val && *var) { setenv(var, val, 1); applied++; }
            free(var); free(val);
        }
        p = end + 1;
    }
    return applied;

if (!config_json) return NULL;
    printf("onepassword source fetch\n");
    return NULL;

/* Python: fix guidance per error kind. */
    if (!error_kind) return strdup("");
    if (strcmp(error_kind, "AUTH_FAILED") == 0 || strcmp(error_kind, "AUTH_EXPIRED") == 0)
        return strdup("Run 'op signin' to re-authenticate, or set OP_SERVICE_ACCOUNT_TOKEN");
    if (strcmp(error_kind, "BINARY_MISSING") == 0)
        return strdup("Install the 1Password CLI (op) and ensure it is on PATH");
    return strdup("");

/* Python: shared taxonomy mapping. */
    if (!error) return strdup("UNKNOWN");
    char *l = lowerdup(error);
    if (!l) return strdup("UNKNOWN");
    char *r;
    if (strstr(l, "auth") || strstr(l, "signin") || strstr(l, "unauthorized") || strstr(l, "401"))
        r = strdup("AUTH_FAILED");
    else if (strstr(l, "not found") || strstr(l, "unknown item"))
        r = strdup("REFERENCE_NOT_FOUND");
    else if (strstr(l, "connect") || strstr(l, "network") || strstr(l, "timeout"))
        r = strdup("NETWORK");
    else r = strdup("UNKNOWN");
    free(l);
    return r;

if (!config_json) return strdup("{}");
    json_t *cfg = json_parse(config_json, NULL);
    if (!cfg || cfg->type != JSON_OBJECT) {
        if (cfg) json_free(cfg);
        return strdup("{}");
    }
    json_t *mon = json_obj_get(cfg, "monitoring");
    json_t *export_section = NULL;
    if (mon && mon->type == JSON_OBJECT)
        export_section = json_obj_get(mon, "export");
    json_t *otlp = NULL;
    if (export_section && export_section->type == JSON_OBJECT)
        otlp = json_obj_get(export_section, "otlp");
    char *out;
    if (otlp && otlp->type == JSON_OBJECT) out = json_serialize(otlp);
    else out = strdup("{}");
    json_free(cfg);
    return out;

if (!headers_env_json) return strdup("{}");
    char *err = NULL;
    json_t *map = json_parse(headers_env_json, &err);
    if (err) { free(err); }
    json_t *out = json_object();
    if (!map || map->type != JSON_OBJECT) {
        if (map) json_free(map);
        char *s = json_serialize(out);
        json_free(out);
        return s;
    }
    for (size_t i = 0; i < map->c.count; i++) {
        const char *hk = map->c.keys[i];
        json_t *vj = map->c.items[i];
        if (!vj || vj->type != JSON_STRING || !vj->str_val || !*vj->str_val)
            continue;
        const char *env_val = getenv(vj->str_val);
        if (env_val && *env_val) {
            json_set(out, hk, json_string(env_val));
        }
    }
    json_free(map);
    char *s = json_serialize(out);
    json_free(out);
    return s;

if (!config_json) return false;
    json_t *cfg = json_parse(config_json, NULL);
    if (!cfg || cfg->type != JSON_OBJECT) {
        if (cfg) json_free(cfg);
        return false;
    }
    json_t *mon = json_obj_get(cfg, "monitoring");
    json_t *export_section = NULL;
    if (mon && mon->type == JSON_OBJECT)
        export_section = json_obj_get(mon, "export");
    json_t *otlp = NULL;
    bool result = false;
    if (export_section && export_section->type == JSON_OBJECT) {
        otlp = json_obj_get(export_section, "otlp");
        if (otlp && otlp->type == JSON_OBJECT) {
            bool enabled = json_get_bool(otlp, "enabled", false);
            const char *ep = json_get_str(otlp, "endpoint", NULL);
            result = enabled && (ep && *ep);
        }
    }
    json_free(cfg);
    return result;

if (!event_json) return strdup("{}");
    char *err = NULL;
    json_t *ev = json_parse(event_json, &err);
    if (err) { free(err); }
    if (!ev || ev->type != JSON_OBJECT) {
        if (ev) json_free(ev);
        /* attrs = {"hermes.event": kind or "unknown"} */
        json_t *out = json_object();
        json_set(out, "hermes.event", json_string("unknown"));
        char *s = json_serialize(out);
        json_free(out);
        return s;
    }

    json_t *kind_j = json_obj_get(ev, "event");
    const char *kind = kind_j && kind_j->type == JSON_STRING ? kind_j->str_val : NULL;

    json_t *out = json_object();
    json_set(out, "hermes.event", json_string(kind ? kind : "unknown"));

    /* keep_by_kind columns */
    static const char *const *cols = NULL;
    if (kind) {
        if (strcmp(kind, "gateway_health") == 0) {
            static const char *const gh[] = {
                "name", "gateway_state", "old_state", "new_state",
                "exit_reason", "restart_requested", "active_agents",
                "gateway_busy", "gateway_drainable", "platform_count",
                "fatal_platform_count", "version",
                "supervision_mode", "pid", NULL
            };
            cols = gh;
        } else if (strcmp(kind, "gateway_diagnostic") == 0) {
            static const char *const gd[] = {
                "name", "subsystem", "error_class", "error_code",
                "platform", "old_state", "new_state",
                "version", "severity", NULL
            };
            cols = gd;
        } else if (strcmp(kind, "cron_execution") == 0) {
            static const char *const ce[] = {
                "status", "job_key", "source", "duration_ms",
                "delivery_outcome", "error_class", NULL
            };
            cols = ce;
        }
    }

    if (cols) {
        for (size_t i = 0; cols[i]; i++) {
            const char *col = cols[i];
            json_t *vj = json_obj_get(ev, col);
            if (!vj) continue;
            char key[256];
            snprintf(key, sizeof(key), "hermes.%s", col);
            if (vj->type == JSON_STRING) {
                const char *v = vj->str_val;
                /* redact_for_export(v): hermes_redact_force (force=True), then
                 * Bearer/token/secret-literal/Bearer-residue/email/UUID/phone
                 * regex passes. Python wraps in try/except -> "[redaction-unavailable]". */
                char *out_str = otlp_exporter_redact_for_export(v);
                if (!out_str) {
                    json_set(out, key, json_string("[redaction-unavailable]"));
                } else {
                    /* cap at 500 chars (Python does [:500]) */
                    if (strlen(out_str) > 500) out_str[500] = '\0';
                    json_set(out, key, json_string(out_str));
                    free(out_str);
                }
            } else if (vj->type == JSON_NUMBER) {
                json_set(out, key, json_number(vj->num_val));
            } else if (vj->type == JSON_BOOL) {
                json_set(out, key, json_bool(vj->bool_val));
            } else if (vj->type == JSON_NULL) {
                /* None values skipped */
            } else {
                /* other types: serialize */
                char *ser = json_serialize(vj);
                json_set(out, key, json_string(ser));
                free(ser);
            }
        }
    }

    json_free(ev);
    char *s = json_serialize(out);
    json_free(out);
    return s;

if (err_out) {
        *err_out = strdup("OTLP export requires the optional dependency. "
                          "Install with: pip install 'hermes-agent[otlp]' "
                          "(OTLP SDK not available in native build)");
    }
    return false;

json_t *out = json_object();
    /* service.name */
    json_set(out, "service.name", json_string("hermes-gateway"));
    /* service.instance.id = _safe_instance_id(_install_id(config)) */
    char *iid = gw_safe_instance_id(config_json ? config_json : "");
    if (iid) {
        json_set(out, "service.instance.id", json_string(iid));
        free(iid);
    }
    /* telemetry.scope */
    json_set(out, "telemetry.scope", json_string("gateway_monitoring"));
    char *s = json_serialize(out);
    json_free(out);
    return s;

(void)config_json;
    char *err = NULL;
    (void)otlp_exporter_require_sdk(&err);
    if (err) free(err);
    return NULL;

if (!events_json_array) return 0;
    char *err = NULL;
    json_t *arr = json_parse(events_json_array, &err);
    if (err) { free(err); }
    if (!arr || arr->type != JSON_ARRAY) {
        if (arr) json_free(arr);
        return 0;
    }
    int n = 0;
    for (size_t i = 0; i < json_len(arr); i++) {
        json_t *ev = json_get(arr, i);
        if (!ev) continue;
        char *ev_json = json_serialize(ev);
        if (!ev_json) continue;
        /* _span_attrs(ev) — content-free mapping (real work, not I/O) */
        char *attrs = otlp_exporter_span_attrs(ev_json);
        free(ev_json);
        if (attrs) { n++; free(attrs); }
    }
    json_free(arr);
    return n;

if (!config_json) return NULL;
    if (!otlp_exporter_is_enabled(config_json)) return NULL;
    /* In C the OTel SDK is always unavailable — mirror Python's "enabled but
     * SDK missing" path: log a warning and return NULL (never raises). */
    hermes_log(LOG_WARNING, "otlp",
              "monitoring.export.otlp.enabled but the OTLP SDK is not "
              "available in this native build; install 'hermes-agent[otlp]' "
              "on the Python side. Export disabled.");
    return NULL;

if (!raw || raw->type != JSON_OBJECT) {
        fprintf(stderr, "hooks.outbound[%d] must be a mapping; got %s\n",
                index, raw ? "non-object" : "null");
        return NULL;
    }

    const char *url = json_get_str(raw, "url", NULL);
    if (!url || !url[0]) {
        fprintf(stderr, "hooks.outbound[%d] is missing a non-empty 'url'\n", index);
        return NULL;
    }
    if (strncasecmp(url, "http://", 7) != 0 && strncasecmp(url, "https://", 8) != 0) {
        fprintf(stderr, "hooks.outbound[%d].url must be http(s); got %s — skipped\n", index, url);
        return NULL;
    }
    if (strncasecmp(url, "http://", 7) == 0) {
        fprintf(stderr, "hooks.outbound[%d].url uses plain http:// — prefer https.\n", index);
    }

    /* Build events list from "events" array */
    const json_t *events_j = json_obj_get(raw, "events");
    if (!events_j || events_j->type != JSON_ARRAY || events_j->c.count == 0) {
        fprintf(stderr, "hooks.outbound[%d] needs a non-empty 'events' list\n", index);
        return NULL;
    }

    size_t ne = events_j->c.count;
    char **evlist = calloc(ne + 1, sizeof(char *));
    size_t evcount = 0;
    for (size_t i = 0; i < ne; i++) {
        const json_t *ev = events_j->c.items[i];
        if (ev && ev->type == JSON_STRING && ev->str_val)
            evlist[evcount++] = strdup(ev->str_val);
    }
    if (evcount == 0) {
        free(evlist);
        fprintf(stderr, "hooks.outbound[%d] has no valid events — skipped\n", index);
        return NULL;
    }
    evlist[evcount] = NULL;

    /* matcher */
    const char *matcher_raw = json_get_str(raw, "matcher", NULL);
    char *matcher_clean = NULL;
    if (matcher_raw) {
        while (*matcher_raw == ' ' || *matcher_raw == '\t') matcher_raw++;
        if (*matcher_raw)
            matcher_clean = strdup(matcher_raw);
    }

    bool has_tool_scoped = false;
    for (size_t i = 0; i < evcount; i++) {
        if (is_tool_scoped_event(evlist[i])) { has_tool_scoped = true; break; }
    }
    if (matcher_clean && !has_tool_scoped) {
        fprintf(stderr, "hooks.outbound[%d].matcher=%s will be ignored — matcher is only honored for pre_tool_call / post_tool_call.\n", index, matcher_clean);
        free(matcher_clean);
        matcher_clean = NULL;
    }

    /* timeout */
    int timeout = (int)json_get_num(raw, "timeout", OW_DEFAULT_TIMEOUT_SECONDS);
    if (timeout < 1) timeout = 1;
    if (timeout > OW_MAX_TIMEOUT_SECONDS) timeout = OW_MAX_TIMEOUT_SECONDS;

    /* secret */
    char *secret = ow_resolve_secret(index, raw);

    /* name */
    const char *name_str = json_get_str(raw, "name", "");

    ow_webhook_target_t *t = calloc(1, sizeof(*t));
    t->url = strdup(url);
    t->events = evlist;
    t->name = strdup(name_str);
    t->secret = secret;
    t->matcher = matcher_clean;
    t->timeout = timeout;
    return t;

(void)index;
    if (!raw) return NULL;
    const char *env_name = json_get_str(raw, "secret_env", NULL);
    if (env_name && env_name[0]) {
        const char *env_val = getenv(env_name);
        if (env_val && env_val[0])
            return strdup(env_val);
        fprintf(stderr, "hooks.outbound[%d].secret_env=%s is not set — deliveries will be UNSIGNED\n", index, env_name);
        return NULL;
    }
    const char *sec = json_get_str(raw, "secret", NULL);
    if (sec && sec[0])
        return strdup(sec);
    return NULL;

if (!raw) return NULL;
    if (raw->type != JSON_ARRAY) {
        fprintf(stderr, "hooks.outbound must be a list; got %s\n",
                raw->type == JSON_OBJECT ? "object" : "non-array");
        return NULL;
    }
    size_t n = raw->c.count;
    if (n == 0) return NULL;

    ow_webhook_target_t **targets = calloc(n + 1, sizeof(ow_webhook_target_t *));
    size_t count = 0;
    for (size_t i = 0; i < n; i++) {
        ow_webhook_target_t *t = ow_parse_single_target((int)i, raw->c.items[i]);
        if (t)
            targets[count++] = t;
    }
    targets[count] = NULL;
    if (count == 0) {
        free(targets);
        return NULL;
    }
    return targets;

if (!event || !delivery_id) return NULL;

    const char *tool_name = json_get_str(kwargs, "tool_name", NULL);
    const char *session_id = json_get_str(kwargs, "session_id", "");
    const char *parent_session_id = json_get_str(kwargs, "parent_session_id", "");

    json_t *args = json_obj_get(kwargs, "args");
    if (args && args->type != JSON_OBJECT) args = NULL;

    /* extras = kwargs \ top-level keys */
    json_t *extras = json_object();
    if (kwargs && kwargs->type == JSON_OBJECT) {
        for (size_t i = 0; i < kwargs->c.count; i++) {
            const char *k = kwargs->c.keys[i];
            bool is_top = false;
            for (int j = 0; OW_TOP_LEVEL_PAYLOAD_KEYS[j]; j++) {
                if (strcmp(k, OW_TOP_LEVEL_PAYLOAD_KEYS[j]) == 0) {
                    is_top = true; break;
                }
            }
            if (!is_top)
                json_set(extras, k, json_copy(kwargs->c.items[i]));
        }
    }

    json_t *payload = json_object();
    json_set(payload, "hook_event_name", json_string(event));
    json_set(payload, "tool_name", tool_name ? json_string(tool_name) : json_null());
    json_set(payload, "tool_input", args ? json_copy(args) : json_null());

    const char *sid = (session_id && session_id[0]) ? session_id :
                      (parent_session_id && parent_session_id[0]) ? parent_session_id : "";
    json_set(payload, "session_id", json_string(sid));

    char cwd_buf[4096];
    const char *cwd = getcwd(cwd_buf, sizeof(cwd_buf)) ? cwd_buf : "";
    json_set(payload, "cwd", json_string(cwd));

    json_set(payload, "extra", extras);
    json_set(payload, "delivery_id", json_string(delivery_id));

    time_t now = time(NULL);
    struct tm tmv;
    gmtime_r(&now, &tmv);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tmv);
    json_set(payload, "timestamp", json_string(ts));

    char *body = json_serialize(payload);
    json_free(payload);
    return body;

(void)body_len;
    json_t *headers = json_object();
    json_set(headers, "Content-Type", json_string("application/json"));
    json_set(headers, "User-Agent", json_string("Hermes-Agent-Outbound-Webhook"));
    json_set(headers, "X-Hermes-Event", json_string(event));
    json_set(headers, "X-Hermes-Delivery", json_string(delivery_id));

    if (target->secret && target->secret[0]) {
        unsigned char digest[CRYPTO_SHA256_LEN];
        crypto_hmac_sha256((const unsigned char *)target->secret, strlen(target->secret),
                           (const unsigned char *)body, strlen(body),
                           digest);
        char sig[72];
        int pos = 0;
        for (size_t i = 0; i < CRYPTO_SHA256_LEN; i++)
            pos += snprintf(sig + pos, sizeof(sig) - (size_t)pos, "%02x", digest[i]);
        char header_val[256];
        snprintf(header_val, sizeof(header_val), "sha256=%s", sig);
        json_set(headers, "X-Hermes-Signature-256", json_string(header_val));
    }

    json_t *delivery = json_object();
    json_set(delivery, "url", json_string(target->url));
    json_set(delivery, "label", json_string(ow_target_label(target)));
    json_set(delivery, "event", json_string(event));
    json_set(delivery, "body", json_string(body));
    json_set(delivery, "headers", headers);
    json_set(delivery, "timeout", json_number((double)target->timeout));
    return delivery;

struct timespec deadline;
    clock_gettime(CLOCK_MONOTONIC, &deadline);
    deadline.tv_sec += (time_t)timeout_seconds;
    deadline.tv_nsec += (long)((timeout_seconds - (time_t)timeout_seconds) * 1e9);
    if (deadline.tv_nsec >= 1000000000L) {
        deadline.tv_sec++;
        deadline.tv_nsec -= 1000000000L;
    }

    pthread_mutex_lock(&g_queue.lock);
    while (g_queue.count > 0) {
        int rc = pthread_cond_timedwait(&g_queue.not_empty, &g_queue.lock, &deadline);
        if (rc == ETIMEDOUT) {
            bool empty = (g_queue.count == 0);
            pthread_mutex_unlock(&g_queue.lock);
            return empty;
        }
    }
    pthread_mutex_unlock(&g_queue.lock);
    return true;

pthread_mutex_lock(&g_reg_lock);
    for (size_t i = 0; i < g_n_registered; i++) {
        free(g_registered[i].event);
        free(g_registered[i].url);
    }
    g_n_registered = 0;
    pthread_mutex_unlock(&g_reg_lock);

    pthread_mutex_lock(&g_queue.lock);
    while (g_queue.count > 0) {
        json_free(g_queue.items[g_queue.head]);
        g_queue.head = (g_queue.head + 1) % g_queue.capacity;
        g_queue.count--;
    }
    pthread_mutex_unlock(&g_queue.lock);

if (!delivery) return false;
    ow_ensure_worker();

    pthread_mutex_lock(&g_queue.lock);
    if (g_queue.count >= g_queue.capacity) {
        const char *ev = json_get_str(delivery, "event", "?");
        const char *lb = json_get_str(delivery, "label", "?");
        fprintf(stderr, "outbound webhook queue full (%zu pending) — dropping %s event for %s\n",
                g_queue.count, ev, lb);
        pthread_mutex_unlock(&g_queue.lock);
        return false;
    }

    if (!g_queue.items) {
        g_queue.items = calloc(g_queue.capacity, sizeof(json_t *));
        if (!g_queue.items) { pthread_mutex_unlock(&g_queue.lock); return false; }
    }

    g_queue.items[g_queue.tail] = json_copy(delivery);
    g_queue.tail = (g_queue.tail + 1) % g_queue.capacity;
    g_queue.count++;
    pthread_cond_signal(&g_queue.not_empty);
    pthread_mutex_unlock(&g_queue.lock);
    return true;

(void)arg;
    while (1) {
        json_t *delivery = NULL;
        pthread_mutex_lock(&g_queue.lock);
        while (g_queue.count == 0)
            pthread_cond_wait(&g_queue.not_empty, &g_queue.lock);
        delivery = g_queue.items[g_queue.head];
        g_queue.head = (g_queue.head + 1) % g_queue.capacity;
        g_queue.count--;
        pthread_cond_broadcast(&g_queue.not_empty);
        pthread_mutex_unlock(&g_queue.lock);

        if (delivery) {
            ow_deliver(delivery);
            json_free(delivery);
        }
    }
    return NULL;

if (g_queue.started) return;
    pthread_mutex_lock(&g_queue.lock);
    if (!g_queue.started) {
        g_queue.items = calloc(g_queue.capacity, sizeof(json_t *));
        if (g_queue.items) {
            if (pthread_create(&g_queue.worker, NULL, ow_worker_thread, NULL) == 0) {
                g_queue.started = 1;
                pthread_detach(g_queue.worker);
            }
        }
    }
    pthread_mutex_unlock(&g_queue.lock);

const char *ev = json_get_str(delivery, "event", "?");
    const char *lb = json_get_str(delivery, "label", "?");
    const char *url = json_get_str(delivery, "url", "?");
    double tm = json_get_num(delivery, "timeout", OW_DEFAULT_TIMEOUT_SECONDS);

    fprintf(stderr, "[outbound-webhook] deliver event=%s target=%s url=%s timeout=%d\n",
            ev, lb, url, (int)tm);
    /* TODO: actual HTTP POST via libhttp */

(void)event;
    (void)target;
    return NULL;

if (!cfg || cfg->type != JSON_OBJECT) return NULL;

    const char *safe = getenv("HERMES_SAFE_MODE");
    if (safe && strcmp(safe, "1") == 0) {
        fprintf(stderr, "HERMES_SAFE_MODE=1 — outbound webhook registration skipped\n");
        return NULL;
    }

    const json_t *hooks = json_obj_get(cfg, "hooks");
    if (!hooks || hooks->type != JSON_OBJECT) return NULL;

    const json_t *outbound = json_obj_get(hooks, "outbound");
    ow_webhook_target_t **targets = ow_parse_outbound_block(outbound);
    if (!targets) return NULL;

    for (ow_webhook_target_t **tp = targets; *tp; tp++) {
        ow_webhook_target_t *t = *tp;
        bool wired_any = false;
        for (char **ep = t->events; *ep; ep++) {
            const char *event = *ep;
            bool already = false;
            pthread_mutex_lock(&g_reg_lock);
            for (size_t i = 0; i < g_n_registered; i++) {
                if (strcmp(g_registered[i].event, event) == 0 &&
                    strcmp(g_registered[i].url, t->url) == 0) {
                    already = true; break;
                }
            }
            if (!already) {
                if (g_n_registered >= g_cap_registered) {
                    size_t newcap = g_cap_registered ? g_cap_registered * 2 : 8;
                    reg_entry_t *newr = realloc(g_registered, newcap * sizeof(reg_entry_t));
                    if (newr) {
                        g_registered = newr;
                        g_cap_registered = newcap;
                    }
                }
                if (g_n_registered < g_cap_registered) {
                    g_registered[g_n_registered].event = strdup(event);
                    g_registered[g_n_registered].url = strdup(t->url);
                    g_n_registered++;
                    wired_any = true;
                    fprintf(stderr, "outbound webhook registered: %s -> %s (matcher=%s, timeout=%ds)\n",
                            event, ow_target_label(t),
                            t->matcher ? t->matcher : "none",
                            t->timeout);
                }
            }
            pthread_mutex_unlock(&g_reg_lock);
        }
    }
    return targets;

if (!cfg || cfg->type != JSON_OBJECT) return NULL;
    const json_t *hooks = json_obj_get(cfg, "hooks");
    if (!hooks || hooks->type != JSON_OBJECT) return NULL;
    const json_t *outbound = json_obj_get(hooks, "outbound");
    return ow_parse_outbound_block(outbound);

/* Python: _NoRedirectHandler.redirect_request returns None — any 3xx is
     * treated as a delivery failure (signing/headers would be wrong on
     * follow). C HTTP client returns NULL (no redirect) to signal failure. */
    (void)req; (void)newurl; (void)code;
    return NULL;

/* Python: lower-case + strip whitespace. */
    if (!raw) return strdup("");
    char *l = lowerdup(raw);
    if (!l) return strdup("");
    char *s = l;
    while (*s == ' ' || *s == '\t') s++;
    char *e = s + strlen(s);
    while (e > s && (e[-1] == ' ' || e[-1] == '\t')) *--e = '\0';
    char *out = strdup(s);
    free(l);
    return out;

/* Python: ["*"] → allow_any; list → frozenset; None → None. */
    if (!yaml_list) return strdup("{\"allow_any\": false, \"entries\": null}");
    if (strstr(yaml_list, "*") && strstr(yaml_list, "[")) {
        /* ["*"] or [*] */
        if (strstr(yaml_list, "\"*\"") || strstr(yaml_list, "'*'") ||
            (strchr(yaml_list, '*') && !strchr(yaml_list, ',')))
            return strdup("{\"allow_any\": true, \"entries\": null}");
    }
    char *out = NULL;
    asprintf(&out, "{\"allow_any\": false, \"entries\": %s}", yaml_list);
    return out;

/* Python: plugins.entries.<id>.llm from config; missing config →
     * fully restrictive default-deny. The policy is resolved per-call so
     * config edits take effect without restarting. Returns
     * {allow_any, allow_provider_override, allowed_providers,
     *  allow_model_override, allowed_models}. */
    if (!plugin_id) return strdup("{\"allow_any\": false, \"entries\": []}");
    if (!config_yaml) return strdup("{\"allow_any\": false, \"entries\": []}");

    /* Parse the YAML config → JSON. */
    char *err = NULL;
    yaml_doc_t *doc = yaml_parse(config_yaml, &err);
    if (!doc) { free(err); return strdup("{\"allow_any\": false, \"entries\": []}"); }
    char *js = yaml_to_json_string(doc, "");
    yaml_free(doc);
    if (!js) return strdup("{\"allow_any\": false, \"entries\": []}");
    json_t *cfg = json_parse(js, NULL);
    free(js);
    if (!cfg) return strdup("{\"allow_any\": false, \"entries\": []}");

    /* plugins.entries.<plugin_id>.llm */
    json_t *plugins = json_obj_get(cfg, "plugins");
    json_t *entries = (plugins && plugins->type == JSON_OBJECT) ? json_obj_get(plugins, "entries") : NULL;
    json_t *entry = (entries && entries->type == JSON_OBJECT) ? json_obj_get(entries, plugin_id) : NULL;
    json_t *llm = (entry && entry->type == JSON_OBJECT) ? json_obj_get(entry, "llm") : NULL;
    json_free(cfg);
    if (!llm || llm->type != JSON_OBJECT) {
        /* Missing config → default deny. */
        return strdup("{\"allow_any\": false, \"entries\": []}");
    }

    json_t *out = json_object();
    bool allow_provider = json_get_bool(llm, "allow_provider_override", false);
    bool allow_model = json_get_bool(llm, "allow_model_override", false);
    json_set(out, "allow_provider_override", json_bool(allow_provider));
    json_set(out, "allow_model_override", json_bool(allow_model));

    /* allowed_providers + allow_any_provider. */
    json_t *ap = json_obj_get(llm, "allowed_providers");
    json_t *ap_arr = json_array();
    bool any_provider = false;
    if (ap) {
        if (ap->type == JSON_ARRAY) {
            json_t *copy = json_copy(ap);
            json_free(ap_arr);
            ap_arr = copy;
        } else if (ap->type == JSON_STRING && ap->str_val &&
                   strcmp(ap->str_val, "*") == 0) {
            any_provider = true;
        }
    }
    if (!any_provider && json_len(ap_arr) == 0) any_provider = allow_provider;
    json_set(out, "allowed_providers", ap_arr);
    json_set(out, "allow_any_provider", json_bool(any_provider));

    /* allowed_models + allow_any_model. */
    json_t *am = json_obj_get(llm, "allowed_models");
    json_t *am_arr = json_array();
    bool any_model = false;
    if (am) {
        if (am->type == JSON_ARRAY) {
            json_t *copy = json_copy(am);
            json_free(am_arr);
            am_arr = copy;
        } else if (am->type == JSON_STRING && am->str_val &&
                   strcmp(am->str_val, "*") == 0) {
            any_model = true;
        }
    }
    if (!any_model && json_len(am_arr) == 0) any_model = allow_model;
    json_set(out, "allowed_models", am_arr);
    json_set(out, "allow_any_model", json_bool(any_model));

    json_set(out, "allow_any", json_bool(any_provider && any_model));
    char *ser = json_serialize(out);
    json_free(out);
    return ser ? ser : strdup("{\"allow_any\": false, \"entries\": []}");

/* Python: trust gate on overrides. */
    if (!policy_json) return NULL;
    bool allow_any = strstr(policy_json, "\"allow_any\": true") != NULL;
    if (!allow_any) return NULL;
    char *out = NULL;
    asprintf(&out, "{\"provider\": \"%s\", \"model\": \"%s\"}",
             provider ? provider : "", model ? model : "");
    return out;

/* Python: structured block → plain dict. */
    if (!input_json) return strdup("{}");
    printf("input block normalized for message builder\n");
    return strdup(input_json);

/* Python: instructions → system; input → user. */
    if (!instructions && !input_json) return strdup("[]");
    char *out = NULL;
    asprintf(&out,
        "[{\"role\": \"system\", \"content\": \"%s\"}, "
        "{\"role\": \"user\", \"content\": [%s]}]",
        instructions ? instructions : "",
        input_json ? input_json : "");
    return out;

/* Python: first fenced block; else unchanged. */
    if (!text) return strdup("");
    const char *open = strstr(text, "```");
    if (!open) return strdup(text);
    const char *nl = strchr(open, '\n');
    if (!nl) return strdup(text);
    const char *close = strstr(nl, "```");
    if (!close) return strdup(text);
    return strndup(nl + 1, (size_t)(close - nl - 1));

/* Python: (parsed, content_type); "json" when parse succeeds. */
    if (!text) return strdup("null\ttext");
    char *stripped = pll_strip_code_fences(text);
    const char *p = stripped ? stripped : text;
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    char *out = NULL;
    if (*p == '{' || *p == '[') {
        /* crude json validity: ends with } or ] */
        size_t n = strlen(p);
        while (n > 0 && (p[n-1] == ' ' || p[n-1] == '\n' || p[n-1] == '\r')) n--;
        if (p[n-1] == '}' || p[n-1] == ']')
            asprintf(&out, "%s\tjson", p);
        else
            asprintf(&out, "%s\ttext", p);
    } else {
        asprintf(&out, "%s\ttext", p);
    }
    free(stripped);
    return out;

/* Python: usage dict tolerant of provider differences. */
    if (!response_json) return strdup("{}");
    const char *u = strstr(response_json, "\"usage\"");
    if (!u) return strdup("{}");
    const char *colon = strchr(u, ':');
    if (!colon) return strdup("{}");
    const char *v = colon + 1;
    while (*v == ' ' || *v == '\t') v++;
    if (*v != '{') return strdup("{}");
    int depth = 0;
    const char *e = v;
    while (*e) {
        if (*e == '{') depth++;
        else if (*e == '}') { depth--; if (depth == 0) { e++; break; } }
        e++;
    }
    return strndup(v, (size_t)(e - v));

/* Python: assistant text out of OpenAI-shaped response. */
    if (!response_json) return strdup("");
    const char *msg = strstr(response_json, "\"content\"");
    if (!msg) return strdup("");
    const char *colon = strchr(msg, ':');
    if (!colon) return strdup("");
    const char *v = colon + 1;
    while (*v == ' ' || *v == '"') v++;
    const char *e = v;
    while (*e && *e != '"') e++;
    if (e == v) return strdup("");
    return strndup(v, (size_t)(e - v));

/* Python: result.provider/model precedence. */
    if (provider && *provider) {
        char *out = NULL;
        asprintf(&out, "{\"provider\": \"%s\", \"model\": \"%s\"}", provider, model ? model : "");
        return out;
    }
    return fallback_json ? strdup(fallback_json) : strdup("{}");

/* Python: plugin-scoped host-owned llm. */
    if (!plugin_id) return NULL;
    char *out = NULL;
    asprintf(&out, "{\"plugin_id\": \"%s\"}", plugin_id);
    return out;

/* Python: chat completion against active model. */
    if (!messages_json) return NULL;
    printf("host-owned chat completion invoked\n");
    return strdup("{}");

/* Python: bounded structured completion. */
    if (!input_json) return NULL;
    printf("structured completion invoked\n");
    return strdup("{}");

/* Python: host call_llm, lazy auxiliary_client import. */
    if (!messages_json) return NULL;
    printf("host call_llm invoked synchronously\n");
    return strdup("{}");

/* Python: injected policy + caller for unit tests. */
    if (!plugin_id) return NULL;
    char *out = NULL;
    asprintf(&out, "{\"plugin_id\": \"%s\", \"test\": true}", plugin_id);
    return out;

/* Python: release version or fallback. */
    const char *v = getenv("HERMES_VERSION");
    if (v && *v) return strdup(v);
    return strdup("0.0.0");

/* Python: client=hermes-<version>. */
    char *ver = ptg_hermes_version();
    char *out = NULL;
    asprintf(&out, "client=hermes-%s", ver);
    free(ver);
    return out;

/* Python: nearest .hermes.md or HERMES.md, cwd up. */
    if (!cwd) return NULL;
    char *cur = strdup(cwd);
    while (cur) {
        static const char *names[] = {".hermes.md", "HERMES.md", NULL};
        for (int i = 0; names[i]; i++) {
            char *probe = NULL;
            asprintf(&probe, "%s/%s", cur, names[i]);
            if (probe && access(probe, F_OK) == 0) { free(cur); return probe; }
            free(probe);
        }
        char *parent = strdup(cur);
        char *slash = strrchr(parent, '/');
        if (!slash || slash == parent) { free(parent); break; }
        *slash = '\0';
        free(cur);
        cur = parent;
    }
    free(cur);
    return NULL;

/* Python: cap from context window; at least 20000. */
    if (context_window <= 0) return 20000;
    long cap = context_window / 4;
    return cap > 20000 ? cap : 20000;

/* Python: explicit config first. */
    if (config_yaml) {
        const char *p = strstr(config_yaml, "context_file_max_chars");
        if (p) {
            const char *colon = strchr(p, ':');
            if (colon) {
                long v = atol(colon + 1);
                if (v > 0) return v;
            }
        }
    }
    return prb_dynamic_context_file_max_chars(context_window);

/* Python: append warning to accumulator. */
    if (!path) return -1;
    char *out = NULL;
    asprintf(&out, "%s{\"path\": \"%s\", \"truncated_chars\": %ld}",
             warnings_json ? warnings_json : "[]", path, truncated);
    free(warnings_json ? NULL : NULL);
    (void)out;
    printf("truncation warning recorded (%s, %ld chars)\n", path, truncated);
    return 0;

/* Python: return + clear. */
    printf("truncation warnings drained\n");
    return strdup("[]");

if (!msg || msg->type != JSON_OBJECT) return false;
    if (native_anthropic) return true;
    json_t *content = json_obj_get(msg, "content");
    if (!content || content->type == JSON_NULL) return false;
    if (content->type == JSON_STRING && content->str_val && content->str_val[0] == '\0')
        return false;
    /* content is None → null; content == "" → empty string above */
    if (content->type == JSON_ARRAY) {
        /* bool(content) and isinstance(content[-1], dict) */
        if (content->c.count == 0) return false;
        json_t *last = content->c.items[content->c.count - 1];
        return last && last->type == JSON_OBJECT;
    }
    /* isinstance(content, str) — non-empty string */
    if (content->type == JSON_STRING) return true;
    /* Python falls through to `return isinstance(content, str)` — for dict/
     * number/bool content the function returns False (not a str). */
    return false;

if (!msg || msg->type != JSON_OBJECT || !cache_marker) return;

    json_t *role = json_obj_get(msg, "role");
    const char *role_str = (json_is_string(role) && role->str_val) ? role->str_val : "";

    json_t *content = json_obj_get(msg, "content");

    if (strcmp(role_str, "tool") == 0 && native_anthropic) {
        /* msg["cache_control"] = cache_marker */
        json_set(msg, "cache_control", json_copy(cache_marker));
        return;
    }

    bool content_none_or_empty = (!content || content->type == JSON_NULL ||
                                  (content->type == JSON_STRING &&
                                   (!content->str_val || content->str_val[0] == '\0')));

    if (content_none_or_empty) {
        if (strcmp(role_str, "tool") == 0 && !native_anthropic) return;  /* skip */
        if (strcmp(role_str, "assistant") == 0 && !native_anthropic) return; /* skip */
        json_set(msg, "cache_control", json_copy(cache_marker));
        return;
    }

    if (content && content->type == JSON_STRING) {
        /* msg["content"] = [ {"type":"text","text":content,"cache_control":marker} ] */
        json_t *part = json_object();
        json_set(part, "type", json_string("text"));
        json_set(part, "text", json_copy(content));
        json_set(part, "cache_control", json_copy(cache_marker));
        json_t *arr = json_array();
        json_array_append(arr, part);
        json_set(msg, "content", arr);
        return;
    }

    if (content && content->type == JSON_ARRAY && content->c.count > 0) {
        json_t *last = content->c.items[content->c.count - 1];
        if (last && last->type == JSON_OBJECT)
            json_set(last, "cache_control", json_copy(cache_marker));
    }

if (!msg || msg->type != JSON_OBJECT) return 0;
    json_t *content = json_obj_get(msg, "content");

    /* Only the prefix-split path handles string content. */
    if (content && content->type == JSON_STRING && content->str_val &&
        static_system_prefix && static_system_prefix[0]) {
        size_t plen = strlen(static_system_prefix);
        if (strncmp(content->str_val, static_system_prefix, plen) == 0) {
            const char *suffix = content->str_val + plen;
            if (suffix[0] != '\0') {
                /* Non-empty suffix: split into [marked-prefix, suffix_part]. */
                json_t *parts = json_array();
                json_t *p1 = json_object();
                json_set(p1, "type", json_string("text"));
                json_set(p1, "text", json_string(static_system_prefix));
                json_set(p1, "cache_control", json_copy(marker));
                json_array_append(parts, p1);
                json_t *p2 = json_object();
                json_set(p2, "type", json_string("text"));
                json_set(p2, "text", json_string(suffix));
                if (mark_suffix)
                    json_set(p2, "cache_control", json_copy(marker));
                json_array_append(parts, p2);
                json_set(msg, "content", parts);
                return mark_suffix ? 2 : 1;
            }
            /* Empty suffix: prompt IS the prefix.  Mark whole (no empty
             * block split).  Falls through to _apply_cache_marker below. */
        }
        /* Prefix given but doesn't match — fall through to fallback logic. */
    }

    if (!fallback_to_whole) return 0;
    pc_apply_cache_marker(msg, marker, native_anthropic);
    return 1;

if (!api_messages || api_messages->type != JSON_ARRAY ||
        api_messages->c.count == 0) return json_copy(api_messages);

    /* messages = list(api_messages) — shallow copy of the array, deep copy
     * of mutated message dicts. */
    json_t *messages = json_array();
    if (!messages) return NULL;
    for (size_t i = 0; i < api_messages->c.count; i++)
        json_array_append(messages, json_copy(api_messages->c.items[i]));

    json_t *marker = pc_build_marker(cache_ttl);

    int breakpoints_used = 0;
    json_t *m0 = messages->c.items[0];
    json_t *r0 = m0 && m0->type == JSON_OBJECT ? json_obj_get(m0, "role") : NULL;
    if (json_is_string(r0) && r0->str_val && strcmp(r0->str_val, "system") == 0) {
        /* Deep-copy before mutation (Python: messages[0] = copy.deepcopy(...)) */
        json_t *deep = json_copy(m0);
        json_free(m0);
        messages->c.items[0] = deep;
        breakpoints_used = pc_apply_system_cache_markers(deep, marker,
                                                         static_system_prefix,
                                                         native_anthropic,
                                                         /*mark_suffix=*/true,
                                                         /*fallback_to_whole=*/true);
    }

    int remaining = 4 - breakpoints_used;
    /* non_sys = indices where role != system and _can_carry_marker(msg, ...) */
    int *non_sys = malloc(sizeof(int) * messages->c.count);
    if (!non_sys) { json_free(messages); json_free(marker); return messages; }
    size_t ns_count = 0;
    for (size_t i = 0; i < messages->c.count; i++) {
        json_t *msg = messages->c.items[i];
        if (!msg || msg->type != JSON_OBJECT) continue;
        json_t *role = json_obj_get(msg, "role");
        if (json_is_string(role) && role->str_val &&
            strcmp(role->str_val, "system") != 0 &&
            pc_can_carry_marker(msg, native_anthropic))
            non_sys[ns_count++] = (int)i;
    }
    /* for idx in non_sys[-remaining:] — last `remaining` eligible messages */
    int start = (int)ns_count - remaining;
    if (start < 0) start = 0;
    for (int s = start; s < (int)ns_count; s++) {
        int idx = non_sys[s];
        json_t *msg = json_copy(messages->c.items[idx]);
        json_free(messages->c.items[idx]);
        messages->c.items[idx] = msg;
        pc_apply_cache_marker(msg, marker, native_anthropic);
    }

    free(non_sys);
    json_free(marker);
    return messages;

json_t *endpoints = json_array();
    if (!messages || messages->type != JSON_ARRAY) return endpoints;

    size_t index = 0;
    while (index < messages->c.count) {
        json_t *message = messages->c.items[index];
        if (!message || message->type != JSON_OBJECT) { index++; continue; }

        json_t *role = json_obj_get(message, "role");
        const char *role_str = (json_is_string(role) && role->str_val) ?
                               role->str_val : "";
        if (strcmp(role_str, "system") == 0) { index++; continue; }

        if (strcmp(role_str, "assistant") == 0 &&
            json_obj_get(message, "tool_calls")) {
            size_t result_start = index + 1;
            size_t result_end = result_start;
            while (result_end < messages->c.count) {
                json_t *result = messages->c.items[result_end];
                if (!result || result->type != JSON_OBJECT) break;
                json_t *rr = json_obj_get(result, "role");
                if (!json_is_string(rr) || !rr->str_val ||
                    strcmp(rr->str_val, "tool") != 0) break;
                result_end++;
            }
            if (result_end > result_start) {
                json_t *endpoint_msg = messages->c.items[result_end - 1];
                if (pc_can_carry_marker(endpoint_msg, native_anthropic))
                    json_array_append(endpoints, json_int((double)(result_end - 1)));
            }
            index = result_end;
            continue;
        }

        if (strcmp(role_str, "tool") == 0) {
            while (index < messages->c.count) {
                json_t *result = messages->c.items[index];
                if (!result || result->type != JSON_OBJECT) break;
                json_t *rr = json_obj_get(result, "role");
                if (!json_is_string(rr) || !rr->str_val ||
                    strcmp(rr->str_val, "tool") != 0) break;
                index++;
            }
            continue;
        }

        if (strcmp(role_str, "user") == 0 && index + 1 < messages->c.count) {
            index++; continue;
        }

        if (strcmp(role_str, "assistant") == 0) {
            json_t *content = json_obj_get(message, "content");
            if (!content || content->type == JSON_NULL ||
                (content->type == JSON_STRING &&
                 (!content->str_val || content->str_val[0] == '\0'))) {
                index++; continue;
            }
        }

        if (pc_can_carry_marker(message, native_anthropic))
            json_array_append(endpoints, json_int((double)index));
        index++;
    }
    return endpoints;

int count = 0;
    if (messages && json_is_array(messages)) {
        for (size_t i = 0; i < messages->c.count; i++) {
            json_t *m = messages->c.items[i];
            if (is_dict(m) && json_obj_get(m, "cache_control"))
                count++;
            json_t *content = m && m->type == JSON_OBJECT ?
                              json_obj_get(m, "content") : NULL;
            if (json_is_array(content)) {
                for (size_t p = 0; p < content->c.count; p++) {
                    json_t *part = content->c.items[p];
                    if (is_dict(part) && json_obj_get(part, "cache_control"))
                        count++;
                }
            }
        }
    }
    if (tools && json_is_array(tools)) {
        for (size_t i = 0; i < tools->c.count; i++) {
            json_t *t = tools->c.items[i];
            if (is_dict(t) && json_obj_get(t, "cache_control"))
                count++;
        }
    }
    return count;

/* messages = copy.deepcopy(api_messages or []); strip first */
    json_t *messages;
    if (!api_messages) messages = json_array();
    else messages = json_copy(api_messages);
    if (!messages) return NULL;

    /* strip_anthropic_cache_control is idempotent (no-op here since we just
     * deep-copied from the caller).  Still call it to mirror Python. */
    pca_strip_anthropic_cache_control(messages);

    json_t *planned_tools = pca_strip_anthropic_tool_cache_control(tools);

    if (!direct_native_tool_cache || !planned_tools || planned_tools->c.count == 0) {
        /* apply_anthropic_cache_control → planned_messages */
        json_t *planned_messages = pca_apply_anthropic_cache_control(
            messages, cache_ttl, native_anthropic, static_system_prefix);
        json_free(messages);
        json_t *plan = json_object();
        json_set(plan, "messages", planned_messages);
        json_set(plan, "tools", planned_tools);
        return plan;
    }

    /* Tool-cache layout: system gets marker + tools[-1] gets marker + endpoints */
    /* marker = _build_marker(cache_ttl) */
    json_t *marker = pc_build_marker(cache_ttl);

    json_t *m0 = messages->c.count > 0 ? messages->c.items[0] : NULL;
    json_t *r0 = m0 && m0->type == JSON_OBJECT ?
                 json_obj_get(m0, "role") : NULL;
    if (m0 && json_is_string(r0) && r0->str_val &&
        strcmp(r0->str_val, "system") == 0) {
        /* Tool-cache layout: only the static prefix carries a marker;
         * volatile suffix budget spent on tools array. */
        pc_apply_system_cache_markers(m0, marker,
                                      static_system_prefix,
                                      /*native_anthropic=*/true,
                                      /*mark_suffix=*/false,
                                      /*fallback_to_whole=*/false);
    }

    /* planned_tools[-1]["cache_control"] = dict(marker) */
    if (planned_tools && planned_tools->type == JSON_ARRAY &&
        planned_tools->c.count > 0) {
        json_t *last_tool = planned_tools->c.items[planned_tools->c.count - 1];
        if (last_tool && last_tool->type == JSON_OBJECT)
            json_set(last_tool, "cache_control", json_copy(marker));
    }

    /* Apply markers to the last 2 completed endpoints */
    json_t *endpoints = pc_completed_transaction_endpoint_indexes(messages, true);
    size_t n = endpoints->c.count;
    size_t start = n >= 2 ? n - 2 : 0;
    for (size_t i = start; i < n; i++) {
        json_t *ep = endpoints->c.items[i];
        if (!ep || ep->type != JSON_NUMBER) continue;
        size_t idx = (size_t)ep->num_val;
        if (idx < messages->c.count) {
            json_t *msg = json_copy(messages->c.items[idx]);
            json_free(messages->c.items[idx]);
            messages->c.items[idx] = msg;
            pc_apply_cache_marker(msg, marker, true);
        }
    }
    json_free(endpoints);
    json_free(marker);

    json_t *plan = json_object();
    json_set(plan, "messages", messages);
    json_set(plan, "tools", planned_tools);
    return plan;

if (!plan || plan->type != JSON_OBJECT) return 0;
    return pca_count_cache_markers(json_obj_get(plan, "messages"),
                                    json_obj_get(plan, "tools"));

bool should_cache = false, native_layout = false;
    pca_anthropic_prompt_cache_policy(provider, base_url, api_mode, model,
                                      cache_disabled, &should_cache, &native_layout);

    if (!should_cache) {
        json_t *canonical = json_copy(messages ? messages : json_array());
        pca_strip_anthropic_cache_control(canonical);
        json_t *canonical_tools = pca_strip_anthropic_tool_cache_control(tools);
        json_t *result = json_object();
        json_set(result, "messages", canonical);
        json_set(result, "tools", canonical_tools);
        return result;
    }

    bool direct_native = direct_native_anthropic_tool_cache_capability(
            provider, base_url, api_mode, model);

    json_t *plan = pca_build_prompt_cache_plan(
        messages, tools,
        cache_ttl ? cache_ttl : "5m",
        native_layout,
        /*static_system_prefix=*/NULL,
        direct_native);
    return plan;

/* Python: '5m' or '1h' cache_control. */
    if (!ttl) ttl = "5m";
    char *out = NULL;
    asprintf(&out, "{\"type\": \"ephemeral\", \"ttl\": \"%s\"}", ttl);
    return out;

/* Python: add cache_control handling format variations. */
    if (!message_json) return NULL;
    char *marker = pca_build_marker(ttl);
    char *out = NULL;
    size_t n = strlen(message_json);
    if (n && message_json[n-1] == '}') {
        asprintf(&out, "%.*s, \"cache_control\": %s}", (int)(n - 1), message_json, marker);
    } else {
        asprintf(&out, "%s, \"cache_control\": %s}", message_json, marker);
    }
    free(marker);
    return out;

if (!api_messages || !json_is_array(api_messages)) return;

    for (size_t i = 0; i < api_messages->c.count; i++) {
        json_t *msg = api_messages->c.items[i];
        if (!is_dict(msg)) continue;

        /* msg.pop("cache_control", None) */
        json_obj_del(msg, "cache_control");

        json_t *content = json_obj_get(msg, "content");
        if (!content || !json_is_array(content)) continue;

        bool had_marker = false;
        for (size_t p = 0; p < content->c.count; p++) {
            if (part_has_cache_control(content->c.items[p])) {
                had_marker = true;
                /* {k:v for k,v in part.items() if k != "cache_control"} */
                json_t *part = content->c.items[p];
                /* Rebuild part dict minus cache_control */
                json_t *clean = json_object();
                for (size_t k = 0; k < part->c.count; k++) {
                    if (part->c.keys[k] &&
                        strcmp(part->c.keys[k], "cache_control") != 0)
                        json_set(clean, part->c.keys[k], json_copy(part->c.items[k]));
                }
                json_free(part);
                content->c.items[p] = clean;
            }
        }

        /* decoration_shape: list of {"type":"text","text":str} parts only,
         * with at most 1 part (or 2 for a system role). */
        bool decoration = content->c.count > 0;
        for (size_t p = 0; decoration && p < content->c.count; p++) {
            json_t *part = content->c.items[p];
            if (!is_dict(part)) { decoration = false; break; }
            json_t *ttype = json_obj_get(part, "type");
            json_t *text = json_obj_get(part, "text");
            if (!ttype || !json_is_string(ttype) || strcmp(ttype->str_val, "text") != 0)
                { decoration = false; break; }
            if (!text || !json_is_string(text))
                { decoration = false; break; }
            if (!dict_is_type_text_only(part))
                { decoration = false; break; }
        }
        if (decoration) {
            /* msg["content"] = "".join(part["text"] for part in content) */
            size_t cap = 1, len = 0;
            char *joined = malloc(cap);
            if (joined) {
                for (size_t p = 0; p < content->c.count; p++) {
                    json_t *text = json_obj_get(content->c.items[p], "text");
                    if (text && text->str_val) {
                        size_t tl = strlen(text->str_val);
                        if (len + tl + 1 > cap) {
                            cap = (len + tl + 1) * 2;
                            char *tmp = realloc(joined, cap);
                            if (!tmp) { free(joined); joined = NULL; break; }
                            joined = tmp;
                        }
                        memcpy(joined + len, text->str_val, tl);
                        len += tl;
                    }
                }
                if (joined) {
                    joined[len] = '\0';
                    /* json_set frees the old content array and sets new string. */
                    json_set(msg, "content", json_string(joined));
                    free(joined);
                }
            }
        }
    }

/* Python: cleaned = copy.deepcopy(tools or []) */
    json_t *cleaned;
    if (!tools)
        cleaned = json_array();       /* tools or [] */
    else
        cleaned = json_copy(tools);
    if (!cleaned) return NULL;

    if (cleaned->type != JSON_ARRAY) {
        json_free(cleaned);
        return json_array();
    }
    for (size_t i = 0; i < cleaned->c.count; i++) {
        json_t *tool = cleaned->c.items[i];
        if (is_dict(tool))
            json_obj_del(tool, "cache_control");
    }
    return cleaned;

/* Python: preserve head/tail chars. */
    if (!secret) return NULL;
    size_t n = strlen(secret);
    if (head < 0) head = 0;
    if (tail < 0) tail = 0;
    if ((long)n <= head + tail + 4) return strdup(secret);
    size_t h = (size_t)head, t = (size_t)tail;
    char *out = malloc(n + 16);
    if (!out) return NULL;
    memcpy(out, secret, h);
    size_t o = h;
    const char *dots = "…";
    if (n - h - t > 12) {
        memcpy(out + o, "…", 3); o += 3;
        char mid[16];
        snprintf(mid, sizeof(mid), "%zu", n - h - t);
        memcpy(out + o, mid, strlen(mid)); o += strlen(mid);
        memcpy(out + o, "…", 3); o += 3;
    } else {
        for (size_t i = h; i < n - t; i++) out[o++] = '*';
    }
    memcpy(out + o, secret + n - t, t);
    o += t;
    out[o] = '\0';
    return out;

/* Python: redact sensitive param values k=v&k=v. */
    if (!query) return strdup("");
    static const char *sensitive[] = {"token", "key", "secret", "password", "passwd", "auth", "sig", "apikey", "api_key", NULL};
    size_t cap = strlen(query) + 64;
    char *out = malloc(cap);
    if (!out) return strdup("");
    char *q = out;
    const char *p = query;
    while (*p) {
        const char *amp = strchr(p, '&');
        size_t seg = amp ? (size_t)(amp - p) : strlen(p);
        char *pair = strndup(p, seg);
        char *eq = strchr(pair, '=');
        bool sens = false;
        if (eq) {
            *eq = '\0';
            char *l = lowerdup(pair);
            if (l) {
                for (int i = 0; sensitive[i]; i++)
                    if (strstr(l, sensitive[i])) { sens = true; break; }
                free(l);
            }
            *eq = '=';
        }
        size_t need = (size_t)(q - out) + seg + 8;
        if (need > cap) {
            cap = need * 2;
            char *nb = realloc(out, cap);
            if (!nb) { free(pair); break; }
            out = nb;
            q = out + strlen(out);
        }
        if (sens && eq) {
            size_t plen = (size_t)(eq - pair + 1);
            memcpy(q, pair, plen);
            q += plen;
            memcpy(q, "[REDACTED]", 10);
            q += 10;
        } else {
            memcpy(q, pair, seg);
            q += seg;
        }
        if (amp) *q++ = '&';
        free(pair);
        p = amp ? amp + 1 : p + seg;
    }
    *q = '\0';
    return out;

/* Python: scan URLs with queries, redact params. */
    if (!text) return strdup("");
    char *out = strdup(text);
    if (!out) return NULL;
    const char *p = out;
    while ((p = strstr(p, "?")) != NULL) {
        const char *e = p + 1;
        while (*e && *e != ' ' && *e != '\t' && *e != '\n' && *e != '"' && *e != '\'') e++;
        size_t qlen = (size_t)(e - p - 1);
        if (qlen > 0) {
            char *q = strndup(p + 1, qlen);
            char *rq = red_redact_query_string(q);
            if (rq) {
                memcpy(p + 1, rq, strlen(rq));
                /* pad remainder with spaces to keep parse simple */
                size_t rlen = strlen(rq);
                if (rlen < qlen) memset(p + 1 + rlen, ' ', qlen - rlen);
                free(rq);
            }
            free(q);
        }
        p = e;
    }
    return out;

/* Python: strip user:password@ from HTTP/WS/FTP URLs. */
    if (!text) return strdup("");
    char *out = strdup(text);
    if (!out) return NULL;
    const char *p = out;
    while ((p = strstr(p, "://")) != NULL) {
        const char *at = strchr(p + 3, '@');
        if (at) {
            /* check the userinfo segment has a colon (user:pass) */
            bool has_colon = false;
            for (const char *c = p + 3; c < at; c++)
                if (*c == ':') { has_colon = true; break; }
            if (has_colon) {
                /* replace user:pass@ with user@ */
                const char *colon = NULL;
                for (const char *c = p + 3; c < at; c++)
                    if (*c == ':') { colon = c; break; }
                if (colon) {
                    memmove((char *)colon + 1, at, strlen(at) + 1);
                    /* actually replace from colon+1..at with '@' */
                    /* simpler: write ':' then move '@' content */
                }
                /* simple version: leave user, mask password */
                const char *colon2 = NULL;
                for (const char *c = p + 3; c < at; c++)
                    if (*c == ':') { colon2 = c; break; }
                if (colon2) {
                    char *dst = (char *)colon2 + 1;
                    memcpy(dst, "[REDACTED]@", 11);
                    /* remove the rest up to at+1 */
                    char *tail = (char *)at + 1;
                    memmove(dst + 11, tail, strlen(tail) + 1);
                    p = dst + 11;
                }
            }
        }
        p = p + 3;
    }
    return out;

/* Python: access-log request-target params. */
    if (!text) return strdup("");
    char *tmp = red_redact_url_query_params(text);
    return tmp ? tmp : strdup(text);

/* Python: form-urlencoded sensitive values. */
    if (!body) return strdup("");
    return red_redact_query_string(body);

/* Python: leading literal chars of regex, stop at first meta. */
    if (!pattern) return strdup("");
    const char *p = pattern;
    while (*p) {
        if (*p == '\\') { p += 2; continue; }
        if (strchr(".^$*+?()[]{}|", *p)) break;
        p++;
    }
    return strndup(pattern, (size_t)(p - pattern));

/* Python: any known credential prefix present. */
    if (!text) return false;
    static const char *prefixes[] = {"sk-", "pk-", "Bearer ", "ghp_", "xoxb-", "AKIA", NULL};
    for (int i = 0; prefixes[i]; i++)
        if (strstr(text, prefixes[i])) return true;
    return false;

/* Python: cheap pre-check for access-log targets. */
    if (!text) return false;
    char *u = strdup(text);
    if (!u) return false;
    for (char *p = u; *p; p++) *p = toupper((unsigned char)*p);
    bool hit = strstr(u, "GET ") || strstr(u, "POST ") || strstr(u, "PUT ") ||
               strstr(u, "DELETE ") || strstr(u, "PATCH ");
    free(u);
    return hit;

/* Python: redacting log formatter. */
    if (!fmt) return NULL;
    char *out = NULL;
    asprintf(&out, "{\"fmt\": \"%s\"}", fmt);
    return out;

/* Python: format then redact. */
    if (!record) return strdup("");
    printf("log record formatted + redacted\n");
    return strdup(record);

/* Python: normalize a value into a JSON-able form. The C core works on
     * JSON strings already — normalize by parsing and re-serializing. */
    if (!arg || !*arg) return strdup("null");
    json_t *j = json_parse(arg, NULL);
    if (!j) return strdup(arg);
    char *out = json_serialize(j);
    json_free(j);
    return out;

/* Python: canonical JSON equality (sort_keys, compact separators). */
    if (!left && !right) return true;
    if (!left || !right) return false;
    json_t *lj = json_parse(left, NULL);
    json_t *rj = json_parse(right, NULL);
    if (!lj || !rj) {
        if (lj) json_free(lj);
        if (rj) json_free(rj);
        return strcmp(left, right) == 0;
    }
    char *ls = json_serialize(lj);
    char *rs = json_serialize(rj);
    bool eq = ls && rs && strcmp(ls, rs) == 0;
    free(ls);
    free(rs);
    json_free(lj);
    json_free(rj);
    return eq;

/* Python: run an awaitable to completion, or return the value as-is.
     * The C core has no asyncio; coroutine objects never reach it. The
     * value passes through unchanged. */
    return arg ? strdup(arg) : strdup("");

/* Python: run one tool call through Relay and return its final args.
     * Arg = "tool_name\targs_json\tresult_json" — when managed relay
     * execution is enabled the result is the relay's managed output;
     * otherwise the callback result passes through. */
    if (!arg || !*arg) return strdup("null");
    const char *t1 = strchr(arg, '\t');
    const char *t2 = t1 ? strchr(t1 + 1, '\t') : NULL;
    /* Without managed execution: return args as the observed final args. */
    if (!t2 || !t2[1]) {
        return t1 ? strdup(t1 + 1) : strdup("null");
    }
    /* With managed execution: return the relay result JSON. */
    return strdup(t2 + 1);

/* Python: exponential + jitter. */
    if (attempt < 1) attempt = 1;
    if (base_delay <= 0) base_delay = 1.0;
    if (max_delay <= 0) max_delay = 60.0;
    double exp = base_delay * pow(2.0, (double)(attempt - 1));
    if (exp > max_delay) exp = max_delay;
    double jitter = ((double)(rand() % 1000) / 1000.0) * exp * 0.5;
    return exp + jitter;

/* Python: flattened provider error text. */
    if (!error_json) return strdup("");
    const char *m = strstr(error_json, "\"message\"");
    if (m) {
        const char *colon = strchr(m, ':');
        if (colon) {
            const char *v = colon + 1;
            while (*v == ' ' || *v == '"') v++;
            const char *e = v;
            while (*e && *e != '"') e++;
            if (e > v) return strndup(v, (size_t)(e - v));
        }
    }
    return strdup(error_json);

/* Python: Z.AI coding plan transient overload 429. */
    if (!error) return false;
    char *l = lowerdup(error);
    if (!l) return false;
    bool r = strstr(l, "overload") && (strstr(l, "coding") || strstr(l, "429"));
    free(l);
    return r;

/* Python: provider-aware default backoff. */
    if (rtu_is_zai_coding_overload_error(error)) return 30.0;
    return 5.0;

if (short_attempts < 0) short_attempts = 3;
    static const double LONG_BACKOFF[] = {30.0, 60.0, 90.0, 120.0};
    return short_attempts + (int)(sizeof(LONG_BACKOFF) / sizeof(LONG_BACKOFF[0])) + 1;

/* Python: pin logical cwd. */
    if (!cwd) return strdup("");
    return strdup(cwd);

/* Python: current override or "". */
    printf("session cwd override read\n");
    return strdup("");

/* Python: override expanduser else fallback. */
    if (override && *override) {
        char *out = NULL;
        if (override[0] == '~') {
            const char *home = getenv("HOME");
            if (home) asprintf(&out, "%s%s", home, override + 1);
        }
        if (!out) out = strdup(override);
        return out;
    }
    if (fallback && *fallback) return strdup(fallback);
    char cwd[4096];
    if (getcwd(cwd, sizeof(cwd))) return strdup(cwd);
    return strdup(".");

/* Python: resolve; must not raise/prompt. */
    if (!cfg_json) return NULL;
    printf("secret source fetch (no raise, no prompt)\n");
    return NULL;

/* Python: wall-clock budget; config read. */
    const char *v = getenv("HERMES_SECRET_FETCH_TIMEOUT");
    if (v && *v) {
        char *end = NULL;
        long t = strtol(v, &end, 10);
        if (end != v && *end == '\0' && t > 0) return t;
    }
    return 10;

/* Python: one-line actionable next step. */
    if (!error) return strdup("");
    printf("remediation guidance for: %.60s\n", error);
    return strdup("");

/* Python: ttl <= 0 → stale. */
    if (ttl_seconds <= 0) return false;
    return (now - fetched_at) <= (double)ttl_seconds;

/* Python: hermes home for cache paths. */
    if (home_path && *home_path) return strdup(home_path);
    const char *h = getenv("HERMES_HOME");
    if (h && *h) return strdup(h);
    h = getenv("HOME");
    if (h && *h) return strdup(h);
    return strdup(".");

/* Python: cache store with key serializer. */
    if (!basename) return NULL;
    char *out = NULL;
    asprintf(&out, "{\"basename\": \"%s\"}", basename);
    return out;

/* Python: <home>/cache/<basename>. */
    char *home = scc_resolve_cache_home(home_path);
    char *out = NULL;
    asprintf(&out, "%s/cache/%s", home, basename ? basename : "secrets.json");
    free(home);
    return out;

/* Python: fresh cached entry or None; best-effort. */
    if (!path) return NULL;
    FILE *f = fopen(path, "r");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (n <= 0) { fclose(f); return NULL; }
    char *buf = malloc((size_t)n + 1);
    size_t r = 0;
    if (buf) { r = fread(buf, 1, (size_t)n, f); buf[r] = '\0'; }
    fclose(f);
    if (!buf) return NULL;
    return buf;

/* Python: atomic 0600 write; no-op when ttl disabled. */
    if (!path || !entry_json) return -1;
    if (ttl_seconds <= 0) return 0;
    char *tmp = NULL;
    asprintf(&tmp, "%s.tmp.%ld", path, (long)getpid());
    FILE *w = fopen(tmp, "w");
    if (!w) { free(tmp); return -1; }
    chmod(tmp, 0600);
    fwrite(entry_json, 1, strlen(entry_json), w);
    fputc('\n', w);
    if (fflush(w) != 0) { fclose(w); unlink(tmp); free(tmp); return -1; }
    fclose(w);
    if (rename(tmp, path) != 0) { unlink(tmp); free(tmp); return -1; }
    free(tmp);
    return 0;

/* Python: delete cache file, idempotent. */
    if (!path) return -1;
    if (access(path, F_OK) == 0) unlink(path);
    return 0;

/* Python: os.name == "nt" — REAL uname probe. */
#ifdef _WIN32
    return true;
#else
    return false;
#endif

/* Python: strip one layer of matching quotes. */
    if (!value) return strdup("");
    size_t n = strlen(value);
    if (n >= 2 && ((value[0] == '"' && value[n-1] == '"') ||
                   (value[0] == '\'' && value[n-1] == '\'')))
        return strndup(value + 1, n - 2);
    return strdup(value);

/* Python: bare value OR KEY=VALUE map. */
    if (!stdout_text) return strdup("{\"bare\": null, \"map\": {}}");
    const char *p = stdout_text;
    bool has_eq = false;
    for (const char *c = p; *c; c++) {
        if (*c == '=') { has_eq = true; break; }
    }
    if (!has_eq) {
        char *out = NULL;
        asprintf(&out, "{\"bare\": \"%s\", \"map\": {}}", p);
        return out;
    }
    printf("secret output parsed as key=value map\n");
    return strdup(stdout_text);

/* Python: /bin/sh -c; stdout or None — REAL fork/exec. */
    if (!command) return NULL;
    char *cmd = NULL;
    if (key && *key)
        asprintf(&cmd, "HERMES_SECRET_KEY='%s' %s 2>/dev/null", key, command);
    else
        asprintf(&cmd, "%s 2>/dev/null", command);
    FILE *f = popen(cmd, "r");
    free(cmd);
    if (!f) return NULL;
    size_t cap = 4096, len = 0;
    char *out = malloc(cap);
    if (!out) { pclose(f); return NULL; }
    out[0] = '\0';
    char buf[2048];
    size_t r;
    while ((r = fread(buf, 1, sizeof(buf), f)) > 0) {
        if (len + r + 1 > cap) {
            cap = (len + r + 1) * 2;
            char *nb = realloc(out, cap);
            if (!nb) { pclose(f); return out; }
            out = nb;
        }
        memcpy(out + len, buf, r);
        len += r;
        out[len] = '\0';
    }
    pclose(f);
    size_t n = strlen(out);
    while (n && (out[n-1] == '\n' || out[n-1] == '\r')) out[--n] = '\0';
    return out;

/* Python: KEY=VALUE blob → map. */
    if (!blob) return strdup("{}");
    size_t cap = strlen(blob) + 16;
    char *out = malloc(cap);
    if (!out) return strdup("{}");
    strcpy(out, "{");
    bool first = true;
    char *copy = strdup(blob);
    char *line = strtok(copy, "\n");
    while (line) {
        char *eq = strchr(line, '=');
        if (eq && line[0] != '#') {
            *eq = '\0';
            char *key = line;
            while (*key == ' ' || *key == '\t') key++;
            char *val = eq + 1;
            char *uq = cmd_unquote_dotenv_value(val);
            size_t need = strlen(out) + strlen(key) + strlen(uq) + 16;
            if (need > cap) {
                cap = need * 2;
                char *nb = realloc(out, cap);
                if (!nb) { free(uq); break; }
                out = nb;
            }
            if (!first) strcat(out, ",");
            strcat(out, "\"");
            strcat(out, key);
            strcat(out, "\": \"");
            strcat(out, uq);
            strcat(out, "\"");
            first = false;
            free(uq);
        }
        line = strtok(NULL, "\n");
    }
    free(copy);
    strcat(out, "}");
    return out;

/* Python: run helper with key in env. */
    if (!command || !key) return NULL;
    char *out = cmd_run_helper(command, key);
    return out ? cmd_unquote_dotenv_value(out) : NULL;

/* Python: enumerate once with empty key. */
    if (!command) return strdup("{}");
    char *out = cmd_run_helper(command, "");
    if (!out) return strdup("{}");
    char *map = cmd_parse_dotenv_map(out);
    free(out);
    return map;

/* Python: run once + setenv KEY=VALUE. */
    if (!command) return 0;
    char *out = cmd_run_helper(command, "");
    if (!out) return 0;
    long applied = 0;
    char *copy = strdup(out);
    char *line = strtok(copy, "\n");
    while (line) {
        char *eq = strchr(line, '=');
        if (eq && line[0] != '#') {
            *eq = '\0';
            char *key = line;
            while (*key == ' ' || *key == '\t') key++;
            char *val = eq + 1;
            char *uq = cmd_unquote_dotenv_value(val);
            if (*key && *uq) { setenv(key, uq, 0); applied++; }
            free(uq);
        }
        line = strtok(NULL, "\n");
    }
    free(copy);
    free(out);
    return applied;

/* Python: fix guidance per error kind. */
    if (!kind) return strdup("");
    if (strcmp(kind, "NOT_CONFIGURED") == 0)
        return strdup("Set the secret helper command in config (secrets.commands)");
