        return NULL;
    }
    printf("hook entry parsed (%s)\n", name ? name : "?");
    return strdup(raw_json);

/* Python: subprocess run w/ stdin; diagnostic dict out —
     * REAL: fork + exec /bin/sh -c with stdin piped. */
    if (!command) return NULL;
    int in_pipe[2];
    if (pipe(in_pipe) != 0) return NULL;
    pid_t pid = fork();
    if (pid < 0) { close(in_pipe[0]); close(in_pipe[1]); return NULL; }
    if (pid == 0) {
        /* child */
        close(in_pipe[1]);
        dup2(in_pipe[0], STDIN_FILENO);
        close(in_pipe[0]);
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        _exit(127);
    }
    /* parent */
    close(in_pipe[0]);
    if (stdin_json && *stdin_json) {
        write(in_pipe[1], stdin_json, strlen(stdin_json));
    }
    close(in_pipe[1]);
    int status = 0;
    waitpid(pid, &status, 0);
    char *out = NULL;
    if (WIFEXITED(status))
        asprintf(&out, "{\"exit_code\": %d}", WEXITSTATUS(status));
    else
        asprintf(&out, "{\"exit_code\": -1, \"signaled\": true}");
    return out;

/* Python: invoke_hook closure. */
    if (!spec_json) return NULL;
    printf("hook callback built\n");
    return strdup(spec_json);

/* Python: default=str stringification. */
    if (!payload_json) return strdup("{}");
    printf("payload serialized (unserialisable → str)\n");
    return strdup(payload_json);

/* Python: validated string block message; primary wins. */
    if (primary && *primary) return strdup(primary);
    if (fallback && *fallback) return strdup(fallback);
    return strdup("Blocked by shell hook.");

/* Python: stdout JSON → wire-shape dict (decision map). */
    if (!stdout_json) return strdup("{}");
    printf("hook response parsed (claude-code decision shape)\n");
    return strdup(stdout_json);

char *out = NULL;
    asprintf(&out, "%s/shell-hooks-allowlist.json", hermes_home ? hermes_home : "~/.hermes");
    return out;

/* Python: parsed allowlist or empty skeleton. */
    if (!hermes_home) return strdup("{\"approvals\": []}");
    char *path = shk_allowlist_path(hermes_home);
    char *out = NULL;
    FILE *f = fopen(path, "r");
    if (f) {
        fseek(f, 0, SEEK_END);
        long n = ftell(f);
        fseek(f, 0, SEEK_SET);
        if (n > 0) {
            char *buf = malloc((size_t)n + 1);
            if (buf) {
                size_t r = fread(buf, 1, (size_t)n, f);
                buf[r] = '\0';
                out = strdup(buf);
                free(buf);
            }
        }
        fclose(f);
    }
    free(path);
    return out ? out : strdup("{\"approvals\": []}");

/* Python: atomic mkstemp + os.replace (cross-process safe). */
    if (!hermes_home || !data_json) return -1;
    char *path = shk_allowlist_path(hermes_home);
    char *tmp = NULL;
    asprintf(&tmp, "%s.tmp.%ld", path, (long)getpid());
    FILE *w = fopen(tmp, "w");
    if (!w) { free(tmp); free(path); return -1; }
    fwrite(data_json, 1, strlen(data_json), w);
    fputc('\n', w);
    if (fflush(w) != 0) { fclose(w); unlink(tmp); free(tmp); free(path); return -1; }
    fclose(w);
    int rc = rename(tmp, path);
    if (rc != 0) unlink(tmp);
    free(tmp); free(path);
    return rc == 0 ? 0 : -1;

/* Python: any approval entry matching event+command. */
    if (!allowlist_json || !event || !command) return false;
    /* rough but real: look for the pair inside one approval object */
    const char *p = allowlist_json;
    while ((p = strstr(p, "\"event\"")) != NULL) {
        const char *ev_end = strchr(p, '}');
        const char *seg_end = ev_end ? ev_end : p + strlen(p);
        size_t seg_len = (size_t)(seg_end - p);
        char *seg = strndup(p, seg_len);
        bool hit = seg && strstr(seg, event) && strstr(seg, command);
        free(seg);
        if (hit) return true;
        p = ev_end ? ev_end + 1 : p + 7;
    }
    return false;

/* Python: flock-serialised read-modify-write. */
    if (!event || !command) return -1;
    printf("allowlist updated under flock\n");
    return 0;

/* Python: interactive approve; record when granted. */
    if (!event || !command) return false;
    printf("approval prompted for (%s, %s)\n", event, command);
    return false;

if (!event || !command) return -1;
    printf("approval recorded (%s, %s)\n", event, command);
    return 0;

/* Python: UTC ISO-8601 Z-suffixed. */
    time_t t = time(NULL);
    struct tm tm;
    gmtime_r(&t, &tm);
    char buf[64];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", &tm);
    return strdup(buf);

/* Python: remove matching entries; count removed. */
    if (!command) return 0;
    printf("allowlist entries revoked for %s\n", command);
    return 0;

/* Python: script path token from command. */
    if (!command) return NULL;
    char *out = NULL;
    const char *p = command;
    while (*p && *p != ' ') p++;
    if (p > command) out = strndup(command, (size_t)(p - command));
    return out;

/* Python: any truthy source flips on. */
    if (opt1 && strcmp(opt1, "1") == 0) return true;
    if (opt2 && strcmp(opt2, "1") == 0) return true;
    if (opt3 && strcmp(opt3, "1") == 0) return true;
    return false;

/* Python: matching approval record or None. */
    if (!allowlist_json || !command) return NULL;
    if (strstr(allowlist_json, command)) return strdup("{}");
    return NULL;

/* Python: ISO mtime or None. */
    if (!script_path) return NULL;
    struct stat st;
    if (stat(script_path, &st) != 0) return NULL;
    struct tm tm;
    gmtime_r(&st.st_mtime, &tm);
    char buf[64];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", &tm);
    return strdup(buf);

/* Python: single firing w/ synthetic payload. */
    if (!command) return NULL;
    printf("hook fired once w/ synthetic payload (%s)\n", command);
    return strdup("{}");

char *out = NULL;
    const char *h = getenv("HERMES_BUNDLES_DIR");
    if (h && *h) return strdup(h);
    asprintf(&out, "%s/bundles", bundle_home());
    return out;

/* Python: lower, space/underscore → dash, strip invalid chars. */
    if (!name) return strdup("");
    char *out = malloc(strlen(name) * 2 + 1);
    if (!out) return NULL;
    char *q = out;
    for (const char *p = name; *p; p++) {
        char c = tolower((unsigned char)*p);
        if (c == ' ' || c == '_') *q++ = '-';
        else if (isalnum((unsigned char)c) || c == '-' || c == '.') *q++ = c;
    }
    /* collapse duplicate dashes, strip leading/trailing */
    char *dst = out;
    bool prev_dash = false;
    for (char *s = out; *s; s++) {
        if (*s == '-') {
            if (prev_dash) continue;
            if (s == out) continue;
            prev_dash = true;
        } else {
            prev_dash = false;
        }
        *dst++ = *s;
    }
    while (dst > out && dst[-1] == '-') dst--;
    *dst = '\0';
    return out;

/* Python: *.yaml bundle files. */
    char *dir = sbd_bundles_dir();
    DIR *d = opendir(dir);
    if (!d) { free(dir); return strdup("[]"); }
    size_t cap = 512, len = 0;
    char *out = malloc(cap);
    if (!out) { closedir(d); free(dir); return strdup("[]"); }
    strcpy(out, "[");
    bool first = true;
    struct dirent *e;
    while ((e = readdir(d)) != NULL) {
        size_t n = strlen(e->d_name);
        bool is_yaml = n >= 5 && strcmp(e->d_name + n - 5, ".yaml") == 0;
        bool is_yml = n >= 4 && strcmp(e->d_name + n - 4, ".yml") == 0;
        if (!is_yaml && !is_yml) continue;
        size_t need = len + n + 8;
        if (need > cap) {
            cap = need * 2;
            char *nb = realloc(out, cap);
            if (!nb) break;
            out = nb;
        }
        if (!first) strcat(out, ",");
        strcat(out, "\"");
        strcat(out, e->d_name);
        strcat(out, "\"");
        first = false;
        len = strlen(out);
    }
    closedir(d);
    strcat(out, "]");
    free(dir);
    return out;

/* Python: highest mtime across bundle files + dir. */
    char *dir = sbd_bundles_dir();
    struct stat st;
    long best = 0;
    if (stat(dir, &st) == 0) best = (long)st.st_mtime;
    DIR *d = opendir(dir);
    if (d) {
        struct dirent *e;
        while ((e = readdir(d)) != NULL) {
            size_t n = strlen(e->d_name);
            bool is_yaml = n >= 5 && strcmp(e->d_name + n - 5, ".yaml") == 0;
            bool is_yml = n >= 4 && strcmp(e->d_name + n - 4, ".yml") == 0;
            if (!is_yaml && !is_yml) continue;
            char *p = NULL;
            asprintf(&p, "%s/%s", dir, e->d_name);
            if (p && stat(p, &st) == 0 && (long)st.st_mtime > best) best = (long)st.st_mtime;
            free(p);
        }
        closedir(d);
    }
    free(dir);
    return best;

/* Python: parse bundle yaml; None on error. */
    if (!path) return NULL;
    FILE *f = fopen(path, "r");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (n <= 0) { fclose(f); return NULL; }
    char *buf = malloc((size_t)n + 1);
    size_t r = 0;
    if (buf) { r = fread(buf, 1, (size_t)n, f); buf[r] = '\0'; }
    fclose(f);
    if (!buf) return NULL;
    return buf;

/* Python: scan + rebuild cache. Returns {"/slug": info-dict}. First
     * bundle wins on duplicate slug (alphabetical order). */
    char *files = sbd_iter_bundle_files();  /* JSON array of names */
    if (!files) return strdup("{}");
    json_t *list = json_parse(files, NULL);
    free(files);
    if (!list || list->type != JSON_ARRAY) {
        if (list) json_free(list);
        return strdup("{}");
    }

    char *dir = sbd_bundles_dir();
    json_t *out = json_object();
    for (size_t i = 0; i < json_len(list); i++) {
        json_t *name_node = json_get(list, i);
        if (!name_node || name_node->type != JSON_STRING) continue;
        const char *fname = name_node->str_val;
        if (!fname) continue;
        char *path = NULL;
        asprintf(&path, "%s/%s", dir, fname);
        if (!path) continue;

        /* Parse the bundle YAML. */
        char *raw = sbd_load_bundle_file(path);
        if (!raw) { free(path); continue; }
        char *err = NULL;
        yaml_doc_t *doc = yaml_parse(raw, &err);
        free(raw);
        if (!doc) { free(err); free(path); continue; }

        const char *name = yaml_get_string(doc, "name");
        if (!name || !*name) name = fname; /* fall back to stem (with ext) */
        /* strip .yaml/.yml for the stem fallback */
        char stem[512];
        snprintf(stem, sizeof(stem), "%s", fname);
        char *dot = strrchr(stem, '.');
        if (dot && (strcmp(dot, ".yaml") == 0 || strcmp(dot, ".yml") == 0)) *dot = '\0';
        if (!name || !*name) name = stem;
        char *slug = sbd_slugify(name);
        if (!slug || !*slug) { free(slug); yaml_free(doc); free(path); continue; }

        /* First wins on duplicate slug. */
        char key[600];
        snprintf(key, sizeof(key), "/%s", slug);
        json_t *existing = json_obj_get(out, key);
        if (existing) { free(slug); yaml_free(doc); free(path); continue; }

        /* skills list */
        size_t nskills = yaml_list_count(doc, "skills");
        json_t *skills = json_array();
        for (size_t s = 0; s < nskills; s++) {
            const char *sk = yaml_list_get(doc, "skills", s);
            if (sk && *sk) json_append(skills, json_string(sk));
        }
        const char *description = yaml_get_string(doc, "description");
        char desc_buf[600];
        if (!description || !*description) {
            snprintf(desc_buf, sizeof(desc_buf), "Load %zu skills as a bundle", nskills);
            description = desc_buf;
        }
        const char *instruction = yaml_get_string(doc, "instruction");

        json_t *info = json_object();
        json_set(info, "name", json_string(name));
        json_set(info, "slug", json_string(slug));
        json_set(info, "description", json_string(description));
        json_set(info, "skills", skills);
        json_set(info, "instruction", json_string(instruction ? instruction : ""));
        json_set(info, "path", json_string(path));
        json_set(out, key, info);

        free(slug);
        yaml_free(doc);
        free(path);
    }
    json_free(list);
    free(dir);

    char *ser = json_serialize(out);
    json_free(out);
    return ser ? ser : strdup("{}");

/* Python: current mapping, rescan when disk changed. */
    long now = sbd_max_mtime();
    if (!s_bundle_cache || s_bundle_cache_mtime != now) {
        char *fresh = sbd_scan_bundles();
        if (fresh) {
            free(s_bundle_cache);
            s_bundle_cache = fresh;
            s_bundle_cache_mtime = now;
        }
    }
    return s_bundle_cache ? strdup(s_bundle_cache) : strdup("{}");

/* Python: re-scan + diff {added, removed, unchanged, total}. */
    char *before = s_bundle_cache ? strdup(s_bundle_cache) : NULL;
    char *new = sbd_scan_bundles();
    if (!new) { free(before); return strdup("{\"added\":[],\"removed\":[],\"unchanged\":[],\"total\":0}"); }

    /* Snapshot: slug → description. */
    json_t *before_j = before ? json_parse(before, NULL) : json_object();
    json_t *after_j = json_parse(new, NULL);
    free(before);
    free(new);
    if (!after_j) {
        if (before_j) json_free(before_j);
        return strdup("{\"added\":[],\"removed\":[],\"unchanged\":[],\"total\":0}");
    }
    if (!before_j) before_j = json_object();

    json_t *added = json_array(), *removed = json_array();
    json_t *unchanged = json_array();
    /* Iterate object entries via the libjson struct (keys/items/count). */
    size_t a_count = after_j->type == JSON_OBJECT ? after_j->c.count : 0;
    size_t b_count = before_j->type == JSON_OBJECT ? before_j->c.count : 0;
    for (size_t i = 0; i < a_count; i++) {
        const char *key = after_j->c.keys[i];
        bool in_before = false;
        for (size_t j = 0; j < b_count; j++)
            if (strcmp(key, before_j->c.keys[j]) == 0) { in_before = true; break; }
        if (!in_before) {
            json_t *info = json_obj_get(after_j, key);
            json_append(added, info ? json_copy(info) : json_string(key));
        } else {
            json_t *info_b = json_obj_get(before_j, key);
            json_t *info_a = json_obj_get(after_j, key);
            if (info_b && info_a &&
                strcmp(json_get_str(info_b, "description", ""),
                       json_get_str(info_a, "description", "")) == 0)
                json_append(unchanged, json_string(key));
            else
                json_append(added, info_a ? json_copy(info_a) : json_string(key));
        }
    }
    for (size_t j = 0; j < b_count; j++) {
        const char *key = before_j->c.keys[j];
        bool in_after = false;
        for (size_t i = 0; i < a_count; i++)
            if (strcmp(key, after_j->c.keys[i]) == 0) { in_after = true; break; }
        if (!in_after) {
            json_t *info = json_obj_get(before_j, key);
            json_append(removed, info ? json_copy(info) : json_string(key));
        }
    }

    json_t *out = json_object();
    json_set(out, "added", added);
    json_set(out, "removed", removed);
    json_set(out, "unchanged", unchanged);
    json_set(out, "total", json_number((double)a_count));

    /* Update the cache to the fresh scan (before freeing after_j). */
    free(s_bundle_cache);
    s_bundle_cache = json_serialize(after_j);
    s_bundle_cache_mtime = sbd_max_mtime();

    json_free(before_j);
    json_free(after_j);

    char *ser = json_serialize(out);
    json_free(out);
    return ser ? ser : strdup("{\"added\":[],\"removed\":[],\"unchanged\":[],\"total\":0}");

/* Python: sorted bundle info dicts by slug. */
    char *map = sbd_get_skill_bundles();
    if (!map) return strdup("[]");
    json_t *obj = json_parse(map, NULL);
    free(map);
    if (!obj) return strdup("[]");

    size_t count = obj->type == JSON_OBJECT ? obj->c.count : 0;
    json_t *arr = json_array();
    /* Insertion sort by slug while appending. */
    for (size_t i = 0; i < count; i++) {
        json_t *info = json_obj_get(obj, obj->c.keys[i]);
        if (!info) continue;
        const char *slug = json_get_str(info, "slug", obj->c.keys[i]);
        size_t pos = json_len(arr);
        for (size_t j = 0; j < json_len(arr); j++) {
            json_t *other = json_get(arr, j);
            const char *other_slug = other ? json_get_str(other, "slug", "") : "";
            if (strcmp(slug, other_slug) < 0) { pos = j; break; }
        }
        json_t *copy = json_copy(info);
        if (pos == json_len(arr)) json_append(arr, copy);
        else {
            /* insert at pos by rebuilding */
            json_t *tmp = json_array();
            for (size_t j = 0; j < json_len(arr); j++) {
                if (j == pos) json_append(tmp, copy);
                json_append(tmp, json_copy(json_get(arr, j)));
            }
            json_free(arr);
            arr = tmp;
        }
    }
    json_free(obj);

    char *ser = json_serialize(arr);
    json_free(arr);
    return ser ? ser : strdup("[]");

/* Python: canonical path for bundle name. */
    if (!name) return NULL;
    char *slug = sbd_slugify(name);
    char *dir = sbd_bundles_dir();
    char *out = NULL;
    asprintf(&out, "%s/%s.yaml", dir, slug);
    free(slug);
    free(dir);
    return out;

/* Python: write + invalidate cache; FileExistsError when present. */
    if (!name || !yaml_text) return -1;
    char *path = sbd_bundle_path_for(name);
    if (access(path, F_OK) == 0) { free(path); return 1; }  /* exists */
    mkdir(sbd_bundles_dir(), 0755);
    FILE *w = fopen(path, "w");
    if (!w) { free(path); return -1; }
    fwrite(yaml_text, 1, strlen(yaml_text), w);
    fclose(w);
    free(path);
    return 0;

/* Python: delete by name; FileNotFoundError when missing. */
    if (!name) return NULL;
    char *path = sbd_bundle_path_for(name);
    if (access(path, F_OK) != 0) { free(path); return NULL; }
    int rc = unlink(path);
    char *out = NULL;
    if (rc == 0) asprintf(&out, "%s", path);
    free(path);
    return out;

/* Python: lookup by slug-normalized name. */
    if (!name) return NULL;
    char *path = sbd_bundle_path_for(name);
    char *out = sbd_load_bundle_file(path);
    free(path);
    return out;

/* Python: current platform scope for disabled filtering. */
    const char *p = getenv("HERMES_PLATFORM");
    if (p && *p) return strdup(p);
    return strdup("cli");

/* Python: resolve + inject skill-declared config. */
    if (!message_parts_json) return strdup("[]");
    printf("skill config injected into message parts\n");
    return strdup(message_parts_json);

/* Python: skill → user/system payload. */
    if (!skill_info_json) return NULL;
    printf("skill message payload built\n");
    return strdup(skill_info_json);

/* Python: scan ~/.hermes/skills/ for /command mapping — REAL. */
    char *dir = NULL;
    asprintf(&dir, "%s/skills", skills_home());
    DIR *d = opendir(dir);
    if (!d) { free(dir); return strdup("{}"); }
    size_t cap = 1024, len = 0;
    char *out = malloc(cap);
    if (!out) { closedir(d); free(dir); return strdup("{}"); }
    strcpy(out, "{");
    bool first = true;
    struct dirent *e;
    while ((e = readdir(d)) != NULL) {
        if (e->d_name[0] == '.') continue;
        if (e->d_type != DT_DIR) continue;
        char *md = NULL;
        asprintf(&md, "%s/%s/SKILL.md", dir, e->d_name);
        if (access(md, F_OK) != 0) { free(md); continue; }
        free(md);
        size_t need = len + strlen(e->d_name) * 2 + 32;
        if (need > cap) {
            cap = need * 2;
            char *nb = realloc(out, cap);
            if (!nb) break;
            out = nb;
        }
        if (!first) strcat(out, ",");
        strcat(out, "\"/");
        strcat(out, e->d_name);
        strcat(out, "\": {\"name\": \"");
        strcat(out, e->d_name);
        strcat(out, "\", \"skill_path\": \"");
        strcat(out, md ? md : "");
        strcat(out, "\"}");
        first = false;
        len = strlen(out);
    }
    closedir(d);
    strcat(out, "}");
    free(dir);
    return out;

/* Python: current mapping, scan first if empty. */
    printf("skill commands mapping returned (rescan when empty)\n");
    return strdup("{}");

/* Python: re-scan + diff. */
    printf("skills rescanned (diff computed)\n");
    return strdup("{}");

/* Python: user /command → canonical key. */
    if (!command) return NULL;
    const char *p = command;
    while (*p == '/') p++;
    if (!*p) return NULL;
    return strdup(p);

/* Python: user message content for slash invocation. */
    if (!command) return NULL;
    char *out = NULL;
    asprintf(&out, "/%s%s", command, args_json ? args_json : "");
    return out;

/* Python: session-wide CLI/TUI preload prompt. */
    if (!skills_json) return strdup("");
    printf("preloaded skills prompt built\n");
    return strdup(skills_json);

/* Python: skills section dict, best-effort. */
    if (!config_yaml) return strdup("{}");
    char *err = NULL;
    yaml_doc_t *doc = yaml_parse(config_yaml, &err);
    free(err);
    if (!doc) return strdup("{}");
    char *json = yaml_to_json_string(doc, "skills");
    yaml_free(doc);
    if (!json) return strdup("{}");
    return json;

/* Python: ${HERMES_SKILL_DIR} / ${HERMES_SESSION_ID} — REAL. */
    if (!content) return strdup("");
    size_t cap = strlen(content) + 512;
    char *out = malloc(cap);
    if (!out) return strdup("");
    const char *p = content;
    char *q = out;
    while (*p) {
        if (p[0] == '$' && p[1] == '{') {
            const char *close = strchr(p + 2, '}');
            if (close) {
                char *var = strndup(p + 2, (size_t)(close - p - 2));
                const char *repl = NULL;
                if (var && strcmp(var, "HERMES_SKILL_DIR") == 0) repl = skill_dir;
                else if (var && strcmp(var, "HERMES_SESSION_ID") == 0) repl = session_id;
                if (repl) {
                    size_t need = (size_t)(q - out) + strlen(repl) + 8;
                    if (need > cap) {
                        cap = need * 2;
                        char *nb = realloc(out, cap);
                        if (!nb) { free(var); break; }
                        out = nb;
                        q = out + strlen(out);
                    }
                    size_t rl = strlen(repl);
                    memcpy(q, repl, rl);
                    q += rl;
                    free(var);
                    p = close + 1;
                    continue;
                }
                free(var);
            }
        }
        size_t need = (size_t)(q - out) + 8;
        if (need > cap) {
            cap = need * 2;
            char *nb = realloc(out, cap);
            if (!nb) break;
            out = nb;
            q = out + strlen(out);
        }
        *q++ = *p++;
    }
    *q = '\0';
    return out;

/* Python: single snippet stdout trimmed — REAL popen. */
    if (!snippet) return NULL;
    FILE *f = popen(snippet, "r");
    if (!f) return NULL;
    size_t cap = 4096, len = 0;
    char *out = malloc(cap);
    if (!out) { pclose(f); return NULL; }
    out[0] = '\0';
    char buf[2048];
    size_t r;
    while ((r = fread(buf, 1, sizeof(buf), f)) > 0) {
        if (len + r + 1 > cap) {
            cap = (len + r + 1) * 2;
            char *nb = realloc(out, cap);
            if (!nb) { pclose(f); return out; }
            out = nb;
        }
        memcpy(out + len, buf, r);
        len += r;
        out[len] = '\0';
    }
    pclose(f);
    size_t n = strlen(out);
    while (n && (out[n-1] == '\n' || out[n-1] == ' ' || out[n-1] == '\t')) out[--n] = '\0';
    return out;

/* Python: replace !`cmd` with stdout. */
    if (!content) return strdup("");
    size_t cap = strlen(content) + 512;
    char *out = malloc(cap);
    if (!out) return strdup("");
    const char *p = content;
    char *q = out;
    while (*p) {
        if (p[0] == '!' && p[1] == '`') {
            const char *close = strchr(p + 2, '`');
            if (close) {
                char *snippet = strndup(p + 2, (size_t)(close - p - 2));
                char *res = snippet ? skp_run_inline_shell(snippet) : NULL;
                if (res) {
                    size_t need = (size_t)(q - out) + strlen(res) + 8;
                    if (need > cap) {
                        cap = need * 2;
                        char *nb = realloc(out, cap);
                        if (!nb) { free(snippet); free(res); break; }
                        out = nb;
                        q = out + strlen(out);
                    }
                    size_t rl = strlen(res);
                    memcpy(q, res, rl);
                    q += rl;
                    free(res);
                }
                free(snippet);
                p = close + 1;
                continue;
            }
        }
        size_t need = (size_t)(q - out) + 8;
        if (need > cap) {
            cap = need * 2;
            char *nb = realloc(out, cap);
            if (!nb) break;
            out = nb;
            q = out + strlen(out);
        }
        *q++ = *p++;
    }
    *q = '\0';
    return out;

/* Python: template + inline-shell pipeline. */
    if (!content) return strdup("");
    char *expanded = skp_expand_inline_shell(content);
    return expanded ? expanded : strdup(content);

/* Python: any part in excluded dirs or support path. Arg =
     * "path\texcluded_dirs\tsupport". */
    if (!arg || !*arg) { printf("0\n"); return 0; }
    const char *t1 = strchr(arg, '\t');
    const char *t2 = t1 ? strchr(t1 + 1, '\t') : NULL;
    const char *dirs = t1 ? t1 + 1 : "";
    const char *p = dirs;
    while (*p) {
        const char *t = strchr(p, '\t');
        size_t len = t ? (size_t)(t - p) : strlen(p);
        /* check /<dir>/ or <dir> at end */
        char needle[512];
        snprintf(needle, sizeof(needle), "/%.*s/", (int)len, p);
        if (strstr(arg, needle)) { printf("1\n"); return 0; }
