            strcpy(q, "<think>");
            q += 7;
            p += 22;
        } else if (strncmp(p, "</REASONING_SCRATCHPAD>", 23) == 0) {
            size_t need = (size_t)(q - out) + 9;
            if (need > cap) { cap = need * 2; char *nb = realloc(out, cap); if (!nb) break; out = nb; q = out + strlen(out); }
