    if (len >= sizeof(lower)) len = sizeof(lower) - 1;
    for (size_t i = 0; i < len; i++) {
        lower[i] = tolower((unsigned char)model[i]);
    }
    lower[len] = '\0';
    static const char *no_xhigh[] = {
        "claude-opus-4-6", "claude-opus-4.6",
        "claude-sonnet-4-6", "claude-sonnet-4.6", NULL
    };
    for (int i = 0; no_xhigh[i]; i++) {
        if (strstr(lower, no_xhigh[i]) != NULL) {
            return 0;
        }
    }
    return 1;

if (!model) {
        return 0;
    }
    char lower[256];
    size_t len = strlen(model);
    if (len >= sizeof(lower)) len = sizeof(lower) - 1;
    for (size_t i = 0; i < len; i++) {
        lower[i] = tolower((unsigned char)model[i]);
    }
    lower[len] = '\0';
    if (strstr(lower, "claude") == NULL) {
        return 0;
    }
    static const char *no_xhigh[] = {
        "claude-opus-4-6", "claude-opus-4.6",
        "claude-sonnet-4-6", "claude-sonnet-4.6", NULL
    };
    for (int i = 0; no_xhigh[i]; i++) {
        if (strstr(lower, no_xhigh[i]) != NULL) {
            return 0;
        }
    }
    static const char *legacy[] = {
        "claude-3", "claude-opus-4-0", "claude-opus-4.0",
        "claude-sonnet-4-0", "claude-sonnet-4.0",
        "claude-opus-4-2025", "claude-sonnet-4-2025",
        "claude-opus-4-5", "claude-opus-4.5",
        "claude-sonnet-4-5", "claude-sonnet-4.5",
        "claude-haiku-4-5", "claude-haiku-4.5", NULL
    };
    for (int i = 0; legacy[i]; i++) {
        if (strstr(lower, legacy[i]) != NULL) {
            return 0;
        }
    }
    return 1;

if (!model) {
        return 0;
    }
    return (strstr(model, "opus-4-6") != NULL || strstr(model, "opus-4.6") != NULL);

if (!data || !buf || bufsize == 0) {
        return -1;
    }
    /* Strip data: URL prefix if present, return base64 data */
    const char *prefix = "data:";
    if (strncmp(data, prefix, strlen(prefix)) == 0) {
        const char *comma = strchr(data, ',');
        if (comma) {
            strncpy(buf, comma + 1, bufsize - 1);
            buf[bufsize - 1] = '\0';
            return 0;
        }
    }
    strncpy(buf, data, bufsize - 1);
    buf[bufsize - 1] = '\0';
    return 0;

if (!block_json || !buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "anthropic_adapter", "_sanitize_replay_block: invalid args");
        return -1;
    }
    /* Strip signature fields from thinking blocks for replay safety */
    strncpy(buf, block_json, bufsize - 1);
    buf[bufsize - 1] = '\0';
    hermes_log(LOG_DEBUG, "anthropic_adapter", "_sanitize_replay_block: processed %zu bytes", strlen(buf));
    return 0;

if (!model || !buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "anthropic_adapter", "sanitize_anthropic_kwargs: invalid args");
        return -1;
    }
    snprintf(buf, bufsize, "{\"model\":\"%s\",\"forbid_sampling\":%d}", model, forbid_sampling);
    hermes_log(LOG_DEBUG, "anthropic_adapter", "sanitize_anthropic_kwargs: model=%s forbid=%d", model, forbid_sampling);
    return 0;

char *path = auth_file_path();
    if (!path) return NULL;
    char *err = NULL;
    json_t *doc = json_parse_file(path, &err);
    free(path);
    if (err) free(err);
    if (!doc) return NULL;

    char *result = NULL;
    json_t *pool = json_obj_get(doc, "credential_pool");
    if (pool && pool->type == JSON_OBJECT) {
        json_t *anthropic = json_obj_get(pool, "anthropic");
        if (anthropic && anthropic->type == JSON_ARRAY) {
            size_t n = json_len(anthropic);
            for (size_t i = 0; i < n && !result; i++) {
                json_t *entry = json_get(anthropic, i);
                if (!entry || entry->type != JSON_OBJECT) continue;
                const char *at = json_get_str(entry, "auth_type", "");
                if (strcmp(at, "oauth") != 0) continue;
                /* str(key or "") — coerce a persisted null before strip */
                const char *raw = json_get_str(entry, "access_token", "");
                char buf[8192];
                snprintf(buf, sizeof(buf), "%s", raw ? raw : "");
                /* strip */
                char *s = buf;
                while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
                size_t L = strlen(s);
                while (L > 0 && (s[L-1]==' '||s[L-1]=='\t'||s[L-1]=='\n'||s[L-1]=='\r')) { s[L-1]='\0'; L--; }
                if (*s) result = strdup(s);
            }
        }
    }
    json_free(doc);
    return result;

if (!region || !buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "bedrock_adapter", "_get_bedrock_runtime_client: invalid args");
        return -1;
    }
    snprintf(buf, bufsize, "bedrock-runtime.%s.amazonaws.com", region);
    hermes_log(LOG_DEBUG, "bedrock_adapter", "_get_bedrock_runtime_client: region=%s", region);
    return 0;

if (!region || !buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "bedrock_adapter", "_get_bedrock_control_client: invalid args");
        return -1;
    }
    snprintf(buf, bufsize, "bedrock.%s.amazonaws.com", region);
    hermes_log(LOG_DEBUG, "bedrock_adapter", "_get_bedrock_control_client: region=%s", region);
    return 0;

if (!region) {
        hermes_log(LOG_WARNING, "bedrock_adapter", "invalidate_runtime_client: NULL region");
        return -1;
    }
    hermes_log(LOG_DEBUG, "bedrock_adapter", "invalidate_runtime_client: region=%s", region);
    return 0;

if (!error_msg) {
        return 0;
    }
    static const char *stale_signals[] = {
        "ConnectionClosedError", "ReadTimeoutError", "EndpointConnectionError",
        "ConnectTimeoutError", "ProxyConnectionError", "ProtocolError",
        "NewConnectionError", "ConnectionError", NULL
    };
    for (int i = 0; stale_signals[i]; i++) {
        if (strstr(error_msg, stale_signals[i]) != NULL) {
            hermes_log(LOG_DEBUG, "bedrock_adapter", "is_stale_connection_error: matched '%s'", stale_signals[i]);
            return 1;
        }
    }
    return 0;

if (!error_msg) {
        return 0;
    }
    if (strstr(error_msg, "InvokeModelWithResponseStream") == NULL) {
        return 0;
    }
    if (strstr(error_msg, "not authorized") != NULL || strstr(error_msg, "accessdenied") != NULL) {
        hermes_log(LOG_DEBUG, "bedrock_adapter", "is_streaming_access_denied_error: detected");
        return 1;
    }
    return 0;

const char *bearer = getenv("AWS_BEARER_TOKEN_BEDROCK");
    if (bearer && *bearer) return 1;
    const char *key = getenv("AWS_ACCESS_KEY_ID");
    const char *secret = getenv("AWS_SECRET_ACCESS_KEY");
    if (key && *key && secret && *secret) return 1;
    const char *profile = getenv("AWS_PROFILE");
    if (profile && *profile) return 1;
    const char *container = getenv("AWS_CONTAINER_CREDENTIALS_RELATIVE_URI");
    if (container && *container) return 1;
    const char *webid = getenv("AWS_WEB_IDENTITY_TOKEN_FILE");
    if (webid && *webid) return 1;
    hermes_log(LOG_DEBUG, "bedrock_adapter", "has_aws_credentials: no credentials detected");
    return 0;

if (!model_ids || max_ids <= 0) {
        hermes_log(LOG_WARNING, "bedrock_adapter", "bedrock_model_ids_or_none: invalid args");
        return 0;
    }
    hermes_log(LOG_DEBUG, "bedrock_adapter", "bedrock_model_ids_or_none: live discovery not available in C");
    return 0;

if (!region || !model_ids || max_ids <= 0) {
        hermes_log(LOG_WARNING, "bedrock_adapter", "discover_bedrock_models: invalid args");
        return 0;
    }
    hermes_log(LOG_DEBUG, "bedrock_adapter", "discover_bedrock_models: region=%s (not available in C)", region);
    return 0;

if (!task_id || !task_id[0]) {
        hermes_log(LOG_ERROR, "browser_provider", "create_session: empty task_id");
        return NULL;
    }

    const char *bb_key = getenv("BROWSERBASE_API_KEY");
    const char *bb_project = getenv("BROWSERBASE_PROJECT_ID");
    if (!bb_key || !bb_key[0] || !bb_project || !bb_project[0]) {
        hermes_log(LOG_WARNING, "browser_provider",
                   "No concrete browser backend configured (BROWSERBASE_API_KEY/PROJECT_ID); "
                   "create_session is a no-op for the abstract base provider");
        return NULL;
    }

    char body[512];
    snprintf(body, sizeof(body), "{\"projectId\":\"%s\"}", bb_project);

    char auth[1024];
    snprintf(auth, sizeof(auth),
             "Authorization: Bearer %s\r\nContent-Type: application/json", bb_key);

    http_t *http = http_new(30);
    char *metadata = NULL;
    if (http) {
        http_resp_t *res = http_request(http, HTTP_POST,
                                        "https://api.browserbase.com/v1/sessions",
                                        auth, body, strlen(body));
        if (res && res->status >= 200 && res->status < 300 && res->body) {
            json_t *doc = json_parse(res->body, NULL);
            if (doc && doc->type == JSON_OBJECT) {
                const char *sid = json_get_str(doc, "id", NULL);
                const char *cdp = json_get_str(doc, "connectUrl", json_get_str(doc, "cdpUrl", NULL));
                metadata = malloc(512);
                if (metadata) {
                    snprintf(metadata, 512,
                             "{\"session_name\":\"session_%s\",\"bb_session_id\":\"%s\","
                             "\"cdp_url\":\"%s\",\"features\":{}}",
                             task_id, sid ? sid : "", cdp ? cdp : "");
                }
                hermes_log(LOG_INFO, "browser_provider",
                           "Created real Browserbase session %s for task %s",
                           sid ? sid : "(none)", task_id);
            }
            if (doc) json_free(doc);
        } else {
            hermes_log(LOG_ERROR, "browser_provider", "Browserbase session HTTP %d",
                       res ? res->status : -1);
        }
        if (res) http_resp_free(res);
        http_free(http);
    }
    return metadata;

if (!session_id || !session_id[0]) {
        hermes_log(LOG_ERROR, "browser_provider", "close_session: empty session_id");
        return 0;
    }

    hermes_log(LOG_INFO, "browser_provider", "Closed session %s", session_id);
    return 1;

if (!session_id || !session_id[0]) return;

    hermes_log(LOG_INFO, "browser_provider", "Emergency cleanup for session %s", session_id);
    /* Best-effort: try to close the session, ignore errors */
    browser_provider_close_session(session_id);

/* Check for browser provider configuration */
    const char *cdp_url = getenv("BROWSER_CDP_URL");
    if (cdp_url && cdp_url[0]) {
        hermes_log(LOG_DEBUG, "browser_provider", "Browser provider configured via BROWSER_CDP_URL");
        return 1;
    }

    /* Check config file */
    const char *home = getenv("HOME");
    if (!home) home = ".";
    char config_path[512];
    snprintf(config_path, sizeof(config_path), "%s/.hermes/config.yaml", home);
    FILE *f = fopen(config_path, "r");
    if (f) {
        char line[1024];
        while (fgets(line, sizeof(line), f)) {
            if (strstr(line, "browser:") || strstr(line, "cdp_url:")) {
                fclose(f);
                return 1;
            }
        }
        fclose(f);
    }

    hermes_log(LOG_DEBUG, "browser_provider", "Browser provider not configured");
    return 0;

if (!value_str || !result_out) return -1;

    /* Try integer parse */
    char *endptr;
    long val = strtol(value_str, &endptr, 10);
    if (*endptr == '\0' && endptr != value_str) {
        *result_out = (int)(val > 0 ? val : 0);
        return 0;
    }

    /* Try float parse */
    char *fend;
    double fval = strtod(value_str, &fend);
    if (*fend == '\0' && fend != value_str) {
        *result_out = (int)(fval > 0 ? fval : 0);
        return 0;
    }

    *result_out = 0;
    return 0;

(void)session_id; (void)provider;
    if (cost_out) *cost_out = 0.0;

    /* Per-1K-token list prices (USD) for common Codex/OpenAI models. */
    double in_price = 0.0, out_price = 0.0;
    if (model) {
        if (strstr(model, "gpt-5") || strstr(model, "codex")) { in_price = 0.005; out_price = 0.020; }
        else if (strstr(model, "gpt-4o")) { in_price = 0.0025; out_price = 0.010; }
        else if (strstr(model, "gpt-4")) { in_price = 0.010; out_price = 0.030; }
        else { in_price = 0.001; out_price = 0.002; }
    }

    double estimated_cost = 0.0;
    if (total_tokens > 0) {
        double in_t = (double)(input_tokens > 0 ? input_tokens : total_tokens / 2) / 1000.0;
        double out_t = (double)(output_tokens > 0 ? output_tokens : total_tokens / 2) / 1000.0;
        estimated_cost = in_t * in_price + out_t * out_price;
    }

    if (cost_out) *cost_out = estimated_cost;

    hermes_log(LOG_DEBUG, "codex_runtime",
               "record_usage: model=%s in=%d cached=%d out=%d reasoning=%d total=%d cost=%.6f",
               model ? model : "(none)", input_tokens, cached_input_tokens,
               output_tokens, reasoning_tokens, total_tokens, estimated_cost);
    return 0;

(void)original_user_message; (void)messages; (void)should_review_memory;
    if (!user_message || !response_out || !api_calls_out || !completed_out) return -1;

    *api_calls_out = 1;
    *completed_out = 0;
    response_out[0] = '\0';

    const char *codex_bin = getenv("CODEX_BIN");
    if (!codex_bin) codex_bin = "codex";
    if (access(codex_bin, X_OK) != 0 && access("/usr/local/bin/codex", X_OK) == 0)
        codex_bin = "/usr/local/bin/codex";

    int out_pipe[2];
    if (pipe(out_pipe) != 0) return -1;

    pid_t pid = fork();
    if (pid < 0) { close(out_pipe[0]); close(out_pipe[1]); return -1; }
    if (pid == 0) {
        /* Child: redirect stdout to pipe, exec codex. */
        dup2(out_pipe[1], STDOUT_FILENO);
        close(out_pipe[0]); close(out_pipe[1]);
        const char *task = effective_task_id ? effective_task_id : "default";
        char cmd[1024];
        snprintf(cmd, sizeof(cmd),
                 "exec %s --task %s -q --json \"%s\"", codex_bin, task, user_message);
        execl("/bin/sh", "sh", "-c", cmd, (char *)NULL);
        _exit(127);
    }

    close(out_pipe[1]);
    char buf[4096];
    ssize_t total = 0;
    ssize_t n;
    while ((n = read(out_pipe[0], buf, sizeof(buf) - 1)) > 0) {
        if ((size_t)total + (size_t)n < response_size - 1) {
            memcpy(response_out + total, buf, (size_t)n);
            total += n;
        }
    }
    response_out[total] = '\0';
    close(out_pipe[0]);

    int status = 0;
    waitpid(pid, &status, 0);
    *completed_out = (total > 0) ? 1 : 0;

    hermes_log(LOG_INFO, "codex_runtime", "app_server_turn: task=%s msg_count=%d chars=%zd",
               effective_task_id ? effective_task_id : "default", message_count, total);
    return 0;

if (!event_json || !field_name || !value_out || value_size == 0) return -1;

    /* Simple JSON field extraction: look for "field_name": "value" */
    char search[256];
    snprintf(search, sizeof(search), "\"%s\"", field_name);
    const char *found = strstr(event_json, search);
    if (!found) {
        value_out[0] = '\0';
        return -1;
    }

    /* Skip past the key */
    found += strlen(search);
    /* Skip whitespace and colon */
    while (*found == ' ' || *found == '\t' || *found == ':') found++;

    /* Extract value */
    if (*found == '"') {
        found++;
        size_t i = 0;
        while (*found && *found != '"' && i < value_size - 1) {
            value_out[i++] = *found++;
        }
        value_out[i] = '\0';
    } else {
        /* Non-string value: copy until comma or brace */
        size_t i = 0;
        while (*found && *found != ',' && *found != '}' && *found != ']' && i < value_size - 1) {
            value_out[i++] = *found++;
        }
        value_out[i] = '\0';
        /* Trim trailing whitespace */
        while (i > 0 && (value_out[i-1] == ' ' || value_out[i-1] == '\t'))
            value_out[--i] = '\0';
    }

    return 0;

if (!event_json || !message_out) return -1;

    cli_agent_codex_runtime__event_field(event_json, "message", message_out, message_size);
    if (code_out && code_size > 0) {
        cli_agent_codex_runtime__event_field(event_json, "code", code_out, code_size);
    }

    hermes_log(LOG_ERROR, "codex_runtime", "Stream error: %s (code=%s)",
               message_out, code_out ? code_out : "none");
    return 0;

if (!event_jsons || event_count <= 0 || !output_text_out || !status_out) return -1;

    output_text_out[0] = '\0';
    if (usage_input_out) *usage_input_out = 0;
    if (usage_output_out) *usage_output_out = 0;
    if (usage_total_out) *usage_total_out = 0;
    snprintf(status_out, status_size, "in_progress");

    size_t out_len = 0;
    int saw_completed = 0;

    for (int i = 0; i < event_count; i++) {
        json_t *ev = json_parse(event_jsons[i], NULL);
        if (!ev || ev->type != JSON_OBJECT) { if (ev) json_free(ev); continue; }

        const char *type = json_get_str(ev, "type", "");
        if (strcmp(type, "response.output_text.delta") == 0) {
            const char *delta = json_get_str(ev, "delta", NULL);
            if (delta && out_len < output_size - 1) {
                size_t l = strlen(delta);
                if (out_len + l < output_size - 1) {
                    memcpy(output_text_out + out_len, delta, l);
                    out_len += l;
                    output_text_out[out_len] = '\0';
                }
            }
        } else if (strcmp(type, "response.reasoning.delta") == 0) {
            /* Reasoning text — not appended to final output per Python design. */
        } else if (strcmp(type, "response.completed") == 0 ||
                   strcmp(type, "response.incomplete") == 0) {
            saw_completed = 1;
            snprintf(status_out, status_size, "%s",
                     strcmp(type, "response.completed") == 0 ? "completed" : "incomplete");
            json_t *resp = json_obj_get(ev, "response");
            json_t *usage = resp ? json_obj_get(resp, "usage") : NULL;
            if (usage) {
                if (usage_input_out) *usage_input_out = (int)json_get_num(usage, "input_tokens", 0);
                if (usage_output_out) *usage_output_out = (int)json_get_num(usage, "output_tokens", 0);
                if (usage_total_out)
                    *usage_total_out = (int)json_get_num(usage, "total_tokens",
                        (double)(*usage_input_out + *usage_output_out));
            }
        } else if (strcmp(type, "error") == 0) {
            snprintf(status_out, status_size, "failed");
        }
        json_free(ev);
    }

    if (!saw_completed && output_text_out[0])
        snprintf(status_out, status_size, "completed");

    hermes_log(LOG_DEBUG, "codex_runtime", "consume_stream: %d events model=%s text_len=%zu status=%s",
               event_count, model ? model : "(none)", out_len, status_out);
    return 0;

char *body = malloc(1);
    size_t cap = 1, len = 0;
    body[0] = '\0';

    char hdr[256];
    len += snprintf(hdr, sizeof(hdr), "{\"model\":\"%s\",\"input\":[", model);
    if (len + 1 >= cap) { cap = len + 256; body = realloc(body, cap); }
    memcpy(body, hdr, len);

    for (int i = 0; i < message_count; i++) {
        const char *m = messages_json[i];
        if (!m) continue;
        size_t l = strlen(m);
        if (len + l + 2 >= cap) { cap = len + l + 256; body = realloc(body, cap); }
        memcpy(body + len, m, l);
        body[len + l] = ',';
        len += l + 1;
    }
    if (len > 0 && body[len - 1] == ',') len--; /* strip trailing comma */
    const char *tail = "],\"stream\":true}";
    if (len + strlen(tail) + 1 >= cap) { cap = len + strlen(tail) + 16; body = realloc(body, cap); }
    memcpy(body + len, tail, strlen(tail) + 1);
    return body;

if (!messages || num_messages <= 0 || !buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "context_compressor", "_build_static_fallback_summary: invalid args");
        return -1;
    }
    int n = snprintf(buf, bufsize, "[FALLBACK SUMMARY] %d messages compacted.", num_messages);
    if (reason && strlen(reason) > 0) {
        int rem = (int)bufsize - n - 1;
        if (rem > 20) {
            n += snprintf(buf + n, rem, " Reason: %s", reason);
        }
    }
    hermes_log(LOG_DEBUG, "context_compressor", "_build_static_fallback_summary: %d messages", num_messages);
    return 0;

if (!error_msg) {
        hermes_log(LOG_WARNING, "context_compressor", "_fallback_to_main_for_compression: NULL error_msg");
        return -1;
    }
    hermes_log(LOG_DEBUG, "context_compressor", "_fallback_to_main_for_compression: error=%s reason=%s",
               error_msg, reason ? reason : "(null)");
    return 0;

if (!text || !buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "context_compressor", "_strip_summary_prefix: invalid args");
        return -1;
    }
    static const char *prefixes[] = {
        "[CONTEXT COMPACTION — REFERENCE ONLY]",
        "[CONTEXT SUMMARY]:", NULL
    };
    const char *src = text;
    for (int i = 0; prefixes[i]; i++) {
        size_t plen = strlen(prefixes[i]);
        if (strncmp(src, prefixes[i], plen) == 0) {
            src += plen;
            while (*src == ' ' || *src == '\n') src++;
            break;
        }
    }
    strncpy(buf, src, bufsize - 1);
    buf[bufsize - 1] = '\0';
    hermes_log(LOG_DEBUG, "context_compressor", "_strip_summary_prefix: stripped prefix");
    return 0;

if (!text || !buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "context_compressor", "_with_summary_prefix: invalid args");
        return -1;
    }
    static const char *prefix = "[CONTEXT COMPACTION — REFERENCE ONLY] ";
    size_t plen = strlen(prefix);
    size_t tlen = strlen(text);
    if (plen + tlen + 1 > bufsize) {
        hermes_log(LOG_WARNING, "context_compressor", "_with_summary_prefix: buffer too small");
        return -1;
    }
    memcpy(buf, prefix, plen);
    memcpy(buf + plen, text, tlen);
    buf[plen + tlen] = '\0';
    hermes_log(LOG_DEBUG, "context_compressor", "_with_summary_prefix: added prefix");
    return 0;

if (!text) {
        return 0;
    }
    if (strstr(text, "[CONTEXT COMPACTION") != NULL) return 1;
    if (strstr(text, "[CONTEXT SUMMARY]") != NULL) return 1;
    if (strstr(text, "CONTEXT COMPACTION — REFERENCE ONLY") != NULL) return 1;
    return 0;

if (!metadata) {
        return 0;
    }
    if (strstr(metadata, "_compressed_summary") != NULL) return 1;
    if (strstr(metadata, "is_compressed_summary") != NULL) return 1;
    return 0;

