        int is_assign = 0;
        if (w && w[0] && ((w[0] >= 'A' && w[0] <= 'Z') || (w[0] >= 'a' && w[0] <= 'z') || w[0] == '_')) {
            size_t k = 1;
            for (; w[k] && w[k] != '='; k++) {
                char c = w[k];
                if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                      (c >= '0' && c <= '9') || c == '_')) break;
            }
            if (w[k] == '=') is_assign = 1;
        }
        if (!is_assign) break;
        index++;
