        if (*body == '{') {
            /* Find matching closing brace */
            int depth = 0;
            const char *end = body;
            for (; *end; end++) {
                if (*end == '{') depth++;
                else if (*end == '}') {
                    depth--;
                    if (depth == 0) { end++; break; }
                }
            }
            size_t len = (size_t)(end - body);
            char *result = (char *)malloc(len + 1);
            if (result) {
                memcpy(result, body, len);
                result[len] = '\0';
