            err += 7;
            while (*err == ' ' || *err == '\t' || *err == ':') err++;
            if (*err == '{') {
                const char *msg = strstr(err, "\"message\"");
                if (msg) {
                    msg += 9;
                    while (*msg == ' ' || *msg == '\t' || *msg == ':') msg++;
                    if (*msg == '"') {
                        msg++;
                        /* Find closing quote */
                        const char *end = msg;
                        while (*end && *end != '"') end++;
                        size_t len = (size_t)(end - msg);
                        if (len > 500) len = 500;
                        char *result = (char *)malloc(len + 1);
                        if (result) {
                            memcpy(result, msg, len);
                            result[len] = '\0';
                            free(body);
