            while (*msg == ' ' || *msg == '\t' || *msg == ':') msg++;
            if (*msg == '"') {
                msg++;
                const char *end = msg;
                while (*end && *end != '"') end++;
                size_t len = (size_t)(end - msg);
                if (len > 500) len = 500;
                char *result = (char *)malloc(len + 1);
                if (result) {
