        http_resp_t *res = http_request(http, HTTP_POST, url, hdr, body, strlen(body));
        if (res && res->body) {
            result = strdup(res->body);
        } else {
            hermes_log(LOG_ERROR, "gemini_adapter", "streamGenerateContent HTTP %d", res ? res->status : -1);
