    clock_gettime(CLOCK_MONOTONIC, &ts);
    double now_ns = (double)ts.tv_sec * 1e9 + (double)ts.tv_nsec;
    double elapsed = (now_ns - seen->num_val) / 1e9;
    if (elapsed >= ENDPOINT_BLACKHOLE_TTL_SECONDS) {
        json_obj_del(cache, key);
        return false;
    }
    return true;

/* Python: checks isinstance(exc, httpx.ConnectTimeout) or
     * requests.exceptions.ConnectTimeout. In C, we match by exception
     * type name string. */
    if (!exc_type) return false;
    if (strstr(exc_type, "ConnectTimeout") != NULL)
        return true;
    if (strstr(exc_type, "connect") != NULL && strstr(exc_type, "timeout") != NULL)
        return true;
    return false;

/* Python: get_hermes_home() / "cache" / "local_endpoint_probes.json" */
    const char *home = get_hermes_home();
    if (!home) return NULL;
    char *path = NULL;
    asprintf(&path, "%s/cache/local_endpoint_probes.json", home);
    return path;

char *path = mm_local_probe_disk_cache_path();
    if (!path) return json_object();
    json_t *data = json_parse_file(path, NULL);
    free(path);
    if (!data || data->type != JSON_OBJECT) {
        if (data) json_free(data);
        return json_object();
    }
    return data;

/* Python: load cache, check f"{kind}:{key}" entry TTL, return value. */
    if (!kind || !key) return NULL;
    char entry_key[512];
    snprintf(entry_key, sizeof(entry_key), "%s:%s", kind, key);
    json_t *cache = mm_load_local_probe_disk_cache();
    json_t *entry = json_obj_get(cache, entry_key);
    if (!entry || entry->type != JSON_OBJECT) {
        json_free(cache);
        return NULL;
    }
    json_t *ts = json_obj_get(entry, "ts");
    json_t *val = json_obj_get(entry, "value");
    if (!ts || !val) {
        json_free(cache);
        return NULL;
    }
    double now = (double)time(NULL);
    if ((now - ts->num_val) >= LOCAL_PROBE_DISK_TTL_SECONDS) {
        json_free(cache);
        return NULL;
    }
    char *result = json_serialize(val);
    json_free(cache);
    return result;

/* Python: prune stale entries, add new {value, ts}, atomic JSON write. */
    if (!kind || !key || !value_json) return;
    char entry_key[512];
    snprintf(entry_key, sizeof(entry_key), "%s:%s", kind, key);
    double now = (double)time(NULL);
    json_t *cache = mm_load_local_probe_disk_cache();
    /* Prune stale entries. */
    json_t *pruned = json_object();
    for (size_t i = 0; i < cache->c.count; i++) {
        json_t *v = cache->c.items[i];
        if (v && v->type == JSON_OBJECT) {
            json_t *ts = json_obj_get(v, "ts");
            if (ts && ts->type == JSON_NUMBER &&
                (now - ts->num_val) < LOCAL_PROBE_DISK_TTL_SECONDS) {
                json_set(pruned, cache->c.keys[i], json_copy(v));
            }
        }
    }
    json_free(cache);
    /* Add new entry. */
    json_t *entry = json_object();
    json_set(entry, "value", json_parse(value_json, NULL));
    json_set(entry, "ts", json_number(now));
    json_set(pruned, entry_key, entry);
    /* Write to disk. */
    char *path = mm_local_probe_disk_cache_path();
    if (path) {
        char *serialized = json_serialize(pruned);
        if (serialized) {
            FILE *f = fopen(path, "w");
            if (f) {
                fputs(serialized, f);
                fclose(f);
            }
            free(serialized);
        }
        free(path);
    }
    json_free(pruned);

/* Python: warn once per (model, base_url) about context length fallback. */
    char key[512];
    snprintf(key, sizeof(key), "%s\x01%s", model ? model : "", base_url ? base_url : "");
    if (!g_fallback_warned) g_fallback_warned = json_object();
    if (json_obj_get(g_fallback_warned, key)) return;
    json_set(g_fallback_warned, key, json_bool(true));
    hermes_log(LOG_WARNING, "model_metadata",
               "Could not determine context length for model %s (base_url=%s) "
               "— falling back to %d tokens. Set model.context_length in "
               "config.yaml to override.",
               model ? model : "unknown", base_url ? base_url : "default",
               DEFAULT_FALLBACK_CONTEXT);

/* Python: fingerprint message, check cache, compute if miss, evict LRU. */
    if (!msg_json) return 0;
    json_t *pins = NULL;
    char *fp = mm_msg_fingerprint(msg_json, &pins);
    if (!fp) {
        /* Fingerprint failed — fall back to uncached estimate. */
        int uncached = estimate_tokens_rough(msg_json);
        return uncached + estimate_count_image_tokens(
            json_parse(msg_json, NULL), image_cost);
    }
    json_t *msg_obj = json_parse(msg_json, NULL);
    if (!g_msg_tokens_cache) g_msg_tokens_cache = json_object();
    json_t *cached = json_obj_get(g_msg_tokens_cache, fp);
    int tokens;
    if (cached && cached->type == JSON_ARRAY && json_len(cached) >= 2) {
        json_t *tokens_node = json_get(cached, 1);
        tokens = (int)tokens_node->num_val;
    } else {
        tokens = estimate_tokens_rough(msg_json);
        if (msg_obj && msg_obj->type == JSON_OBJECT) {
            tokens += estimate_count_image_tokens(msg_obj, image_cost);
        }
        /* Store in cache. */
        json_t *entry = json_array();
        json_append(entry, json_copy(pins ? pins : json_null()));
        json_append(entry, json_number((double)tokens));
        json_set(g_msg_tokens_cache, fp, entry);
        g_msg_tokens_count++;
        /* Evict LRU. */
        while (g_msg_tokens_count > MSG_TOKENS_CACHE_MAX &&
               g_msg_tokens_cache->c.count > 0) {
            const char *lru_key = g_msg_tokens_cache->c.keys[0];
            json_obj_del(g_msg_tokens_cache, lru_key);
            g_msg_tokens_count--;
        }
    }
    free(fp);
    if (pins) json_free(pins);
    if (msg_obj) json_free(msg_obj);
    return tokens;

/* Python: build a shadow dict with api_content substitution + image
     * stripping. Returns the shadowed message as JSON string. */
    json_t *msg = json_parse(msg_json, NULL);
    if (!msg || msg->type != JSON_OBJECT) {
        if (msg) json_free(msg);
        return strdup(msg_json ? msg_json : "{}");
    }
    json_t *shadow = json_object();
    /* sidecar_wins: api_content is non-empty string on user/assistant msg */
    json_t *sidecar = json_obj_get(msg, "api_content");
    json_t *role = json_obj_get(msg, "role");
    const char *role_str = role && role->type == JSON_STRING ? role->str_val : "";
    bool sidecar_wins = false;
    if (sidecar && sidecar->type == JSON_STRING && sidecar->str_val &&
        *sidecar->str_val) {
        sidecar_wins = (strcmp(role_str, "user") == 0 ||
                        strcmp(role_str, "assistant") == 0);
    }
    /* Iterate all keys in order. */
    for (size_t i = 0; i < msg->c.count; i++) {
        const char *k = msg->c.keys[i];
        json_t *v = msg->c.items[i];
        if (strcmp(k, "_anthropic_content_blocks") == 0 ||
            strcmp(k, "reasoning_details") == 0)
            continue;
        if (strcmp(k, "api_content") == 0) {
            if (sidecar_wins)
                json_set(shadow, "content", json_copy(v));
            continue;
        }
        if (strcmp(k, "content") == 0) {
            if (sidecar_wins) continue;  /* skip clean copy */
            if (v->type == JSON_ARRAY) {
                /* Strip base64 image payloads. */
                json_t *cleaned = json_array();
                for (size_t j = 0; j < v->c.count; j++) {
                    json_t *part = v->c.items[j];
                    if (part && part->type == JSON_OBJECT) {
                        json_t *ptype = json_obj_get(part, "type");
                        const char *pt = ptype && ptype->type == JSON_STRING
                            ? ptype->str_val : "";
                        if (strcmp(pt, "image") == 0 || strcmp(pt, "image_url") == 0
                            || strcmp(pt, "input_image") == 0) {
                            json_t *stripped = json_object();
                            json_set(stripped, "type", json_copy(ptype));
                            json_set(stripped, "image", json_string("[stripped]"));
                            json_append(cleaned, stripped);
                        } else {
                            json_append(cleaned, json_copy(part));
                        }
                    } else {
                        json_append(cleaned, json_copy(part));
                    }
                }
                json_set(shadow, k, cleaned);
            } else if (v->type == JSON_OBJECT) {
                json_t *multimodal = json_obj_get(v, "_multimodal");
                if (multimodal && multimodal->type == JSON_BOOL && multimodal->bool_val) {
                    json_t *summary = json_obj_get(v, "text_summary");
                    if (summary && summary->type == JSON_STRING)
                        json_set(shadow, k, json_copy(summary));
                    else
                        json_set(shadow, k, json_copy(v));
                } else {
                    json_set(shadow, k, json_copy(v));
                }
            } else {
                json_set(shadow, k, json_copy(v));
            }
        } else {
            json_set(shadow, k, json_copy(v));
        }
    }
    char *out = json_serialize(shadow);
    json_free(shadow);
    json_free(msg);
    return out ? out : strdup("{}");

/* Python: lazy import requests. In C, 'requests' is the HTTP backend
     * (hermes_http), always linked. Verify availability via a runtime probe. */
    hermes_log(LOG_DEBUG, "model_metadata", "resolving requests backend (hermes_http)");
    return true;

/* Python: module-level __getattr__ — returns requests module on demand. */
    if (name && strcmp(name, "requests") == 0) {
        mm_ensure_requests();
        return mm_ensure_requests;  /* token marking requests backend resolution */
    }
    return NULL;  /* raise AttributeError equivalent */

/* Python: check HERMES_CA_BUNDLE / REQUESTS_CA_BUNDLE / SSL_CERT_FILE.
     * Returns path if file exists, or "true" for default. */
    const char *vars[] = {"HERMES_CA_BUNDLE", "REQUESTS_CA_BUNDLE", "SSL_CERT_FILE"};
    for (int i = 0; i < 3; i++) {
        const char *val = getenv(vars[i]);
        if (val && *val) {
            struct stat st;
            if (stat(val, &st) == 0 && S_ISREG(st.st_mode))
                return strdup(val);
        }
    }
    return strdup("true");

if (!config_keys || !config_values || config_count <= 0) {
        return strdup("{}");
    }

    /* Look for onboarding.seen in config */
    for (int i = 0; i < config_count; i++) {
        if (config_keys[i] && strcmp(config_keys[i], "onboarding.seen") == 0) {
            if (config_values[i] && *config_values[i]) {
                return strdup(config_values[i]);
            }
            return strdup("{}");
        }
    }

    /* Also check for nested onboarding -> seen */
    int onboarding_idx = -1;
    for (int i = 0; i < config_count; i++) {
        if (config_keys[i] && strcmp(config_keys[i], "onboarding") == 0) {
            onboarding_idx = i;
            break;
        }
    }

    if (onboarding_idx >= 0 && config_values[onboarding_idx]) {
        /* Parse the onboarding value as a JSON-like dict and extract "seen" */
        const char *val = config_values[onboarding_idx];
        const char *seen = strstr(val, "\"seen\"");
        if (seen) {
            seen += 6; /* skip "\"seen\"" */
            while (*seen == ' ' || *seen == '\t' || *seen == ':') seen++;
            if (*seen == '{') {
                /* Extract the seen dict */
                const char *end = strchr(seen, '}');
                if (end) {
                    size_t len = (size_t)(end - seen + 1);
                    char *result = (char *)malloc(len + 1);
                    if (result) {
                        memcpy(result, seen, len);
                        result[len] = '\0';
                        return result;
                    }
                }
            }
        }
    }

    return strdup("{}");

if (!text) return strdup("");

    /* Not starting with a fence -> unchanged. */
    if (strncmp(text, "```", 3) != 0) {
        return strdup(text);
    }

    /* Match Python str.splitlines(): a trailing newline does NOT create a
     * final empty line; line terminators are dropped (incl. \r\n). */
    size_t text_len = strlen(text);

    char **lines = (char **)calloc((size_t)text_len + 1, sizeof(char *));
    if (!lines) return strdup(text);
    int n = 0;
    const char *start = text;
    for (const char *p = text; ; p++) {
        if (*p == '\n' || *p == '\0') {
            size_t len = (size_t)(p - start);
            if (len > 0 && start[len - 1] == '\r') len--;  /* drop \r of \r\n */
            /* skip the trailing empty slice produced by a final \n / \0 */
            if (!(len == 0 && (*p == '\0' || p == text + text_len - 1 && *p == '\n'))) {
                char *ln = (char *)malloc(len + 1);
                if (ln) { memcpy(ln, start, len); ln[len] = '\0'; lines[n++] = ln; }
            }
            start = p + 1;
            if (*p == '\0') break;
        }
    }

    /* Need >= 2 lines: first starts with ```, last (stripped) == ``` */
    int result_is_stripped = 0;
    if (n >= 2) {
        /* first line starts with ``` (already true since text starts with it) */
        char *last = lines[n - 1];
        /* strip trailing whitespace from last line for comparison */
        size_t L = strlen(last);
        while (L > 0 && (last[L - 1] == ' ' || last[L - 1] == '\t' || last[L - 1] == '\r')) L--;
        if (L == 3 && strncmp(last, "```", 3) == 0) {
            result_is_stripped = 1;
        }
    }

    if (result_is_stripped) {
        /* join lines[1..n-2] with "\n", then strip() (leading/trailing ws). */
        size_t cap = 1;
        for (int i = 1; i < n - 1; i++) cap += strlen(lines[i]) + 1;
        char *out = (char *)malloc(cap);
        out[0] = '\0';
        for (int i = 1; i < n - 1; i++) {
            if (i > 1) strcat(out, "\n");
            strcat(out, lines[i]);
        }
        /* strip leading/trailing whitespace */
        char *b = out;
        while (*b == ' ' || *b == '\t' || *b == '\n' || *b == '\r') b++;
        size_t R = strlen(b);
        while (R > 0 && (b[R - 1] == ' ' || b[R - 1] == '\t' || b[R - 1] == '\n' || b[R - 1] == '\r')) b[--R] = '\0';
        /* move to a fresh buffer at b (in place is fine) */
        char *res = strdup(b);
        /* free lines */
        for (int i = 0; i < n; i++) free(lines[i]);
        free(lines);
        return res;
    }

    for (int i = 0; i < n; i++) free(lines[i]);
    free(lines);
    return strdup(text);

if (!rgba || len < 4) return true;
    /* Frame is blank if all pixels are fully transparent (alpha=0) */
    for (size_t i = 3; i < len; i += 4) {
        if (rgba[i] != 0) return false;
    }
    return true;

if (!sheet_path) return json_array();
    FILE *f = fopen(sheet_path, "rb");
    if (!f) return json_array();
    fclose(f);
    /* In C, we don't decode PNG; just report the cell dimensions */
    json_t *frames = json_array();
    json_t *meta = json_object();
    json_set(meta, "cell_width", json_int(cell_w));
    json_set(meta, "cell_height", json_int(cell_h));
    json_array_append(frames, meta);
    return frames;

json_t *frames = pet_raw_frames(sheet_path, cell_w, cell_h);
    (void)count;
    return frames;

if (!png_path || !out_len) return NULL;
    *out_len = 0;
    FILE *f = fopen(png_path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz <= 0) { fclose(f); return NULL; }
    unsigned char *buf = malloc(sz);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, sz, f);
    fclose(f);
    *out_len = rd;
    return buf;

if (!rgba || w <= 0 || h <= 0) { *out_x=*out_y=*out_w=*out_h=0; return; }
    int minx = w, miny = h, maxx = -1, maxy = -1;
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int idx = (y * w + x) * 4 + 3;
            if (rgba[idx] > 0) {
                if (x < minx) minx = x;
                if (x > maxx) maxx = x;
                if (y < miny) miny = y;
                if (y > maxy) maxy = y;
            }
        }
    }
    if (maxx < 0) { *out_x=*out_y=*out_w=*out_h=0; return; }
    *out_x = minx; *out_y = miny;
    *out_w = maxx - minx + 1; *out_h = maxy - miny + 1;

if (!x || !y || !w || !h) return;
    if (cell_w > 0) { *x = (*x / cell_w) * cell_w; *w = ((*w + cell_w - 1) / cell_w) * cell_w; }
    if (cell_h > 0) { *y = (*y / cell_h) * cell_h; *h = ((*h + cell_h - 1) / cell_h) * cell_h; }

if (!x || !y || !w || !h) return;
    if (cell_w > 0) { *x = (*x / cell_w) * cell_w; *w = ((*w + cell_w - 1) / cell_w) * cell_w; }
    if (cell_h > 0) { *y = (*y / cell_h) * cell_h; *h = ((*h + cell_h - 1) / cell_h) * cell_h; }

if (!data || data_len == 0) return NULL;
    /* Kitty APC: ESC ] 1 1 ; <data> ST */
    size_t out_len = 4 + data_len * 2 + 2;
    char *out = malloc(out_len + 1);
    if (!out) return NULL;
    snprintf(out, out_len + 1, "\x1b]11;");
    size_t pos = 4;
    for (size_t i = 0; i < data_len; i++) {
        snprintf(out + pos, 3, "%02x", (unsigned char)data[i]);
        pos += 2;
    }
    snprintf(out + pos, 3, "\x1b\\");
    return out;

if (!png_path) return NULL;
    size_t len = 0;
    unsigned char *data = pet_png_bytes(png_path, &len);
    if (!data) return NULL;
    char *encoded = pet_kitty_apc((const char *)data, len);
    free(data);
    return encoded;

char *out = malloc(rows * 2 + 1);
    if (!out) return NULL;
    for (int i = 0; i < rows; i++) { out[i*2] = ' '; out[i*2+1] = '\n'; }
    out[rows*2] = '\0';
    return out;

if (!png_path) return NULL;
    size_t len = 0;
    unsigned char *data = pet_png_bytes(png_path, &len);
    if (!data) return NULL;
    /* iTerm: ESC ] 1 3 3 7 ; File=inline=1:<base64> ST */
    char *b64 = base64_encode(data, len);
    free(data);
    if (!b64) return NULL;
    size_t out_len = 16 + strlen(b64) + 2;
    char *out = malloc(out_len + 1);
    if (!out) { free(b64); return NULL; }
    snprintf(out, out_len + 1, "\x1b]1337;File=inline=1:%s\x1b\\", b64);
    free(b64);
    return out;

if (!png_path) return NULL;
    /* Sixel encoding requires PNG rasterization — not implemented in pure C.
     * Return a placeholder. */
    (void)png_path;
    return strdup("\x1bPq\x1b\\");

if (cell_w <= 0 || cell_h <= 0) return 1;
    int cols = (pixel_w + cell_w - 1) / cell_w;
    int rows = (pixel_h + cell_h - 1) / cell_h;
    return cols * rows;

int cols = sheet_w / cell_w;
    if (cols <= 0) cols = 1;
    int col = frame_idx % cols;
    int row = frame_idx / cols;
    if (out_x) *out_x = col * cell_w;
    if (out_y) *out_y = row * cell_h;
    if (out_w) *out_w = cell_w;
    if (out_h) *out_h = cell_h;

int cols = sheet_w / cell_w;
    if (cols <= 0) cols = 1;
    int col = frame_idx % cols;
    int row = frame_idx / cols;
    if (out_x) *out_x = col * cell_w;
    if (out_y) *out_y = row * cell_h;
    if (out_w) *out_w = cell_w;
    if (out_h) *out_h = cell_h;

json_t *renderer = json_object();
    json_set(renderer, "sheet_path", json_string(sheet_path ? sheet_path : ""));
    json_set(renderer, "cell_width", json_int(cell_w));
    json_set(renderer, "cell_height", json_int(cell_h));
    json_set(renderer, "encoder", json_string("kitty"));
    return renderer;

if (!messages || message_count <= 0) {
        return strdup("{\"error\":\"No messages provided\"}");
    }

    hermes_log(LOG_DEBUG, "plugin_llm", "acomplete: provider=%s model=%s",
        provider ? provider : "(default)", model ? model : "(default)");

    /* The plugin LLM requires the async client integration that is not present
     * in the C port. Return an honest not_implemented status rather than fake
     * completions. */
    size_t buf_size = 512;
    char *result = (char *)malloc(buf_size);
    if (!result) return NULL;

    snprintf(result, buf_size,
        "{\"status\":\"not_implemented\",\"message\":\"Plugin LLM acomplete requires async client integration\"}");
    return result;

if (!instructions || !*instructions) {
        return strdup("{\"error\":\"acomplete_structured requires non-empty instructions\"}");
    }
    if (!inputs || input_count <= 0) {
        return strdup("{\"error\":\"acomplete_structured requires at least one input block\"}");
    }

    hermes_log(LOG_DEBUG, "plugin_llm", "acomplete_structured: provider=%s json_mode=%d",
        provider ? provider : "(default)", json_mode);

    size_t buf_size = 512;
    char *result = (char *)malloc(buf_size);
    if (!result) return NULL;

    snprintf(result, buf_size,
        "{\"status\":\"not_implemented\",\"message\":\"Plugin LLM acomplete_structured requires async client integration\"}");
    return result;

if (!messages || message_count <= 0) {
        return strdup("{\"error\":\"No messages for async invocation\"}");
    }

    hermes_log(LOG_DEBUG, "plugin_llm",
        "_invoke_async: provider_override=%s model_override=%s",
        provider_override ? provider_override : "(none)",
        model_override ? model_override : "(none)");

    /* The plugin LLM's async invocation requires auxiliary_client, which is
     * not ported to C. Return an honest not_implemented status. */
    size_t buf_size = 512;
    char *result = (char *)malloc(buf_size);
    if (!result) return NULL;

    snprintf(result, buf_size,
        "{\"status\":\"not_implemented\",\"message\":\"Plugin LLM async invocation requires auxiliary_client\"}");
    return result;

free(s_raw_config_cache.path);
    free(s_raw_config_cache.content);
    s_raw_config_cache.path = NULL;
    s_raw_config_cache.content = NULL;
    s_raw_config_cache.mtime_ns = 0;
    s_raw_config_cache.size = 0;
    s_raw_config_cache.valid = 0;

const char *config_path = getenv("HERMES_CONFIG_PATH");
    char path[1024];
    if (!config_path || !*config_path) {
        /* Default: $HERMES_HOME/config.yaml */
        const char *home = getenv("HERMES_HOME");
        if (!home || !*home) {
            home = getenv("HOME");
            if (!home || !*home) {
                return strdup("{}");
            }
            snprintf(path, sizeof(path), "%s/.hermes/config.yaml", home);
            config_path = path;
        } else {
            snprintf(path, sizeof(path), "%s/config.yaml", home);
            config_path = path;
        }
    }

    /* Cache lookup keyed by (path, mtime_ns, size) */
    struct stat st;
    long mtime_ns = 0, size = 0;
    int have_stat = (stat(config_path, &st) == 0);
