        return strdup("{}");
    }

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (fsize <= 0) {
        fclose(f);
        return strdup("{}");
    }

    char *content = (char *)malloc((size_t)fsize + 1);
    if (!content) {
