        free(s_raw_config_cache.content);
        s_raw_config_cache.path = strdup(config_path);
        s_raw_config_cache.content = strdup(content);
        s_raw_config_cache.mtime_ns = mtime_ns;
        s_raw_config_cache.size = size;
