    /* mkdir -p parent */
    char dir[PATH_MAX];
    snprintf(dir, sizeof(dir), "%s", path);
    char *slash = strrchr(dir, '/');
    if (slash) { *slash = '\0'; if (dir[0]) mkdir(dir, 0700); }
    secure_parent_dir_c(path);

