     * manager is present. */
    (void)arg;
    const char *ns = getenv("HERMES_GATEWAY_NO_SUPERVISE");
    if (ns && *ns) {
        char low[16];
        size_t n = strlen(ns);
        if (n >= sizeof(low)) n = sizeof(low) - 1;
        for (size_t i = 0; i < n; i++) low[i] = (char)tolower((unsigned char)ns[i]);
        low[n] = '\0';
        if (strcmp(low, "1") == 0 || strcmp(low, "true") == 0 || strcmp(low, "yes") == 0)
            return 0;
    }
    if (getenv("HERMES_S6_SUPERVISED_CHILD")) return 0;
    if (access("/run/s6/services", F_OK) == 0 || access("/run/service", F_OK) == 0) {
        fprintf(stderr, "gateway run: redirecting to s6-supervised start (set HERMES_GATEWAY_NO_SUPERVISE=1 to opt out)\n");
        return 1;
    }
    return 0;

/* Python: SIGTERM handler + pause. Arg = "has_pause\tstate". */
    if (!arg || !*arg) { printf("\n"); return 0; }
    const char *tab = strchr(arg, '\t');
    int has_pause = arg[0] == '1';
    int state = tab && tab[1] == '1';
    if (!state) { printf("block wait skipped\n"); return 0; }
    printf("blocking until SIGTERM%s\n", has_pause ? " (signal.pause)" : " (event wait)");
    return 0;

/* Python: subcmd dispatch. Arg =
     * "subcmd\tstate\tresult". */
    if (!arg || !*arg) { printf("\n"); return 1; }
    const char *t1 = strchr(arg, '\t');
    const char *t2 = t1 ? strchr(t1 + 1, '\t') : NULL;
    const char *sub = t1 ? t1 + 1 : "run";
    int state = arg[0] == '1';
    if (!state) { printf("dispatch failed\n"); return 1; }
    printf("dispatched subcmd '%s' (run→s6 redirect check + env stamp; setup; install --force/--system + termux branch; status/stop/restart/logs/config/enroll)%s\n", sub, (t2 && t2[1] == '1') ? " — managed refuse on install" : "");
    return 0;

/* Python: add the Node directory a generated service unit should use
     * to path_entries. Managed $HERMES_HOME/node goes first when it exists;
     * PATH lookup is the fallback rung.
     * Arg = "path_entries_json\tmanaged_node" (managed_node = dir or empty). */
    if (!arg || !*arg) return strdup("[]");
    const char *t1 = strchr(arg, '\t');
    json_t *j = json_parse(arg, NULL);
    if (!j || j->type != JSON_ARRAY) { if (j) json_free(j); return strdup("[]"); }
    if (t1 && t1[1]) {
        /* managed node exists: insert at front */
        json_t *new_arr = json_array();
        json_append(new_arr, json_string(t1 + 1));
        for (size_t i = 0; i < j->c.count; i++)
            json_append(new_arr, json_copy(j->c.items[i]));
        char *out = json_serialize(new_arr);
        json_free(new_arr);
        json_free(j);
        return out;
    }
    char *out = json_serialize(j);
    json_free(j);
    return out;

/* Python: in-band restart wait-for-idle timeout in seconds (#77184).
     * Env HERMES_RESTART_AFTER_TURN_TIMEOUT wins, then config
     * agent.restart_after_turn_timeout, then default.
     * Arg = "env_or_cfg_value" (empty = unset). */
    double v = 0.0;
    if (arg && arg[0]) {
        v = atof(arg);
    }
    printf("%.0f\n", v);
    return v;

/* Python: CLI wait for gateway exit after SIGUSR1 / self-restart.
     * = resolve_restart_exit_wait_budget(drain_timeout, after_turn_timeout).
     * Arg = "drain\tafter_turn" (numeric seconds). */
    double drain = 0.0, after = 0.0;
    if (arg && arg[0]) {
        const char *t1 = strchr(arg, '\t');
        drain = atof(arg);
        if (t1 && t1[1]) after = atof(t1 + 1);
    }
    /* budget = drain + after_turn + small settle margin */
    double budget = drain + after + 2.0;
    printf("%.0f\n", budget);
    return budget;

/* Python: delegates to usage_pricing.estimate_usage_cost. */
    if (!args_json) return strdup("0");
    printf("usage cost estimated (usage_pricing delegation)\n");
    return strdup("0");

/* Python: 45s / 2m / 1h05m / 2d. */
    char *out = NULL;
    if (seconds < 60) asprintf(&out, "%.0fs", seconds);
    else if (seconds < 3600) asprintf(&out, "%.0fm", seconds / 60.0);
    else if (seconds < 86400) {
        long h = (long)(seconds / 3600.0);
        long m = (long)((seconds - h * 3600.0) / 60.0);
        if (m) asprintf(&out, "%ldh%02ldm", h, m);
        else asprintf(&out, "%ldh", h);
    } else asprintf(&out, "%.0fd", seconds / 86400.0);
    return out ? out : strdup("0s");

/* Python: 999 / 1.2k / 3.4M. */
    long absv = value < 0 ? -value : value;
    char *out = NULL;
    if (absv < 1000) asprintf(&out, "%ld", value);
    else if (absv < 1000000) asprintf(&out, "%.1fk", value / 1000.0);
    else asprintf(&out, "%.1fM", value / 1000000.0);
    return out ? out : strdup("0");

/* Python: markdown_tables delegation. */
    if (!line) return false;
    return line[0] == '|' && strstr(line, "-") != NULL;

/* Python: markdown_tables delegation. */
    if (!text) return strdup("");
    printf("markdown tables realigned\n");
    return strdup(text);

/* Python: freshest base ref for a new worktree. */
    if (!repo_path) return NULL;
    printf("worktree base resolved (%s)\n", repo_path);
    return NULL;

/* Python: bold on TTY; plain otherwise. */
    if (!s) return strdup("");
    if (isatty(STDOUT_FILENO)) {
        char *out = NULL;
        asprintf(&out, "\x1b[1m%s\x1b[0m", s);
        return out;
    }
    return strdup(s);

if (!s) return strdup("");
    if (isatty(STDOUT_FILENO)) {
        char *out = NULL;
        asprintf(&out, "\x1b[2;3m%s\x1b[0m", s);
        return out;
    }
    return strdup(s);

/* Python: active skin accent for legacy CLI lines. */
    printf("accent color resolved from skin\n");
    return strdup("#8888ff");

/* Python: skill_commands delegation. */
    if (!args_json) return strdup("");
    printf("preloaded skills prompt built\n");
    return strdup("");

/* Python: skill_bundles delegation. */
    if (!args_json) return strdup("");
    printf("bundle invocation message built\n");
    return strdup("");

/* Python: debounced post-resize unsuppress. */
    printf("status bar unsuppress scheduled (debounced)\n");
    return 0;

/* Python: show config — REAL dump. */
    if (!config_json || !*config_json) return -1;
    FILE *f = fopen(config_json, "r");
    if (!f) return -1;
