        for (int k = 0; k < 3; k++) {
            /* dedup */
            bool found = false;
            for (size_t j = 0; j < n; j++) {
                if (strcmp(aliases[j], variants[k]) == 0) { found = true; break; }
            }
            if (!found) {
                if (n == cap) { cap = cap ? cap * 2 : 8; aliases = realloc(aliases, (cap + 1) * sizeof(char *)); }
                aliases[n++] = variants[k];
            } else {
