/* Python: normalize line formatting in-place; returns count. */
    if (!path) return 0;
    FILE *f = fopen(path, "r");
    if (!f) return 0;
    char *buf = NULL;
    size_t cap = 0, len = 0;
    char chunk[4096];
    size_t r;
    while ((r = fread(chunk, 1, sizeof(chunk), f)) > 0) {
        if (len + r + 1 > cap) {
            cap = (cap ? cap * 2 : 65536);
            if (cap < len + r + 1) cap = len + r + 1;
            char *nb = realloc(buf, cap);
            if (!nb) { free(buf); fclose(f); return 0; }
            buf = nb;
        }
        memcpy(buf + len, chunk, r);
        len += r;
    }
    fclose(f);
    if (!buf) return 0;
    buf[len] = '\0';
    /* count lines with surrounding whitespace / CRLF to normalize */
    long changed = 0;
    char *out = malloc(len + 1);
    if (!out) { free(buf); return 0; }
    char *q = out;
    char *line = buf;
    while (line && *line) {
        char *nl = strchr(line, '\n');
        size_t ll = nl ? (size_t)(nl - line) : strlen(line);
        char *copy = strndup(line, ll);
        if (!copy) { break; }
        /* strip trailing 
 */
        size_t cl = strlen(copy);
        if (cl && copy[cl-1] == '\r') { copy[--cl] = '\0'; changed++; }
        /* strip surrounding spaces around key = value on non-comment lines */
        if (copy[0] != '#' && strchr(copy, '=')) {
            char *eq = strchr(copy, '=');
            /* strip spaces before = */
            char *e = eq;
            while (e > copy && (e[-1] == ' ' || e[-1] == '\t')) { e--; changed++; }
            if (e != eq) { memmove(e + 1, eq + 1, strlen(eq + 1) + 1); memcpy(e, "=", 1); }
            /* strip spaces after = */
            char *v = e + 1;
            char *vs = v;
            while (*vs == ' ' || *vs == '\t') { vs++; changed++; }
            if (vs != v) memmove(v, vs, strlen(vs) + 1);
        }
        size_t cplen = strlen(copy);
        memcpy(q, copy, cplen);
        q += cplen;
        *q++ = '\n';
        free(copy);
        line = nl ? nl + 1 : NULL;
    }
    *q = '\0';
    free(buf);
    FILE *w = fopen(path, "w");
    if (w) { fwrite(out, 1, (size_t)(q - out), w); fclose(w); }
    free(out);
    return changed;

/* Python: managed guard + write key=value. */
    if (!path || !key) return -1;
    FILE *f = fopen(path, "r");
    char *buf = NULL;
    if (f) {
        fseek(f, 0, SEEK_END);
        long n = ftell(f);
        fseek(f, 0, SEEK_SET);
        if (n > 0) {
            buf = malloc((size_t)n + 1);
            if (buf) {
                size_t rr = fread(buf, 1, (size_t)n, f);
                buf[rr] = '\0';
            }
        }
        fclose(f);
    }
    FILE *w = fopen(path, "w");
    if (!w) { free(buf); return -1; }
    bool replaced = false;
    if (buf) {
        size_t klen = strlen(key);
        char *p = buf;
        while (*p) {
            char *nl = strchr(p, '\n');
            size_t ll = nl ? (size_t)(nl - p) : strlen(p);
            bool match = ll > klen && strncmp(p, key, klen) == 0 && p[klen] == '=';
            if (match) {
                fprintf(w, "%s=%s\n", key, value ? value : "");
                replaced = true;
            } else {
                fwrite(p, 1, ll, w);
                fputc('\n', w);
            }
            p = nl ? nl + 1 : p + ll;
        }
    }
    if (!replaced) fprintf(w, "%s=%s\n", key, value ? value : "");
    fclose(w);
    free(buf);
    return 0;

/* Python: remove from .env and os.environ. */
    if (!path || !key) return false;
    FILE *f = fopen(path, "r");
    if (!f) return false;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = NULL;
    if (n > 0) {
        buf = malloc((size_t)n + 1);
        if (buf) { size_t rr = fread(buf, 1, (size_t)n, f); buf[rr] = '\0'; }
    }
    fclose(f);
    if (!buf) return false;
    size_t klen = strlen(key);
    bool found = false;
    FILE *w = fopen(path, "w");
    if (!w) { free(buf); return false; }
    char *p = buf;
    while (*p) {
        char *nl = strchr(p, '\n');
        size_t ll = nl ? (size_t)(nl - p) : strlen(p);
        bool match = ll > klen && strncmp(p, key, klen) == 0 && p[klen] == '=';
        if (match) {
            found = true;
        } else {
            fwrite(p, 1, ll, w);
            fputc('\n', w);
        }
        p = nl ? nl + 1 : p + ll;
