    fclose(w);
    free(buf);
    return found;

/* Python: ANTHROPIC_TOKEN + clear API-key slot — REAL write. */
    if (!value) return -1;
    setenv("ANTHROPIC_TOKEN", value, 1);
    unsetenv("ANTHROPIC_API_KEY");
    return 0;

/* Python: use claude code's own credential files. */
    unsetenv("ANTHROPIC_TOKEN");
