            json_t *rv = (raw && raw->type == JSON_ARRAY && i < raw->c.count) ? raw->c.items[i] : NULL;
            json_t *lv = (loaded_expanded && loaded_expanded->type == JSON_ARRAY && i < loaded_expanded->c.count)
                ? loaded_expanded->c.items[i] : NULL;
