        if (!vs || !vs[0]) { free(vs); json_free(args); free(sb.buf); return strdup(""); }
        char *t = cli_agent_display__truncate_preview(vs, max_len);
        sb_append_str(&sb, t);
        free(t); free(vs);
    }

    json_free(args);
    result = (sb.len > 0) ? strdup(sb.buf) : strdup("");
    free(sb.buf);
