        /* Also check via kill(pid, 0) — no signal sent */
        if (kill(pid, 0) != 0 && errno == ESRCH)
            return true;

        /* Sleep poll_interval seconds (500ms) */
        usleep((useconds_t)(poll_interval * 1000000));
        elapsed += poll_interval;
    }
    /* Drain didn't finish in time */
    return false;
