/* Generate 32 random bytes (256-bit key) from the OS RNG. */
    unsigned char key[32];
    if (!crypto_random_bytes(key, 32)) {
        hermes_log(LOG_ERROR, "qqbot_crypto", "Failed to generate random key");
        return NULL;
    }

    /* Standard base64 (matches Python base64.b64encode). Caller owns result. */
    return base64_encode(key, 32);

if (!encrypted_base64 || !key_base64) {
        hermes_log(LOG_ERROR, "qqbot_crypto", "decrypt_secret: NULL argument");
        return NULL;
    }

    /* base64-decode the 32-byte AES key (matches Python base64.b64decode). */
    size_t key_len = 0;
    unsigned char *key = base64_decode(key_base64, &key_len);
    if (!key || key_len != 32) {
        hermes_log(LOG_ERROR, "qqbot_crypto", "decrypt_secret: bad key (need 32 bytes)");
        free(key);
        return NULL;
    }

    /* base64-decode the ciphertext blob. */
    size_t raw_len = 0;
    unsigned char *raw = base64_decode(encrypted_base64, &raw_len);
    if (!raw || raw_len < 12 + 16 + 1) {
        hermes_log(LOG_ERROR, "qqbot_crypto", "decrypt_secret: ciphertext too short");
        free(key);
        free(raw);
        return NULL;
    }

    /* crypto_aes_decrypt expects IV(12) || ciphertext || tag(16) — exactly the
     * decoded layout — and uses the raw key directly when key_len == 32. */
    size_t pt_len = 0;
    unsigned char *plaintext = crypto_aes_decrypt(raw, raw_len, key, key_len, &pt_len);
    free(key);
    free(raw);
    if (!plaintext || pt_len == 0) {
        hermes_log(LOG_ERROR, "qqbot_crypto",
                   "decrypt_secret: AES-GCM auth failed (wrong key / tampered)");
        free(plaintext);
        return NULL;
    }

    /* Return as a NUL-terminated UTF-8 string (Python returns .decode()). */
    char *out = (char *)malloc(pt_len + 1);
    if (!out) {
        free(plaintext);
        return NULL;
    }
    memcpy(out, plaintext, pt_len);
    out[pt_len] = '\0';
    free(plaintext);

    hermes_log(LOG_DEBUG, "qqbot_crypto", "decrypt_secret: decrypted %zu bytes", pt_len);
    return out;

/*
     * Parse approval button_data into (session_key, decision).
     * Returns a JSON object with session_key and decision, or NULL if not an approval button.
     * Pattern: approve:<session_key>:<decision>
     * session_key may itself contain colons, so the session_key group is greedy.
     */
    if (!button_data || !button_data[0]) return NULL;
    size_t len = strlen(button_data);
    if (len < 10) return NULL; /* Minimum: "approve:x:y" */
    /* Check prefix */
    if (strncmp(button_data, APPROVAL_PREFIX, strlen(APPROVAL_PREFIX)) != 0) {
        return NULL;
    }
    /* Find the last colon (decision separator) */
    const char *last_colon = strrchr(button_data, ':');
    if (!last_colon || last_colon == button_data) return NULL;
    /* Extract decision */
    const char *decision = last_colon + 1;
    if (strcmp(decision, "allow-once") != 0 &&
        strcmp(decision, "allow-always") != 0 &&
        strcmp(decision, "deny") != 0) {
        return NULL;
    }
    /* Extract session_key (between prefix and last colon) */
    const char *key_start = button_data + strlen(APPROVAL_PREFIX);
    size_t key_len = last_colon - key_start;
    if (key_len == 0 || key_len >= 1024) return NULL;
    char *session_key = (char*)malloc(key_len + 1);
    if (!session_key) return NULL;
    memcpy(session_key, key_start, key_len);
    session_key[key_len] = '\0';
    json_node_t *result = json_new_object();
    if (result) {
        json_object_set(result, "session_key", json_new_string(session_key));
        json_object_set(result, "decision", json_new_string(decision));
    }
    hermes_log(LOG_DEBUG, "qqbot_keyboards",
               "parse_approval_button_data: session=%.30s decision=%s", session_key, decision);
    free(session_key);
    return result;

/*
     * Parse update_prompt button_data into 'y' or 'n'.
     * Returns "y", "n", or NULL if not an update_prompt button.
     */
    if (!button_data || !button_data[0]) return NULL;
    if (strncmp(button_data, UPDATE_PROMPT_PREFIX, strlen(UPDATE_PROMPT_PREFIX)) != 0) {
        return NULL;
    }
    const char *answer = button_data + strlen(UPDATE_PROMPT_PREFIX);
    if (strcmp(answer, "y") == 0 || strcmp(answer, "n") == 0) {
        hermes_log(LOG_DEBUG, "qqbot_keyboards", "parse_update_prompt_button_data: %s", answer);
        return answer;
    }
    return NULL;

/*
     * Build a KeyboardButton JSON object with render data and callback action.
     */
    json_node_t *button = json_new_object();
    if (!button) return NULL;
    json_object_set(button, "id", json_new_string(btn_id ? btn_id : ""));
    /* Render data */
    json_node_t *render = json_new_object();
    if (render) {
        json_object_set(render, "label", json_new_string(label ? label : ""));
        json_object_set(render, "visited_label", json_new_string(visited_label ? visited_label : ""));
        json_object_set(render, "style", json_new_number(style));
        json_object_set(button, "render_data", render);
    }
    /* Action */
    json_node_t *action = json_new_object();
    if (action) {
        json_object_set(action, "type", json_new_number(1)); /* Callback */
        json_object_set(action, "data", json_new_string(data ? data : ""));
        json_node_t *perm = json_new_object();
        if (perm) {
            json_object_set(perm, "type", json_new_number(2)); /* All users */
            json_object_set(action, "permission", perm);
        }
        json_object_set(action, "click_limit", json_new_number(1));
        json_object_set(button, "action", action);
    }
    json_object_set(button, "group_id", json_new_string(group_id ? group_id : "default"));
    return button;

/*
     * Build the 3-button approval keyboard.
     * Layout: [✅ 允许一次] [⭐ 始终允许] [❌ 拒绝]
     * All three share group_id='approval' so clicking one greys out the rest.
     */
    json_node_t *keyboard = json_new_object();
    if (!keyboard) return NULL;
    json_node_t *content = json_new_object();
    if (!content) return keyboard;
    json_node_t *rows = json_new_array();
    if (!rows) return keyboard;
    /* Row 1: three buttons */
    json_node_t *row1 = json_new_object();
    if (!row1) return keyboard;
    json_node_t *buttons = json_new_array();
    if (!buttons) return keyboard;
    /* ✅ 允许一次 (allow-once) */
    json_node_t *btn_allow = cli_gateway_platforms_qqbot_keyboards__make_callback_button(
        "allow", "✅ 允许一次", "已允许",
        NULL /* data built below */, 1, "approval");
    if (btn_allow) {
        /* Set data with session_key */
        json_node_t *action = json_object_get(btn_allow, "action");
        if (action) {
            char data_buf[512];
            snprintf(data_buf, sizeof(data_buf), "%s%s:allow-once",
                     APPROVAL_PREFIX, session_key ? session_key : "");
            json_object_set(action, "data", json_new_string(data_buf));
        }
        json_array_append(buttons, btn_allow);
    }
    /* ⭐ 始终允许 (allow-always) */
    json_node_t *btn_always = cli_gateway_platforms_qqbot_keyboards__make_callback_button(
        "always", "⭐ 始终允许", "已始终允许", "", 1, "approval");
    if (btn_always) {
        json_node_t *action = json_object_get(btn_always, "action");
        if (action) {
            char data_buf[512];
            snprintf(data_buf, sizeof(data_buf), "%s%s:allow-always",
                     APPROVAL_PREFIX, session_key ? session_key : "");
            json_object_set(action, "data", json_new_string(data_buf));
        }
        json_array_append(buttons, btn_always);
    }
    /* ❌ 拒绝 (deny) */
    json_node_t *btn_deny = cli_gateway_platforms_qqbot_keyboards__make_callback_button(
        "deny", "❌ 拒绝", "已拒绝", "", 0, "approval");
    if (btn_deny) {
        json_node_t *action = json_object_get(btn_deny, "action");
        if (action) {
            char data_buf[512];
            snprintf(data_buf, sizeof(data_buf), "%s%s:deny",
                     APPROVAL_PREFIX, session_key ? session_key : "");
            json_object_set(action, "data", json_new_string(data_buf));
        }
        json_array_append(buttons, btn_deny);
    }
    json_object_set(row1, "buttons", buttons);
    json_array_append(rows, row1);
    json_object_set(content, "rows", rows);
    json_object_set(keyboard, "content", content);
    hermes_log(LOG_INFO, "qqbot_keyboards",
               "build_approval_keyboard: session=%.20s...", session_key ? session_key : "");
    return keyboard;

/*
     * Build a Yes/No keyboard for update confirmation prompts.
     * Layout: [✓ 确认] [✗ 取消]
     */
    json_node_t *keyboard = json_new_object();
    if (!keyboard) return NULL;
    json_node_t *content = json_new_object();
    if (!content) return keyboard;
    json_node_t *rows = json_new_array();
    if (!rows) return keyboard;
    json_node_t *row1 = json_new_object();
    if (!row1) return keyboard;
    json_node_t *buttons = json_new_array();
    if (!buttons) return keyboard;
    /* ✓ 确认 (yes) */
    char yes_data[64];
    snprintf(yes_data, sizeof(yes_data), "%sy", UPDATE_PROMPT_PREFIX);
    json_node_t *btn_yes = cli_gateway_platforms_qqbot_keyboards__make_callback_button(
        "yes", "✓ 确认", "已确认", yes_data, 1, "update_prompt");
    if (btn_yes) json_array_append(buttons, btn_yes);
    /* ✗ 取消 (no) */
    char no_data[64];
    snprintf(no_data, sizeof(no_data), "%sn", UPDATE_PROMPT_PREFIX);
    json_node_t *btn_no = cli_gateway_platforms_qqbot_keyboards__make_callback_button(
        "no", "✗ 取消", "已取消", no_data, 0, "update_prompt");
    if (btn_no) json_array_append(buttons, btn_no);
    json_object_set(row1, "buttons", buttons);
    json_array_append(rows, row1);
    json_object_set(content, "rows", rows);
    json_object_set(keyboard, "content", content);
    return keyboard;

/*
     * Render an ApprovalRequest into the message body (markdown).
     * Returns a JSON object with text and is_exec fields.
     */
    if (!req || !json_node_is_object(req)) return NULL;
    json_node_t *cmd_preview = json_object_get(req, "command_preview");
    json_node_t *cwd_node = json_object_get(req, "cwd");
    if (cmd_preview || cwd_node) {
        return cli_gateway_platforms_qqbot_keyboards__build_exec_text(req);
    }
    return cli_gateway_platforms_qqbot_keyboards__build_plugin_text(req);

/*
     * Build the approval message text for exec approvals.
     * Returns a JSON object with text field and is_exec=true.
     */
    json_node_t *result = json_new_object();
    if (!result) return NULL;
    if (!req || !json_node_is_object(req)) {
        json_object_set(result, "text", json_new_string("🔐 **命令执行审批**"));
        json_object_set(result, "is_exec", json_new_bool(1));
        return result;
    }
    json_node_t *cmd = json_object_get(req, "command_preview");
    json_node_t *cwd_node = json_object_get(req, "cwd");
    json_node_t *title = json_object_get(req, "title");
    json_node_t *desc = json_object_get(req, "description");
    json_node_t *timeout = json_object_get(req, "timeout_sec");
    /* Build text lines */
    json_node_t *lines = json_new_array();
    if (!lines) return result;
    json_array_append(lines, json_new_string("🔐 **命令执行审批**"));
    json_array_append(lines, json_new_string(""));
    if (cmd && json_node_is_string(cmd)) {
        const char *cmd_str = json_node_get_string(cmd);
        size_t cmd_len = strlen(cmd_str);
        if (cmd_len > 300) cmd_len = 300;
        char code_buf[512];
        snprintf(code_buf, sizeof(code_buf), "```\\n%.*s\\n```", (int)cmd_len, cmd_str);
        json_array_append(lines, json_new_string(code_buf));
    }
    if (cwd_node && json_node_is_string(cwd_node)) {
        char buf[256];
        snprintf(buf, sizeof(buf), "📁 目录: %s", json_node_get_string(cwd_node));
        json_array_append(lines, json_new_string(buf));
    }
    if (title && json_node_is_string(title)) {
        char buf[256];
        snprintf(buf, sizeof(buf), "📋 %s", json_node_get_string(title));
        json_array_append(lines, json_new_string(buf));
    }
    if (desc && json_node_is_string(desc)) {
        const char *d = json_node_get_string(desc);
        if (d && d[0]) {
            char buf[256];
            snprintf(buf, sizeof(buf), "📝 %s", d);
            json_array_append(lines, json_new_string(buf));
        }
    }
    json_array_append(lines, json_new_string(""));
    int timeout_sec = 120;
    if (timeout && json_node_is_number(timeout)) {
        timeout_sec = json_node_get_int(timeout);
    }
    char timeout_buf[64];
    snprintf(timeout_buf, sizeof(timeout_buf), "⏱️ 超时: %d 秒", timeout_sec);
    json_array_append(lines, json_new_string(timeout_buf));
    json_object_set(result, "lines", lines);
    json_object_set(result, "is_exec", json_new_bool(1));
    return result;

/*
     * Build the approval message text for plugin tool approvals.
     */
    json_node_t *result = json_new_object();
    if (!result) return NULL;
    json_node_t *severity = json_object_get(req, "severity");
    const char *icon = "🟡";
    if (severity && json_node_is_string(severity)) {
        const char *sev = json_node_get_string(severity);
        if (strcmp(sev, "critical") == 0) icon = "🔴";
        else if (strcmp(sev, "info") == 0) icon = "🔵";
    }
    json_node_t *lines = json_new_array();
    if (!lines) return result;
    char header[64];
    snprintf(header, sizeof(header), "%s **审批请求**", icon);
    json_array_append(lines, json_new_string(header));
    json_array_append(lines, json_new_string(""));
    json_node_t *title = json_object_get(req, "title");
    if (title && json_node_is_string(title)) {
        char buf[256];
        snprintf(buf, sizeof(buf), "📋 %s", json_node_get_string(title));
        json_array_append(lines, json_new_string(buf));
    }
    json_node_t *desc = json_object_get(req, "description");
    if (desc && json_node_is_string(desc)) {
        const char *d = json_node_get_string(desc);
        if (d && d[0]) {
            char buf[256];
            snprintf(buf, sizeof(buf), "📝 %s", d);
            json_array_append(lines, json_new_string(buf));
        }
    }
    json_node_t *tool = json_object_get(req, "tool_name");
    if (tool && json_node_is_string(tool)) {
        const char *t = json_node_get_string(tool);
        if (t && t[0]) {
            char buf[256];
            snprintf(buf, sizeof(buf), "🔧 工具: %s", t);
            json_array_append(lines, json_new_string(buf));
        }
    }
    json_array_append(lines, json_new_string(""));
    json_node_t *timeout = json_object_get(req, "timeout_sec");
    int timeout_sec = 120;
    if (timeout && json_node_is_number(timeout)) timeout_sec = json_node_get_int(timeout);
    char timeout_buf[64];
    snprintf(timeout_buf, sizeof(timeout_buf), "⏱️ 超时: %d 秒", timeout_sec);
    json_array_append(lines, json_new_string(timeout_buf));
    json_object_set(result, "lines", lines);
    json_object_set(result, "is_exec", json_new_bool(0));
    return result;

/*
     * Best available operator openid (group -> member; c2c -> user).
     * Returns the operator's openid string or empty string.
     */
    if (!event || !json_node_is_object(event)) return "";
    const char *openid = "";
    /* Try group_member_openid first */
    json_node_t *gmid = json_object_get(event, "group_member_openid");
    if (gmid && json_node_is_string(gmid)) {
        openid = json_node_get_string(gmid);
        if (openid && openid[0]) return openid;
    }
    /* Try user_openid */
    json_node_t *uid = json_object_get(event, "user_openid");
    if (uid && json_node_is_string(uid)) {
        openid = json_node_get_string(uid);
        if (openid && openid[0]) return openid;
    }
    /* Try resolver_user_id */
    json_node_t *rid = json_object_get(event, "resolver_user_id");
    if (rid && json_node_is_string(rid)) {
        openid = json_node_get_string(rid);
    }
    return openid;

/*
     * Parse a raw INTERACTION_CREATE dispatch payload (d field).
     * Returns a JSON object with all parsed event fields.
     */
    if (!raw || !json_node_is_object(raw)) return NULL;
    json_node_t *event = json_new_object();
    if (!event) return NULL;
    /* Top-level fields */
    json_node_t *id = json_object_get(raw, "id");
    json_object_set(event, "id", id ? id : json_new_string(""));
    json_node_t *chat_type = json_object_get(raw, "chat_type");
    int scene_code = chat_type && json_node_is_number(chat_type) ? json_node_get_int(chat_type) : 0;
    json_object_set(event, "chat_type", json_new_number(scene_code));
    const char *scene;
    switch (scene_code) {
        case 0: scene = "guild"; break;
        case 1: scene = "group"; break;
        case 2: scene = "c2c"; break;
        default: scene = ""; break;
    }
    json_object_set(event, "scene", json_new_string(scene));
    /* data.resolved fields */
    json_node_t *data = json_object_get(raw, "data");
    json_node_t *resolved = data && json_node_is_object(data) ? json_object_get(data, "resolved") : NULL;
    json_node_t *button_data = resolved && json_node_is_object(resolved) ? json_object_get(resolved, "button_data") : NULL;
    json_object_set(event, "button_data", button_data && json_node_is_string(button_data) ? button_data : json_new_string(""));
    json_node_t *button_id = resolved && json_node_is_object(resolved) ? json_object_get(resolved, "button_id") : NULL;
    json_object_set(event, "button_id", button_id && json_node_is_string(button_id) ? button_id : json_new_string(""));
    /* Other fields */
    json_node_t *goid = json_object_get(raw, "group_openid");
    json_object_set(event, "group_openid", goid && json_node_is_string(goid) ? goid : json_new_string(""));
    json_node_t *gmid = json_object_get(raw, "group_member_openid");
    json_object_set(event, "group_member_openid", gmid && json_node_is_string(gmid) ? gmid : json_new_string(""));
    json_node_t *uid = json_object_get(raw, "user_openid");
    json_object_set(event, "user_openid", uid && json_node_is_string(uid) ? uid : json_new_string(""));
    hermes_log(LOG_INFO, "qqbot_keyboards",
               "parse_interaction_event: scene=%s button=%s",
               scene, button_data && json_node_is_string(button_data) ? json_node_get_string(button_data) : "");
    return event;

if (!url || !url[0]) return 0;
    hermes_log(LOG_DEBUG, "qqbot_onboard", "QR rendering not available, use URL: %s", url);
    return 0;

if (!task_id || !aes_key) return -1;

    /* Generate the bind key: base64(32 random bytes) from /dev/urandom. */
    unsigned char raw[32];
    int ur = open("/dev/urandom", O_RDONLY);
    if (ur < 0 || read(ur, raw, sizeof(raw)) != (ssize_t)sizeof(raw)) {
        if (ur >= 0) close(ur);
        return -1;
    }
    close(ur);
    char *key_b64 = base64_encode(raw, sizeof(raw));
    if (!key_b64) return -1;
    snprintf(aes_key, key_len, "%s", key_b64);
    free(key_b64);

    const char *host = getenv(QQ_PORTAL_HOST_ENV);
    if (!host) host = "q.qq.com";

    char url[512];
    snprintf(url, sizeof(url), "https://%s%s", host, QQ_ONBOARD_CREATE_PATH);

    char body[256];
    snprintf(body, sizeof(body), "{\"key\":\"%s\"}", aes_key);

    char headers[256];
    snprintf(headers, sizeof(headers),
             "Content-Type: application/json\r\nAccept: application/json\r\nUser-Agent: QQBotAdapter/1.0.0 (Hermes/slermes)");

    http_t *http = http_new(QQ_ONBOARD_API_TIMEOUT);
    if (!http) return -1;

    http_resp_t *res = http_request(http, HTTP_POST, url, headers, body, strlen(body));
    int rc = -1;
    if (res && res->status >= 200 && res->status < 300 && res->body) {
        json_t *doc = json_parse(res->body, NULL);
        if (doc && doc->type == JSON_OBJECT) {
            int retcode = (int)json_get_num(doc, "retcode", -1);
            if (retcode == 0) {
                json_t *data = json_obj_get(doc, "data");
                const char *tid = data ? json_get_str(data, "task_id", NULL) : NULL;
                if (tid && tid[0]) {
                    snprintf(task_id, task_id_len, "%s", tid);
                    rc = 0;
                }
            } else {
                const char *msg = json_get_str(doc, "msg", "create_bind_task failed");
                hermes_log(LOG_ERROR, "qqbot_onboard", "create_bind_task: %s", msg);
            }
        }
        if (doc) json_free(doc);
    }
    if (res) http_resp_free(res);
    http_free(http);

    if (rc == 0)
        hermes_log(LOG_INFO, "qqbot_onboard", "Created bind task: %s", task_id);
    return rc;

if (!task_id || !task_id[0]) return -1;
    if (bot_appid && appid_len) bot_appid[0] = '\0';
    if (encrypted_secret && secret_len) encrypted_secret[0] = '\0';
    if (user_openid && openid_len) user_openid[0] = '\0';

    const char *host = getenv(QQ_PORTAL_HOST_ENV);
    if (!host) host = "q.qq.com";

    char url[512];
    snprintf(url, sizeof(url), "https://%s%s", host, QQ_ONBOARD_POLL_PATH);

    char body[256];
    snprintf(body, sizeof(body), "{\"task_id\":\"%s\"}", task_id);

    char headers[256];
    snprintf(headers, sizeof(headers),
             "Content-Type: application/json\r\nAccept: application/json\r\nUser-Agent: QQBotAdapter/1.0.0 (Hermes/slermes)");

    http_t *http = http_new(QQ_ONBOARD_API_TIMEOUT);
    if (!http) return -1;

    int status = 1; /* PENDING default */
    http_resp_t *res = http_request(http, HTTP_POST, url, headers, body, strlen(body));
    if (res && res->status >= 200 && res->status < 300 && res->body) {
        json_t *doc = json_parse(res->body, NULL);
        if (doc && doc->type == JSON_OBJECT) {
            int retcode = (int)json_get_num(doc, "retcode", -1);
            if (retcode == 0) {
                json_t *d = json_obj_get(doc, "data");
                if (d) {
                    status = (int)json_get_num(d, "status", 1);
                    const char *appid = json_get_str(d, "bot_appid", NULL);
                    const char *secret = json_get_str(d, "bot_encrypt_secret", NULL);
                    const char *openid = json_get_str(d, "user_openid", NULL);
                    if (appid && bot_appid) snprintf(bot_appid, appid_len, "%s", appid);
                    if (secret && encrypted_secret) snprintf(encrypted_secret, secret_len, "%s", secret);
                    if (openid && user_openid) snprintf(user_openid, openid_len, "%s", openid);
                }
            } else {
                const char *msg = json_get_str(doc, "msg", "poll_bind_result failed");
                hermes_log(LOG_WARNING, "qqbot_onboard", "poll_bind_result: %s", msg);
            }
        }
        if (doc) json_free(doc);
    }
    if (res) http_resp_free(res);
    http_free(http);

    hermes_log(LOG_DEBUG, "qqbot_onboard", "Polled bind result for %s: status=%d", task_id, status);
    return status;

if (!task_id || !task_id[0]) return strdup("");
    char *url = malloc(512);
    if (url)
        snprintf(url, 512, "https://q.qq.com/qqbot/openclaw/connect.html?task_id=%s&_wv=2&source=hermes", task_id);
    return url;

if (timeout_seconds <= 0) timeout_seconds = 600;

    char task_id[128];
    char aes_key[64];
    char url[512];
    char *connect_url = NULL;

    printf("\n  QQBot QR Registration\n  ======================\n\n");

    for (int refresh = 0; refresh <= MAX_REFRESHES; refresh++) {
        if (qqbot_onboard__create_bind_task(task_id, sizeof(task_id), aes_key, sizeof(aes_key)) != 0) {
            fprintf(stderr, "  Failed to create bind task\n");
            return -1;
        }

        connect_url = qqbot_onboard_build_connect_url(task_id);
        if (connect_url) {
            snprintf(url, sizeof(url), "%s", connect_url);
            free(connect_url);
        }

        if (!qqbot_onboard__render_qr(url)) {
            printf("  Open this URL in QQ on your phone:\n  %s\n", url);
        }
        printf("\n");

        time_t deadline = time(NULL) + timeout_seconds;
        while (time(NULL) < deadline) {
            char bot_appid[128] = {0};
            char encrypted_secret[256] = {0};
            char user_openid[128] = {0};

            int status = qqbot_onboard__poll_bind_result(task_id,
                                                          bot_appid, sizeof(bot_appid),
                                                          encrypted_secret, sizeof(encrypted_secret),
                                                          user_openid, sizeof(user_openid));
            if (status == 2) { /* COMPLETED */
                printf("  QR scan complete! (App ID: %s)\n", bot_appid);
                hermes_log(LOG_INFO, "qqbot_onboard", "QR registration successful");
                return 0;
            }
            if (status == 3) { /* EXPIRED */
                if (refresh >= MAX_REFRESHES) {
                    fprintf(stderr, "  QR code expired %d times - giving up\n", MAX_REFRESHES);
                    return -1;
                }
                printf("  QR code expired, refreshing... (%d/%d)\n", refresh + 1, MAX_REFRESHES);
                break;
            }
            sleep(ONBOARD_POLL_INTERVAL);
        }
    }

    fprintf(stderr, "  QR registration timed out or failed\n");
    return -1;

const char *hermes_version = HERMES_VERSION;
    if (!hermes_version) hermes_version = "dev";

    /* Detect OS — simplified for C */
    const char *os_name = "linux";
#if defined(_WIN32) || defined(_WIN64)
    os_name = "windows";
#elif defined(__APPLE__)
    os_name = "darwin";
#elif defined(__linux__)
    os_name = "linux";
#else
    os_name = "unknown";
#endif

    /* Build: "QQBotAdapter/1.0.0 (C/<hermes_version>; linux; Hermes/0.15.1)" */
    size_t len = 128 + strlen(QQBOT_VERSION) + strlen(os_name) + strlen(hermes_version);
    char *result = (char *)malloc(len);
    if (result) {
        snprintf(result, len,
                 "QQBotAdapter/%s (C/%s; %s; Hermes/%s)",
                 QQBOT_VERSION, hermes_version, os_name, hermes_version);
    }
    return result ? result : strdup("QQBotAdapter/1.0.0 (unknown)");

char *ua = cli_gateway_platforms_qqbot_utils_build_user_agent();

    size_t len = 128 + (ua ? strlen(ua) : 32);
    char *result = (char *)malloc(len);
    if (result) {
        snprintf(result, len,
                 "{\"Content-Type\":\"application/json\",\"Accept\":\"application/json\",\"User-Agent\":\"%s\"}",
                 ua ? ua : "unknown");
    }
    if (ua) free(ua);
    return result ? result : strdup("{}");

if (count_out) *count_out = 0;

    if (!value || !value[0]) {
        /* Return empty array */
        char **result = (char **)malloc(sizeof(char *));
        if (result) result[0] = NULL;
        return result;
    }

    /* Count commas to estimate max items */
    int max_items = 1;
    for (const char *p = value; *p; p++) {
        if (*p == ',') max_items++;
    }

    char **result = (char **)malloc((max_items + 1) * sizeof(char *));
    if (!result) return NULL;

    int count = 0;
    const char *start = value;
    const char *p = value;

    while (*p) {
        if (*p == ',') {
            /* Extract item from start..p */
            size_t item_len = (size_t)(p - start);
            /* Trim leading/trailing whitespace */
            while (item_len > 0 && (start[0] == ' ' || start[0] == '\t')) {
                start++;
                item_len--;
            }
            while (item_len > 0 && (start[item_len - 1] == ' ' || start[item_len - 1] == '\t')) {
                item_len--;
            }
            if (item_len > 0) {
                char *item = (char *)malloc(item_len + 1);
                if (item) {
                    memcpy(item, start, item_len);
                    item[item_len] = '\0';
                    result[count++] = item;
                }
            }
            start = p + 1;
        }
        p++;
    }

    /* Last item (no trailing comma) */
    if (start < p) {
        size_t item_len = (size_t)(p - start);
        while (item_len > 0 && (start[0] == ' ' || start[0] == '\t')) {
            start++;
            item_len--;
        }
        while (item_len > 0 && (start[item_len - 1] == ' ' || start[item_len - 1] == '\t')) {
            item_len--;
        }
        if (item_len > 0) {
            char *item = (char *)malloc(item_len + 1);
            if (item) {
                memcpy(item, start, item_len);
                item[item_len] = '\0';
                result[count++] = item;
            }
        }
    }

    result[count] = NULL;
    if (count_out) *count_out = count;
    return result;

if (!retry_after_header || !retry_after_header[0]) {
        hermes_log(LOG_DEBUG, "signal_rl", "_extract_retry_after: NULL header");
        return -1;
    }
    /* Path 1: JSON object with data.response.results[*].retryAfterSeconds */
    char *parse_err = NULL;
    json_t *doc = json_parse(retry_after_header, &parse_err);
    if (parse_err) free(parse_err);
    if (doc) {
        json_t *data = json_obj_get(doc, "data");
        json_t *response = data ? json_obj_get(data, "response") : NULL;
        json_t *results = response ? json_obj_get(response, "results") : NULL;
        if (results && results->type == JSON_ARRAY) {
            double best = -1.0;
            size_t nres = json_len(results);
            for (size_t k = 0; k < nres; k++) {
                json_t *r = json_get(results, (int)k);
                if (!r || r->type != JSON_OBJECT) continue;
                json_t *ras = json_obj_get(r, "retryAfterSeconds");
                if (ras && ras->type == JSON_NUMBER && ras->num_val > 0) {
                    if (ras->num_val > best) best = ras->num_val;
                }
            }
            if (best >= 0) {
                json_free(doc);
                return (int)best;
            }
        }
        /* fall through to message regex */
        const char *m = json_get_str(doc, "message", NULL);
        if (m) {
            int r = extract_retry_after_regex(m);
            json_free(doc);
            return r;
        }
        json_free(doc);
        return -1;
    }
    /* Path 2: plain string message */
    return extract_retry_after_regex(retry_after_header);

/* Faithful port of the Python _is_signal_rate_limit_error(err):
     *   - typed RATELIMIT_ERROR code (signal-cli >= v0.14.3)
     *   - legacy "[429]" / "RateLimitException" substrings
     *   - libsignal-net "RetryLaterException" / "Retry after N seconds"
     *     surfaced inside AttachmentInvalidException (never re-tagged as
     *     RateLimitException), so substring is the only signal.
     * `err` is either a JSON object {"code":..,"message":..} or a plain
     * string. */
    if (!err || !err[0]) return 0;

    const char *message = err;
    long code = -1;
    char *parse_err = NULL;
    json_t *doc = json_parse(err, &parse_err);
    if (parse_err) free(parse_err);
    if (doc) {
        json_t *c = json_obj_get(doc, "code");
        if (c && c->type == JSON_NUMBER) code = (long)c->num_val;
        const char *m = json_get_str(doc, "message", NULL);
        if (m) message = m;
    }

    if (code == -5) {            /* SIGNAL_RPC_ERROR_RATELIMIT = -5 (signal-cli v0.14.3+) */
        if (doc) json_free(doc);
        return 1;
    }

    /* Case-insensitive substring match (Python str(err).lower()). */
    char low[2048];
    size_t i, n = 0;
    for (i = 0; err[i] && n < sizeof(low) - 1; i++) {
        char ch = err[i];
        if (ch >= 'A' && ch <= 'Z') ch = ch - 'A' + 'a';
        low[n++] = ch;
    }
    low[n] = '\0';

    int hit = (strstr(low, "[429]") != NULL ||
               strstr(low, "ratelimit") != NULL ||
               strstr(low, "retrylaterexception") != NULL ||
               strstr(low, "retry after") != NULL);
    if (doc) json_free(doc);
    return hit;

/*
     * Format a wait duration as a human-readable string.
     * Examples: "30s", "2m", "1h"
     */
    if (!buf || bufsz == 0) return NULL;
    if (seconds < 60) {
        snprintf(buf, bufsz, "%ds", seconds);
    } else if (seconds < 3600) {
        snprintf(buf, bufsz, "%dm", seconds / 60);
    } else {
        snprintf(buf, bufsz, "%dh", seconds / 3600);
    }
    hermes_log(LOG_DEBUG, "signal_rl", "_format_wait: %d seconds -> %s", seconds, buf);
    return buf;

/*
     * Refill the token bucket based on elapsed time.
     * Returns the new token count.
     */
    if (!bucket || capacity <= 0 || tokens_per_second <= 0) {
        hermes_log(LOG_WARNING, "signal_rl", "_refill: invalid parameters");
        return -1;
    }
    /* In C, time-based refill is managed by the rate limiter */
    int new_tokens = *bucket + tokens_per_second;
    if (new_tokens > capacity) new_tokens = capacity;
    *bucket = new_tokens;
    hermes_log(LOG_DEBUG, "signal_rl", "_refill: bucket=%d capacity=%d", *bucket, capacity);
    return new_tokens;

/*
     * Estimate how long to wait before retrying.
     * Considers both the Retry-After header and the token bucket state.
     */
    if (retry_after > 0) {
        hermes_log(LOG_INFO, "signal_rl", "estimate_wait: retry_after=%d", retry_after);
        return retry_after;
    }
    if (!bucket || capacity <= 0) return 60; /* Default 60s */
    int deficit = capacity - *bucket;
    if (deficit <= 0) return 0;
    int wait = deficit; /* 1 token per second refill rate */
    hermes_log(LOG_DEBUG, "signal_rl", "estimate_wait: bucket=%d capacity=%d wait=%d", *bucket, capacity, wait);
    return wait;

/*
     * Acquire tokens from the bucket. Returns 1 if successful, 0 if not enough tokens.
     */
    if (!bucket || tokens_needed <= 0) return 0;
    if (*bucket >= tokens_needed) {
        *bucket -= tokens_needed;
        hermes_log(LOG_DEBUG, "signal_rl", "acquire: consumed %d tokens, remaining=%d", tokens_needed, *bucket);
        return 1;
    }
    hermes_log(LOG_DEBUG, "signal_rl", "acquire: insufficient tokens (need=%d have=%d)", tokens_needed, *bucket);
    return 0;

/*
     * Provide feedback to the rate limiter about throttling events.
     * Adjusts the bucket based on whether we were throttled.
     */
    if (was_throttled) {
        hermes_log(LOG_INFO, "signal_rl", "feedback: throttled, retry_after=%d", retry_after);
        /* Reduce bucket to avoid further throttling */
    } else {
        hermes_log(LOG_DEBUG, "signal_rl", "feedback: not throttled");
    }

/*
     * Initialize a token bucket. Returns a JSON object with bucket state.
     */
    json_node_t *bucket = json_new_object();
    if (!bucket) return NULL;
    json_object_set(bucket, "capacity", json_new_number(capacity));
    json_object_set(bucket, "tokens", json_new_number(capacity));
    json_object_set(bucket, "tokens_per_second", json_new_number(tokens_per_second));
    json_object_set(bucket, "last_refill", json_new_number(time(NULL)));
    hermes_log(LOG_DEBUG, "signal_rl", "_token_bucket_init: capacity=%d rate=%d", capacity, tokens_per_second);
    return bucket;

/*
     * Refill the token bucket if enough time has passed.
     * Returns the current token count.
     */
    if (!bucket || !json_node_is_object(bucket)) return 0;
    json_node_t *tokens_node = json_object_get(bucket, "tokens");
    json_node_t *cap_node = json_object_get(bucket, "capacity");
    int tokens = tokens_node ? json_node_get_int(tokens_node) : 0;
    int capacity = cap_node ? json_node_get_int(cap_node) : 0;
    if (tokens < capacity) {
        tokens = capacity; /* Full refill for simplicity */
        json_object_set(bucket, "tokens", json_new_number(tokens));
    }
    hermes_log(LOG_DEBUG, "signal_rl", "_maybe_refill: tokens=%d capacity=%d", tokens, capacity);
    return tokens;

/*
     * Update the rate limiter state based on an HTTP response.
     * Handles 429 responses and Retry-After headers.
     */
    if (!bucket) return;
    if (status_code == 429 && retry_after && retry_after[0]) {
        int seconds = cli_gateway_platforms_signal_rate_limit__extract_retry_after_seconds(retry_after);
        if (seconds > 0) {
            json_object_set(bucket, "tokens", json_new_number(0));
            hermes_log(LOG_INFO, "signal_rl", "_update_from_response: rate limited, wait=%d", seconds);
        }
    } else if (status_code == 200) {
        hermes_log(LOG_DEBUG, "signal_rl", "_update_from_response: success");
    }

if (!bucket || !json_node_is_object(bucket)) return;
    if (n_attachments <= 0) return;

    double token_before = json_object_get_number(bucket, "tokens", 0.0);
    double token_after = token_before - (double)n_attachments;
    if (token_after < 0.0) token_after = 0.0;
    json_object_set(bucket, "tokens", json_new_number(token_after));
    json_object_set(bucket, "last_refill", json_new_number((double)time(NULL)));

    double refill_rate = json_object_get_number(bucket, "tokens_per_second", 0.0);
    int level = (rpc_duration > 10.0 && n_attachments > 5) ? LOG_INFO : LOG_DEBUG;
    hermes_log(level, "signal_rl",
        "report_rpc_duration: RPC for %d att took %.1fs — tokens %.1f -> %.1f (deducted=%d, no upload refill credited, refill=%.4f/s)",
        n_attachments, rpc_duration, token_before, token_after, n_attachments, refill_rate);

/* Check for required env vars */
    const char *account_sid = getenv("TWILIO_ACCOUNT_SID");
    const char *auth_token = getenv("TWILIO_AUTH_TOKEN");

    if (!account_sid || !*account_sid) {
        hermes_log(LOG_DEBUG, "sms", "TWILIO_ACCOUNT_SID not set");
        return 0;
    }
    if (!auth_token || !*auth_token) {
        hermes_log(LOG_DEBUG, "sms", "TWILIO_AUTH_TOKEN not set");
        return 0;
    }

    hermes_log(LOG_DEBUG, "sms", "SMS requirements met (SID=%.*s...)",
               account_sid ? 8 : 0, account_sid ? account_sid : "");
    return 1;

if (!account_sid || !auth_token || !header_out || header_size == 0) return -1;

    /* Build base64-encoded credentials: base64("sid:token") */
    char creds[512];
    snprintf(creds, sizeof(creds), "%s:%s", account_sid, auth_token);

    char *b64 = base64_encode((const unsigned char *)creds, strlen(creds));
    if (!b64) return -1;
    snprintf(header_out, header_size, "Basic %s", b64);
    free(b64);
    hermes_log(LOG_DEBUG, "sms", "Built auth header for SID=%.*s",
               account_sid ? 8 : 0, account_sid ? account_sid : "");
    return 0;

if (!url || !signature || !auth_token) return 0;

    /* Try primary URL */
    int result = cli_gateway_platforms_sms__check_signature(
        url, param_keys, param_values, param_count, signature, auth_token);
    if (result) return 1;

    /* Try port variant URL */
    char variant_url[2048];
    /* Build variant: toggle default port */
    if (strstr(url, "https://") == url) {
        /* For https, try without :443 or with :443 */
        char *port_pos = strstr(url + 8, ":443");
        if (port_pos) {
            /* Has explicit :443 — try without */
            size_t prefix = (size_t)(port_pos - url);
            snprintf(variant_url, sizeof(variant_url), "%.*s%s", (int)prefix, url, port_pos + 4);
        } else {
            /* No port — try adding :443 */
            char *path_pos = strchr(url + 8, '/');
            if (path_pos) {
                size_t prefix = (size_t)(path_pos - url);
                snprintf(variant_url, sizeof(variant_url), "%.*s:443%s",
                         (int)prefix, url, path_pos);
            } else {
                snprintf(variant_url, sizeof(variant_url), "%s:443", url);
            }
        }
    } else if (strstr(url, "http://") == url) {
        char *port_pos = strstr(url + 7, ":80");
        if (port_pos) {
            size_t prefix = (size_t)(port_pos - url);
            snprintf(variant_url, sizeof(variant_url), "%.*s%s", (int)prefix, url, port_pos + 3);
        } else {
            char *path_pos = strchr(url + 7, '/');
            if (path_pos) {
                size_t prefix = (size_t)(path_pos - url);
                snprintf(variant_url, sizeof(variant_url), "%.*s:80%s",
                         (int)prefix, url, path_pos);
            } else {
                snprintf(variant_url, sizeof(variant_url), "%s:80", url);
            }
        }
    } else {
        variant_url[0] = '\0';
    }

    if (variant_url[0]) {
        result = cli_gateway_platforms_sms__check_signature(
            variant_url, param_keys, param_values, param_count, signature, auth_token);
        if (result) return 1;
    }

    hermes_log(LOG_WARNING, "sms", "Twilio signature validation failed");
    return 0;

if (!url || !signature || !auth_token) return 0;

    /* Build data_to_sign = url + sorted(key + value).
     * Twilio sorts the concatenation of each "keyvalue" pair. */
    char data[8192];
    snprintf(data, sizeof(data), "%s", url);

    /* Collect "keyvalue" pairs, sort them, append. */
    char pairs[256][512];
    int np = 0;
    for (int i = 0; i < param_count && np < 256; i++) {
        if (param_keys[i] && param_values[i]) {
            snprintf(pairs[np], sizeof(pairs[np]), "%s%s", param_keys[i], param_values[i]);
            np++;
        }
    }
    /* Simple insertion sort (ascending, byte-wise). */
    for (int i = 1; i < np; i++) {
        char key[512];
        snprintf(key, sizeof(key), "%s", pairs[i]);
        int j = i - 1;
        while (j >= 0 && strcmp(pairs[j], key) > 0) {
            char tmp[512];
            snprintf(tmp, sizeof(tmp), "%s", pairs[j]);
            snprintf(pairs[j + 1], sizeof(pairs[j + 1]), "%s", tmp);
            j--;
        }
        snprintf(pairs[j + 1], sizeof(pairs[j + 1]), "%s", key);
    }
    for (int i = 0; i < np; i++) {
        size_t pos = strlen(data);
        if (pos < sizeof(data) - 512)
            snprintf(data + pos, sizeof(data) - pos, "%s", pairs[i]);
    }

    /* Compute HMAC-SHA1(auth_token, data) and base64-encode it. */
    unsigned char mac[20];
    crypto_hmac_sha1((const unsigned char *)auth_token, strlen(auth_token),
                     (const unsigned char *)data, strlen(data), mac);
    char *computed = base64_encode(mac, sizeof(mac));
    if (!computed) return 0;

    int match = (strcmp(computed, signature) == 0);
    free(computed);

    hermes_log(LOG_DEBUG, "sms", "Checking signature for URL (len=%zu) match=%d",
               strlen(data), match);
    return match;

if (!url || !variant_out || variant_size == 0) return -1;

    variant_out[0] = '\0';

    /* Parse scheme */
    int default_port = 0;
    const char *scheme_end = strstr(url, "://");
    if (!scheme_end) return -1;

    size_t scheme_len = (size_t)(scheme_end - url);
    if (scheme_len == 5 && strncmp(url, "https", 5) == 0) {
        default_port = 443;
    } else if (scheme_len == 4 && strncmp(url, "http", 4) == 0) {
        default_port = 80;
    } else {
        return -1; /* Unknown scheme */
    }

    /* Find hostname and port */
    const char *host_start = scheme_end + 3;
    const char *path_start = strchr(host_start, '/');
    const char *port_start = strchr(host_start, ':');

    if (port_start && (!path_start || port_start < path_start)) {
        /* Has explicit port */
        int port = atoi(port_start + 1);
        if (port == default_port) {
            /* Strip default port */
            size_t host_len = (size_t)(port_start - host_start);
            size_t path_len = path_start ? strlen(path_start) : 0;
            if (host_len + path_len + 1 > variant_size) return -1;
            snprintf(variant_out, variant_size, "%.*s%s",
                     (int)host_len, host_start, path_start ? path_start : "");
            return 0;
        }
    } else if (!port_start || (path_start && port_start > path_start)) {
        /* No port — add default */
        size_t host_len = path_start ? (size_t)(path_start - host_start) : strlen(host_start);
        size_t remaining = variant_size;
        int written = snprintf(variant_out, remaining, "%.*s:%d",
                               (int)host_len, host_start, default_port);
        if (written > 0 && (size_t)written < remaining && path_start) {
            strncat(variant_out, path_start, remaining - written - 1);
        }
        return 0;
    }

    /* Non-standard port — no variant */
    return -1;

/*
     * Check if all required dependencies are available.
     * Requires aiohttp, httpx, and defusedxml.
     * In C, these are built-in (libhttp, libxml).
     */
    int aiohttp_ok = 1; /* libhttp provides HTTP server */
    int httpx_ok = 1;   /* libhttp provides HTTP client */
    int defused_ok = 1; /* libxml provides XML parsing */
    int result = aiohttp_ok && httpx_ok && defused_ok;
    hermes_log(LOG_DEBUG, "wecom_callback", "check_requirements: %d", result);
    return result;

/*
     * Normalize the apps configuration from the extra config dict.
     * Returns a JSON array of app configuration objects.
     */
    json_node_t *apps = json_new_array();
    if (!apps) return json_new_array();
    if (!extra || !json_node_is_object(extra)) return apps;
    /* Check if apps list is provided */
    json_node_t *apps_list = json_object_get(extra, "apps");
    if (apps_list && json_node_is_array(apps_list)) {
        int n = json_array_count(apps_list);
        int i;
        for (i = 0; i < n; i++) {
            json_node_t *app = json_array_get(apps_list, i);
            if (app && json_node_is_object(app)) {
                json_array_append(apps, app);
            }
        }
    } else {
        /* Single app from individual fields */
        json_node_t *corp_id = json_object_get(extra, "corp_id");
        if (corp_id && json_node_is_string(corp_id)) {
            json_node_t *app = json_new_object();
            if (app) {
                json_object_set(app, "name", json_new_string("default"));
                json_object_set(app, "corp_id", corp_id);
                json_object_set(app, "corp_secret", json_object_get(extra, "corp_secret"));
                json_object_set(app, "agent_id", json_object_get(extra, "agent_id"));
                json_object_set(app, "token", json_object_get(extra, "token"));
                json_object_set(app, "encoding_aes_key", json_object_get(extra, "encoding_aes_key"));
                json_array_append(apps, app);
            }
        }
    }
    hermes_log(LOG_DEBUG, "wecom_callback", "_normalize_apps: %d app(s)", json_array_count(apps));
    return apps;

/*
     * Pick the app associated with chat_id, falling back sensibly.
     * Returns the app JSON object.
     */
    if (!chat_id || !apps || !json_node_is_array(apps)) return NULL;
    int n = json_array_count(apps);
    if (n == 0) return NULL;
    /* Try to find app by user_app_map */
    if (user_app_map && json_node_is_object(user_app_map)) {
        json_node_t *app_name = json_object_get(user_app_map, chat_id);
        if (app_name && json_node_is_string(app_name)) {
            const char *name = json_node_get_string(app_name);
            int i;
            for (i = 0; i < n; i++) {
                json_node_t *app = json_array_get(apps, i);
                if (app && json_node_is_object(app)) {
                    json_node_t *app_name_field = json_object_get(app, "name");
                    if (app_name_field && json_node_is_string(app_name_field) &&
                        strcmp(json_node_get_string(app_name_field), name) == 0) {
                        return app;
                    }
                }
            }
        }
    }
    /* Fallback: return first app */
    return json_array_get(apps, 0);

/*
     * GET endpoint — WeCom URL verification handshake.
     * Tries each app's crypto to verify the URL.
     * Returns 0 on success, -1 on failure.
     */
    if (!msg_signature || !timestamp || !nonce || !echostr || !apps) return -1;
    if (!json_node_is_array(apps)) return -1;
    int n = json_array_count(apps);
    int i;
    for (i = 0; i < n; i++) {
        json_node_t *app = json_array_get(apps, i);
        if (!app || !json_node_is_object(app)) continue;
        /* In C, URL verification uses the crypto module */
        hermes_log(LOG_DEBUG, "wecom_callback", "_handle_verify: trying app %d", i);
        /* Simplified: in real implementation, call WXBizMsgCrypt.verify_url */
    }
    hermes_log(LOG_WARNING, "wecom_callback", "_handle_verify: signature verification failed");
    return -1;

/*
     * GET endpoint — WeCom URL verification handshake.
     * Tries each app's crypto to verify the URL.
     * Returns 0 on success, -1 on failure.
     */
    if (!msg_signature || !timestamp || !nonce || !echostr || !apps) return -1;
    if (!json_node_is_array(apps)) return -1;
    int n = json_array_count(apps);
    int i;
    for (i = 0; i < n; i++) {
        json_node_t *app = json_array_get(apps, i);
        if (!app || !json_node_is_object(app)) continue;
        /* In C, URL verification uses the crypto module */
        hermes_log(LOG_DEBUG, "wecom_callback", "_handle_verify: trying app %d", i);
        /* Simplified: in real implementation, call WXBizMsgCrypt.verify_url */
    }
    hermes_log(LOG_WARNING, "wecom_callback", "_handle_verify: signature verification failed");
    return -1;

/*
     * POST endpoint — receive an encrypted message callback.
     * Decrypts the message, builds a MessageEvent, and queues it.
