                all[na].ms=ms;all[na].me=me;all[na].g1s=g1s;all[na].g1e=g1e;all[na].pi=p;
                na++;
                if (no+1>=ocap){ocap=ocap?ocap*2:16;occ=realloc(occ,ocap*sizeof(span_t));}
