            if (nr+1>=rcap){rcap=rcap?rcap*2:16;rems=realloc(rems,rcap*sizeof(rem_t));}
            rems[nr].pos=all[a].ms; rems[nr].len=all[a].g1s-all[a].ms; nr++;
        }
        if (all[a].me > all[a].g1e) {
            if (nr+1>=rcap){rcap=rcap?rcap*2:16;rems=realloc(rems,rcap*sizeof(rem_t));}
            rems[nr].pos=all[a].g1e; rems[nr].len=all[a].me-all[a].g1e; nr++;
