    size_t n = end - start;
    char *out = malloc(n + 1);
    if (!out) return NULL;
    size_t j = 0;
    bool in_space = false;
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)text[start + i];
        if (isspace(c)) {
            if (!in_space) { out[j++] = ' '; in_space = true; }
        } else {
            out[j++] = (char)tolower(c);
