if (!bearer_out || bearer_size == 0 || !base_url_out || url_size == 0) {
        return -1;
    }
    bearer_out[0] = '\0';
    strncpy(base_url_out, "https://inference-api.nousresearch.com/v1", url_size - 1);
    base_url_out[url_size - 1] = '\0';
    if (!auth_path) return 0;
    /* Pull an access_token / agent_key out of the saved state if present. */
    char state[4096];
    if (cli_hermes_cli_proxy_adapters_nous_portal__read_state(auth_path, state, sizeof(state)) == 0) {
        const char *tok = strstr(state, "\"access_token\"");
        if (!tok) tok = strstr(state, "\"agent_key\"");
        if (tok) {
            const char *q1 = strchr(tok, '"');
            if (q1) { q1 = strchr(q1 + 1, '"'); if (q1) {
                const char *q2 = strchr(q1 + 1, '"');
                if (q2) {
                    size_t len = (size_t)(q2 - (q1 + 1));
                    if (len >= bearer_size) len = bearer_size - 1;
                    memcpy(bearer_out, q1 + 1, len);
                    bearer_out[len] = '\0';
                }
            }}
        }
    }
    return 0;

const char *json =
        "[\"/chat/completions\",\"/completions\",\"/embeddings\","
        "\"/models\",\"/responses\",\"/audio/speech\",\"/audio/transcriptions\"]";
    return strdup(json);

const char *def_base = "https://api.x.ai/v1";
    if (!bearer_out || bearer_size == 0 || !base_url_out || url_size == 0) {
        return -1;
    }
    bearer_out[0] = '\0';
    strncpy(base_url_out, def_base, url_size - 1);
    base_url_out[url_size - 1] = '\0';

    if (!entry_json) return -1;

    /* Prefer runtime_api_key, fall back to access_token. */
    const char *tok = strstr(entry_json, "\"runtime_api_key\"");
    if (!tok) tok = strstr(entry_json, "\"access_token\"");
    if (tok) {
        const char *q1 = strchr(tok, '"');
        if (q1) { q1 = strchr(q1 + 1, '"'); if (q1) {
            const char *q2 = strchr(q1 + 1, '"');
            if (q2) {
                size_t len = (size_t)(q2 - (q1 + 1));
                if (len >= bearer_size) len = bearer_size - 1;
                memcpy(bearer_out, q1 + 1, len);
                bearer_out[len] = '\0';
            }
        }}
    }
    if (!bearer_out[0]) return -1;  /* no token -> raise equivalent */

    /* Optional base URL override. */
    const char *bu = strstr(entry_json, "\"runtime_base_url\"");
    if (!bu) bu = strstr(entry_json, "\"base_url\"");
    if (bu) {
        const char *q1 = strchr(bu, '"');
        if (q1) { q1 = strchr(q1 + 1, '"'); if (q1) {
            const char *q2 = strchr(q1 + 1, '"');
            if (q2) {
                size_t len = (size_t)(q2 - (q1 + 1));
                if (len >= url_size) len = url_size - 1;
                if (len > 0) {
                    memcpy(base_url_out, q1 + 1, len);
                    base_url_out[len] = '\0';
                }
            }
        }}
    }
    /* strip a trailing slash from base URL */
    size_t bl = strlen(base_url_out);
    while (bl > 0 && base_url_out[bl - 1] == '/') base_url_out[--bl] = '\0';
    return 0;

/* Python: shared-metrics policy from config.telemetry.shared_metrics
     * .enabled; deactivates the runtime when disabled. */
    bool value = false;
    if (config_json) {
        json_t *cfg = json_parse(config_json, NULL);
        if (cfg && cfg->type == JSON_OBJECT) {
            json_t *tel = json_obj_get(cfg, "telemetry");
            if (tel && tel->type == JSON_OBJECT) {
                json_t *sm = json_obj_get(tel, "shared_metrics");
                if (sm && sm->type == JSON_OBJECT) {
                    json_t *e = json_obj_get(sm, "enabled");
                    if (e && e->type == JSON_BOOL) value = e->bool_val;
                }
            }
        }
        if (cfg) json_free(cfg);
    }
    if (!value) rsm_runtime_deactivate(NULL);
    return value;

/* Python: hook_name in HANDLED_HOOKS and enabled(). */
    if (!hook_name) return false;
    static const char *handled[] = {
        "on_session_start", "pre_llm_call", "pre_api_request",
        "post_tool_call", "post_api_request", "api_request_error",
        "on_session_end", "subagent_stop",
        "on_session_finalize", "on_session_reset", NULL
    };
    bool known = false;
    for (int i = 0; handled[i]; i++)
        if (strcmp(hook_name, handled[i]) == 0) { known = true; break; }
    if (!known) return false;
    return rsm_enabled(config_json);

/* Python: project one lifecycle event into the runtime. Returns 1 when
     * handled. */
    if (!hook_name || !event_json) return 0;
    json_t *ev = json_parse(event_json, NULL);
    if (!ev) return 0;
    const char *session_id = rsm_json_get_str(ev, "session_id", "");
    const char *task_id = rsm_json_get_str(ev, "task_id", "");
    const char *turn_id = rsm_json_get_str(ev, "turn_id", "");
    const char *request_id = rsm_json_get_str(ev, "api_request_id", "");
    const char *tool_call_id = rsm_json_get_str(ev, "tool_call_id", "");
    int rc = 0;
    if (strcmp(hook_name, "on_session_start") == 0) {
        rc = rsm_runtime_ensure_session(host, session_id);
    } else if (strcmp(hook_name, "pre_llm_call") == 0) {
        rc = rsm_runtime_start_task(host, session_id, task_id, turn_id, event_json);
    } else if (strcmp(hook_name, "pre_api_request") == 0) {
        rc = rsm_runtime_start_model_call(host, session_id, task_id, request_id,
                                          turn_id, event_json);
    } else if (strcmp(hook_name, "post_tool_call") == 0) {
        rc = rsm_runtime_record_tool_call(host, session_id, task_id, tool_call_id,
                                          turn_id, event_json);
    } else if (strcmp(hook_name, "post_api_request") == 0) {
        rc = rsm_runtime_end_model_call(host, session_id, task_id, request_id,
                                        turn_id, "success", event_json);
    } else if (strcmp(hook_name, "api_request_error") == 0) {
        const char *retryable = rsm_json_get_str(ev, "retryable", "");
        if (strcmp(retryable, "false") == 0)
            rc = rsm_runtime_end_model_call(host, session_id, task_id, request_id,
                                            turn_id, "failed", event_json);
    } else if (strcmp(hook_name, "on_session_end") == 0) {
        rc = rsm_runtime_finish_task(host, session_id, task_id, turn_id, event_json);
    } else if (strcmp(hook_name, "subagent_stop") == 0) {
        const char *child = rsm_json_get_str(ev, "child_session_id", "");
        if (child[0]) {
            char cev[320];
            snprintf(cev, sizeof(cev), "{\"session_id\":\"%s\"}", child);
            rc = rsm_runtime_close_session(host, child, cev);
        }
    } else if (strcmp(hook_name, "on_session_finalize") == 0 ||
               strcmp(hook_name, "on_session_reset") == 0) {
        rc = rsm_runtime_close_session(host, session_id, event_json);
    }
    json_free(ev);
    return rc;

/* Python: register the subscriber before any producer opens the session
     * scope (no-op when disabled). */
    if (!rsm_enabled(config_json)) return 0;
    if (!host) return 0;
    return rsm_get_runtime(host) ? 1 : 0;

/* Python: prepare the profile subscriber when the host's profile is the
     * active one. */
    (void)config_json;
    if (!host) return 0;
    return rsm_prepare_session_start(host, config_json);

/* Python: start task metrics at the outer Hermes execution boundary. */
    if (!rsm_enabled(config_json)) return 0;
    if (!host) return 0;
    char *event = NULL;
    asprintf(&event,
             "{\"session_id\":\"%s\",\"task_id\":\"%s\",\"platform\":\"%s\","
             "\"parent_session_id\":\"%s\"}",
             session_id ? session_id : "", task_id ? task_id : "",
             platform ? platform : "", parent_session_id ? parent_session_id : "");
    int rc = rsm_runtime_start_task(host, session_id, task_id, NULL, event);
    free(event);
    return rc;

/* Python: finish task metrics for every return or exception path;
     * terminal fields are derived from result/error. */
    if (!rsm_enabled(config_json)) return 0;
    if (!host) return 0;
    bool interrupted = false, completed = false, failed = false;
    const char *reason = "";
    json_t *terminal = result_json ? json_parse(result_json, NULL) : NULL;
    if (terminal) {
        interrupted = rsm_json_get_bool(terminal, "interrupted");
        completed = rsm_json_get_bool(terminal, "completed");
        failed = rsm_json_get_bool(terminal, "failed");
        const char *r = rsm_json_get_str(terminal, "turn_exit_reason", NULL);
        if (!r || !r[0]) r = rsm_json_get_str(terminal, "failure_reason", "");
        reason = r ? r : "";
    }
    if (error_name && error_name[0]) {
        interrupted = (strstr(error_name, "KeyboardInterrupt") != NULL ||
                       strstr(error_name, "InterruptedError") != NULL ||
                       strstr(error_name, "CancelledError") != NULL);
        bool timed_out = (strstr(error_name, "TimeoutError") != NULL ||
                          strstr(error_name, "Timeout") != NULL);
        completed = false;
        failed = !interrupted;
        if (interrupted) reason = "interrupted_by_user";
        else if (timed_out) reason = "timed_out";
        else reason = "system_aborted";
    } else if (!reason || !reason[0]) {
        reason = failed ? "failed" : "unknown";
    }
    char *event = NULL;
    asprintf(&event,
             "{\"session_id\":\"%s\",\"task_id\":\"%s\",\"platform\":\"%s\","
             "\"completed\":%s,\"failed\":%s,\"interrupted\":%s,"
             "\"turn_exit_reason\":\"%s\"}",
             session_id ? session_id : "", task_id ? task_id : "",
             platform ? platform : "",
             completed ? "true" : "false", failed ? "true" : "false",
             interrupted ? "true" : "false", reason);
    int rc = rsm_runtime_finish_task(host, session_id, task_id, NULL, event);
    free(event);
    if (terminal) json_free(terminal);
    return rc;

/* Python: resolve the profile's runtime (initializing on first use). */
    if (!host) return 0;
    pthread_mutex_lock(&g_rsm_lock);
    bool init = !g_sessions;
    pthread_mutex_unlock(&g_rsm_lock);
    if (init) return rsm_runtime_init(host) == 0;
    return 1;

/* Python: tear down every runtime and reset the registry (tests only). */
    pthread_mutex_lock(&g_rsm_lock);
    if (g_sessions) { omap_free(g_sessions); g_sessions = NULL; }
    if (g_task_sessions) { omap_free(g_task_sessions); g_task_sessions = NULL; }
    if (g_turn_sessions) { omap_free(g_turn_sessions); g_turn_sessions = NULL; }
    g_rsm_active = false;
    g_rsm_registered = false;
    g_host = NULL;
    pthread_mutex_unlock(&g_rsm_lock);
    return 0;

if (!out || out_sz == 0) return false;
    out[0] = '\0';
    if (!pkg_name || !*pkg_name) return false;

    char norm_pkg[512];
    pep503_normalize(pkg_name, norm_pkg, sizeof(norm_pkg));

    char roots[16][HERMES_PATH_MAX];
    int nroots = collect_site_packages(roots, 16);
    for (int i = 0; i < nroots; i++) {
        if (scan_site_packages(roots[i], norm_pkg, out, out_sz))
            return true;
    }
    return false;

json_t *hits = json_array();
    for (size_t ai = 0; ai < N_ADVISORIES; ai++) {
        const advisory_t *a = &ADVISORIES[ai];
        for (int pi = 0; a->compromised[pi].pkg; pi++) {
            const advisory_pkg_t *cp = &a->compromised[pi];
            char installed[128];
            if (!cli_security_advisories_installed_version(
                    cp->pkg, installed, sizeof(installed)))
                continue;
            bool empty_set = (cp->versions[0] == NULL);
            bool match = empty_set;
            for (int vi = 0; !match && cp->versions[vi]; vi++)
                if (strcmp(installed, cp->versions[vi]) == 0) match = true;
            if (match)
                json_append(hits, make_hit(a, cp->pkg, installed));
        }
    }
    return hits;

json_t *out = json_array();
    json_t *cfg = config_py_read_raw_config();
    if (!cfg) return out;
    json_t *sec = json_obj_get(cfg, "security");
    json_t *raw = (sec && sec->type == JSON_OBJECT)
                      ? json_obj_get(sec, "acked_advisories") : NULL;
    if (raw && raw->type == JSON_ARRAY) {
        for (size_t i = 0; i < raw->c.count; i++) {
            json_t *it = raw->c.items[i];
            if (!it || it->type != JSON_STRING || !it->str_val) continue;
            /* strip() then skip empties, same as the Python set-builder */
            const char *s = it->str_val;
            while (*s == ' ' || *s == '\t') s++;
            size_t len = strlen(s);
            while (len > 0 && (s[len-1] == ' ' || s[len-1] == '\t')) len--;
            if (len == 0) continue;
            char tmp[256];
            if (len >= sizeof(tmp)) len = sizeof(tmp) - 1;
            memcpy(tmp, s, len);
            tmp[len] = '\0';
            json_append(out, json_string(tmp));
        }
    }
    json_free(cfg);
    return out;

if (!advisory_id) return false;
    while (*advisory_id == ' ' || *advisory_id == '\t') advisory_id++;
    char trimmed[256];
    snprintf(trimmed, sizeof(trimmed), "%s", advisory_id);
    for (size_t len = strlen(trimmed);
         len > 0 && (trimmed[len-1] == ' ' || trimmed[len-1] == '\t');
         len--)
        trimmed[len-1] = '\0';
    if (!trimmed[0]) return false;

    json_t *cfg = config_py_read_raw_config();
    if (!cfg) {
        hermes_log(LOG_WARNING, "security",
                   "Could not load config to persist ack");
        return false;
    }
    json_t *sec = json_obj_get(cfg, "security");
    if (!sec || sec->type != JSON_OBJECT) {
        sec = json_object();
        json_set(cfg, "security", sec);
    }
    json_t *existing = json_obj_get(sec, "acked_advisories");
    if (!existing || existing->type != JSON_ARRAY) {
        existing = json_array();
        json_set(sec, "acked_advisories", existing);
    }
    bool present = false;
    for (size_t i = 0; !present && i < existing->c.count; i++) {
        json_t *it = existing->c.items[i];
        if (it && it->type == JSON_STRING && it->str_val &&
            strcmp(it->str_val, trimmed) == 0)
            present = true;
    }
    bool ok = true;
    if (!present) {
        json_append(existing, json_string(trimmed));
        char path[HERMES_PATH_MAX];
        config_py_get_config_path(path, sizeof(path));
        ok = (config_py_atomic_config_write(path, cfg) == 0);
        if (!ok)
            hermes_log(LOG_ERROR, "security",
                       "Failed to persist advisory ack for %s", trimmed);
    }
    json_free(cfg);
    return ok;

json_t *out = json_array();
    if (!hits || hits->type != JSON_ARRAY || hits->c.count == 0) return out;
    json_t *acked = cli_security_advisories_get_acked_ids();
    for (size_t i = 0; i < hits->c.count; i++) {
        json_t *h = hits->c.items[i];
        if (!h || h->type != JSON_OBJECT) continue;
        json_t *idv = json_obj_get(h, "advisory_id");
        const char *hid = (idv && idv->type == JSON_STRING) ? idv->str_val : NULL;
        bool is_acked = false;
        if (hid) {
            for (size_t j = 0; !is_acked && j < acked->c.count; j++) {
                json_t *aid = acked->c.items[j];
                if (aid && aid->type == JSON_STRING && aid->str_val &&
                    strcmp(aid->str_val, hid) == 0)
                    is_acked = true;
            }
        }
        if (!is_acked) json_append(out, json_copy(h));
    }
    json_free(acked);
    return out;

const char *no_color = getenv("NO_COLOR");
    if (no_color && *no_color) return false;
    if (!isatty(STDOUT_FILENO)) return false;
    return true;

if (!out || out_sz == 0) return false;
    out[0] = '\0';
    if (!hits || hits->type != JSON_ARRAY || hits->c.count == 0) return false;

    json_t *primary = hits->c.items[0];
    if (!primary || primary->type != JSON_OBJECT) return false;
    json_t *jid = json_obj_get(primary, "advisory_id");
    json_t *jtitle = json_obj_get(primary, "title");
    json_t *jpkg = json_obj_get(primary, "package");
    json_t *jver = json_obj_get(primary, "installed_version");
    const char *id = (jid && jid->str_val) ? jid->str_val : "unknown";
    const char *title = (jtitle && jtitle->str_val) ? jtitle->str_val : "";
    const char *pkg = (jpkg && jpkg->str_val) ? jpkg->str_val : "";
    const char *ver = (jver && jver->str_val) ? jver->str_val : "";

    size_t pos = 0;
    buf_append(out, out_sz, &pos, "SECURITY ADVISORY [%s]: %s\n", id, title);
    if (hits->c.count > 1) {
        size_t extra = hits->c.count - 1;
        buf_append(out, out_sz, &pos, "  (%zu additional advisor%s also active.)\n",
                   extra, extra > 1 ? "ies" : "y");
    }
    buf_append(out, out_sz, &pos, "  Detected: %s==%s\n", pkg, ver);
    buf_append(out, out_sz, &pos, "  Run 'hermes doctor' for remediation steps.");
    return true;

if (!out || out_sz == 0) return false;
    out[0] = '\0';
    if (!hit || hit->type != JSON_OBJECT) return false;

    json_t *jid = json_obj_get(hit, "advisory_id");
    json_t *jtitle = json_obj_get(hit, "title");
    json_t *jsev = json_obj_get(hit, "severity");
    json_t *jpub = json_obj_get(hit, "published");
    json_t *jpkg = json_obj_get(hit, "package");
    json_t *jver = json_obj_get(hit, "installed_version");
    json_t *jurl = json_obj_get(hit, "url");
    json_t *jsum = json_obj_get(hit, "summary");
    json_t *jrem = json_obj_get(hit, "remediation");

    size_t pos = 0;
    buf_append(out, out_sz, &pos, "=== %s ===\n",
               (jtitle && jtitle->str_val) ? jtitle->str_val : "");
    buf_append(out, out_sz, &pos, "ID:        %s    Severity: %s    Published: %s\n",
               (jid && jid->str_val) ? jid->str_val : "",
               (jsev && jsev->str_val) ? jsev->str_val : "high",
               (jpub && jpub->str_val) ? jpub->str_val : "");
    buf_append(out, out_sz, &pos, "Detected:  %s==%s\n",
               (jpkg && jpkg->str_val) ? jpkg->str_val : "",
               (jver && jver->str_val) ? jver->str_val : "");
    buf_append(out, out_sz, &pos, "Reference: %s\n\n",
               (jurl && jurl->str_val) ? jurl->str_val : "");
    buf_append(out, out_sz, &pos, "%s\n\n",
               (jsum && jsum->str_val) ? jsum->str_val : "");
    buf_append(out, out_sz, &pos, "Remediation:");
    if (jrem && jrem->type == JSON_ARRAY) {
        for (size_t i = 0; i < jrem->c.count; i++) {
            json_t *step = jrem->c.items[i];
            if (step && step->type == JSON_STRING && step->str_val)
                buf_append(out, out_sz, &pos, "\n  %zu. %s", i + 1, step->str_val);
        }
    }
    return true;

if (!out || out_sz == 0) return false;
    char home[HERMES_PATH_MAX];
    hermes_get_home(home, sizeof(home));
    if (!home[0]) return false;
    char cache_dir[HERMES_PATH_MAX];
    snprintf(cache_dir, sizeof(cache_dir), "%s/cache", home);
    if (mkdir(cache_dir, 0755) != 0) {
        struct stat st;
        if (stat(cache_dir, &st) != 0 || !S_ISDIR(st.st_mode)) return false;
    }
    snprintf(out, out_sz, "%s/%s", cache_dir, BANNER_CACHE_FILE);
    return true;

json_t *out = json_object();
    char path[HERMES_PATH_MAX];
    if (!cli_security_advisories_banner_cache_path(path, sizeof(path)))
        return out;
    FILE *f = fopen(path, "r");
    if (!f) return out;
    char line[512];
    while (fgets(line, sizeof(line), f)) {
        char aid[256];
        double ts;
        if (sscanf(line, "%255s %lf", aid, &ts) == 2 && aid[0])
            json_set(out, aid, json_number(ts));
    }
    fclose(f);
    return out;

if (!seen || seen->type != JSON_OBJECT) return;
    char path[HERMES_PATH_MAX];
    if (!cli_security_advisories_banner_cache_path(path, sizeof(path)))
        return;
    FILE *f = fopen(path, "w");
    if (!f) {
        hermes_log(LOG_DEBUG, "security",
                   "Could not write advisory banner cache");
        return;
    }
    for (size_t i = 0; i < seen->c.count; i++) {
        json_t *v = seen->c.items[i];
        double ts = (v && v->type == JSON_NUMBER) ? v->num_val : 0.0;
        fprintf(f, "%s %f\n", seen->c.keys[i], ts);
    }
    fclose(f);

json_t *fresh = cli_security_advisories_filter_unacked(hits);
    if (fresh->c.count == 0) return fresh;

    double now = (double)time(NULL);
    double cutoff = now - ((double)repeat_hours * 3600.0);
    json_t *cache = cli_security_advisories_read_banner_cache();

    json_t *due = json_array();
    for (size_t i = 0; i < fresh->c.count; i++) {
        json_t *h = fresh->c.items[i];
        json_t *jid = (h && h->type == JSON_OBJECT)
                          ? json_obj_get(h, "advisory_id") : NULL;
        const char *hid = (jid && jid->type == JSON_STRING) ? jid->str_val : NULL;
        if (!hid) continue;
        json_t *lastv = json_obj_get(cache, hid);
        double last = (lastv && lastv->type == JSON_NUMBER) ? lastv->num_val : 0.0;
        if (last < cutoff) {
            json_append(due, json_copy(h));
            json_set(cache, hid, json_number(now));
        }
    }
    if (due->c.count > 0)
        cli_security_advisories_write_banner_cache(cache);
    json_free(cache);
    json_free(fresh);
    return due;

if (!out || out_sz == 0) return false;
    json_t *fresh = cli_security_advisories_filter_unacked(hits);
    if (fresh->c.count == 0) {
        snprintf(out, out_sz, "No active security advisories.  ✓");
        json_free(fresh);
        return false;
    }
    size_t pos = 0;
    out[0] = '\0';
    for (size_t i = 0; i < fresh->c.count; i++) {
        if (i) buf_append(out, out_sz, &pos, "\n\n");
        char block[8192];
        cli_security_advisories_full_remediation_text(
            fresh->c.items[i], block, sizeof(block));
        buf_append(out, out_sz, &pos, "%s", block);
    }
    json_free(fresh);
    return true;

if (!out || out_sz == 0) return false;
    out[0] = '\0';
    json_t *due = cli_security_advisories_hits_due_for_banner(
        hits, BANNER_REPEAT_HOURS);
    if (due->c.count == 0) {
        json_free(due);
        return false;
    }
    char lines[8192];
    cli_security_advisories_short_banner_lines(due, lines, sizeof(lines));
    if (cli_security_advisories_term_supports_color())
        snprintf(out, out_sz, "\x1b[1;31m%s\x1b[0m", lines);
    else
        snprintf(out, out_sz, "%s", lines);
    json_free(due);
    return true;

if (!out || out_sz == 0) return false;
    out[0] = '\0';
    json_t *fresh = cli_security_advisories_filter_unacked(hits);
    if (fresh->c.count == 0) {
        json_free(fresh);
        return false;
    }
    if (fresh->c.count == 1) {
        json_t *h = fresh->c.items[0];
        json_t *jid = json_obj_get(h, "advisory_id");
        json_t *jpkg = json_obj_get(h, "package");
        json_t *jver = json_obj_get(h, "installed_version");
        json_t *jtitle = json_obj_get(h, "title");
        json_t *jurl = json_obj_get(h, "url");
        snprintf(out, out_sz,
                 "Security advisory [%s] active: %s==%s matches %s. See %s",
                 (jid && jid->str_val) ? jid->str_val : "",
                 (jpkg && jpkg->str_val) ? jpkg->str_val : "",
                 (jver && jver->str_val) ? jver->str_val : "",
                 (jtitle && jtitle->str_val) ? jtitle->str_val : "",
                 (jurl && jurl->str_val) ? jurl->str_val : "");
    } else {
        size_t pos = 0;
        buf_append(out, out_sz, &pos, "%zu security advisories active (IDs: ",
                   fresh->c.count);
        for (size_t i = 0; i < fresh->c.count; i++) {
            json_t *h = fresh->c.items[i];
            json_t *jid = (h && h->type == JSON_OBJECT)
                              ? json_obj_get(h, "advisory_id") : NULL;
            buf_append(out, out_sz, &pos, "%s%s", i ? ", " : "",
                       (jid && jid->str_val) ? jid->str_val : "?");
        }
        buf_append(out, out_sz, &pos,
                   "). Run `hermes doctor` on the gateway host for details.");
    }
    json_free(fresh);
    return true;

if (!s) return false;
    for (size_t i = 0; i < smc_execution_surfaces_count; i++)
        if (strcmp(s, smc_execution_surfaces[i]) == 0) return true;
    return false;

if (!metric_name || !dim_keys || !dim_vals)
        return false;

    /* The Python contract defines dimension schemas per metric.
     * For the C port, we validate against the known schemas.
     * model_call: call_role, locality, model_family, outcome, provider_family
     * task_started: entrypoint, execution_surface
     * task_finished: 9 fields (duration_bucket, end_reason, entrypoint, ...)
     */
    size_t expected_count = 0;
    const char * const *expected_keys = NULL;

    if (strcmp(metric_name, SMC_MODEL_CALL_METRIC) == 0) {
        expected_count = 5;
        static const char *keys[] =
            {"call_role", "locality", "model_family", "outcome", "provider_family"};
        expected_keys = keys;
        /* Value validation: each dimension value must be in its allowlist */
        /* For the pure contract, we validate that values match known sets */
    } else if (strcmp(metric_name, SMC_TASK_STARTED_METRIC) == 0) {
        expected_count = 2;
        static const char *keys[] = {"entrypoint", "execution_surface"};
        expected_keys = keys;
    } else if (strcmp(metric_name, SMC_TASK_FINISHED_METRIC) == 0) {
        expected_count = 9;
        static const char *keys[] = {
            "duration_bucket", "end_reason", "entrypoint",
            "execution_surface", "model_call_count_bucket", "outcome",
            "retry_count_bucket", "termination", "tool_call_count_bucket",
        };
        expected_keys = keys;
    } else {
        return false;
    }

    if (dim_count != expected_count)
        return false;

    /* Check all expected keys present and in order (like Python's set(dimensions) != set(contract)) */
    for (size_t i = 0; i < expected_count; i++) {
        bool found = false;
        for (size_t j = 0; j < dim_count; j++) {
            if (strcmp(dim_keys[j], expected_keys[i]) == 0) {
                found = true;
                break;
            }
        }
        if (!found) return false;
    }

    /* Validate each dimension value against its allowlist */
    for (size_t i = 0; i < dim_count; i++) {
        const char *val = dim_vals[i];
        if (!val) return false;
        if (strcmp(dim_keys[i], "call_role") == 0) {
            if (strcmp(val, SMC_PRIMARY_MODEL_CALL_ROLE) != 0)
                return false;
        } else if (strcmp(dim_keys[i], "locality") == 0) {
            if (!str_in_set(val, smc_model_localities, smc_model_localities_count))
                return false;
        } else if (strcmp(dim_keys[i], "model_family") == 0) {
            if (!str_in_set(val, smc_model_families, smc_model_families_count))
                return false;
        } else if (strcmp(dim_keys[i], "outcome") == 0) {
            if (!str_in_set(val, smc_model_outcomes, smc_model_outcomes_count)
                && !str_in_set(val, smc_task_outcomes, smc_task_outcomes_count))
                return false;
        } else if (strcmp(dim_keys[i], "provider_family") == 0) {
            if (!str_in_set(val, smc_provider_families, smc_provider_families_count))
                return false;
        } else if (strcmp(dim_keys[i], "entrypoint") == 0) {
            if (!str_in_set(val, smc_task_entrypoints, smc_task_entrypoints_count))
                return false;
        } else if (strcmp(dim_keys[i], "execution_surface") == 0) {
            if (!str_in_set(val, smc_execution_surfaces, smc_execution_surfaces_count))
                return false;
        } else if (strcmp(dim_keys[i], "duration_bucket") == 0) {
            if (!str_in_set(val, smc_duration_buckets, smc_duration_buckets_count))
                return false;
        } else if (strcmp(dim_keys[i], "end_reason") == 0) {
            if (!str_in_set(val, smc_task_end_reasons, smc_task_end_reasons_count))
                return false;
        } else if (strcmp(dim_keys[i], "termination") == 0) {
            if (!str_in_set(val, smc_task_terminations, smc_task_terminations_count))
                return false;
        } else if (strcmp(dim_keys[i], "model_call_count_bucket") == 0
                   || strcmp(dim_keys[i], "retry_count_bucket") == 0
                   || strcmp(dim_keys[i], "tool_call_count_bucket") == 0) {
            if (!str_in_set(val, smc_count_buckets, smc_count_buckets_count))
                return false;
        }
    }

    return true;

if (!platform_value) return "unknown";

    char *normalized = str_lower_strip(platform_value);
    if (!normalized) return "unknown";

    const char *result = NULL;

    /* Empty string maps to "unknown" */
    if (!*normalized) {
        free(normalized);
        return "unknown";
    }

    if (str_in_set(normalized, smc_execution_surfaces, smc_execution_surfaces_count)) {
        /* Find the canonical form (it may have been lowercased) */
        for (size_t i = 0; i < smc_execution_surfaces_count; i++) {
            if (strcmp(normalized, smc_execution_surfaces[i]) == 0) {
                result = smc_execution_surfaces[i];
                break;
            }
        }
    } else if (strcmp(normalized, "api_server") == 0) {
        result = "api";
    } else if (strcmp(normalized, "cron") == 0
               || strcmp(normalized, "scheduler") == 0
               || strcmp(normalized, "scheduled") == 0) {
        result = "scheduled_task";
    } else if (strcmp(normalized, "discord") == 0
               || strcmp(normalized, "email") == 0
               || strcmp(normalized, "slack") == 0
               || strcmp(normalized, "telegram") == 0
               || strcmp(normalized, "teams") == 0
               || strcmp(normalized, "whatsapp") == 0) {
        result = "gateway";
    } else {
        result = (strcmp(normalized, "unknown") == 0) ? "unknown" : "other";
    }

    free(normalized);
    return result;

const char *surface = smc_execution_surface(platform_val);
    const char *ep = smc_task_entrypoint(entrypoint_val, surface, false, false);

    /* Build JSON string */
    int needed = snprintf(NULL, 0,
        "{\"entrypoint\":\"%s\",\"execution_surface\":\"%s\"}", ep, surface);
    char *result = malloc((size_t)needed + 1);
    if (result) {
        snprintf(result, (size_t)needed + 1,
            "{\"entrypoint\":\"%s\",\"execution_surface\":\"%s\"}", ep, surface);
    }
    return result;

if (!entrypoint_val) entrypoint_val = "";
    if (!surface) surface = "";

    char *normalized = str_lower_strip(entrypoint_val);
    if (!normalized) return "other";

    const char *result = NULL;

    if (str_in_set(normalized, smc_task_entrypoints, smc_task_entrypoints_count)) {
        for (size_t i = 0; i < smc_task_entrypoints_count; i++) {
            if (strcmp(normalized, smc_task_entrypoints[i]) == 0) {
                result = smc_task_entrypoints[i];
                goto cleanup;
            }
        }
    }

    /* Resolved surface logic */
    if (has_parent_task || has_parent_session) {
        result = "delegated";
        goto cleanup;
    }

    if (strcmp(surface, "api") == 0)
        result = "api";
    else if (strcmp(surface, "batch") == 0)
        result = "batch";
    else if (strcmp(surface, "cli") == 0)
        result = "interactive";
    else if (strcmp(surface, "desktop") == 0)
        result = "interactive";
    else if (strcmp(surface, "gateway") == 0)
        result = "gateway_message";
    else if (strcmp(surface, "python") == 0)
        result = "python";
    else if (strcmp(surface, "scheduled_task") == 0)
        result = "scheduled_task";
    else if (strcmp(surface, "tui") == 0)
        result = "interactive";
    else if (strcmp(surface, "unknown") == 0)
        result = "unknown";
    else
        result = "other";

cleanup:
    free(normalized);
    return result;

const char *surface = smc_execution_surface(platform_val);
    const char *ep = smc_task_entrypoint(entrypoint_val, surface, false, false);
    const char *dur_bucket = smc_duration_bucket(duration_ms);
    const char *mc_bucket = smc_count_bucket(model_call_count);
    const char *tc_bucket = smc_count_bucket(tool_call_count);
    const char *rc_bucket = smc_count_bucket(retry_count);

    /* Default outcome/end_reason/termination — caller should override */
    const char *outcome = "unknown";
    const char *end_reason = "unknown";
    const char *termination = "unknown";

    int needed = snprintf(NULL, 0,
        "{"
        "\"entrypoint\":\"%s\","
        "\"execution_surface\":\"%s\","
        "\"duration_bucket\":\"%s\","
        "\"end_reason\":\"%s\","
        "\"model_call_count_bucket\":\"%s\","
        "\"outcome\":\"%s\","
        "\"retry_count_bucket\":\"%s\","
        "\"termination\":\"%s\","
        "\"tool_call_count_bucket\":\"%s\""
        "}",
        ep, surface, dur_bucket, end_reason,
        mc_bucket, outcome, rc_bucket, termination, tc_bucket);

    char *result = malloc((size_t)needed + 1);
    if (result) {
        snprintf(result, (size_t)needed + 1,
            "{"
            "\"entrypoint\":\"%s\","
            "\"execution_surface\":\"%s\","
            "\"duration_bucket\":\"%s\","
            "\"end_reason\":\"%s\","
            "\"model_call_count_bucket\":\"%s\","
            "\"outcome\":\"%s\","
            "\"retry_count_bucket\":\"%s\","
            "\"termination\":\"%s\","
            "\"tool_call_count_bucket\":\"%s\""
            "}",
            ep, surface, dur_bucket, end_reason,
            mc_bucket, outcome, rc_bucket, termination, tc_bucket);
    }
    return result;

const char *outcome = "unknown";
    const char *end_reason = "unknown";
    const char *termination = "unknown";

    if (!turn_exit_reason) turn_exit_reason = "";

    char *reason = str_lower_strip(turn_exit_reason);
    if (!reason) {
        /* fallback to defaults */
        goto build_result;
    }

    if (interrupted || strstr(reason, "interrupt") || strstr(reason, "cancel")) {
        outcome = "cancelled";
        end_reason = "user_cancelled";
        termination = "user_cancelled";
    } else if (strstr(reason, "timeout") || strstr(reason, "timed_out")) {
        outcome = "timed_out";
        end_reason = "timed_out";
        termination = "timed_out";
    } else if (strstr(reason, "max_iterations") || strstr(reason, "budget_exhausted")) {
        outcome = "failed";
        end_reason = "iteration_limit";
        termination = "system_aborted";
    } else if (strstr(reason, "approval") && (strstr(reason, "denied") || strstr(reason, "rejected"))) {
        outcome = "failed";
        end_reason = "approval_denied";
        termination = "none";
    } else if (strstr(reason, "guardrail")) {
        outcome = "failed";
        end_reason = "guardrail_blocked";
        termination = "system_aborted";
    } else if (strcmp(reason, "system_aborted") == 0) {
        outcome = "failed";
        end_reason = "system_aborted";
        termination = "system_aborted";
    } else if (completed) {
        outcome = "success";
        end_reason = "completed";
        termination = "none";
    } else if (failed || (reason[0] && strcmp(reason, "unknown") != 0)) {
        outcome = "failed";
        end_reason = "failed";
        termination = "none";
    }

    free(reason);

build_result:
    {
        int needed = snprintf(NULL, 0,
            "[\"%s\",\"%s\",\"%s\"]", outcome, end_reason, termination);
        char *result = malloc((size_t)needed + 1);
        if (result) {
            snprintf(result, (size_t)needed + 1,
                "[\"%s\",\"%s\",\"%s\"]", outcome, end_reason, termination);
        }
        return result;
    }

int value = duration_ms > 0 ? duration_ms : 0;
    if (value < 1000)
        return "lt_1s";
    if (value < 5000)
        return "1s_to_5s";
    if (value < 30000)
        return "5s_to_30s";
    if (value < 120000)
        return "30s_to_2m";
    if (value < 600000)
        return "2m_to_10m";
    return "gte_10m";

int value = count > 0 ? count : 0;
    if (value <= 2) {
        /* Return "0", "1", or "2" */
        static const char *buckets[] = {"0", "1", "2"};
        return buckets[value > 2 ? 2 : value];
    }
    if (value <= 5)
        return "3_to_5";
    if (value <= 10)
        return "6_to_10";
    return "gte_11";

if (declared_family) {
        char *norm = str_lower_strip(declared_family);
        if (norm) {
            /* Check if it's a known family (excluding "unknown") */
            for (size_t i = 0; i < smc_model_families_count; i++) {
                if (strcmp(norm, smc_model_families[i]) == 0
                    && strcmp(norm, "unknown") != 0) {
                    free(norm);
                    return smc_model_families[i];
                }
            }
            free(norm);
        }
    }

    /* Try to extract family from model name using regex-like pattern */
    const char *model_str = NULL;
    if (response_model && *response_model)
        model_str = response_model;
    else if (model_name && *model_name)
        model_str = model_name;
    else
        model_str = "";
    if (!*model_str)
        return "unknown";

    /* Build patterns from known families (sorted longest-first) */
    /* In Python: (?:^|[/_.:-])(family1|family2|...)(?=$|[/_.:-]|\d) */
    /* We'll use a simpler approach: iterate families and check for substring
     * preceded by boundary chars at start or after / _ . : - */

    /* Known families sorted by length descending (longer match first) */
    static const char *families_by_len[] = {
        "deepseek", "minimax", "nemotron", "mistral", "claude",
        "gemini", "gemma", "gpt", "grok", "kimi", "llama",
        "mimo", "nova", "qwen", "step", "glm", "o1", "o3", "o4",
    };

    size_t model_len = strlen(model_str);
    for (size_t f = 0; f < sizeof(families_by_len)/sizeof(families_by_len[0]); f++) {
        const char *family = families_by_len[f];
        size_t family_len = strlen(family);
        if (family_len > model_len) continue;

        for (size_t i = 0; i <= model_len - family_len; i++) {
            if (strncmp(model_str + i, family, family_len) == 0) {
                /* Check boundary before: must be start-of-string or one of [/_.:-] */
                if (i > 0) {
                    char c = model_str[i - 1];
                    if (c != '/' && c != '_' && c != '.' && c != ':' && c != '-')
                        continue;
                }
                /* i == 0 means start-of-string — always matches (like Python ^) */
                /* Check boundary after */
                size_t after = i + family_len;
                if (after < model_len) {
                    char c = model_str[after];
                    if (c != '/' && c != '_' && c != '.' && c != ':' && c != '-'
                        && !(c >= '0' && c <= '9'))
                        continue;
                }
                return family;
            }
        }
    }

    return "unknown";

if (!outcome) return "failed";
    char *norm = str_lower_strip(outcome);
    if (!norm) return "failed";
    const char *result = str_in_set(norm, smc_model_outcomes, smc_model_outcomes_count)
                             ? norm /* points to our static set */
                             : "failed";
    /* If result is pointing to our heap-allocated norm, we can't return that.
     * Check if the value is in the set and return the canonical string. */
    if (strcmp(result, "failed") == 0) {
        free(norm);
        return "failed";
    }
    for (size_t i = 0; i < smc_model_outcomes_count; i++) {
        if (strcmp(norm, smc_model_outcomes[i]) == 0) {
            free(norm);
            return smc_model_outcomes[i];
        }
    }
    free(norm);
    return "failed";

if (!provider) return false;
    char *norm = str_lower_strip(provider);
    if (!norm) return false;
    /* Replace _ with - */
    char *dashed = str_replace_char(norm, '_', '-');
    free(norm);
    if (!dashed) return false;
    bool result = str_in_set(dashed, smc_aggregator_overrides,
                              smc_aggregator_overrides_count);
    free(dashed);
    return result;

if (!provider) return false;
    return str_in_set(provider, smc_local_custom_aliases,
                      smc_local_custom_aliases_count);

if (!provider || !*provider) return "unknown";

    char *norm = str_lower_strip(provider);
    if (!norm) return "unknown";
    char *dashed = str_replace_char(norm, '_', '-');
    free(norm);
    if (!dashed) return "unknown";

    const char *result = NULL;

    if (!*dashed) {
        free(dashed);
        return "unknown";
    }

    if (str_in_set(dashed, smc_local_custom_aliases,
                   smc_local_custom_aliases_count)) {
        result = "local";
        goto done;
    }

    if (strcmp(dashed, "custom") == 0
        || strncmp(dashed, "custom-", 7) == 0
        || strncmp(dashed, "custom:", 7) == 0) {
        result = "custom";
        goto done;
    }

    /* Check for known local providers */
    if (strcmp(dashed, "lmstudio") == 0 || strcmp(dashed, "local") == 0) {
        result = "local";
        goto done;
    }

    /* Check aggregator overrides */
    if (str_in_set(dashed, smc_aggregator_overrides,
                   smc_aggregator_overrides_count)) {
        result = "aggregator";
        goto done;
    }

    /* Check if it's a direct provider (known via catalog) */
    /* For the C port without provider catalog, we classify direct providers
     * as those that aren't local/custom/aggregator/unknown */
    result = "direct";

done:
    free(dashed);
    return result;

if (base_url && *base_url) {
        /* Check for local endpoints: localhost, 127.0.0.1, 0.0.0.0, ::1 */
        if (strstr(base_url, "localhost") != NULL
            || strstr(base_url, "127.0.0.1") != NULL
            || strstr(base_url, "0.0.0.0") != NULL
