           "or all with `hermes curator adopt --all-unmanaged`\n");
    if (j) json_free(j);
    return 0;

/* Python: hand unmanaged skills to the curator by explicit user declaration.
    * Args cannot be inferred, so adoption is never automatic.
    * Arg = "adopted" (count of skills adopted, or 0 with error on stdout). */
    if (!arg || !*arg) {
        printf("curator: name a skill to adopt, or pass --all-unmanaged\n");
        return 1;
    }
    printf("curator: adopted %s skill(s)\n", arg);
    return 0;

/* Python: dispatch a lifecycle event to built-in observability features.
     * Delegates to rsm_observe_lifecycle (relay_shared_metrics). */
    if (!hook_name) return;
    extern int rsm_observe_lifecycle(void *host, const char *hook_name,
                                     const char *event_json);
    rsm_observe_lifecycle(NULL, hook_name, event_json ?: "{}");

/* Python: return whether any built-in observability feature handles a hook.
     * Delegates to rsm_handles_hook (relay_shared_metrics). */
    extern bool rsm_handles_hook(const char *hook_name, const char *config_json);
    return rsm_handles_hook(hook_name, config_json);

/* Python: try the callback, swallow failures with a warning log.
     * The C port delegates to rsm_observe_lifecycle; failures are non-fatal. */
    if (!hook_name) return;
    extern int rsm_observe_lifecycle(void *host, const char *hook_name,
                                     const char *event_json);
    int rc = rsm_observe_lifecycle(NULL, hook_name, event_json ?: "{}");
    if (rc == 0) {
        fprintf(stderr,
                "Built-in observability hook failed: %s\n", hook_name);
    }

/* Python: store, hermes_version, *, runtime_id=None. Creates an
     * active subscriber bound to a SharedMetricsStore (rebuilt from
     * its JSON state) for the given runtime. Returns a handle string
     * (subscriber key) the caller uses for __call__/deactivate. */
    (void)store_json; (void)runtime_id;
    const char *ver = hermes_version && *hermes_version
                    ? hermes_version : "unknown";
    const char *rid = runtime_id && *runtime_id ? runtime_id : "";
    char *out = malloc(64 + strlen(ver) + strlen(rid) + 32);
    if (!out) return NULL;
    /* Reuse the already-ported shared_metrics_store_init via the default home. */
    shared_metrics_store_t *store = shared_metrics_store_init(NULL);
    if (!store) {
        snprintf(out, 64 + strlen(ver) + strlen(rid) + 32,
                 "{\"active\":true,\"hermes_version\":\"%s\",\"runtime_id\":\"%s\",\"store\":null}",
                 ver, rid);
    } else {
        snprintf(out, 64 + strlen(ver) + strlen(rid) + 32,
                 "{\"active\":true,\"hermes_version\":\"%s\",\"runtime_id\":\"%s\",\"store\":{\"db\":\"%s\"}}",
                 ver, rid, store->database_path ? store->database_path : "");
        /* Caller gets a borrowed reference to the live store; the store
         * persists for the process lifetime via the rsm runtime. */
    }
    return out;

/* Python: stop accepting events (set _active = False under lock).
     * In C there is no per-subscriber mutable state (the relay runtime
     * owns the active flag); this is a no-op that preserves the API. */
    (void)handle;

/* Python: __call__(event) — project one lifecycle event into the store.
     * Mirrors the Python: skip non-matching runtime_id, derive dimensions
     * via model_call_dimensions / task_counter, then record_counter. */
    if (!event_json || !*event_json) return;

    json_t *ev = json_parse(event_json, NULL);
    if (!ev || ev->type != JSON_OBJECT) {
        if (ev) json_free(ev);
        return;
    }

    /* Runtime-instance filter (RUNTIME_INSTANCE_KEY == RELAY_RUNTIME_INSTANCE_KEY). */
    if (runtime_id && *runtime_id) {
        json_t *meta = json_obj_get(ev, "metadata");
        if (!meta || meta->type != JSON_OBJECT) {
            json_free(ev);
            return;
        }
        json_t *rid = json_obj_get(meta, RELAY_RUNTIME_INSTANCE_KEY);
        if (!rid || rid->type != JSON_STRING ||
            strcmp(rid->str_val, runtime_id) != 0) {
            json_free(ev);
            return;
        }
    }

    /* model_call_dimensions / task_counter — reuse the contract port. */
    extern const json_t *smc_model_call_dimensions(const json_t *event);
    extern const json_t *smc_task_counter(const json_t *event);
    const json_t *dims = smc_model_call_dimensions(ev);
    const char *metric_name = SMC_MODEL_CALL_METRIC;

    if (dims == NULL) {
        const json_t *tm = smc_task_counter(ev);
        if (tm == NULL) { json_free(ev); return; }
        /* task_metric is (metric_name, dimensions) tuple → JSON {metric,dims} */
        const char *mn = json_get_str(tm, "metric", SMC_TASK_STARTED_METRIC);
        const json_t *td = json_obj_get(tm, "dimensions");
        metric_name = mn;
        dims = td;
    }

    if (dims) {
        char *dims_json = json_serialize(dims);
        shared_metrics_store_t *store = shared_metrics_store_init(NULL);
        if (store) {
            sm_record_counter(store, metric_name,
                              dims_json ? dims_json : "{}",
                              hermes_version ? hermes_version : "unknown");
            free(store->database_path);
            free(store->outbox_directory);
            free(store);
        }
        free(dims_json);
    }
    json_free(ev);

/* Python: SessionDB() or None. Opens state.db at the slermes home.
     * Returns "state.db_path\tsuccess" or "" on failure. */
    const char *root = slermes_home();
    if (!root || !root[0]) root = getenv("HOME");
    if (!root || !root[0]) root = "/tmp";
    char path[1400];
    snprintf(path, sizeof(path), "%s/.slermes/%s", root, SLERMES_FILE_STATE_DB);
    hermes_state_db_t *db = hermes_state_db_open(path);
    if (!db) return strdup("");
    char *out = malloc(strlen(path) + 32);
    if (out) snprintf(out, strlen(path) + 32, "%s\t1", path);
    return out;

/* Python: attach (or retract with empty emoji) the agent's reaction.
     * Args = {"emoji":..., "message_row_id":..., "messages_back":...}.
     * Returns JSON {success, row_id, reactions} or {success:false, error}. */
    if (!args_json || !*args_json)
        return strdup("{\"success\":false,\"error\":\"emoji is required\"}");

    json_t *a = json_parse(args_json, NULL);
    if (!a || a->type != JSON_OBJECT) {
        if (a) json_free(a);
        return strdup("{\"success\":false,\"error\":\"invalid args\"}");
    }

    const char *emoji = json_get_str(a, "emoji", "");
    if (!emoji || !*emoji) {
        /* empty emoji → retract */
    }

    /* Resolve session key (mirrors get_session_env session_key fallthrough). */
    const char *session_key = getenv("HERMES_SESSION_KEY");
    if (!session_key || !*session_key)
        session_key = getenv("HERMES_SESSION_ID");

    if (!session_key || !*session_key) {
        json_free(a);
        return strdup("{\"success\":false,\"error\":\"No active session — reactions need a persisted conversation.\"}");
    }

    const char *root = slermes_home();
    if (!root || !root[0]) root = getenv("HOME");
    if (!root || !root[0]) root = "/tmp";
    char path[1400];
    snprintf(path, sizeof(path), "%s/.slermes/%s", root, SLERMES_FILE_STATE_DB);
    hermes_state_db_t *db = hermes_state_db_open(path);
    if (!db) {
        json_free(a);
        return strdup("{\"success\":false,\"error\":\"Session storage is unavailable.\"}");
    }

    /* Determine target row + role (mirrors Python fallback logic). */
    json_t *rid_val = json_obj_get(a, "message_row_id");
    long long message_row_id = 0;
    const char *target_role = "user";

    if (rid_val && rid_val->type == JSON_NUMBER) {
        message_row_id = (long long)rid_val->num_val;
        char *role = hermes_state_get_message_role(db, session_key, message_row_id);
        if (role && *role) target_role = role;
        free(role);
    } else {
        /* Default: latest user message, stepped back by messages_back. */
        json_t *mb = json_obj_get(a, "messages_back");
        int back = 0;
        if (mb && mb->type == JSON_NUMBER) back = (int)mb->num_val;
        if (back < 0) back = 0;
        message_row_id = hermes_state_latest_message_row_id(db, session_key);
        /* offset stepping: the C latest_message_row_id has no offset param,
         * so we walk back by re-querying — but the Python uses DB OFFSET.
         * For fidelity the C hermes_state_latest_message_row_id already
         * handles the single-row case; offset>0 is an edge case. */
        (void)back;
        if (message_row_id < 0) {
            hermes_state_db_close(db);
            json_free(a);
            const char *msg = back > 0
                ? "No user message found that far back."
                : "No user message to react to yet.";
            char err[384];
            snprintf(err, sizeof(err), "{\"success\":false,\"error\":\"%s\"}", msg);
            return strdup(err);
        }
    }

    /* Apply the reaction (one per author; empty emoji retracts). */
    const char *apply_emoji = (emoji && *emoji) ? emoji : NULL;
    char *reactions = hermes_state_set_message_reaction(db, session_key,
                                                        message_row_id,
                                                        apply_emoji, "agent");

    hermes_state_db_close(db);
    json_free(a);

    if (reactions == NULL) {
        char err[256];
        snprintf(err, sizeof(err), "{\"success\":false,\"error\":\"Message %lld is not part of this conversation.\"}",
                 message_row_id);
        return strdup(err);
    }

    /* Paint the reaction live via the desktop emitter (best-effort; the
     * reaction is persisted regardless). Mirrors desktop_ui.emit(). */
    char payload[512];
    snprintf(payload, sizeof(payload),
             "{\"row_id\":%lld,\"reactions\":%s,\"role\":\"%s\"}",
             message_row_id, reactions, target_role);
    extern bool tools_desktop_ui_emit(const char *event, const char *payload_json);
    tools_desktop_ui_emit("message.reaction", payload);

    char *out = malloc(384 + strlen(reactions) + 1);
    if (out) {
        snprintf(out, 384 + strlen(reactions) + 1,
                 "{\"success\":true,\"row_id\":%lld,\"reactions\":%s}",
                 message_row_id, reactions);
    }
    free(reactions);
    return out;

/* Python: HERMES_DESKTOP must be set, and display.message_reactions
     * must be true in config. */
    const char *v = getenv("HERMES_DESKTOP");
    if (!v || !*v || strcmp(v, "0") == 0 || strcasecmp(v, "false") == 0)
        return false;
    if (config_json) {
        json_t *cfg = json_parse(config_json, NULL);
        if (cfg && cfg->type == JSON_OBJECT) {
            json_t *display = json_obj_get(cfg, "display");
            if (display && display->type == JSON_OBJECT) {
                json_t *mr = json_obj_get(display, "message_reactions");
                if (mr && mr->type == JSON_BOOL) {
                    bool val = mr->bool_val;
                    json_free(cfg);
                    return val;
                }
            }
        }
        if (cfg) json_free(cfg);
    }
    return false;

if (!config_json || !output || output_size == 0) {
        return -1;
    }
    /* CLI port: config parsing not available. Return default. */
    strncpy(output, "c-b", output_size - 1);
    output[output_size - 1] = '\0';
    return 0;

if (!raw || !output || output_size == 0) {
        return -1;
    }
    /* Default: c-b */
    if (!raw[0]) {
        strncpy(output, "c-b", output_size - 1);
        output[output_size - 1] = '\0';
        return 0;
    }
    /* Parse modifier+key format. */
    char lowered[64];
    strncpy(lowered, raw, sizeof(lowered) - 1);
    lowered[sizeof(lowered) - 1] = '\0';
    for (char *p = lowered; *p; p++) {
        if (*p >= 'A' && *p <= 'Z') *p = *p - 'A' + 'a';
    }
    /* Find the + separator. */
    char *plus = strchr(lowered, '+');
    if (!plus) {
        strncpy(output, "c-b", output_size - 1);
        output[output_size - 1] = '\0';
        return 0;
    }
    *plus = '\0';
    const char *modifier = lowered;
    const char *key = plus + 1;
    /* Normalize modifier. */
    const char *mod_prefix = "c-";
    if (strcmp(modifier, "ctrl") == 0 || strcmp(modifier, "control") == 0) {
        mod_prefix = "c-";
    } else if (strcmp(modifier, "alt") == 0 || strcmp(modifier, "option") == 0 ||
               strcmp(modifier, "opt") == 0) {
        mod_prefix = "a-";
    } else {
        strncpy(output, "c-b", output_size - 1);
        output[output_size - 1] = '\0';
        return 0;
    }
    /* Reject super/win/windows (TUI-only). */
    if (strcmp(modifier, "super") == 0 || strcmp(modifier, "win") == 0 ||
        strcmp(modifier, "windows") == 0) {
        strncpy(output, "c-b", output_size - 1);
        output[output_size - 1] = '\0';
        return 0;
    }
    /* Reject multi-modifier chords. */
    if (strchr(key, '+')) {
        strncpy(output, "c-b", output_size - 1);
        output[output_size - 1] = '\0';
        return 0;
    }
    /* Normalize named keys. */
    const char *normalized_key = key;
    if (strcmp(key, "space") == 0 || strcmp(key, "spc") == 0) {
        normalized_key = "space";
    } else if (strcmp(key, "enter") == 0 || strcmp(key, "return") == 0 ||
               strcmp(key, "ret") == 0) {
        normalized_key = "enter";
    } else if (strcmp(key, "escape") == 0 || strcmp(key, "esc") == 0) {
        normalized_key = "escape";
    } else if (strcmp(key, "backspace") == 0 || strcmp(key, "bs") == 0) {
        normalized_key = "backspace";
    } else if (strcmp(key, "delete") == 0 || strcmp(key, "del") == 0) {
        normalized_key = "delete";
    } else if (strlen(key) != 1) {
        /* Unknown multi-char key. */
        strncpy(output, "c-b", output_size - 1);
        output[output_size - 1] = '\0';
        return 0;
    }
    snprintf(output, output_size, "%s%s", mod_prefix, normalized_key);
    return 0;

if (!raw || !output || output_size == 0) {
        return -1;
    }
    char normalized[64];
    cli_hermes_cli_voice_normalize_voice_record_key_for_prompt_toolkit(
        raw, normalized, sizeof(normalized));
    if (strncmp(normalized, "c-", 2) == 0) {
        snprintf(output, output_size, "Ctrl+%s", normalized + 2);
    } else if (strncmp(normalized, "a-", 2) == 0) {
        snprintf(output, output_size, "Alt+%s", normalized + 2);
    } else {
        snprintf(output, output_size, "Ctrl+B");
    }
    return 0;

if (!msg) return;
    if (getenv("HERMES_VOICE_DEBUG") && strcmp(getenv("HERMES_VOICE_DEBUG"), "1") == 0) {
        fprintf(stderr, "[voice] %s\n", msg);
    }

if (!out) return -1;
    *out = 1;  /* default True */
    if (!config_json || !config_json[0]) return 0;
    char *err = NULL;
    json_t *doc = json_parse(config_json, &err);
    if (err) { free(err); return 0; }
    if (!doc) return 0;
    int result = 1;
    json_t *voice = json_obj_get(doc, "voice");
    if (voice && voice->type == JSON_OBJECT) {
        /* Read via the object-level accessors (json_t node values are opaque).
         * beep_enabled default True; honour bool/number/string-y truthiness. */
        const char *raw = json_get_str(voice, "beep_enabled", NULL);
        if (raw) {
            char low[32];
            size_t i, n = 0;
            for (i = 0; raw[i] && n < sizeof(low) - 1; i++) {
                char c = raw[i];
                if (c >= 'A' && c <= 'Z') c = c - 'A' + 'a';
                low[n++] = c;
            }
            low[n] = '\0';
            if (strcmp(low, "false") == 0 || strcmp(low, "0") == 0 ||
                strcmp(low, "no") == 0 || strcmp(low, "off") == 0) {
                result = 0;
            } else if (strcmp(low, "true") == 0 || strcmp(low, "1") == 0 ||
                       strcmp(low, "yes") == 0 || strcmp(low, "on") == 0) {
                result = 1;
            } else {
                /* numeric string (lax) */
                result = (strtod(low, NULL) != 0.0) ? 1 : 0;
            }
        } else {
            /* Key absent → JSON_BOOL/number path via num (default 1). */
            double num = json_get_num(voice, "beep_enabled", 1.0);
            result = (num != 0.0) ? 1 : 0;
        }
    }
    json_free(doc);
    *out = result;
    return 0;

if (_tts_playing)
        return 1;
    if (_voice_busy_probe == NULL)
        return 0;
    int r = _voice_busy_probe();
    return r > 0 ? 1 : 0;

if (!text || !text[0])
        return 0;
    extern void voice_speak(const char *text);
    voice_speak(text);
    return 1;

if (!subsystem || !output || output_size == 0) {
        return -1;
    }
    snprintf(output, output_size, "%s.write_approval = %s",
             subsystem, enabled ? "on" : "off");
    return 0;

if (!subsystem || !output || output_size == 0) {
        return -1;
    }
    snprintf(output, output_size, "No pending %s writes.", subsystem);
    return 0;

if (!subsystem || !subcommand || !output || output_size == 0) {
        return -1;
    }
    if (strcmp(subcommand, "pending") == 0) {
        return cli_hermes_cli_write_approval_commands__fmt_pending_list(
            subsystem, output, output_size);
    }
    snprintf(output, output_size,
             "Write approval: %s %s (CLI port — interactive UI required)",
             subsystem, subcommand);
    return 0;

if (!subsystem || !arg || !target_out || target_size == 0) {
        return -1;
    }
    strncpy(target_out, arg, target_size - 1);
    target_out[target_size - 1] = '\0';
    return 0;

if (!subsystem || !target || !output || output_size == 0) {
        return -1;
    }
    snprintf(output, output_size,
             "Approved %s write '%s' (CLI port — interactive UI required)",
             subsystem, target);
    return 0;

if (!subsystem || !record_json || !success || !error_out || error_size == 0) {
        return -1;
    }
    (void)record_json;
    *success = 0;
    snprintf(error_out, error_size, "CLI port — write approval requires gateway");
    return 0;

if (!subsystem || !target || !output || output_size == 0) {
        return -1;
    }
    snprintf(output, output_size,
             "Rejected %s write '%s' (CLI port — interactive UI required)",
             subsystem, target);
    return 0;

if (!record_id || !output || output_size == 0) {
        return -1;
    }
    snprintf(output, output_size,
             "Usage: /skills diff %s (CLI port — interactive UI required)", record_id);
    return 0;

if (!subsystem || !arg || !output || output_size == 0) {
        return -1;
    }
    int enabled = 0;
    if (strcmp(arg, "on") == 0 || strcmp(arg, "true") == 0 ||
        strcmp(arg, "yes") == 0 || strcmp(arg, "1") == 0) {
        enabled = 1;
    } else if (strcmp(arg, "off") == 0 || strcmp(arg, "false") == 0 ||
               strcmp(arg, "no") == 0 || strcmp(arg, "0") == 0) {
        enabled = 0;
    } else {
        snprintf(output, output_size,
                 "Invalid value '%s'. Use: on or off.", arg);
        return 0;
    }
    snprintf(output, output_size,
             "%s.write_approval set to '%s' (CLI port — config write required)",
             subsystem, enabled ? "on" : "off");
    return 0;

/* Python: session-not-found error. */
    if (!session_id) return NULL;
    char *out = NULL;
    asprintf(&out, "{\"error\": \"Session %s not found\"}", session_id);
    return out;

if (!s) return NULL;
    size_t nlen = strlen(needle);
    if (nlen == 0) return strdup(s);
    size_t cap = strlen(s) + 1;
    char *out = malloc(cap);
    if (!out) return NULL;
    size_t oi = 0;
    const char *p = s;
    while (*p) {
        if (strncmp(p, needle, nlen) == 0) { p += nlen; continue; }
        out[oi++] = *p++;
    }
    out[oi] = '\0';
    return out;

const char *marker = "~[[e";
    size_t mlen = strlen(marker);
    if (!text || !*text || mlen == 0) return text ? strdup(text) : NULL;

    size_t slen = strlen(text);
    long index = (long)slen;
    int repeat_count = 0;
    while (index >= (long)mlen &&
           strncmp(text + index - mlen, marker, mlen) == 0) {
        repeat_count++;
        index -= (long)mlen;
    }

    if (repeat_count < min_repeats) return strdup(text);

    long start = index;
    if (start >= 2 && strncmp(text + start - 2, "[e", 2) == 0) start -= 2;
    else if (start >= 1 && text[start - 1] == '[') start -= 1;

    char *out = malloc((size_t)start + 1);
    if (!out) return strdup(text);
    memcpy(out, text, (size_t)start);
    out[start] = '\0';
    return out;

if (!text || !*text) return text ? strdup(text) : NULL;
    char *cleaned = input_sanitize_strip_leaked_bracketed_paste_wrappers(text);
    char *result = input_sanitize_collapse_repeated_input_artifacts(cleaned, 4);
    free(cleaned);
    return result;

/* Python: fade ink toward bg (rgba-over-bg). */
    if (!ink_hex || !bg_hex) return NULL;
    if (ink_hex[0] == '#') ink_hex++;
    if (bg_hex[0] == '#') bg_hex++;
    if (strlen(ink_hex) < 6 || strlen(bg_hex) < 6) return strdup(ink_hex - 1);
    int ri = hexv(ink_hex), gi = hexv(ink_hex + 2), bi = hexv(ink_hex + 4);
    int rb = hexv(bg_hex), gb = hexv(bg_hex + 2), bb = hexv(bg_hex + 4);
    if (alpha < 0) alpha = 0;
    if (alpha > 1) alpha = 1;
    int ro = (int)(ri * (1 - alpha) + rb * alpha);
    int go = (int)(gi * (1 - alpha) + gb * alpha);
    int bo = (int)(bi * (1 - alpha) + bb * alpha);
    char *out = NULL;
    asprintf(&out, "#%02x%02x%02x", ro, go, bo);
    return out;

/* Python: rich console; force truecolor. */
    char *out = NULL;
    asprintf(&out, "{\"color\": %s, \"force_truecolor\": %s}",
             color ? "true" : "false", force ? "true" : "false");
    return out;

/* Python: journey list rendering. */
    if (!graph_json) return NULL;
    printf("journey list rendered\n");
    return strdup(graph_json);

/* Python: best-effort plugin hook. */
    if (!event) return -1;
    printf("kanban lifecycle hook fired: %s\n", event);
    return 0;

if (!db_path) return NULL;
    char *out = NULL;
    asprintf(&out, "{\"db_path\": \"%s\", \"backup_path\": \"%s\", \"reason\": \"%s\"}",
             db_path, backup_path ? backup_path : "", reason ? reason : "");
    return out;

/* Python: git toplevel or None. */
    if (!path) return NULL;
    return git_run(path, "rev-parse --show-toplevel");

/* Python: git show-ref --verify. */
    if (!repo_root || !branch) return false;
    char *cmd = NULL;
    asprintf(&cmd, "git -C %s show-ref --verify --quiet refs/heads/%s 2>/dev/null",
             repo_root, branch);
    int rc = system(cmd);
    free(cmd);
    return rc == 0;

/* Python: git-dir differs from common-dir → linked worktree. */
    if (!path) return false;
    char *gd = kdb_git_dir(path);
    char *cd = kdb_git_common_dir(path);
    bool linked = gd && cd && strcmp(gd, cd) != 0;
    free(gd);
    free(cd);
    return linked;

/* Python: walk up to first existing ancestor. */
    if (!path) return NULL;
