    i = 1;
    while (i < len && ((spec[i] >= 'A' && spec[i] <= 'Z') || (spec[i] >= 'a' && spec[i] <= 'z') ||
                       (spec[i] >= '0' && spec[i] <= '9') || spec[i] == '_' || spec[i] == '.' || spec[i] == '-'))
