                int same_alpha = fabs(prev->alpha - alpha) < 1e-6;
                int same_hex = (prev->hex == NULL && hx == NULL) ||
                               (prev->hex && hx && strcmp(prev->hex, hx) == 0);
                if (same_style && same_alpha && same_hex) {
                    char *nt = malloc(strlen(prev->text) + strlen(text ? text : "") + 1);
