    fclose(bt);
    if (btime < 0) { printf("\n"); return 0; }
    long clk = sysconf(_SC_CLK_TCK);
    if (clk <= 0) clk = 100;
    printf("%lld\n", btime + (long long)(startticks / (unsigned long long)clk));
    return 0;

