        for (int i = 0; i < 2; i++) {
            if (!keys[i] || !*keys[i]) continue;
            json_t *p = json_obj_get(prompts, keys[i]);
            if (p && p->type == JSON_STRING) {
                const char *s = p->str_val ? p->str_val : "";
                while (*s && isspace((unsigned char)*s)) s++;
                if (*s) { result = strdup(s); break; }
            }
        }
    }
    json_free(extra);
