if (!content) return strdup("");
    size_t L = strlen(content);
    char *out = malloc(L + 1);
    strcpy(out, content);
    /* fenced code blocks ```...``` */
    char *p = out;
    while ((p = strstr(p, "```"))) {
        char *end = strstr(p + 3, "```");
        if (!end) break;
        for (char *q = p; q <= end + 2; q++) *q = ' ';
        p = end + 3;
    }
    /* inline code `...` (skip if preceded by "MEDIA:") */
    p = out;
    while ((p = strchr(p, '`'))) {
        char *close = strchr(p + 1, '`');
        if (!close) break;
        int is_media = 0;
        char *pre = p - 20; if (pre < out) pre = out;
        if (strncmp(pre, "MEDIA:", 6) == 0) is_media = 1;
        if (!is_media) for (char *q = p; q <= close; q++) *q = ' ';
        p = close + 1;
    }
    /* blockquotes: lines starting with '>' */
    p = out;
    while (*p) {
        if (*p == '>') {
            char *nl = strchr(p, '\n');
            for (char *q = p; q != nl && *q; q++) *q = ' ';
            p = nl ? nl + 1 : p + strlen(p);
        } else {
            char *nl = strchr(p, '\n');
            p = nl ? nl + 1 : p + strlen(p);
        }
    }
    return out;

