if (err) err[0] = '\0';
    if (!member || !*member) {
        if (err) snprintf(err, errsz, "Unsafe archive member path: %s", member ? member : "(null)");
        return -1;
    }
    /* windows drive detection: a ':' with no preceding '/' and no '/' before it */
    int has_drive = 0;
    for (const char *q = member; *q; q++) {
        if (*q == ':') { has_drive = 1; break; }
        if (*q == '/') { has_drive = 0; break; }
    }
    /* backslash => treat as windows separator; presence of leading '\\' or ':' => absolute */
    const char *scan = member;
    int lead_bslash = (scan[0] == '\\');
    if (has_drive || lead_bslash) {
        if (err) snprintf(err, errsz, "Unsafe archive member path: %s", member);
        return -1;
    }
    /* posix absolute */
    if (member[0] == '/') {
        if (err) snprintf(err, errsz, "Unsafe archive member path: %s", member);
        return -1;
    }
    /* split on / and \\ */
    int cnt = 0;
    const char *seg = member;
    while (*seg && cnt < maxparts) {
        /* skip separators */
        while (*seg == '/' || *seg == '\\') seg++;
        if (!*seg) break;
        const char *end = seg;
        while (*end && *end != '/' && *end != '\\') end++;
        size_t len = (size_t)(end - seg);
        if (len == 1 && seg[0] == '.') { seg = end; continue; } /* '.' skip */
        if (len == 2 && seg[0] == '.' && seg[1] == '.') {
            if (err) snprintf(err, errsz, "Unsafe archive member path: %s", member);
            /* free already-allocated */
            for (int i = 0; i < cnt; i++) free(parts[i]);
            return -1;
        }
        parts[cnt] = malloc(len + 1);
        memcpy(parts[cnt], seg, len);
        parts[cnt][len] = '\0';
        cnt++;
        seg = end;
    }
    if (cnt == 0) {
        if (err) snprintf(err, errsz, "Unsafe archive member path: %s", member);
        return -1;
    }
    return cnt;

/* Python: best-effort slug from human name. */
    if (!name) return strdup("");
    size_t n = strlen(name);
    char *out = malloc(n + 1);
    if (!out) return strdup("");
    size_t o = 0;
    bool dash = false;
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)name[i];
        if (isalnum(c)) {
            out[o++] = (char)tolower(c);
            dash = false;
        } else if (!dash && o > 0) {
            out[o++] = '-';
            dash = true;
        }
    }
    while (o > 0 && out[o-1] == '-') o--;
    out[o] = '\0';
    return out;

/* Python: WAL with DELETE checkpoint — REAL sqlite. */
    if (!db_path) return -1;
    sqlite3 *db = NULL;
    int rc = sqlite3_open(db_path, &db);
    if (rc != SQLITE_OK) { if (db) sqlite3_close(db); return -1; }
    sqlite3_exec(db, "PRAGMA journal_mode=WAL;", NULL, NULL, NULL);
    sqlite3_exec(db, "PRAGMA wal_checkpoint(DELETE);", NULL, NULL, NULL);
    sqlite3_close(db);
    return 0;

