    pty_session_t *s = pty_session_new(NULL);
    if (!s) return -1;
    pthread_mutex_lock(&g_registry_lock);
    s->next = g_sessions;
    g_sessions = s;
    pthread_mutex_unlock(&g_registry_lock);
    if (pthread_create(&s->drain_tid, NULL, pty_drain_thread, s) != 0) {
        pthread_mutex_lock(&g_registry_lock);
        g_sessions = s->next;
        pthread_mutex_unlock(&g_registry_lock);
