    while (g_sessions) {
        pthread_mutex_lock(&g_registry_lock);
        pty_session_t *s = g_sessions;
        if (s) g_sessions = s->next;
        pthread_mutex_unlock(&g_registry_lock);
        if (!s) break;
        s->drain_stopped = true;
        if (s->drain_started)
