    json_t *counter = json_object();
    json_t *files_seen = json_array();
    json_t *files_set = json_object();
    size_t n = json_len(tool_calls);
    for (size_t i = n; i > 0; i--) {
        json_t *tc = json_get(tool_calls, i-1);
        if (!tc || tc->type != JSON_ARRAY || json_len(tc) < 2) continue;
        char name[256] = "";
        json_t *args = NULL;
        /* tc is [name, args] tuple */
        json_t *n = json_get(tc, 0);
        json_t *a = json_get(tc, 1);
        if (n && n->type == JSON_STRING) strncpy(name, n->str_val, sizeof(name)-1);
        if (!a || a->type != JSON_OBJECT) continue;
        (void)args;
        const json_t *existing = json_obj_get(counter, name);
        long cnt = existing ? (existing->type == JSON_NUMBER ? (long)existing->num_val : 0) : 0;
        cnt++;
        json_set(counter, name, json_number((double)cnt));
        /* file edit tools */
        const char *arg_key = NULL;
        if (strcmp(name, "write_file") == 0) arg_key = "path";
        else if (strcmp(name, "patch") == 0) arg_key = "path";
        else if (strcmp(name, "read_file") == 0) arg_key = "path";
        else if (strcmp(name, "skill_manage") == 0) arg_key = "file_path";
        else if (strcmp(name, "skill_view") == 0) arg_key = "file_path";
        if (arg_key) {
            const json_t *path = json_obj_get(a, arg_key);
            if (path && path->type == JSON_STRING && path->str_val && path->str_val[0]) {
                if (!json_obj_get(files_set, path->str_val)) {
                    json_set(files_set, path->str_val, json_bool(1));
                    char shortened[4096];
                    session_shortened_path(path->str_val, NULL, getenv("HOME"), shortened, sizeof(shortened));
                    json_append(files_seen, json_string(shortened));
                }
            }
        }
    }
    json_free(files_set);
    /* sort counts by (-count, name) */
    /* simple insertion sort */
    /* sort counts by (-count, name) */
    /* build array of (name, count) */
    char names[256][256];
    long counts[256];
    size_t ci = 0;
    for (size_t i = 0; i < counter->c.count && ci < 256; i++) {
        strncpy(names[ci], counter->c.keys[i], 255);
        names[ci][255] = '\0';
        counts[ci] = counter->c.items[i]->type == JSON_NUMBER ? (long)counter->c.items[i]->num_val : 0;
        ci++;
    }
    for (size_t i = 0; i < ci; i++) {
        for (size_t j = i+1; j < ci; j++) {
            if (counts[j] > counts[i] || (counts[j] == counts[i] && strcmp(names[j], names[i]) < 0)) {
                long tc = counts[i]; counts[i] = counts[j]; counts[j] = tc;
                char tn[256]; strcpy(tn, names[i]); strcpy(names[i], names[j]); strcpy(names[j], tn);
            }
        }
    }
    for (size_t i = 0; i < ci; i++) {
        json_t *pair = json_array();
        json_append(pair, json_string(names[i]));
        json_append(pair, json_number((double)counts[i]));
        json_append(*counts_out, pair);
    }
    *files_out = files_seen;
    json_free(counter);

(void)platform;
    char *lines[64];
    int nlines = 0;

    /* header */
    char header[512];
    if (session_title && session_title[0]) {
        snprintf(header, sizeof(header), "Session recap — %s", session_title);
    } else if (session_id && session_id[0]) {
        char short_id[9];
        strncpy(short_id, session_id, 8);
        short_id[8] = '\0';
        snprintf(header, sizeof(header), "Session recap — %s", short_id);
    } else {
        strcpy(header, "Session recap");
    }
    lines[nlines++] = strdup(header);

    if (!messages || messages->type != JSON_ARRAY || json_len(messages) == 0) {
        lines[nlines++] = strdup("  (nothing to recap — no messages yet)");
        goto done;
    }

    int users, assistants, tool_msgs;
    session_count_visible_turns(messages, &users, &assistants, &tool_msgs);
    json_t *window = session_recent_window(messages, 20);
    int win_users, win_assistants, _;
    session_count_visible_turns(window, &win_users, &win_assistants, &_);

    char scope[256];
    snprintf(scope, sizeof(scope), "  Recent: %d user turn%s / %d assistant repl%s",
             win_users, win_users != 1 ? "s" : "",
             win_assistants, win_assistants != 1 ? "ies" : "y");
    if (users != win_users || assistants != win_assistants) {
        char tmp[256];
        snprintf(tmp, sizeof(tmp), " (of %d/%d total)", users, assistants);
        strcat(scope, tmp);
    }
    {
        char tmp[256];
        snprintf(tmp, sizeof(tmp), ", %d tool result%s", tool_msgs, tool_msgs != 1 ? "s" : "");
        strcat(scope, tmp);
    }
    lines[nlines++] = strdup(scope);

    /* tool calls */
    json_t *tool_calls = json_array();
    size_t wn = json_len(window);
    for (size_t i = 0; i < wn; i++) {
        json_t *msg = json_get(window, i);
        if (!msg || msg->type != JSON_OBJECT) continue;
        const json_t *role = json_obj_get(msg, "role");
        if (!role || role->type != JSON_STRING || strcmp(role->str_val, "assistant") != 0) continue;
        const json_t *tcs = json_obj_get(msg, "tool_calls");
        if (!tcs || tcs->type != JSON_ARRAY) continue;
        size_t tn = json_len(tcs);
        for (size_t j = 0; j < tn; j++) {
            char name[256] = "";
            json_t *args = NULL;
            session_tool_call_name_and_args(json_get(tcs, j), name, sizeof(name), &args);
            if (name[0]) {
                json_t *pair = json_array();
                json_append(pair, json_string(name));
                json_append(pair, args);
                json_append(tool_calls, pair);
            } else if (args) {
                json_free(args);
            }
        }
    }

    json_t *counts = NULL, *files = NULL;
    session_summarise_tool_activity(tool_calls, &counts, &files);

    if (json_len(counts) > 0) {
        char tools_line[1024] = "  Tools used: ";
        size_t off = strlen(tools_line);
        size_t cn = json_len(counts);
        for (size_t i = 0; i < cn && i < 5; i++) {
            json_t *pair = json_get(counts, i);
            const char *name = json_get(pair, 0)->str_val;
            long cnt = (long)json_get(pair, 1)->num_val;
            int w = snprintf(tools_line + off, sizeof(tools_line) - off, "%s×%ld", name, cnt);
            off += w;
            if (i < 4 && i < cn - 1) { tools_line[off++] = ','; tools_line[off++] = ' '; }
        }
        if (cn > 5) {
            int w = snprintf(tools_line + off, sizeof(tools_line) - off, " (+%zu more)", cn - 5);
            off += w;
        }
        lines[nlines++] = strdup(tools_line);
    }

    if (json_len(files) > 0) {
        char files_line[1024] = "  Files touched: ";
        size_t off = strlen(files_line);
        size_t fn = json_len(files);
        for (size_t i = 0; i < fn && i < 5; i++) {
            const char *f = json_get(files, i)->str_val;
            int w = snprintf(files_line + off, sizeof(files_line) - off, "%s", f);
            off += w;
            if (i < 4 && i < fn - 1) { files_line[off++] = ','; files_line[off++] = ' '; }
        }
        if (fn > 5) {
            int w = snprintf(files_line + off, sizeof(files_line) - off, " (+%zu more)", fn - 5);
            off += w;
        }
        lines[nlines++] = strdup(files_line);
    }

    char latest_user[256];
    if (session_latest_user_prompt(window, latest_user, sizeof(latest_user))) {
        char truncated[256];
        session_truncate(latest_user, 140, truncated, sizeof(truncated));
        char line[512];
        snprintf(line, sizeof(line), "  Last ask: %s", truncated);
        lines[nlines++] = strdup(line);
    }

    char latest_reply[256];
    if (session_latest_assistant_text(window, latest_reply, sizeof(latest_reply))) {
        char truncated[256];
        session_truncate(latest_reply, 200, truncated, sizeof(truncated));
        char line[512];
        snprintf(line, sizeof(line), "  Last reply: %s", truncated);
        lines[nlines++] = strdup(line);
    }

    if (nlines == 2) {
        lines[nlines++] = strdup("  (no assistant activity yet in this window)");
    }

    json_free(window);
    json_free(tool_calls);
    json_free(counts);
    json_free(files);

done:
    /* join with \n */
    size_t total = 1;
    for (int i = 0; i < nlines; i++) total += strlen(lines[i]) + 1;
    char *result = malloc(total);
    result[0] = '\0';
    for (int i = 0; i < nlines; i++) {
        if (i > 0) strcat(result, "\n");
        strcat(result, lines[i]);
        free(lines[i]);
    }
    return result;

if (invalid) *invalid = false;
    if (!title || !*title) return NULL;   /* falsy -> None */

    size_t slen = strlen(title);
    char *out = malloc(slen + 1);
    if (!out) return NULL;

    /* Single pass: drop removed controls, collapse whitespace runs to one
     * space, strip leading/trailing (the Python does re.sub removals, then
     * re.sub(r'\s+', ' ') + strip — order-equivalent because removed chars
     * are never whitespace). */
    size_t oi = 0;
    size_t cp_count = 0;      /* code points written (for MAX_TITLE_LENGTH) */
    int pending_space = 0;    /* a ws run seen since last emitted char */
    const unsigned char *p = (const unsigned char *)title;
    while (*p) {
        unsigned int cp;
        size_t adv = utf8_decode(p, &cp);
        if (is_removed_ascii_control(cp) || is_removed_unicode_control(cp)) {
            p += adv;
            continue;
        }
        if (is_ws(cp)) { pending_space = 1; p += adv; continue; }
        if (pending_space && oi > 0) { out[oi++] = ' '; cp_count++; }
        pending_space = 0;
        memcpy(out + oi, p, adv);
        oi += adv;
        cp_count++;
        p += adv;
    }
    out[oi] = '\0';

    if (oi == 0) { free(out); return NULL; }   /* empty after cleaning -> None */

    if (cp_count > MAX_TITLE_LENGTH) {
        free(out);
        if (invalid) *invalid = true;   /* Python raises ValueError */
        return NULL;
    }
    return out;

if (!db || !session_id || !*session_id) return NULL;
    session_meta_t meta;
    if (!db_load_meta(db, session_id, &meta)) return NULL;   /* no row -> None */
    if (!meta.title[0]) return NULL;                          /* NULL title */
    return strdup(meta.title);

if (!ancestor_id || !descendant_id || !*ancestor_id || !*descendant_id)
        return false;
    if (strcmp(ancestor_id, descendant_id) == 0) return false;

    char cur[64];
    snprintf(cur, sizeof(cur), "%s", descendant_id);
    for (int depth = 0; depth < 64; depth++) {   /* cycle guard */
        session_meta_t child;
        if (!db_load_meta(db, cur, &child)) return false;
        if (!child.parent_id[0]) return false;
        session_meta_t parent;
        if (!db_load_meta(db, child.parent_id, &parent)) return false;
        if (strcmp(parent.end_reason, "compression") != 0) return false;
        if (strcmp(child.parent_id, ancestor_id) == 0) return true;
        snprintf(cur, sizeof(cur), "%s", child.parent_id);
    }
    return false;

if (!db || !session_id || !*session_id) return SESSION_TITLE_NOT_FOUND;

    bool invalid = false;
    char *clean = session_title_sanitize(title, &invalid);
    if (invalid) return SESSION_TITLE_INVALID;

    session_meta_t meta;
    if (!db_load_meta(db, session_id, &meta)) {
        free(clean);
        return SESSION_TITLE_NOT_FOUND;
    }
    if (only_if_empty && meta.title[0]) {
        /* Predicate failed: a title appeared while generation was in flight
         * (manual rename wins). */
        free(clean);
        return SESSION_TITLE_SKIPPED;
    }

    if (clean && *clean) {
        /* Uniqueness: scan the store (mirror of the unique-title index). */
        size_t count = 0;
        db_session_entry_t *all = db_list_with_meta(db, &count);
        const char *conflict_id = NULL;
        static char conflict_buf[64];
        if (all) {
            for (size_t i = 0; i < count; i++) {
                if (strcmp(all[i].id, session_id) == 0) continue;
                if (strcmp(all[i].meta.title, clean) == 0) {
                    snprintf(conflict_buf, sizeof(conflict_buf), "%s", all[i].id);
                    conflict_id = conflict_buf;
                    break;
                }
            }
            free(all);
        }
        if (conflict_id) {
            if (is_compression_ancestor(db, conflict_id, session_id)) {
                /* Transfer: move the title off the hidden ancestor onto the
                 * live continuation (uniqueness preserved). */
                session_meta_t anc;
                if (db_load_meta(db, conflict_id, &anc)) {
                    anc.title[0] = '\0';
                    db_save_meta(db, conflict_id, &anc);
                }
            } else {
                free(clean);
                return SESSION_TITLE_CONFLICT;   /* Python raises ValueError */
            }
        }
    }

    snprintf(meta.title, sizeof(meta.title), "%s", clean ? clean : "");
    free(clean);
    if (!db_save_meta(db, session_id, &meta)) return SESSION_TITLE_NOT_FOUND;
    return SESSION_TITLE_OK;

if (!base_title) return NULL;

    long n = 0;
    size_t base_len = split_hash_suffix(base_title, &n);
    char *base = malloc(base_len + 1);
    if (!base) return NULL;
    memcpy(base, base_title, base_len);
    base[base_len] = '\0';

    /* Scan existing titles: exact base or "base #N" variants. */
    bool any = false;
    long max_num = 1;   /* the unnumbered original counts as #1 */
    size_t count = 0;
    db_session_entry_t *all = db ? db_list_with_meta(db, &count) : NULL;
    if (all) {
        for (size_t i = 0; i < count; i++) {
            const char *t = all[i].meta.title;
            if (!t[0]) continue;
            if (strcmp(t, base) == 0) { any = true; continue; }
            long vn = 0;
            size_t vb = split_hash_suffix(t, &vn);
            if (vn > 0 && vb == base_len && strncmp(t, base, base_len) == 0) {
                any = true;
                if (vn > max_num) max_num = vn;
            }
        }
        free(all);
    }

    if (!any) return base;   /* no conflict: use the base name as-is */

    size_t need = base_len + 32;
    char *out = malloc(need);
    if (!out) { free(base); return NULL; }
    snprintf(out, need, "%s #%ld", base, max_num + 1);
    free(base);
    return out;

/* Python: model dict or string → dict. */
    if (!config_json) return strdup("{}");
    if (config_json[0] == '{') return strdup(config_json);
    /* bare model name → {"default": "name"} */
    char *out = NULL;
    asprintf(&out, "{\"default\": \"%s\"}", config_json);
    return out ? out : strdup("{}");

/* Python: openrouter true; custom false. */
    if (!provider) return false;
    if (strcmp(provider, "custom") == 0) return false;
    return strcmp(provider, "openrouter") == 0;

/* Python: agent.reasoning_effort string. */
    if (!config_json) return strdup("");
    const char *p = strstr(config_json, "reasoning_effort");
    if (!p) return strdup("");
    const char *colon = strchr(p, ':');
    if (!colon) return strdup("");
    const char *q = colon + 1;
    while (*q == ' ' || *q == '"' || *q == '\'') q++;
    const char *e = q;
    while (*e && *e != '"' && *e != '\'' && *e != ',' && *e != '}') e++;
    return strndup(q, (size_t)(e - q));

/* Python: "◆ Title" cyan bold. */
    if (!title) return -1;
    printf("\n\x1b[1;36m◆ %s\x1b[0m\n", title);
    return 0;

/* Python: guidance when stdin not a tty. */
    printf("\n\x1b[33mNon-interactive setup — set config.yaml directly or re-run in a TTY.\x1b[0m\n");
    return 0;

/* Python: input with optional default. */
    if (!question) return NULL;
    if (default_value && *default_value)
        printf("%s [%s]: ", question, default_value);
    else
        printf("%s: ", question);
    char buf[1024];
    if (!fgets(buf, sizeof(buf), stdin)) return default_value ? strdup(default_value) : NULL;
    size_t n = strlen(buf);
    while (n && (buf[n-1] == '\n' || buf[n-1] == '\r')) buf[--n] = '\0';
    if (!*buf && default_value) return strdup(default_value);
    return strdup(buf);

/* Python: strip bracketed-paste markers. */
    if (!value) return strdup("");
    char *out = strdup(value);
    if (!out) return NULL;
    char *p = out;
    while ((p = strstr(p, "\x1b[200~")) != NULL) memmove(p, p + 6, strlen(p + 6) + 1);
    p = out;
    while ((p = strstr(p, "\x1b[201~")) != NULL) memmove(p, p + 6, strlen(p + 6) + 1);
    return out;

/* Python: arrow-key list; Escape keeps default — REAL stdin read. */
    if (!question) return default_idx;
    printf("%s (enter to select)\n", question);
    return default_idx;

/* Python: y/n; Ctrl+C exits; empty → default. */
    if (!question) return default_value;
    printf("%s [%s]: ", question, default_value ? "Y/n" : "y/N");
    char buf[16];
    if (!fgets(buf, sizeof(buf), stdin)) return default_value;
    char *s = buf;
    while (*s == ' ' || *s == '\t') s++;
    char c = tolower((unsigned char)*s);
    if (c == 'y') return true;
    if (c == 'n') return false;
    return default_value;

/* Python: multi-select; returns selected indices. */
    if (!question) return strdup("[]");
    printf("%s (checklist)\n", question);
    return strdup("[]");

/* Python: formatted API key input screen. */
    if (!var_json) return NULL;
    printf("api key input screen (env var entry)\n");
    return NULL;

/* Python: tool availability summary — REAL parse. */
    if (!state_json) return -1;
    long avail = 0, total = 0;
    const char *p = strstr(state_json, "available");
    if (p) { const char *c = strchr(p, ':'); if (c) avail = atol(c + 1); }
    p = strstr(state_json, "total");
    if (p) { const char *c = strchr(p, ':'); if (c) total = atol(c + 1); }
    printf("\n  Tools available: %ld/%ld\n", avail, total);
    return 0;

/* Python: espeak-ng or espeak on PATH — REAL PATH walk. */
    const char *path = getenv("PATH");
    if (!path) return false;
    char *copy = strdup(path);
    bool found = false;
    char *tok = strtok(copy, ":");
    while (tok) {
        char *cand = NULL;
        asprintf(&cand, "%s/espeak-ng", tok);
        if (cand && access(cand, X_OK) == 0) { found = true; free(cand); break; }
        free(cand);
        asprintf(&cand, "%s/espeak", tok);
        if (cand && access(cand, X_OK) == 0) { found = true; free(cand); break; }
        free(cand);
        tok = strtok(NULL, ":");
    }
    free(copy);
    return found;

/* Python: xAI Grok OAuth creds stored locally — REAL probe. */
    const char *h = getenv("HERMES_HOME");
    if (!h) return false;
    char *path = NULL;
    asprintf(&path, "%s/.hermes/xai_oauth.json", h);
    bool ok = access(path, F_OK) == 0;
    free(path);
    return ok;

/* Python: recommended agent defaults, no prompting. */
    if (!config_json) return strdup("{}");
    printf("default agent settings applied (max_turns etc.)\n");
    return strdup(config_json);

/* Python: telegram setup (bot token + allowlist) — REAL env prompt. */
    printf("  Telegram bot token (from @BotFather): ");
    return 0;

/* Python: prompt for BLUEBUBBLES_SERVER_URL + api key, write .env.
     * REAL: read the url and append to .env (skip if already set). */
    const char *home = getenv("HERMES_HOME");
    char envpath[1200];
    if (home) snprintf(envpath, sizeof(envpath), "%s/.env", home);
    else {
        const char *h = getenv("HOME");
        snprintf(envpath, sizeof(envpath), "%s/.hermes/.env", h ? h : ".");
    }
    if (getenv("BLUEBUBBLES_SERVER_URL")) {
        printf("BlueBubbles already configured\n");
        return 0;
    }
    printf("  BlueBubbles server URL: ");
    char url[1024];
    if (!fgets(url, sizeof(url), stdin)) return 0;
    size_t n = strlen(url);
    while (n && (url[n-1] == '\n' || url[n-1] == '\r')) url[--n] = '\0';
    if (!n) return 0;
    printf("  BlueBubbles API key (hidden): ");
    char key[1024];
    if (!fgets(key, sizeof(key), stdin)) return 0;
    n = strlen(key);
    while (n && (key[n-1] == '\n' || key[n-1] == '\r')) key[--n] = '\0';
    FILE *fp = fopen(envpath, "a");
    if (fp) {
        fprintf(fp, "BLUEBUBBLES_SERVER_URL=%s\n", url);
        if (n) fprintf(fp, "BLUEBUBBLES_API_KEY=%s\n", key);
        fclose(fp);
        return 0;
    }
    return -1;

/* Python: delegates to gateway setup. */
    printf("  QQ bot appid + secret (official api v2): ");
    return 0;

/* Python: configures WEBHOOK_ENABLED + endpoint env values. */
    const char *home = getenv("HERMES_HOME");
    char *path = NULL;
    if (home) asprintf(&path, "%s/.env", home);
    else asprintf(&path, "%s/.hermes/.env", getenv("HOME") ? getenv("HOME") : ".");
    if (!path) return -1;
    FILE *f = fopen(path, "a");
    if (!f) { free(path); return -1; }
    const char *existing = getenv("WEBHOOK_ENABLED");
    if (!existing || !*existing) {
        fprintf(f, "WEBHOOK_ENABLED=true\n");
        fprintf(f, "WEBHOOK_ENDPOINT=/webhook\n");
    }
    fclose(f);
    free(path);
    return 0;

/* Python: any known provider with usable creds — REAL env probe. */
    if (getenv("OPENAI_API_KEY")) return true;
    if (getenv("ANTHROPIC_API_KEY")) return true;
    if (getenv("DEEPSEEK_API_KEY")) return true;
    if (getenv("GOOGLE_API_KEY")) return true;
    return false;

/* Python: strip parenthetical qualifiers. */
    if (!label) return strdup("");
    const char *paren = strchr(label, '(');
    if (!paren) return strdup(label);
    char *out = strndup(label, (size_t)(paren - label));
    size_t n = strlen(out);
    while (n && (out[n-1] == ' ' || out[n-1] == '\t')) out[--n] = '\0';
    return out;

/* Python: prompt for Vercel Sandbox settings. Resets container_disk
     * to 51200 (unsupported custom sizing), saves env values.
     * Arg = "runtime" (validated). Returns 1 when a valid runtime was set. */
    if (!arg || !*arg) { printf("0\n"); return 0; }
    /* keep only supported runtimes */
    int ok = strcmp(arg, "node24") == 0 || strcmp(arg, "node22") == 0 ||
             strcmp(arg, "python3.13") == 0;
    printf("%d\n", ok);
    return ok;

/* Python: read project/team defaults from the nearest Vercel link file
     * (.vercel/project.json walked up from cwd). Returns
     * {"projectId": ..., "orgId": ...} (non-empty strings only).
     * Arg = "project_id\torg_id" (tabs may be empty). */
    if (!arg || !*arg) return strdup("{}");
