     * Arg = "valid\tdims_json" (valid 1/0). */
    if (!arg || !*arg) return strdup("None");
    const char *tab = strchr(arg, '\t');
    int valid = arg[0] == '1';
    if (!valid) return strdup("None");
    if (tab && tab[1]) return strdup(tab + 1);
