    char *result = NULL;
    if (len > s) {
        result = malloc(len - s + 1);
        if (result) {
            for (size_t i = 0; i < len - s; i++)
                result[i] = (char)tolower((unsigned char)buf[s + i]);
            result[len - s] = '\0';
