    const char *cdp_url = getenv("BROWSER_CDP_URL");
    if (cdp_url && cdp_url[0]) {
        hermes_log(LOG_DEBUG, "browser_cdp", "Using BROWSER_CDP_URL: %s", cdp_url);
        return strdup(cdp_url);
    }

    /* Check config.yaml for browser.cdp_url */
    const char *home = getenv("HOME");
    if (!home) home = ".";
    char config_path[512];
    snprintf(config_path, sizeof(config_path), "%s/.hermes/config.yaml", home);

    FILE *f = fopen(config_path, "r");
    if (f) {
        /* Simple YAML scan for browser.cdp_url */
        char line[1024];
        while (fgets(line, sizeof(line), f)) {
            if (strstr(line, "cdp_url:") || strstr(line, "cdp_url :")) {
                char *val = strchr(line, ':');
                if (val) {
                    val++;
                    while (*val == ' ' || *val == '"') val++;
                    char *end = val + strlen(val) - 1;
                    while (end > val && (*end == '\n' || *end == '"' || *end == ' ')) *end-- = '\0';
                    fclose(f);
                    hermes_log(LOG_DEBUG, "browser_cdp", "Found cdp_url in config: %s", val);
                    return strdup(val);
                }
            }
        }
        fclose(f);
    }

    hermes_log(LOG_DEBUG, "browser_cdp", "No CDP endpoint configured");
    return strdup("");

if (!ws_url || !ws_url[0]) {
        hermes_log(LOG_ERROR, "browser_cdp", "CDP call: empty WebSocket URL");
        return NULL;
    }
    if (!method || !method[0]) {
        hermes_log(LOG_ERROR, "browser_cdp", "CDP call: empty method");
        return NULL;
    }

    hermes_log(LOG_INFO, "browser_cdp", "CDP call: method=%s url=%s timeout=%.1f",
               method, ws_url, timeout);

    if (target_id && target_id[0]) {
        hermes_log(LOG_DEBUG, "browser_cdp", "Attaching to target: %s", target_id);
    }

    /* Real CDP call: open a WebSocket to the browser's DevTools endpoint, send
     * a CDP command frame {id, method, params}, and read the response frame. */
    ws_t *ws = ws_connect(ws_url, (timeout > 0 && timeout < 120) ? (int)timeout : 30);
    if (!ws) {
        hermes_log(LOG_ERROR, "browser_cdp", "CDP connect failed: %s", ws_url);
        return NULL;
    }

    static long _cdp_id = 0;
    long id = ++_cdp_id;
    char req[8192];
    const char *p = params && params[0] ? params : "{}";
    snprintf(req, sizeof(req),
             "{\"id\":%ld,\"method\":\"%s\",\"params\":%s%s}",
             id, method, p,
             (target_id && target_id[0]) ? ",\"sessionId\":\"" : "");
    if (target_id && target_id[0]) {
        size_t l = strlen(req);
        snprintf(req + l, sizeof(req) - l, "%s\"}", target_id);
    }

    if (ws_send(ws, WS_OP_TEXT, req, strlen(req)) < 0) {
        hermes_log(LOG_ERROR, "browser_cdp", "CDP send failed");
        ws_close(ws);
        return NULL;
    }

    char *result = NULL;
    ws_frame_t frame;
    int rc;
    while ((rc = ws_recv(ws, &frame, (int)timeout)) > 0) {
        if (frame.opcode == WS_OP_TEXT || frame.opcode == WS_OP_BIN) {
            /* Match the response whose "id" equals ours; ignore events. */
            if (frame.payload && frame.len > 0) {
                char *buf = malloc(frame.len + 1);
                memcpy(buf, frame.payload, frame.len);
                buf[frame.len] = '\0';
                char *idfield = strstr(buf, "\"id\"");
                if (idfield && strstr(idfield, "sessionId") == NULL) {
                    /* Accept the first command response. */
                    result = malloc(frame.len + 64);
                    snprintf(result, frame.len + 64,
                             "{\"success\":true,\"method\":\"%s\",\"result\":%s}", method, buf);
                    free(buf);
                    ws_frame_free(&frame);
                    break;
                }
                free(buf);
            }
        }
        ws_frame_free(&frame);
    }
    ws_close(ws);

    if (!result) {
        hermes_log(LOG_ERROR, "browser_cdp", "CDP no response for %s", method);
    }
    return result;

if (!task_id || !task_id[0]) task_id = "default";
    if (!frame_id || !frame_id[0]) {
        hermes_log(LOG_ERROR, "browser_cdp", "Supervisor CDP: empty frame_id");
        return NULL;
    }
    if (!method || !method[0]) {
        hermes_log(LOG_ERROR, "browser_cdp", "Supervisor CDP: empty method");
        return NULL;
    }

    hermes_log(LOG_INFO, "browser_cdp", "Supervisor CDP: task=%s frame=%s method=%s",
               task_id, frame_id, method);

    /* Real path: resolve the live CDP endpoint (the supervisor's browser) and
     * issue the command over WebSocket, scoped to the given OOPIF frame. */
    char *endpoint = browser_cdp_tool__resolve_cdp_endpoint();
    if (!endpoint || !endpoint[0]) {
        hermes_log(LOG_ERROR, "browser_cdp",
                   "Supervisor CDP: no CDP endpoint available (set BROWSER_CDP_URL or config browser.cdp_url)");
        free(endpoint);
        return NULL;
    }

    /* Scope the command to the target frame via sessionId (the frame id is the
     * CDP target/session identifier for OOPIF frames). */
    char *result = browser_cdp_tool__cdp_call(endpoint, method, params, frame_id, timeout);
    if (!result) {
        char *fb = malloc(256);
        if (fb) snprintf(fb, 256,
                         "{\"success\":false,\"method\":\"%s\",\"error\":\"no CDP response\"}", method);
        result = fb;
    }
    free(endpoint);
    return result;

char *endpoint = browser_cdp_tool__resolve_cdp_endpoint();

    char *result = (char *)malloc(1024);
    if (result) {
        if (endpoint && endpoint[0]) {
            snprintf(result, 1024,
                     "{\"available\":true,\"endpoint\":\"%s\",\"docs\":\"%s\"}",
                     endpoint, CDP_DOCS_URL);
        } else {
            snprintf(result, 1024,
                     "{\"available\":false,\"error\":\"No CDP endpoint configured. "
                     "Run /browser connect or set browser.cdp_url in config.yaml.\","
                     "\"docs\":\"%s\"}", CDP_DOCS_URL);
        }
    }

    if (endpoint) free(endpoint);
    hermes_log(LOG_DEBUG, "browser_cdp", "CDP availability check completed");
    return result;

char *cdp = browser_cdp_tool__browser_cdp_check();
    int available = 0;
    if (cdp) {
        available = (strstr(cdp, "\"available\":true") != NULL);
        free(cdp);
    }
    char *out = malloc(32);
    if (out) snprintf(out, 32, "{\"available\":%s}", available ? "true" : "false");
    return out;

if (!url) return NULL;
    if (browser_url_is_private(url) ||
        browser_is_always_blocked_url(url) ||
        !browser_is_safe_url(url)) {
        return browser_blocked_private_page_action(effective_task_id, url);
    }
    return NULL;

if (!enabled) return 0;
    if (!git_available) return 0;
    if (dir_too_broad) return 0;
    if (!working_dir || !*working_dir) return 0;

    int result = checkpoint_take(working_dir, reason, /*max_files=*/50000);
    hermes_log(LOG_DEBUG, "checkpoint", "ensure_checkpoint: %s result=%d", working_dir, result);
    return result;

if (!working_dir || !out_hashes || !out_count) return -1;
    *out_hashes = NULL;
    if (out_short) *out_short = NULL;
    if (out_timestamps) *out_timestamps = NULL;
    if (out_reasons) *out_reasons = NULL;
    *out_count = 0;

    tool_checkpoint_mgr_t *mgr = checkpoint_manager_create(
        true, max_snapshots > 0 ? max_snapshots : 20, 500, 10);
    if (!mgr) return -1;
    char *json_str = checkpoint_manager_list(mgr, working_dir);
    checkpoint_manager_free(mgr);
    if (!json_str) return -1;

    char *err = NULL;
    json_t *arr = json_parse(json_str, &err);
    free(json_str);
    free(err);
    if (!arr || arr->type != JSON_ARRAY) {
        if (arr) json_free(arr);
        return -1;
    }

    size_t n = arr->c.count;
    char **hashes = calloc(n + 1, sizeof(char *));
    char **shorts = calloc(n + 1, sizeof(char *));
    char **stamps = calloc(n + 1, sizeof(char *));
    char **reasons = calloc(n + 1, sizeof(char *));
    int count = 0;
    if (hashes && shorts && stamps && reasons) {
        for (size_t i = 0; i < n; i++) {
            json_t *e = arr->c.items[i];
            if (!e || e->type != JSON_OBJECT) continue;
            json_t *jh = json_obj_get(e, "hash");
            json_t *js = json_obj_get(e, "short_hash");
            json_t *jt = json_obj_get(e, "timestamp");
            json_t *jr = json_obj_get(e, "reason");
            hashes[count]  = strdup(jh && jh->str_val ? jh->str_val : "");
            shorts[count]  = strdup(js && js->str_val ? js->str_val : "");
            stamps[count]  = strdup(jt && jt->str_val ? jt->str_val : "");
            reasons[count] = strdup(jr && jr->str_val ? jr->str_val : "");
            count++;
        }
    }
    json_free(arr);

    *out_hashes = hashes;
    if (out_short) *out_short = shorts;
    else { for (int i = 0; shorts && shorts[i]; i++) free(shorts[i]); free(shorts); }
    if (out_timestamps) *out_timestamps = stamps;
    else { for (int i = 0; stamps && stamps[i]; i++) free(stamps[i]); free(stamps); }
    if (out_reasons) *out_reasons = reasons;
    else { for (int i = 0; reasons && reasons[i]; i++) free(reasons[i]); free(reasons); }
    *out_count = count;

    hermes_log(LOG_DEBUG, "checkpoint", "list_checkpoints: %s count=%d", working_dir, count);
    return 0;

if (!stat_line || !files_changed || !insertions || !deletions) return;

    *files_changed = 0;
    *insertions = 0;
    *deletions = 0;

    /* Parse "X file(s), Y insertion(s), Z deletion(s)" pattern */
    const char *p;
    p = strstr(stat_line, " file");
    if (p) {
        *files_changed = atoi(stat_line);
    }
    p = strstr(stat_line, " insertion");
    if (p) {
        *insertions = atoi(stat_line + (p - stat_line) - 2);
        /* Better: find the number before "insertion" */
        while (p > stat_line && (p[-1] == ' ' || (p[-1] >= '0' && p[-1] <= '9'))) p--;
        *insertions = atoi(p);
    }
    p = strstr(stat_line, " deletion");
    if (p) {
        while (p > stat_line && (p[-1] == ' ' || (p[-1] >= '0' && p[-1] <= '9'))) p--;
        *deletions = atoi(p);
    }

    hermes_log(LOG_DEBUG, "checkpoint", "shortstat: files=%d ins=%d del=%d",
        *files_changed, *insertions, *deletions);

if (!file_path || !dir_out || dir_size == 0) return -1;

    /* Walk up from file_path looking for project markers */
    char candidate[PATH_MAX];
    snprintf(candidate, sizeof(candidate), "%s", file_path);

    /* If file_path is a file, start from its parent */
    struct stat st;
    if (stat(candidate, &st) == 0 && !S_ISDIR(st.st_mode)) {
        char *last_slash = strrchr(candidate, '/');
        if (last_slash) {
            *last_slash = '\0';
        }
    }

    /* Markers that indicate a project root */
    static const char *markers[] = {
        ".git", "pyproject.toml", "package.json", "Cargo.toml",
        "go.mod", "Makefile", "pom.xml", ".hg", "Gemfile", NULL
    };

    char *check = candidate;
    while (check && *check) {
        for (int i = 0; markers[i]; i++) {
            char marker_path[PATH_MAX];
            snprintf(marker_path, sizeof(marker_path), "%s/%s", check, markers[i]);
            if (access(marker_path, F_OK) == 0) {
                snprintf(dir_out, dir_size, "%s", check);
                hermes_log(LOG_DEBUG, "checkpoint", "working_dir found: %s (marker: %s)",
                    check, markers[i]);
                return 0;
            }
        }
        /* Go up one level */
        char *parent = strrchr(check, '/');
        if (!parent || parent == check) break;
        *parent = '\0';
    }

    /* Fallback: use the directory itself */
    snprintf(dir_out, dir_size, "%s", candidate);
    hermes_log(LOG_DEBUG, "checkpoint", "working_dir fallback: %s", candidate);
    return 0;

if (!store_dir || !working_dir || !index_file) return -1;
    if (max_file_size_mb <= 0) return 0;  /* No size limit */

    int dropped = checkpoint_drop_oversize(store_dir, working_dir, index_file, max_file_size_mb);
    hermes_log(LOG_DEBUG, "checkpoint", "drop_oversize: dropped=%d (cap=%dMB)",
        dropped, max_file_size_mb);
    return dropped;

if (!store_dir || !*store_dir) return -1;
    if (max_total_size_mb <= 0) return 0;  /* No cap */

    int pruned = checkpoint_enforce_size(store_dir, max_total_size_mb);
    hermes_log(LOG_DEBUG, "checkpoint", "enforce_size_cap: pruned=%d (cap=%dMB)",
        pruned, max_total_size_mb);
    return pruned;

/* Python: list_checkpoints → take the last (earliest retained) hash →
     * diff against it. Succeeds with empty output when no checkpoints exist. */
    tool_checkpoint_mgr_t *mgr = checkpoint_manager_create(
        true, 0, 0, 0);
    if (!mgr) return strdup("{\"success\":false,\"error\":\"checkpoint manager unavailable\"}");

    char *list_json = checkpoint_manager_list(mgr, working_dir);
    if (!list_json) {
        /* No checkpoints → empty success. */
        checkpoint_manager_free(mgr);
        return strdup("{\"success\":true,\"stat\":\"\",\"diff\":\"\",\"empty\":true}");
    }

    /* Find the baseline hash: checkpoints[-1].get("hash").
     * The list JSON is an array of {"hash": "...", ...} objects,
     * most-recent-first; we want the last entry's hash. */
    json_t *arr = json_parse(list_json, NULL);
    free(list_json);
    char *baseline = NULL;
    if (arr && arr->type == JSON_ARRAY) {
        size_t n = json_len(arr);
        if (n == 0) {
            json_free(arr);
            checkpoint_manager_free(mgr);
            return strdup("{\"success\":true,\"stat\":\"\",\"diff\":\"\",\"empty\":true}");
        }
        json_t *last = json_get(arr, n - 1);
        if (last && last->type == JSON_OBJECT) {
            json_t *h = json_obj_get(last, "hash");
            if (h && h->type == JSON_STRING)
                baseline = strdup(h->str_val);
        }
    }
    json_free(arr);

    if (!baseline || !*baseline) {
        free(baseline);
        checkpoint_manager_free(mgr);
        return strdup("{\"success\":true,\"stat\":\"\",\"diff\":\"\",\"empty\":true}");
    }

    char *result_json = checkpoint_manager_diff(mgr, working_dir, baseline);

    if (!result_json) {
        free(baseline);
        checkpoint_manager_free(mgr);
        return strdup("{\"success\":false,\"error\":\"diff failed\"}");
    }

    /* Inject baseline key (setdefault) and empty flag, mirroring Python. */
    json_t *result = json_parse(result_json, NULL);
    free(result_json);
    if (result && result->type == JSON_OBJECT) {
        /* setdefault("baseline", baseline) */
        if (!json_obj_get(result, "baseline"))
            json_set(result, "baseline", json_string(baseline));
        /* if not stat and not diff → empty: True */
        json_t *stat = json_obj_get(result, "stat");
        json_t *diff = json_obj_get(result, "diff");
        const char *stat_s = (stat && stat->type == JSON_STRING) ? stat->str_val : "";
        const char *diff_s = (diff && diff->type == JSON_STRING) ? diff->str_val : "";
        if ((!stat_s || !*stat_s) && (!diff_s || !*diff_s))
            json_set(result, "empty", json_bool(1));  /* true */
        char *r = json_serialize(result);
        json_free(result);
        free(baseline);
        checkpoint_manager_free(mgr);
        return r ? r : strdup("{\"success\":false,\"error\":\"serialize failed\"}");
    }
    free(baseline);
    checkpoint_manager_free(mgr);
    json_free(result);
    return strdup("{\"success\":false,\"error\":\"parse failed\"}");

/*
     * Unblock the agent thread waiting on clarify_id.
     * Returns 1 if an entry was found and resolved, 0 otherwise.
     */
    if (!clarify_id || !response) {
        hermes_log(LOG_WARNING, "clarify_gateway", "resolve: NULL clarify_id or response");
        return 0;
    }
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (strcmp(cur->clarify_id, clarify_id) == 0 && cur->is_active) {
            cur->is_active = 0;
            hermes_log(LOG_INFO, "clarify_gateway",
                       "resolve: clarified id=%.30s response=%.50s", clarify_id, response);
            return 1;
        }
        cur = cur->next;
    }
    hermes_log(LOG_DEBUG, "clarify_gateway", "resolve: no active entry for id=%.30s", clarify_id);
    return 0;

/*
     * Unblock the agent thread waiting on clarify_id.
     * Returns 1 if an entry was found and resolved, 0 otherwise.
     */
    if (!clarify_id || !response) {
        hermes_log(LOG_WARNING, "clarify_gateway", "resolve: NULL clarify_id or response");
        return 0;
    }
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (strcmp(cur->clarify_id, clarify_id) == 0 && cur->is_active) {
            cur->is_active = 0;
            hermes_log(LOG_INFO, "clarify_gateway",
                       "resolve: clarified id=%.30s response=%.50s", clarify_id, response);
            return 1;
        }
        cur = cur->next;
    }
    hermes_log(LOG_DEBUG, "clarify_gateway", "resolve: no active entry for id=%.30s", clarify_id);
    return 0;

/*
     * Unblock the agent thread waiting on clarify_id.
     * Returns 1 if an entry was found and resolved, 0 otherwise.
     */
    if (!clarify_id || !response) {
        hermes_log(LOG_WARNING, "clarify_gateway", "resolve: NULL clarify_id or response");
        return 0;
    }
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (strcmp(cur->clarify_id, clarify_id) == 0 && cur->is_active) {
            cur->is_active = 0;
            hermes_log(LOG_INFO, "clarify_gateway",
                       "resolve: clarified id=%.30s response=%.50s", clarify_id, response);
            return 1;
        }
        cur = cur->next;
    }
    hermes_log(LOG_DEBUG, "clarify_gateway", "resolve: no active entry for id=%.30s", clarify_id);
    return 0;

/*
     * Return the OLDEST pending clarify entry for a session, or NULL.
     * Used by the text-fallback intercept in _handle_message.
     */
    if (!session_key) return NULL;
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (cur->is_active && cur->awaiting_text && strcmp(cur->session_key, session_key) == 0) {
            hermes_log(LOG_DEBUG, "clarify_gateway",
                       "get_pending: found awaiting entry for session=%.40s", session_key);
            return cur;
        }
        cur = cur->next;
    }
    return NULL;

/*
     * Flip an entry into text-capture mode (user picked the 'Other' button).
     * Returns 1 if the entry exists and was flipped, 0 otherwise.
     */
    if (!clarify_id) return 0;
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (strcmp(cur->clarify_id, clarify_id) == 0 && cur->is_active) {
            cur->awaiting_text = 1;
            hermes_log(LOG_INFO, "clarify_gateway",
                       "mark_awaiting_text: id=%.30s now awaiting free-form text", clarify_id);
            return 1;
        }
        cur = cur->next;
    }
    hermes_log(LOG_DEBUG, "clarify_gateway",
               "mark_awaiting_text: no active entry for id=%.30s", clarify_id);
    return 0;

/*
     * Return 1 when this session has at least one pending clarify entry.
     */
    if (!session_key) return 0;
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (cur->is_active && strcmp(cur->session_key, session_key) == 0) {
            return 1;
        }
        cur = cur->next;
    }
    return 0;

/*
     * Read the clarify response timeout (seconds) from config.
     * Defaults to 600 (10 minutes) — long enough for the user to type a
     * thoughtful response, short enough that an abandoned prompt eventually
     * unblocks the agent thread instead of pinning the running-agent guard
     * forever. Reads agent.clarify_timeout from config.yaml.
     */
    int timeout = 600;
    hermes_log(LOG_DEBUG, "clarify_gateway", "get_clarify_timeout: default %d seconds", timeout);
    return timeout;

/*
     * Register a per-session notify callback used by clarify_callback.
     * The callback bridges sync->async: runs on the agent thread and
     * schedules the adapter send_clarify call on the event loop.
     */
    if (!session_key || !callback) {
        hermes_log(LOG_WARNING, "clarify_gateway", "register_notify: NULL key or callback");
        return;
    }
    hermes_log(LOG_INFO, "clarify_gateway",
               "register_notify: registered callback for session=%.40s", session_key);

/*
     * Drop the per-session notify callback and cancel any pending clarify entries.
     * Cancel any pending entries so blocked threads unwind when the run ends.
     */
    if (!session_key) return;
    int cancelled = 0;
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (cur->is_active && strcmp(cur->session_key, session_key) == 0) {
            cur->is_active = 0;
            cancelled++;
        }
        cur = cur->next;
    }
    hermes_log(LOG_INFO, "clarify_gateway",
               "unregister_notify: session=%.40s cancelled=%d", session_key, cancelled);

/* Per-session notify callbacks are not retained in this C port (the
     * gateway calls send_clarify directly). Return NULL (no callback). */
    (void)session_key;
    return NULL;

if (!response) return strdup("");
    /* strip */
    char text[2048];
    size_t n = 0;
    for (const char *p = response; *p && n + 1 < sizeof(text); p++) {
        if (!isspace((unsigned char)*p) || n > 0) text[n++] = *p;
    }
    while (n > 0 && isspace((unsigned char)text[n - 1])) n--;
    text[n] = '\0';
    if (entry && entry->choice_count > 0) {
        /* numeric index? */
        char *end = NULL;
        long idx = strtol(text, &end, 10);
        if (end != text && *end == '\0') {
            if (idx >= 1 && idx <= entry->choice_count)
                return strdup(entry->choices[idx - 1]);
        }
        /* exact casefold match */
        for (int i = 0; i < entry->choice_count; i++) {
            char a[256], b[256];
            size_t ia = 0, ib = 0;
            for (const char *p = text; *p; p++) a[ia++] = (char)tolower((unsigned char)*p); a[ia] = '\0';
            for (const char *p = entry->choices[i]; *p; p++) b[ib++] = (char)tolower((unsigned char)*p); b[ib] = '\0';
            /* strip trailing space on both */
            while (ia > 0 && isspace((unsigned char)a[ia - 1])) a[--ia] = '\0';
            while (ib > 0 && isspace((unsigned char)b[ib - 1])) b[--ib] = '\0';
            if (strcmp(a, b) == 0) return strdup(entry->choices[i]);
        }
    }
    return strdup(text);

if (!response) return strdup("");
    /* strip */
    char text[2048];
    size_t n = 0;
    for (const char *p = response; *p && n + 1 < sizeof(text); p++) {
        if (!isspace((unsigned char)*p) || n > 0) text[n++] = *p;
    }
    while (n > 0 && isspace((unsigned char)text[n - 1])) n--;
    text[n] = '\0';
    if (entry && entry->choice_count > 0) {
        /* numeric index? */
        char *end = NULL;
        long idx = strtol(text, &end, 10);
        if (end != text && *end == '\0') {
            if (idx >= 1 && idx <= entry->choice_count)
                return strdup(entry->choices[idx - 1]);
        }
        /* exact casefold match */
        for (int i = 0; i < entry->choice_count; i++) {
            char a[256], b[256];
            size_t ia = 0, ib = 0;
            for (const char *p = text; *p; p++) a[ia++] = (char)tolower((unsigned char)*p); a[ia] = '\0';
            for (const char *p = entry->choices[i]; *p; p++) b[ib++] = (char)tolower((unsigned char)*p); b[ib] = '\0';
            /* strip trailing space on both */
            while (ia > 0 && isspace((unsigned char)a[ia - 1])) a[--ia] = '\0';
            while (ib > 0 && isspace((unsigned char)b[ib - 1])) b[--ib] = '\0';
            if (strcmp(a, b) == 0) return strdup(entry->choices[i]);
        }
    }
    return strdup(text);

clarify_entry_t *entry = cli_tools_clarify_gateway_get_pending_for_session(session_key);
    if (!entry) return 0;
    char *coerced = cli_tools_clarify_gateway__coerce_text_response(entry, response);
    int ok = cli_tools_clarify_gateway_resolve_gateway_clarify(entry->clarify_id, coerced);
    free(coerced);
    return ok;

if (!text || !*text) return NULL;
    if (!entry || entry->choice_count <= 0) return NULL;

    const char *choices[16];
    int nchoices = 0;
    for (int i = 0; i < entry->choice_count && i < 16; i++) choices[nchoices++] = entry->choices[i];

    /* Split on commas first; if no commas and every whitespace-separated
     * token is numeric, treat spaces as separators too ("1 3"). */
    char *tokens[64];
    int ntokens = 0;
    if (strchr(text, ',')) {
        char *copy = strdup(text);
        char *save = NULL;
        for (char *t = strtok_r(copy, ",", &save); t && ntokens < 64; t = strtok_r(NULL, ",", &save)) {
            while (*t == ' ' || *t == '\t') t++;
            size_t l = strlen(t);
            while (l > 0 && (t[l-1]==' '||t[l-1]=='\t')) t[--l] = '\0';
            if (*t) tokens[ntokens++] = strdup(t);
        }
        free(copy);
    } else {
        char *copy = strdup(text);
        char *parts[64];
        int nparts = 0;
        char *save = NULL;
        for (char *t = strtok_r(copy, " \t", &save); t && nparts < 64; t = strtok_r(NULL, " \t", &save)) {
            parts[nparts++] = t;
        }
        int all_numeric = 1;
        for (int i = 0; i < nparts; i++) {
            for (const char *p = parts[i]; *p; p++) {
                if (!isdigit((unsigned char)*p)) { all_numeric = 0; break; }
            }
            if (!all_numeric) break;
        }
        if (nparts > 1 && all_numeric) {
            for (int i = 0; i < nparts; i++) tokens[ntokens++] = strdup(parts[i]);
        } else {
            tokens[ntokens++] = strdup(text);  /* single token */
        }
        free(copy);
    }

    /* Resolve tokens against choices. */
    char *selected[16];
    int nselected = 0;
    int ok = 1;
    for (int i = 0; i < ntokens && ok; i++) {
        const char *token = tokens[i];
        int is_digit = 1;
        for (const char *p = token; *p; p++) if (!isdigit((unsigned char)*p)) { is_digit = 0; break; }
        if (is_digit) {
            long idx = strtol(token, NULL, 10) - 1;
            if (idx < 0 || idx >= nchoices) { ok = 0; break; }
            /* canonical label from choices[idx], stripped */
            const char *label = choices[idx];
            while (*label == ' ' || *label == '\t') label++;
            size_t ll = strlen(label);
            while (ll > 0 && (label[ll-1]==' '||label[ll-1]=='\t')) ll--;
            /* dedupe */
            int dup = 0;
            for (int s = 0; s < nselected; s++) {
                if (strlen(selected[s]) == ll && strncmp(selected[s], label, ll) == 0) { dup = 1; break; }
            }
            if (!dup) {
                selected[nselected] = malloc(ll + 1);
                if (selected[nselected]) { memcpy(selected[nselected], label, ll); selected[nselected][ll] = '\0'; nselected++; }
            }
            continue;
        }
        /* Exact label match (case-insensitive) */
        int matched = 0;
        for (int c = 0; c < nchoices && !matched; c++) {
            const char *choice = choices[c];
            while (*choice == ' ' || *choice == '\t') choice++;
            size_t cl = strlen(choice);
            while (cl > 0 && (choice[cl-1]==' '||choice[cl-1]=='\t')) cl--;
            if (strlen(token) == cl) {
                int same = 1;
                for (size_t k = 0; k < cl; k++) {
                    if (tolower((unsigned char)token[k]) != tolower((unsigned char)choice[k])) { same = 0; break; }
                }
                if (same) {
                    /* dedupe */
                    int dup = 0;
                    for (int s = 0; s < nselected; s++) {
                        if (strcmp(selected[s], choice) == 0) { dup = 1; break; }
                    }
                    /* strip trailing for dedupe compare */
                    if (!dup) {
                        char canon[256];
                        size_t ccl = cl < sizeof(canon) - 1 ? cl : sizeof(canon) - 1;
                        memcpy(canon, choice, ccl); canon[ccl] = '\0';
                        for (int s = 0; s < nselected; s++) {
                            if (strcmp(selected[s], canon) == 0) { dup = 1; break; }
                        }
                        if (!dup) { selected[nselected] = strdup(canon); nselected++; }
                    }
                    matched = 1;
                }
            }
        }
        if (!matched) { ok = 0; break; }
    }

    for (int i = 0; i < ntokens; i++) free(tokens[i]);

    if (!ok) {
        for (int s = 0; s < nselected; s++) free(selected[s]);
        return NULL;
    }

    /* Build JSON array. */
    size_t total = 2;
    for (int s = 0; s < nselected; s++) {
        total += strlen(selected[s]) + 3;  /* quote + comma + quotes */
    }
    char *out = malloc(total + 1);
    if (!out) {
        for (int s = 0; s < nselected; s++) free(selected[s]);
        return NULL;
    }
    char *w = out;
    *w++ = '[';
    for (int s = 0; s < nselected; s++) {
        if (s > 0) *w++ = ',';
        *w++ = '"';
        for (const char *p = selected[s]; *p; p++) {
            if (*p == '"' || *p == '\\') *w++ = '\\';
            *w++ = *p;
        }
        *w++ = '"';
    }
    *w++ = ']';
    *w = '\0';
    for (int s = 0; s < nselected; s++) free(selected[s]);
    return out;

if (!question || !*question) {
        return strdup("{\"error\":\"Question text is required.\"}");
    }

    /* Validate and trim choices */
    if (choices && choice_count > MAX_CHOICES) {
        return strdup("{\"error\":\"Too many choices (max 4).\"}");
    }

    /* Build JSON response with question and choices */
    size_t buf_size = 4096;
    char *json = (char *)malloc(buf_size);
    if (!json) return NULL;

    int pos = 0;
    pos += snprintf(json + pos, buf_size - pos,
        "{\"question\":\"%s\"", question);

    if (choices && choice_count > 0) {
        pos += snprintf(json + pos, buf_size - pos, ",\"choices\":[");
        for (int i = 0; i < choice_count; i++) {
            if (i > 0) pos += snprintf(json + pos, buf_size - pos, ",");
            pos += snprintf(json + pos, buf_size - pos, "\"%s\"",
                choices[i] ? choices[i] : "");
        }
        pos += snprintf(json + pos, buf_size - pos, "]");
    }

    pos += snprintf(json + pos, buf_size - pos, "}");

    return json;

if (!x || !y) {
        return -1;
    }
    /* CLI port: screen interaction requires platform-specific code. */
    *x = 0;
    *y = 0;
    return 0;

if (!provider || !model) return -1;

    /* Look for image_routing.supports_vision.<provider>.<model> in config */
    char lookup_key[512];
    snprintf(lookup_key, sizeof(lookup_key),
        "image_routing.supports_vision.%s.%s", provider, model);

    for (int i = 0; i < cfg_count; i++) {
        if (cfg_keys[i] && strcmp(cfg_keys[i], lookup_key) == 0) {
            if (cfg_values[i]) {
                if (strcmp(cfg_values[i], "true") == 0 || strcmp(cfg_values[i], "1") == 0) {
                    return 1;
                }
                return 0;
            }
        }
    }

    return -1; /* not configured */

if (!provider || !*provider) return -1;

    /* Known providers that accept multimodal tool results */
    /* In a full implementation, this would query tools.vision_tools */
    /* For now, use a simplified lookup based on known provider capabilities */

    /* Anthropic models accept multimodal tool results */
    if (strcmp(provider, "anthropic") == 0) {
        return 1;
    }

    /* OpenAI GPT-4o and later accept multimodal */
    if (strcmp(provider, "openai") == 0 || strcmp(provider, "openai-codex") == 0) {
        if (model && (strstr(model, "gpt-4o") || strstr(model, "gpt-4.1") ||
                       strstr(model, "o1") || strstr(model, "o3") || strstr(model, "o4"))) {
            return 1;
        }
        return 0;
    }

    /* Google Gemini accepts multimodal */
    if (strcmp(provider, "google") == 0 || strcmp(provider, "gemini") == 0) {
        return 1;
    }

    return -1; /* unknown — caller should fall back to aux routing */

if (!provider || !model) return 0;

    /* 1. Check user-declared supports_vision override */
    int declared = cli_tools_computer_use_vision_routing__lookup_user_declared_supports_vision(
        provider, model, cfg_keys, cfg_values, cfg_count);
    if (declared == 1) return 0;  /* main model handles vision natively */
    if (declared == 0) return 1;  /* explicitly disabled, use aux */

    /* 2. Check if provider accepts multimodal tool results */
    int accepts_multimodal = cli_tools_computer_use_vision_routing__provider_accepts_multimodal_tool_result(
        provider, model);
    if (accepts_multimodal == 1) return 0;  /* main model handles it */

    /* 3. Default: route to aux vision */
    return 1;

if (!label) return strdup("");
    char *text = strdup(label);
    if (!text) return strdup("");
    /* strip leading/trailing whitespace */
    char *s = text;
    while (*s == ' ' || *s == '\t') s++;
    size_t L = strlen(s);
    while (L > 0 && (s[L - 1] == ' ' || s[L - 1] == '\t')) { s[--L] = '\0'; }

    /* split on first whitespace run */
    char *sp = s;
    while (*sp && !(*sp == ' ' || *sp == '\t')) sp++;
    int has_two = 0;
    if (*sp) {
        /* skip the whitespace run */
        char *r = sp;
        while (*r == ' ' || *r == '\t') r++;
        has_two = (*r != '\0');
    }
    char *out;
    if (has_two) {
        /* first token must be non-alphanumeric (an icon) to strip it */
        int first_is_alnum = 0;
        for (char *p = s; p < sp; p++) {
            if (isalnum((unsigned char)*p)) { first_is_alnum = 1; break; }
        }
        if (!first_is_alnum) {
            /* skip whitespace after the icon token */
            char *r = sp;
            while (*r == ' ' || *r == '\t') r++;
            out = strdup(r);
        } else {
            out = strdup(s);
        }
    } else {
        out = strdup(s);
    }
    free(text);
    return out ? out : strdup("");

if (!ts_key || !platform) return true; /* absent entry => allowed everywhere */
    for (size_t i = 0; PLAT_RESTRICTIONS[i].ts_key; i++) {
        if (strcmp(PLAT_RESTRICTIONS[i].ts_key, ts_key) == 0) {
            /* restricted: only allowed on its listed platform */
            return strcmp(PLAT_RESTRICTIONS[i].platform, platform) == 0;
        }
    }
    return true;

if (value == NULL) return default_val;
    /* Python distinguishes int vs str, but at the C boundary everything is a
     * string. The str branch already covers "1"/"0" (the only integer literals
     * that have a defined meaning); any other all-digit string is
     * unrecognized and falls through to default, matching Python. */
    char buf[32];
    size_t j = 0;
    for (const char *q = value; *q && j + 1 < sizeof(buf); q++) {
        char c = *q;
        if (c == ' ' || c == '\t') continue;
        buf[j++] = (char)tolower((unsigned char)c);
    }
    buf[j] = '\0';
    if (strcmp(buf, "true") == 0 || strcmp(buf, "1") == 0 ||
        strcmp(buf, "yes") == 0 || strcmp(buf, "on") == 0) return true;
    if (strcmp(buf, "false") == 0 || strcmp(buf, "0") == 0 ||
        strcmp(buf, "no") == 0 || strcmp(buf, "off") == 0) return false;
    return default_val;

const char *m = model_id ? model_id : "";
    const char *sp = speed ? speed : "";
    const char *st = strengths ? strengths : "";
    const char *pr = price ? price : "";
    /* layout: "{model:<Wm}  {speed:<Ws}  {strengths:<Wst}  {price}" */
    int need = width_model + 2 + width_speed + 2 + width_strengths + 2 + (int)strlen(pr) + 1;
    char *out = malloc((size_t)need > 0 ? (size_t)need : 1);
    if (!out) return strdup("");
    snprintf(out, (size_t)need, "%-*s  %-*s  %-*s  %s",
             width_model, m, width_speed, sp, width_strengths, st, pr);
    return out;

const char *token = secret_scope_get_secret("HASS_TOKEN", NULL);
    if (!token) token = getenv("HASS_TOKEN");
