if (!value) return strdup("''");
    size_t n = strlen(value);
    char *out = malloc(n * 2 + 3);  /* worst case: every ' doubled, +2 quotes */
    if (!out) return NULL;
    out[0] = '\'';
    size_t j = 1;
    for (size_t i = 0; i < n; i++) {
        if (value[i] == '\'') { out[j++] = '\''; out[j++] = '\''; }
