    /* Simple JSON extraction: look for "access_token": "..." */
    const char *key = "\"access_token\"";
    const char *p = strstr(auth_json, key);
    if (p) {
        p += strlen(key);
        while (*p == ' ' || *p == ':') p++;
        if (*p == '"') {
            p++;
            size_t j = 0;
            while (*p && *p != '"' && j < bufsize - 1) {
                buf[j++] = *p++;
