if (!buf || bufsize == 0) return -1;
    int rc = cli_tools_managed_tool_gateway_peek_nous_access_token(buf, bufsize);
    hermes_log(LOG_DEBUG, "managed_tg", "read_nous_access_token: rc=%d", rc);
