const char *scheme = getenv("TOOL_GATEWAY_SCHEME");
    if (scheme && *scheme) {
        if (strcmp(scheme, "http") == 0 || strcmp(scheme, "https") == 0) {
            hermes_log(LOG_DEBUG, "managed_tg", "get_tool_gateway_scheme: %s", scheme);
