    /* Build from shared config */
    const char *scheme = cli_tools_managed_tool_gateway_get_tool_gateway_scheme();
    const char *domain = getenv("TOOL_GATEWAY_DOMAIN");
    if (!domain || !*domain) domain = "nousresearch.com";
    snprintf(buf, bufsize, "%s://%s-gateway.%s", scheme, vendor, domain);
    hermes_log(LOG_DEBUG, "managed_tg", "build_vendor_gateway_url: %s", buf);
    return 0;

if (!vendor || !gateway_buf || !token_buf) {
        hermes_log(LOG_WARNING, "managed_tg", "resolve_managed_tool_gateway: invalid args");
        return -1;
    }
    int rc = cli_tools_managed_tool_gateway_build_vendor_gateway_url(vendor, gateway_buf, gw_size);
    if (rc != 0) return rc;
    rc = cli_tools_managed_tool_gateway_read_nous_access_token(token_buf, tok_size);
    if (rc != 0) return rc;
    hermes_log(LOG_DEBUG, "managed_tg", "resolve_managed_tool_gateway: vendor=%s gw=%s", vendor, gateway_buf);
    return 0;

if (!vendor) return 0;
    char gateway[2048] = {0};
    char token[4096] = {0};
    int rc = cli_tools_managed_tool_gateway_resolve_managed_tool_gateway(vendor, gateway, sizeof(gateway), token, sizeof(token));
    int ready = (rc == 0 && gateway[0] && token[0]);
    hermes_log(LOG_DEBUG, "managed_tg", "is_managed_tool_gateway_ready: vendor=%s ready=%d", vendor, ready);
    return ready;

/* Python: surface error.message from the gateway's 4xx body verbatim
     * (rate-limit waits, size caps), else a generic status-code message. */
    if (response_body && response_body[0]) {
        char *err_msg = NULL;
        json_t *payload = json_parse(response_body, NULL);
        if (payload) {
            json_t *err = json_obj_get(payload, "error");
            const char *msg = err ? json_get_str(err, "message", "") : "";
            if (msg && msg[0]) {
                /* Python: message.strip() */
                const char *s = msg;
                while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
                size_t len = strlen(s);
                while (len > 0 && (s[len-1] == ' ' || s[len-1] == '\t' ||
                                    s[len-1] == '\n' || s[len-1] == '\r')) len--;
                if (len > 0) {
                    err_msg = strndup(s, len);
                }
            }
            json_free(payload);
        }
        if (err_msg) return err_msg;
    }
    char *out = NULL;
    asprintf(&out, "the gateway refused the upload (HTTP %ld)", http_status);
    return out;

if (reason_out && reason_size > 0) reason_out[0] = '\0';
    if (!server_url || !upload_path || !data || !mime) return -2;

    /* Python: is_managed_nous_gateway_url gate + upload_path must start with /. */
    if (!is_managed_nous_gateway_url(NULL, server_url)) return -2;
    if (upload_path[0] != '/') return -2;

    /* origin = scheme://netloc */
    char origin[2048];
    origin[0] = '\0';
    const char *scheme_end = strstr(server_url, "://");
    if (!scheme_end) return -2;
    const char *host_start = scheme_end + 3;
    const char *path_start = strchr(host_start, '/');
    size_t host_len = path_start ? (size_t)(path_start - host_start) : strlen(host_start);
    snprintf(origin, sizeof(origin), "%.*s://%.*s",
             (int)(scheme_end - server_url), server_url,
             (int)host_len, host_start);

    char presign_url[4096];
    snprintf(presign_url, sizeof(presign_url), "%s%s", origin, upload_path);

    /* Auth headers (managed_gateway_auth_headers). */
    char auth_buf[4096];
    const char *hermes_home = slermes_home();
    if (managed_gateway_auth_headers(hermes_home, server_url,
                                     auth_buf, sizeof(auth_buf)) != 0 || !auth_buf[0]) {
        if (reason_out) snprintf(reason_out, reason_size,
                                 "no Nous credential is available for the upload");
        return -1;
    }

    /* 1. Presign POST. */
    char headers[8192];
    snprintf(headers, sizeof(headers), "Authorization: %s\r\nContent-Type: application/json",
             auth_buf);
    char body[1024];
    snprintf(body, sizeof(body),
             "{\"contentType\":\"%s\",\"contentLength\":%zu}", mime, data_len);

    http_t *h = http_new(30);
    if (!h) {
        if (reason_out) snprintf(reason_out, reason_size,
                                 "the gateway refused the upload (transport)");
        return -1;
    }
    http_resp_t *presign = http_post_json_auth(h, presign_url, body, headers);
    if (!presign) {
        if (reason_out) snprintf(reason_out, reason_size,
                                 "the gateway refused the upload (transport)");
        http_free(h);
        return -1;
    }
    if (presign->status != 200) {
        char *desc = cli_tools_managed_tool_gateway__describe_media_upload_refusal(
            presign->body, presign->status);
        if (reason_out) snprintf(reason_out, reason_size, "%s", desc);
        free(desc);
        http_resp_free(presign);
        http_free(h);
        return -1;
    }

    /* 2. Parse uploadUrl + token. */
    json_t *payload = json_parse(presign->body, NULL);
    http_resp_free(presign);
    http_free(h);
    if (!payload) {
        if (reason_out) snprintf(reason_out, reason_size,
                                 "the gateway's upload response was malformed");
        return -1;
    }
    const char *upload_url = json_get_str(payload, "uploadUrl", "");
    const char *token = json_get_str(payload, "token", "");
    if (!upload_url[0] || !token[0]) {
        json_free(payload);
        if (reason_out) snprintf(reason_out, reason_size,
                                 "the gateway's upload response was malformed");
        return -1;
    }

    /* 3. PUT bytes to the presigned URL (direct to storage). */
    char put_headers[512];
    snprintf(put_headers, sizeof(put_headers), "Content-Type: %s", mime);
    http_t *hp = http_new(60);
    if (!hp) {
        json_free(payload);
        if (reason_out) snprintf(reason_out, reason_size,
                                 "storage refused the upload (transport)");
        return -1;
    }
    http_resp_t *put = http_request(hp, HTTP_PUT, upload_url, put_headers,
                                    (const char *)data, data_len);
    if (!put || put->status != 200) {
        long code = put ? put->status : 0;
        if (put) http_resp_free(put);
        http_free(hp);
        json_free(payload);
        if (reason_out) snprintf(reason_out, reason_size,
                                 "storage refused the upload (HTTP %ld)", code);
        return -1;
    }
    http_resp_free(put);
    http_free(hp);
    json_free(payload);

    /* 4. Return "nous-upload:<token>". */
    snprintf(token_out, token_size, "nous-upload:%s", token);
    return 0;

/* Exercise the real storage constructor; if it returns NULL the SDK
     * OAuth support is effectively unavailable for this server. */
    mcp_oauth_storage_t *probe = mcp_oauth_storage_new("__probe__");
    if (!probe) {
        hermes_log(LOG_DEBUG, "mcp_oauth",
                   "make_hermes_provider_class: SDK storage unavailable");
        return 0;
    }
    mcp_oauth_storage_free(probe);
    return 1;

if (!server_name || !server_url || !provider_out) return -1;
    *provider_out = NULL;

    mcp_oauth_manager_t *mgr = cli_tools_mcp_oauth_manager_get_manager();
    if (!mgr) return -1;

    pthread_mutex_lock(&mgr->entries_lock);
    mcp_oauth_entry_t *entry = NULL;
    for (int i = 0; i < MCP_OAUTH_MAX_SERVERS; i++) {
        if (mgr->entries[i].active &&
            strcmp(mgr->entries[i].server_name, server_name) == 0) {
            entry = &mgr->entries[i];
            break;
        }
    }

    if (entry && strcmp(entry->server_url, server_url) != 0) {
        hermes_log(LOG_INFO, "mcp_oauth",
                   "get_or_build_provider '%s': URL changed %s -> %s, discarding cache",
                   server_name, entry->server_url, server_url);
        if (entry->provider) {
            mcp_oauth_storage_free(entry->provider->storage);
            free(entry->provider);
            entry->provider = NULL;
        }
        entry->active = 0;
        entry = NULL;
    }

    if (!entry) {
        for (int i = 0; i < MCP_OAUTH_MAX_SERVERS; i++) {
            if (!mgr->entries[i].active) {
                entry = &mgr->entries[i];
                memset(entry, 0, sizeof(*entry));
                pthread_mutex_init(&entry->lock, NULL);
                snprintf(entry->server_name, sizeof(entry->server_name), "%s", server_name);
                entry->active = 1;
                mgr->entries[i] = *entry;  /* keep slot; re-grab ptr below */
                entry = &mgr->entries[i];
                break;
            }
        }
    }
    if (!entry) {
        pthread_mutex_unlock(&mgr->entries_lock);
        hermes_log(LOG_WARNING, "mcp_oauth", "get_or_build_provider: server table full");
        return -1;
    }

    snprintf(entry->server_url, sizeof(entry->server_url), "%s", server_url);
    if (oauth_config)
        snprintf(entry->oauth_config, sizeof(entry->oauth_config), "%s", oauth_config);

    if (entry->provider == NULL) {
        void *p = NULL;
        cli_tools_mcp_oauth_manager__build_provider(server_name, server_url,
                                                     oauth_config, &p);
        entry->provider = (mcp_oauth_provider_t *)p;
    }

    *provider_out = entry->provider;
    pthread_mutex_unlock(&mgr->entries_lock);
    return (*provider_out != NULL) ? 0 : -1;

if (!server_name || !server_url || !provider_out) return -1;
    *provider_out = NULL;

    if (cli_tools_mcp_oauth_manager__make_hermes_provider_class() == 0)
        return -1;

    /* Parse preregistered (client_id in config) + callback port + timeout. */
    int preregistered = 0;
    int callback_port = 0;
    if (oauth_config) {
        if (strstr(oauth_config, "\"client_id\"")) preregistered = 1;
        const char *p = strstr(oauth_config, "\"callback_port\"");
        if (p) callback_port = atoi(p + strlen("\"callback_port\""));
    }

    mcp_oauth_storage_t *storage = mcp_oauth_storage_new(server_name);
    if (!storage) return -1;

    /* Non-interactive + no cached tokens => cannot proceed (mirrors
     * OAuthNonInteractiveError in the Python build path). */
    if (!isatty(STDIN_FILENO) && !mcp_oauth_storage_has_tokens(storage)) {
        mcp_oauth_storage_free(storage);
        hermes_log(LOG_WARNING, "mcp_oauth",
                   "build_provider '%s': non-interactive and no cached tokens",
                   server_name);
        return -1;
    }

    mcp_oauth_provider_t *prov = calloc(1, sizeof(*prov));
    if (!prov) { mcp_oauth_storage_free(storage); return -1; }
    snprintf(prov->server_name, sizeof(prov->server_name), "%s", server_name);
    snprintf(prov->server_url, sizeof(prov->server_url), "%s", server_url);
    if (oauth_config)
        snprintf(prov->oauth_config, sizeof(prov->oauth_config), "%s", oauth_config);
    prov->preregistered = preregistered;
    prov->callback_port = callback_port ? callback_port : mcp_oauth_find_free_port();
    prov->can_refresh = mcp_oauth_storage_has_tokens(storage) ? 1 : 0;
    prov->storage = storage;

    *provider_out = prov;
    hermes_log(LOG_INFO, "mcp_oauth", "Built provider for %s (preregistered=%d)",
               server_name, preregistered);
    return 0;

if (!server_name) return 0;

    mcp_oauth_manager_t *mgr = cli_tools_mcp_oauth_manager_get_manager();
    if (!mgr) return 0;

    mcp_oauth_entry_t *entry = NULL;
    pthread_mutex_lock(&mgr->entries_lock);
    for (int i = 0; i < MCP_OAUTH_MAX_SERVERS; i++) {
        if (mgr->entries[i].active &&
            strcmp(mgr->entries[i].server_name, server_name) == 0) {
            entry = &mgr->entries[i];
            break;
        }
    }
    if (!entry || entry->provider == NULL) {
        pthread_mutex_unlock(&mgr->entries_lock);
        return 0;
    }

    char token_path[PATH_MAX];
    if (token_dir && *token_dir) {
        char safe[256];
        size_t j = 0;
        for (size_t i = 0; server_name[i] && j + 1 < sizeof(safe); i++) {
            char c = server_name[i];
            safe[j++] = (c >= 'A' && c <= 'Z') ? (char)(c + 32) : c;
        }
        safe[j] = '\0';
        snprintf(token_path, sizeof(token_path), "%s/%s.json", token_dir, safe);
    } else {
        mcp_om_token_path(server_name, token_path, sizeof(token_path));
    }

    struct stat st;
    if (stat(token_path, &st) != 0) {
        pthread_mutex_unlock(&mgr->entries_lock);
        return 0;
    }

    long long mtime_ns = (long long)st.st_mtime * 1000000000LL + st.st_mtim.tv_nsec;
    pthread_mutex_lock(&entry->lock);
    int changed = (mtime_ns != entry->last_mtime_ns);
    if (changed) {
        long long old = entry->last_mtime_ns;
        entry->last_mtime_ns = mtime_ns;
        hermes_log(LOG_INFO, "mcp_oauth",
                   "invalidate_if_disk_changed '%s': mtime %lld -> %lld, forcing reload",
                   server_name, (long long)old, (long long)mtime_ns);
    }
    pthread_mutex_unlock(&entry->lock);
    pthread_mutex_unlock(&mgr->entries_lock);
    return changed;

if (!server_name || !access_token || !refreshed_out) return -1;
    *refreshed_out = 0;

    mcp_oauth_manager_t *mgr = cli_tools_mcp_oauth_manager_get_manager();
    if (!mgr) return -1;

    mcp_oauth_entry_t *entry = NULL;
    pthread_mutex_lock(&mgr->entries_lock);
    for (int i = 0; i < MCP_OAUTH_MAX_SERVERS; i++) {
        if (mgr->entries[i].active &&
            strcmp(mgr->entries[i].server_name, server_name) == 0) {
            entry = &mgr->entries[i];
            break;
        }
    }
    if (!entry || entry->provider == NULL) {
        pthread_mutex_unlock(&mgr->entries_lock);
        return 0;
    }

    pthread_mutex_lock(&entry->lock);
    pthread_mutex_unlock(&mgr->entries_lock);

    /* Step 1: did the disk change? Picks up an external refresh. */
    int disk_changed = cli_tools_mcp_oauth_manager_invalidate_if_disk_changed(
        server_name, NULL);
    if (disk_changed) {
        *refreshed_out = 1;
        pthread_mutex_unlock(&entry->lock);
        return 0;
    }

    /* Step 2: no disk change — can the provider refresh in place?
     * In C the SDK refresh capability is tracked on the provider record. */
    int can_refresh = entry->provider->can_refresh;
    *refreshed_out = can_refresh ? 1 : 0;
    pthread_mutex_unlock(&entry->lock);
    if (can_refresh) {
        hermes_log(LOG_INFO, "mcp_oauth",
                   "handle_401 '%s': provider can refresh in place", server_name);
    } else {
        hermes_log(LOG_WARNING, "mcp_oauth",
                   "handle_401 '%s': no recovery path — needs interactive reauth",
                   server_name);
    }
    return 0;

static mcp_oauth_manager_t *singleton = NULL;
    static pthread_mutex_t init_lock = PTHREAD_MUTEX_INITIALIZER;
    static int inited = 0;
    pthread_mutex_lock(&init_lock);
    if (!inited) {
        singleton = calloc(1, sizeof(*singleton));
        if (singleton) {
            pthread_mutex_init(&singleton->entries_lock, NULL);
            for (int i = 0; i < MCP_OAUTH_MAX_SERVERS; i++)
                pthread_mutex_init(&singleton->entries[i].lock, NULL);
            inited = 1;
            hermes_log(LOG_DEBUG, "mcp_oauth", "Created singleton manager");
        }
    }
    pthread_mutex_unlock(&init_lock);
    return singleton;

mcp_oauth_manager_t *mgr = cli_tools_mcp_oauth_manager_get_manager();
    if (!mgr) return;
    pthread_mutex_lock(&mgr->entries_lock);
