            for (size_t k = 0; k < klen; k++) {
                char c = key[k];
                if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
                      (c >= '0' && c <= '9') || c == '_' || c == '.' || c == '-')) {
                    conforms = false; break;
                }
            }
        }
        if (conforms) {
            taken = realloc(taken, (taken_n + 1) * sizeof(char *));
            taken[taken_n++] = strdup(key);
        } else {
            char *base = cli_tools_schema_sanitizer_sanitize_property_key(key);
            if (base && *base) {
                char candidate[128];
                snprintf(candidate, sizeof(candidate), "%s", base);
                int suffix = 2;
                bool collides;
                do {
                    collides = false;
                    for (size_t t = 0; t < taken_n; t++) {
                        if (strcmp(taken[t], candidate) == 0) {
                            collides = true; break;
                        }
                    }
                    if (collides) {
                        char suf[16];
                        int suflen = snprintf(suf, sizeof(suf), "_%d", suffix);
                        size_t blen = strlen(base);
                        size_t keep = (blen > 64 - (size_t)suflen) ? 64 - (size_t)suflen : blen;
                        if (keep == 0) keep = 1;
                        snprintf(candidate, sizeof(candidate), "%.*s%s", (int)keep, base, suf);
                        suffix++;
                    }
                } while (collides);
                json_set(out, key, json_string(candidate));
                taken = realloc(taken, (taken_n + 1) * sizeof(char *));
                taken[taken_n++] = strdup(candidate);
            }
            free(base);
        }
    }

    for (size_t i = 0; i < taken_n; i++) free(taken[i]);
    free(taken);
    json_free(props);

    char *s = json_serialize(out);
    json_free(out);
    return s ? s : strdup("{}");

/* Python: reverse-map sanitized keys back to original wire names.
     * params_schema is the ORIGINAL (unsanitized) schema. Recurses into
     * object-typed values and array items. */
    if (!params_schema_json || !*params_schema_json ||
        !args_json || !*args_json) {
        return args_json ? strdup(args_json) : NULL;
    }

    json_t *schema = json_parse(params_schema_json, NULL);
    json_t *args = json_parse(args_json, NULL);
    if (!schema || schema->type != JSON_OBJECT ||
        !args || args->type != JSON_OBJECT) {
        if (schema) json_free(schema);
        if (args) json_free(args);
        return args_json ? strdup(args_json) : NULL;
    }

    json_t *props = json_obj_get(schema, "properties");
    if (!props || props->type != JSON_OBJECT) {
        json_free(schema); json_free(args);
        return args_json ? strdup(args_json) : NULL;
    }

    /* reverse = {v: k for k, v in _rename_property_keys(props, "<unrename>")} */
    char *renames_json = cli_tools_schema_sanitizer__rename_property_keys(
        json_serialize(props), "<unrename>");
    json_t *renames = json_parse(renames_json, NULL);
    free(renames_json);
    json_t *reverse = json_object();
    if (renames && renames->type == JSON_OBJECT) {
        for (size_t i = 0; i < renames->c.count; i++) {
            const char *orig = renames->c.keys[i];
            json_t *conf = renames->c.items[i];
            if (orig && conf && conf->type == JSON_STRING) {
                json_set(reverse, conf->str_val, json_string(orig));
            }
        }
    }
    if (renames) json_free(renames);
    json_free(schema);

    json_t *out = json_object();
    for (size_t i = 0; i < args->c.count; i++) {
        const char *key = args->c.keys[i];
        json_t *value = args->c.items[i];
        const char *orig_key = key;
        json_t *rev = json_obj_get(reverse, key);
        if (rev && rev->type == JSON_STRING)
            orig_key = rev->str_val;

        json_t *orig_schema = json_obj_get(props, orig_key);
        if (value && orig_schema && orig_schema->type == JSON_OBJECT) {
            if (value->type == JSON_OBJECT) {
                char *sub_args = json_serialize(value);
                char *sub_schema = json_serialize(orig_schema);
                char *mapped = cli_tools_schema_sanitizer_unrename_tool_args(sub_schema, sub_args);
                free(sub_args); free(sub_schema);
                if (mapped) {
                    json_t *parsed = json_parse(mapped, NULL);
                    if (parsed) json_set(out, orig_key, parsed);
                    else json_set(out, orig_key, json_copy(value));
                    free(mapped);
                } else {
                    json_set(out, orig_key, json_copy(value));
                }
            } else if (value->type == JSON_ARRAY) {
                json_t *item_schema = json_obj_get(orig_schema, "items");
                if (item_schema && item_schema->type == JSON_OBJECT) {
                    char *sub_schema = json_serialize(item_schema);
                    json_t *new_arr = json_array();
                    for (size_t j = 0; j < json_len(value); j++) {
                        json_t *item = json_get(value, j);
                        char *item_args = json_serialize(item);
                        char *mapped = cli_tools_schema_sanitizer_unrename_tool_args(sub_schema, item_args);
                        free(item_args);
                        if (mapped) {
                            json_t *parsed = json_parse(mapped, NULL);
                            if (parsed) json_append(new_arr, parsed);
                            else json_append(new_arr, json_copy(item));
                            free(mapped);
                        } else {
                            json_append(new_arr, json_copy(item));
                        }
                    }
                    free(sub_schema);
                    json_set(out, orig_key, new_arr);
                } else {
                    json_set(out, orig_key, json_copy(value));
                }
            } else {
                json_set(out, orig_key, json_copy(value));
            }
        } else {
            json_set(out, orig_key, json_copy(value));
        }
    }

    json_free(args);
    json_free(reverse);
    char *result = json_serialize(out);
    json_free(out);
    return result ? result : strdup(args_json);

out[0] = '\0';
    if (!raw) return;
    size_t plen = sizeof(SST_CONTENT_JSON_PREFIX) - 1; /* excludes NUL */
    if (strncmp(raw, SST_CONTENT_JSON_PREFIX, plen) == 0) {
        const char *js = raw + plen;
        /* It is JSON-encoded scalar/list content; surface the raw JSON
         * text (decode would require a JSON parser round-trip and the
         * value is already valid JSON). Keep the JSON payload verbatim. */
        snprintf(out, outsz, "%s", js);
        return;
    }
    snprintf(out, outsz, "%s", raw);

(void)parent_chain; (void)chain_len;
    if (!session_id || !root_out || root_size == 0) return -1;

    sqlite3 *db = sst_open_readonly(NULL);
    if (!db) {
        /* No DB available — return the input as the best-known root. */
        snprintf(root_out, root_size, "%s", session_id);
        return 0;
    }
    sst_resolve_to_parent_db(db, session_id, root_out, root_size);
    sqlite3_close(db);

    hermes_log(LOG_DEBUG, "session_search", "resolve_to_parent: %s -> %s",
               session_id, root_out);
    return 0;

if (!msg_json || !shaped_json_out || shaped_size == 0) return -1;

    json_t *root = json_parse(msg_json, NULL);
    if (!root || root->type != JSON_OBJECT) {
        if (root) json_free(root);
        snprintf(shaped_json_out, shaped_size, "%s", msg_json);
        if (is_anchor_out) *is_anchor_out = 0;
        return 0;
    }

    json_t *obj = json_object();
    double mid = json_get_num(root, "id", -1);
    json_set(obj, "id", json_number(mid));
    const char *role = json_get_str(root, "role", "");
    json_set(obj, "role", json_string(role && *role ? role : ""));
    const char *content = json_get_str(root, "content", NULL);
    json_set(obj, "content", json_string(content ? content : "")); /* keep even if empty */
    json_set(obj, "timestamp", json_number(json_get_num(root, "timestamp", 0)));
    json_t *tn = json_obj_get(root, "tool_name");
    if (tn && tn->type == JSON_STRING && tn->str_val && *tn->str_val)
        json_set(obj, "tool_name", json_string(tn->str_val));
    json_t *tc = json_obj_get(root, "tool_calls");
    if (tc && tc->type == JSON_STRING && tc->str_val && *tc->str_val)
        json_set(obj, "tool_calls", json_string(tc->str_val));
    json_t *tci = json_obj_get(root, "tool_call_id");
    if (tci && tci->type == JSON_STRING && tci->str_val && *tci->str_val)
        json_set(obj, "tool_call_id", json_string(tci->str_val));
    int is_anchor = 0;
    if (anchor_id >= 0 && (long)mid == (long)anchor_id) {
        json_set(obj, "anchor", json_bool(true));
        is_anchor = 1;
    }

    char *serialized = json_serialize(obj);
    if (serialized) {
        snprintf(shaped_json_out, shaped_size, "%s", serialized);
        free(serialized);
    } else {
        shaped_json_out[0] = '\0';
    }
    json_free(obj);
    json_free(root);
    if (is_anchor_out) *is_anchor_out = is_anchor;

    hermes_log(LOG_DEBUG, "session_search", "shape_message: %zu chars",
               strlen(shaped_json_out));
    return 0;

if (!db_path_out || !needs_free_out) return -1;

    *needs_free_out = 0;
    db_path_out[0] = '\0';

    if (!profile || !*profile) {
        if (default_db_path && *default_db_path)
            snprintf(db_path_out, path_size, "%s", default_db_path);
        return 0;
    }

    /* Build ~/.hermes/profiles/<profile>/state.db (normalize: strip path
     * separators so a malicious profile name can't escape the dir). */
    char safe[256];
    int si = 0;
    for (const char *p = profile; *p && si < (int)sizeof(safe) - 1; p++) {
        if (*p == '/' || *p == '\\' || *p == '.' ) continue;
        safe[si++] = *p;
    }
    safe[si] = '\0';

    const char *home = slermes_home();
    if (!home || !*home) home = ".";
    snprintf(db_path_out, path_size, "%s/profiles/%s/state.db", home, safe);
    hermes_log(LOG_DEBUG, "session_search", "resolve_profile_db: profile=%s path=%s",
               safe, db_path_out);
    return 0;

if (!session_id || !db_path_out || !found_out) return -1;

    *found_out = 0;
    db_path_out[0] = '\0';
    if (profile_out) profile_out[0] = '\0';

    const char *home = slermes_home();
    if (!home || !*home) home = ".";

    /* Candidate DBs: default + each profile subdir. */
    char candidates[SST_MAX_SESSIONS][1024];
    char cand_names[SST_MAX_SESSIONS][128];
    int ncand = 0;
    snprintf(candidates[ncand], sizeof(candidates[ncand]), "%s/state.db", home);
    snprintf(cand_names[ncand], sizeof(cand_names[ncand]), "default");
    ncand++;

    char prof_root[1024];
    snprintf(prof_root, sizeof(prof_root), "%s/profiles", home);
    if (!profiles_dir || !*profiles_dir) profiles_dir = prof_root;

    /* Enumerate profile directories via opendir/readdir and probe each
     * state.db directly (no shell invocation). */
    {
        DIR *d = opendir(profiles_dir);
        if (d) {
            struct dirent *ent;
            while ((ent = readdir(d)) != NULL && ncand < SST_MAX_SESSIONS) {
                if (ent->d_name[0] == '.') continue;
                char pdir[1200];
                snprintf(pdir, sizeof(pdir), "%s/%s", profiles_dir, ent->d_name);
                struct stat stt;
                if (stat(pdir, &stt) != 0 || !S_ISDIR(stt.st_mode)) continue;
                char pdb[1300];
                snprintf(pdb, sizeof(pdb), "%s/state.db", pdir);
                if (access(pdb, F_OK) != 0) continue;
                snprintf(candidates[ncand], sizeof(candidates[ncand]), "%s", pdb);
                snprintf(cand_names[ncand], sizeof(cand_names[ncand]), "%s", ent->d_name);
                ncand++;
            }
            closedir(d);
        }
    }

    for (int c = 0; c < ncand; c++) {
        sqlite3 *db = sst_open_readonly(candidates[c]);
        if (!db) continue;
        sqlite3_stmt *st = NULL;
        int hit = 0;
        if (sqlite3_prepare_v2(db, "SELECT 1 FROM sessions WHERE id = ? LIMIT 1",
                               -1, &st, NULL) == SQLITE_OK) {
            sqlite3_bind_text(st, 1, session_id, -1, SQLITE_TRANSIENT);
            if (sqlite3_step(st) == SQLITE_ROW) hit = 1;
            sqlite3_finalize(st);
        }
        sqlite3_close(db);
        if (hit) {
            snprintf(db_path_out, path_size, "%s", candidates[c]);
            if (profile_out) snprintf(profile_out, profile_size, "%s", cand_names[c]);
            *found_out = 1;
            hermes_log(LOG_DEBUG, "session_search", "locate_session: %s in %s (%s)",
                       session_id, candidates[c], cand_names[c]);
            break;
        }
    }
    return 0;

if (!session_id || !json_out || json_size == 0 || !total_messages_out) return -1;
    *total_messages_out = 0;

    if (head <= 0) head = 20;
    if (tail <= 0) tail = 10;

    sqlite3 *db = sst_open_readonly(NULL);
    if (!db) {
        snprintf(json_out, json_size,
                 "{\"success\":false,\"mode\":\"read\",\"error\":\"session DB unavailable\"}");
        return 0;
    }

    /* Session meta. */
    char source[64] = "", model[256] = "", title[1024] = "";
    double started_at = 0;
    int meta_found = 0;
    {
        sqlite3_stmt *st = NULL;
        if (sqlite3_prepare_v2(db,
                "SELECT source, model, title, started_at FROM sessions WHERE id = ?",
                -1, &st, NULL) == SQLITE_OK) {
            sqlite3_bind_text(st, 1, session_id, -1, SQLITE_TRANSIENT);
            if (sqlite3_step(st) == SQLITE_ROW) {
                meta_found = 1;
                const char *s = (const char *)sqlite3_column_text(st, 0);
                snprintf(source, sizeof(source), "%s", s ? s : "");
                const char *m = (const char *)sqlite3_column_text(st, 1);
                snprintf(model, sizeof(model), "%s", m ? m : "");
                const char *t = (const char *)sqlite3_column_text(st, 2);
                snprintf(title, sizeof(title), "%s", t ? t : "");
                started_at = sqlite3_column_double(st, 3);
            }
            sqlite3_finalize(st);
        }
    }
    if (!meta_found) {
        sqlite3_close(db);
        snprintf(json_out, json_size,
                 "{\"success\":false,\"mode\":\"read\",\"error\":\"session_id not found: %s\"}",
                 session_id);
        return 0;
    }

    /* All messages — heap-allocated to avoid a 200KB stack frame. */
    sst_msg_t *msgs = calloc((size_t)SST_MAX_MESSAGES, sizeof(sst_msg_t));
    if (!msgs) {
        sqlite3_close(db);
        snprintf(json_out, json_size,
                 "{\"success\":false,\"mode\":\"read\",\"error\":\"out of memory\"}");
        return 0;
    }
    int nmsg = 0;
    {
        sqlite3_stmt *st = NULL;
        if (sqlite3_prepare_v2(db,
                "SELECT id, role, content, tool_name, tool_calls, tool_call_id, timestamp "
                "FROM messages WHERE session_id = ? AND active = 1 ORDER BY id",
                -1, &st, NULL) == SQLITE_OK) {
            sqlite3_bind_text(st, 1, session_id, -1, SQLITE_TRANSIENT);
            while (sqlite3_step(st) == SQLITE_ROW && nmsg < SST_MAX_MESSAGES) {
                sst_msg_t *m = &msgs[nmsg++];
                m->id = (long)sqlite3_column_int64(st, 0);
                const char *role = (const char *)sqlite3_column_text(st, 1);
                snprintf(m->role, sizeof(m->role), "%s", role ? role : "");
                const char *content = (const char *)sqlite3_column_text(st, 2);
                sst_decode_content(content, m->content, sizeof(m->content));
                const char *tn = (const char *)sqlite3_column_text(st, 3);
                if (tn && *tn) { snprintf(m->tool_name, sizeof(m->tool_name), "%s", tn); m->has_tool_name = 1; }
                const char *tc = (const char *)sqlite3_column_text(st, 4);
                if (tc && *tc) { snprintf(m->tool_calls, sizeof(m->tool_calls), "%s", tc); m->has_tool_calls = 1; }
                const char *tci = (const char *)sqlite3_column_text(st, 5);
                if (tci && *tci) { snprintf(m->tool_call_id, sizeof(m->tool_call_id), "%s", tci); m->has_tool_call_id = 1; }
                m->timestamp = sqlite3_column_double(st, 6);
            }
            sqlite3_finalize(st);
        }
    }
    sqlite3_close(db);

    int total = nmsg;
    *total_messages_out = total;
    int truncated = total > head + tail;
    int wstart = 0, wcount = total;
    if (truncated) {
        /* First `head` messages, then a gap, then last `tail` messages.
         * We serialize head, then tail (Python emits head + tail with the
         * middle omitted since only head+tail are shown). */
        wcount = head + tail;
    }

    json_t *resp = json_object();
    json_set(resp, "success", json_bool(true));
    json_set(resp, "mode", json_string("read"));
    json_set(resp, "session_id", json_string(session_id));

    json_t *meta = json_object();
    json_set(meta, "when", json_string(sst_format_timestamp(started_at)));
    json_set(meta, "source", json_string(source[0] ? source : "agent"));
    json_set(meta, "model", json_string(model[0] ? model : ""));
    json_set(meta, "title", json_string(title[0] ? title : ""));
    json_set(resp, "session_meta", meta);

    json_set(resp, "message_count", json_number((double)total));
    json_set(resp, "truncated", json_bool(truncated));

    json_t *arr = json_array();
    if (truncated) {
        /* First `head` messages, then a gap marker, then last `tail` messages. */
        int tail_start = total - tail > head ? total - tail : head;
        for (int i = 0; i < head && i < total; i++)
            json_append(arr, sst_shape_message_obj(&msgs[i], -1));
        if (tail_start > head) {
            json_t *gap = json_object();
            json_set(gap, "role", json_string("system"));
            json_set(gap, "content", json_string("… (middle of session omitted) …"));
            json_set(gap, "anchor", json_bool(false));
            json_append(arr, gap);
        }
        for (int i = tail_start; i < total; i++)
            json_append(arr, sst_shape_message_obj(&msgs[i], -1));
    } else {
        for (int i = 0; i < total; i++)
            json_append(arr, sst_shape_message_obj(&msgs[i], -1));
    }
    json_set(resp, "messages", arr);

    if (truncated) {
        char msg[256];
        snprintf(msg, sizeof(msg),
                 "Session has %d messages; showing first %d + last %d. "
                 "Pass around_message_id (any id above) to scroll the middle.",
                 total, head, tail);
        json_set(resp, "message", json_string(msg));
    }

    char *serialized = json_serialize(resp);
    if (serialized) {
        snprintf(json_out, json_size, "%s", serialized);
        free(serialized);
    } else {
        json_out[0] = '\0';
    }
    json_free(resp);
    free(msgs);

    hermes_log(LOG_DEBUG, "session_search", "read_session: %s (%d msgs)", session_id, total);
    return 0;

if (!json_out || json_size == 0 || !count_out) return -1;
    *count_out = 0;
    if (limit <= 0) limit = 10;

    sqlite3 *db = sst_open_readonly(NULL);
    if (!db) {
        snprintf(json_out, json_size,
                 "{\"success\":true,\"mode\":\"browse\",\"results\":[],\"count\":0,"
                 "\"message\":\"Session DB unavailable.\"}");
        return 0;
    }

    char cur_root[256] = "";
    if (current_session_id && *current_session_id)
        sst_resolve_to_parent_db(db, current_session_id, cur_root, sizeof(cur_root));

    /* Fetch recent root sessions, excluding hidden sources and children. */
    char sql[1024];
    snprintf(sql, sizeof(sql),
        "SELECT id, title, source, started_at, message_count, "
        "  (SELECT SUBSTR(REPLACE(REPLACE(m.content, char(10), ' '), char(13), ' '), 1, 60) "
        "   FROM messages m WHERE m.session_id = s.id AND m.role = 'user' "
        "   AND m.content IS NOT NULL ORDER BY m.timestamp, m.id LIMIT 1) AS preview "
        "FROM sessions s "
        "WHERE parent_session_id IS NULL AND source NOT IN ('subagent','tool') "
        "AND archived = 0 "
        "ORDER BY started_at DESC LIMIT ?");

    json_t *results = json_array();
    int count = 0;
    {
        sqlite3_stmt *st = NULL;
        if (sqlite3_prepare_v2(db, sql, -1, &st, NULL) == SQLITE_OK) {
            sqlite3_bind_int(st, 1, limit + 5);
            while (sqlite3_step(st) == SQLITE_ROW && count < limit) {
                const char *sid = (const char *)sqlite3_column_text(st, 0);
                if (!sid) continue;
                /* Skip current lineage root. */
                if (cur_root[0] && (strcmp(sid, cur_root) == 0 ||
                                    strcmp(sid, current_session_id ? current_session_id : "") == 0))
                    continue;
                json_t *r = json_object();
                json_set(r, "session_id", json_string(sid));
                const char *t = (const char *)sqlite3_column_text(st, 1);
                json_set(r, "title", json_string(t && *t ? t : ""));
                const char *src = (const char *)sqlite3_column_text(st, 2);
                json_set(r, "source", json_string(src ? src : ""));
                json_set(r, "started_at", json_number(sqlite3_column_double(st, 3)));
                json_set(r, "message_count", json_number((double)sqlite3_column_int(st, 4)));
                const char *prev = (const char *)sqlite3_column_text(st, 5);
                json_set(r, "preview", json_string(prev ? prev : ""));
                json_append(results, r);
                count++;
            }
            sqlite3_finalize(st);
        }
    }
    sqlite3_close(db);

    *count_out = count;
    json_t *resp = json_object();
    json_set(resp, "success", json_bool(true));
    json_set(resp, "mode", json_string("browse"));
    json_set(resp, "results", results);
    json_set(resp, "count", json_number((double)count));
    char msg[256];
    snprintf(msg, sizeof(msg),
             "Showing %d most recent sessions. Pass a query= to search, or "
             "session_id+around_message_id to scroll.", count);
    json_set(resp, "message", json_string(msg));

    char *serialized = json_serialize(resp);
    if (serialized) {
        snprintf(json_out, json_size, "%s", serialized);
        free(serialized);
    } else {
        json_out[0] = '\0';
    }
    json_free(resp);

    hermes_log(LOG_DEBUG, "session_search", "list_recent: limit=%d count=%d", limit, count);
    return 0;

if (!query || !json_out || json_size == 0 || !count_out) return -1;
    *count_out = 0;
    if (limit <= 0) limit = 3;
    if (limit > 10) limit = 10;

    sqlite3 *db = sst_open_readonly(NULL);
    if (!db) {
        snprintf(json_out, json_size,
                 "{\"success\":true,\"mode\":\"discover\",\"query\":\"%s\",\"results\":[],"
                 "\"count\":0,\"sessions_searched\":0,\"message\":\"Session DB unavailable.\"}",
                 query);
        return 0;
    }

    char cur_root[256] = "";
    if (current_session_id && *current_session_id)
        sst_resolve_to_parent_db(db, current_session_id, cur_root, sizeof(cur_root));

    /* Sanitize + build the FTS5 MATCH query. */
    char sanitized[SST_MAX_QUERY_LEN * 2];
    sst_sanitize_fts5(query, sanitized, sizeof(sanitized));
    if (!sanitized[0]) {
        sqlite3_close(db);
        snprintf(json_out, json_size,
                 "{\"success\":true,\"mode\":\"discover\",\"query\":\"%s\",\"results\":[],"
                 "\"count\":0,\"sessions_searched\":0,\"message\":\"No matching sessions found.\"}",
                 query);
        return 0;
    }

    const char *roles = "user','assistant";
    if (role_count > 0 && role_filter) {
        /* Use the supplied role filter (already validated upstream). */
        static char rb[256]; rb[0] = '\0';
        for (int i = 0; i < role_count && i < 8; i++) {
            if (i) strncat(rb, "','", sizeof(rb) - strlen(rb) - 1);
            strncat(rb, role_filter[i], sizeof(rb) - strlen(rb) - 1);
        }
        roles = rb;
    }

    char order_by[64] = "ORDER BY rank";
    if (sort && strcasecmp(sort, "newest") == 0)
        snprintf(order_by, sizeof(order_by), "ORDER BY m.timestamp DESC, rank");
    else if (sort && strcasecmp(sort, "oldest") == 0)
        snprintf(order_by, sizeof(order_by), "ORDER BY m.timestamp ASC, rank");

    char sql[1024];
    snprintf(sql, sizeof(sql),
        "SELECT m.id, m.session_id, m.role, "
        "snippet(messages_fts, 0, '>>>', '<<<', '...', 40) AS snippet, "
        "m.timestamp, s.source, s.model, s.started_at AS session_started "
        "FROM messages_fts "
        "JOIN messages m ON m.id = messages_fts.rowid "
        "JOIN sessions s ON s.id = m.session_id "
        "WHERE messages_fts MATCH ? "
        "AND (m.active = 1 OR m.compacted = 1) "
        "AND s.source NOT IN ('subagent','tool') "
        "AND m.role IN ('%s') "
        "%s LIMIT ?",
        roles, order_by);

    /* Pass 1: collect raw FTS rows (BM25 order). */
    typedef struct { long id; char sid[256]; char role[32]; char snippet[512];
                     double ts; char source[64]; char model[256]; double sstart; } raw_t;
    raw_t raw[SST_DISCOVER_SCAN_LIMIT];
    int nraw = 0;
    {
        sqlite3_stmt *st = NULL;
        if (sqlite3_prepare_v2(db, sql, -1, &st, NULL) == SQLITE_OK) {
            sqlite3_bind_text(st, 1, sanitized, -1, SQLITE_TRANSIENT);
            sqlite3_bind_int(st, 2, SST_DISCOVER_SCAN_LIMIT);
            while (sqlite3_step(st) == SQLITE_ROW && nraw < SST_DISCOVER_SCAN_LIMIT) {
                raw_t *r = &raw[nraw++];
                r->id = (long)sqlite3_column_int64(st, 0);
                const char *sid = (const char *)sqlite3_column_text(st, 1);
                snprintf(r->sid, sizeof(r->sid), "%s", sid ? sid : "");
                const char *rl = (const char *)sqlite3_column_text(st, 2);
                snprintf(r->role, sizeof(r->role), "%s", rl ? rl : "");
                const char *sn = (const char *)sqlite3_column_text(st, 3);
                snprintf(r->snippet, sizeof(r->snippet), "%s", sn ? sn : "");
                r->ts = sqlite3_column_double(st, 4);
                const char *src = (const char *)sqlite3_column_text(st, 5);
                snprintf(r->source, sizeof(r->source), "%s", src ? src : "");
                const char *mdl = (const char *)sqlite3_column_text(st, 6);
                snprintf(r->model, sizeof(r->model), "%s", mdl ? mdl : "");
                r->sstart = sqlite3_column_double(st, 7);
            }
            sqlite3_finalize(st);
        }
    }

    /* Demote cron below interactive; stable — preserves BM25 order within class. */
    /* Pass 2: two queues (interactive first, then cron). */
    int order[SST_DISCOVER_SCAN_LIMIT];
    int nordered = 0;
    for (int pass = 0; pass < 2; pass++) {
        for (int i = 0; i < nraw; i++) {
            int is_cron = (strcmp(raw[i].source, "cron") == 0);
            if ((pass == 0 && !is_cron) || (pass == 1 && is_cron)) order[nordered++] = i;
        }
    }

    /* Dedupe by lineage root, skipping current lineage. */
    char seen[SST_MAX_SESSIONS][256];
    int nseen = 0;
    json_t *results = json_array();
    int sessions_searched = 0;

    for (int oi = 0; oi < nordered && nseen < limit; oi++) {
        raw_t *r = &raw[order[oi]];
        char resolved[256];
        sst_resolve_to_parent_db(db, r->sid, resolved, sizeof(resolved));
        sessions_searched++;

        if (cur_root[0] && (strcmp(resolved, cur_root) == 0 ||
                            strcmp(r->sid, current_session_id ? current_session_id : "") == 0))
            continue;

        int dup = 0;
        for (int k = 0; k < nseen; k++)
            if (strcmp(seen[k], resolved) == 0) { dup = 1; break; }
        if (dup) continue;

        if (nseen < SST_MAX_SESSIONS) snprintf(seen[nseen], sizeof(seen[0]), "%s", resolved);
        nseen++;

        /* Anchored view around the FTS match. */
        json_t *win = json_array();
        json_t *bstart = json_array();
        json_t *bend = json_array();
        int before = 0, after = 0;
        sst_anchored_view(db, r->sid, r->id, SST_WINDOW_DEFAULT, SST_BOOKEND_DEFAULT,
                          win, bstart, bend, &before, &after);

        /* Lineage root session meta. */
        char lsource[64] = "", lmodel[256] = "", ltitle[1024] = "";
        double lstart = r->sstart;
        {
            sqlite3_stmt *st = NULL;
            if (sqlite3_prepare_v2(db,
                    "SELECT source, model, title, started_at FROM sessions WHERE id = ?",
                    -1, &st, NULL) == SQLITE_OK) {
                sqlite3_bind_text(st, 1, resolved, -1, SQLITE_TRANSIENT);
                if (sqlite3_step(st) == SQLITE_ROW) {
                    const char *s = (const char *)sqlite3_column_text(st, 0);
                    snprintf(lsource, sizeof(lsource), "%s", s ? s : "");
                    const char *m = (const char *)sqlite3_column_text(st, 1);
                    snprintf(lmodel, sizeof(lmodel), "%s", m ? m : "");
                    const char *t = (const char *)sqlite3_column_text(st, 2);
                    snprintf(ltitle, sizeof(ltitle), "%s", t ? t : "");
                    lstart = sqlite3_column_double(st, 3);
                }
                sqlite3_finalize(st);
            }
        }

        json_t *entry = json_object();
        json_set(entry, "session_id", json_string(r->sid));
        json_set(entry, "when", json_string(sst_format_timestamp(lstart)));
        json_set(entry, "source", json_string(lsource[0] ? lsource : "unknown"));
        json_set(entry, "model", json_string(lmodel[0] ? lmodel : "unknown"));
        json_set(entry, "title", json_string(ltitle[0] ? ltitle : ""));
        json_set(entry, "matched_role", json_string(r->role));
        json_set(entry, "match_message_id", json_number((double)r->id));
        json_set(entry, "snippet", json_string(r->snippet));
        json_set(entry, "bookend_start", bstart);
        json_set(entry, "messages", win);
        json_set(entry, "bookend_end", bend);
        json_set(entry, "messages_before", json_number((double)before));
        json_set(entry, "messages_after", json_number((double)after));
        if (strcmp(resolved, r->sid) != 0)
            json_set(entry, "parent_session_id", json_string(resolved));
        json_append(results, entry);
    }

    int cnt = (int)json_len(results);
    *count_out = cnt;
    json_t *resp = json_object();
    json_set(resp, "success", json_bool(true));
    json_set(resp, "mode", json_string("discover"));
    json_set(resp, "query", json_string(query));
    json_set(resp, "results", results);
    json_set(resp, "count", json_number((double)cnt));
    json_set(resp, "sessions_searched", json_number((double)sessions_searched));

    char *serialized = json_serialize(resp);
    if (serialized) {
        snprintf(json_out, json_size, "%s", serialized);
        free(serialized);
    } else {
        json_out[0] = '\0';
    }
    json_free(resp);
    sqlite3_close(db);

    hermes_log(LOG_DEBUG, "session_search", "discover: query='%s' limit=%d results=%d",
               query, limit, cnt);
    return 0;

if (!available_out) return -1;

    *available_out = 0;
    if (reason_out && reason_size > 0) reason_out[0] = '\0';

    if (!db_path || !*db_path) db_path = sst_default_db();

    /* DB file must exist and open read-only. */
    struct stat stt;
    if (stat(db_path, &stt) != 0) {
        if (reason_out && reason_size > 0)
            snprintf(reason_out, reason_size, "Session DB not found: %s", db_path);
        hermes_log(LOG_DEBUG, "session_search", "check_requirements: DB not found (%s)", db_path);
        return 0;
    }

    sqlite3 *db = sst_open_readonly(db_path);
    if (!db) {
        if (reason_out && reason_size > 0)
            snprintf(reason_out, reason_size, "Cannot open session DB: %s", db_path);
        return 0;
    }
    /* Confirm the FTS5 virtual table exists. */
    int fts_ok = 0;
    sqlite3_stmt *st = NULL;
    if (sqlite3_prepare_v2(db,
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='messages_fts' LIMIT 1",
            -1, &st, NULL) == SQLITE_OK) {
        if (sqlite3_step(st) == SQLITE_ROW) fts_ok = 1;
        sqlite3_finalize(st);
    }
    sqlite3_close(db);

    if (!fts_ok) {
        if (reason_out && reason_size > 0)
            snprintf(reason_out, reason_size, "FTS5 index unavailable in %s", db_path);
        hermes_log(LOG_DEBUG, "session_search", "check_requirements: FTS5 missing (%s)", db_path);
        return 0;
    }

    *available_out = 1;
    hermes_log(LOG_DEBUG, "session_search", "check_requirements: available (%s)", db_path);
    return 0;

if (!message_id || !message_id[0]) return -1;
    if (!db) return -1;

    sqlite3_stmt *st = NULL;
    int rc = sqlite3_prepare_v2(db,
        "SELECT session_id, active, compacted FROM messages WHERE id = ?",
        -1, &st, NULL);
    if (rc != SQLITE_OK) {
        hermes_log(LOG_DEBUG, "session_search", "storage_state: prepare failed: %s",
                   sqlite3_errmsg(db));
        return -1;
    }
    sqlite3_bind_text(st, 1, message_id, -1, SQLITE_TRANSIENT);
    if (sqlite3_step(st) != SQLITE_ROW) {
        sqlite3_finalize(st);
        return -1;   /* no row — Python returns None */
    }

    const unsigned char *sid = sqlite3_column_text(st, 0);
    if (sid && session_id_out && session_size > 0)
        snprintf(session_id_out, session_size, "%s", (const char *)sid);
    if (active_out)   *active_out   = sqlite3_column_int(st, 1);
    if (compacted_out) *compacted_out = sqlite3_column_int(st, 2);

    sqlite3_finalize(st);
    hermes_log(LOG_DEBUG, "session_search", "storage_state: %s -> %s active=%d compacted=%d",
               message_id, sid ? (const char *)sid : "?", *active_out, *compacted_out);
    return 0;

if (!session_id || !session_id[0]) return NULL;

    char name[256];
    name[0] = '\0';

    const char *p = profile;
    while (p && *p == ' ') p++;
    size_t plen = p ? strlen(p) : 0;
    while (plen > 0 && p[plen - 1] == ' ') plen--;
    if (p && plen > 0) {
        snprintf(name, sizeof(name), "%.*s", (int)plen, p);
    } else {
        /* Resolve the active profile (mirrors get_active_profile_name).
         * "custom" (unrecognized HERMES_HOME) must not be emitted. */
        extern const char *hermes_get_profile(void);
        const char *resolved = hermes_get_profile();
        if (resolved && resolved[0] && strcmp(resolved, "custom") != 0)
            snprintf(name, sizeof(name), "%s", resolved);
    }

    if (name[0]) {
        char *out = NULL;
        if (asprintf(&out, "@session:%s/%s", name, session_id) < 0) return NULL;
        return out;
    }
    char *out = NULL;
    if (asprintf(&out, "@session:%s", session_id) < 0) return NULL;
    return out;

if (!content || !rel_path) {
        return strdup("[]");
    }

    /* Check for dangerous patterns using string matching */
    size_t buf_size = 4096;
    char *findings = (char *)malloc(buf_size);
    if (!findings) return strdup("[]");

    int pos = 0;
    pos += snprintf(findings + pos, buf_size - pos, "[", 0);

    int found = 0;

    /* Pattern 1: importlib.import_module() */
    if (strstr(content, "import_module")) {
        pos += snprintf(findings + pos, buf_size - pos,
            "%s{\"file\":\"%s\",\"pattern\":\"dynamic_import\","
            "\"description\":\"importlib.import_module() detected\"}",
            found ? "," : "", rel_path);
        found++;
    }

    /* Pattern 2: __import__() */
    if (strstr(content, "__import__")) {
        pos += snprintf(findings + pos, buf_size - pos,
            "%s{\"file\":\"%s\",\"pattern\":\"dynamic_import\","
            "\"description\":\"__import__() detected\"}",
            found ? "," : "", rel_path);
        found++;
    }

    /* Pattern 3: eval() */
    if (strstr(content, "eval(")) {
        pos += snprintf(findings + pos, buf_size - pos,
            "%s{\"file\":\"%s\",\"pattern\":\"code_execution\","
            "\"description\":\"eval() detected\"}",
            found ? "," : "", rel_path);
        found++;
    }

    /* Pattern 4: exec() */
    if (strstr(content, "exec(")) {
        pos += snprintf(findings + pos, buf_size - pos,
            "%s{\"file\":\"%s\",\"pattern\":\"code_execution\","
            "\"description\":\"exec() detected\"}",
            found ? "," : "", rel_path);
        found++;
    }

    /* Pattern 5: subprocess with shell=True */
    if (strstr(content, "shell=True")) {
        pos += snprintf(findings + pos, buf_size - pos,
            "%s{\"file\":\"%s\",\"pattern\":\"shell_injection\","
            "\"description\":\"subprocess with shell=True detected\"}",
            found ? "," : "", rel_path);
        found++;
    }

    pos += snprintf(findings + pos, buf_size - pos, "]");
    return findings;

if (!path || !*path) {
        return strdup("[]");
    }

    size_t path_len = strlen(path);

    /* Check if it's a .py file */
    if (path_len > 3 && strcmp(path + path_len - 3, ".py") == 0) {
        /* Read file and scan */
        FILE *f = fopen(path, "r");
        if (!f) {
            return strdup("[]");
        }

        fseek(f, 0, SEEK_END);
        long size = ftell(f);
        fseek(f, 0, SEEK_SET);

        if (size <= 0) {
            fclose(f);
            return strdup("[]");
        }

        char *content = (char *)malloc((size_t)size + 1);
        if (!content) {
            fclose(f);
            return strdup("[]");
        }

        size_t n = fread(content, 1, (size_t)size, f);
        fclose(f);
        content[n] = '\0';

        /* Extract filename from path */
        const char *filename = strrchr(path, '/');
        filename = filename ? filename + 1 : path;

        char *result = cli_tools_skills_ast_audit__scan_source(content, filename);
        free(content);
        return result;
    }

    /* For directories, return empty (recursive scan would require filesystem traversal) */
    return strdup("[]");

if (!findings_json) {
        findings_json = "[]";
    }

    size_t buf_size = 4096;
    char *report = (char *)malloc(buf_size);
    if (!report) return strdup("AST deep scan: error");

    int pos = 0;

    /* Header */
    if (skill_name && *skill_name) {
        pos += snprintf(report + buf_size - pos, buf_size - (size_t)pos,
            "AST deep scan: %s\n", skill_name);
    } else {
        pos += snprintf(report, buf_size, "AST deep scan\n");
    }

    /* Check if findings array is empty */
    if (strcmp(findings_json, "[]") == 0) {
        pos += snprintf(report + pos, buf_size - (size_t)pos,
            "  No dynamic import/access patterns detected.\n");
    } else {
        /* Count findings (count commas + 1) */
        int count = 1;
        for (const char *p = findings_json; *p; p++) {
            if (*p == ',') count++;
        }

        pos += snprintf(report + pos, buf_size - (size_t)pos,
            "  %d finding(s):\n", count);

        /* Simple extraction: just report that findings exist */
        pos += snprintf(report + pos, buf_size - (size_t)pos,
            "  (see JSON findings for details)\n");
    }

    pos += snprintf(report + pos, buf_size - (size_t)pos,
        "\n  Note: diagnostic hints for human review, not security verdicts.\n");

    return report;

char path[4096];
    snprintf(path, sizeof(path), "%s%s%s", root, rel[0] ? "/" : "", rel);
    DIR *d = opendir(path);
    if (!d) return 0;
    struct dirent *e;
    while ((e = readdir(d)) != NULL) {
        if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0) continue;
        char child[4096];
        snprintf(child, sizeof(child), "%s%s%s", rel, rel[0] ? "/" : "", e->d_name);
        char full[4096];
        snprintf(full, sizeof(full), "%s/%s", root, child);
        struct stat st;
        if (stat(full, &st) != 0) continue;
        if (S_ISDIR(st.st_mode)) {
            sg_collect_files(root, child, out, n, cap);
        } else if (S_ISREG(st.st_mode)) {
            if (*n < cap) out[(*n)++] = strdup(child);
        }
    }
    closedir(d);
    return 0;

char *digest = skills_guard_content_digest(skill_path);
    if (!digest) return NULL;
    size_t need = strlen(digest) + 8;  /* "sha256:" + digest + NUL */
    char *out = malloc(need);
    if (!out) { free(digest); return NULL; }
    snprintf(out, need, "sha256:%s", digest);
    free(digest);
    return out;

if (!s) s = "";
    if (*off + 1 < cap) buf[(*off)++] = '"';
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        char tmp[8]; size_t n = 0;
        switch (*p) {
            case '"':  memcpy(tmp, "\\\"", 2); n = 2; break;
            case '\\': memcpy(tmp, "\\\\", 2); n = 2; break;
            case '\n': memcpy(tmp, "\\n", 2); n = 2; break;
            case '\r': memcpy(tmp, "\\r", 2); n = 2; break;
            case '\t': memcpy(tmp, "\\t", 2); n = 2; break;
            default:
                if (*p < 0x20) { snprintf(tmp, sizeof(tmp), "\\u%04x", *p); n = 6; }
                else tmp[n++] = (char)*p;
        }
        if (*off + n + 1 < cap) memcpy(buf + *off, tmp, n), *off += n;
    }
    if (*off + 1 < cap) buf[(*off)++] = '"';

if (!out) return -1;
    memset(out, 0, sizeof(*out));
    if (!skill_path) return -1;
    if (!source) source = "community";
    if (!source_url) source_url = "";

    char *bundle_hash = skills_guard_full_content_hash(skill_path);
    if (!bundle_hash) return -1;

    /* cache_root = cache_dir or <skill_path.parent>/.scan-cache */
    char cache_root[4096];
    if (cache_dir && *cache_dir) {
        snprintf(cache_root, sizeof(cache_root), "%s", cache_dir);
    } else {
        char parent[4096];
        const char *slash = strrchr(skill_path, '/');
        if (slash) { size_t pl = (size_t)(slash - skill_path); memcpy(parent, skill_path, pl); parent[pl] = '\0'; }
        else snprintf(parent, sizeof(parent), ".");
        snprintf(cache_root, sizeof(cache_root), "%s/.scan-cache", parent);
    }

    /* source_identity = sha256(f"{source}\0{source_url}")[:16] */
    char sid_in[1024];
    int sid_l = snprintf(sid_in, sizeof(sid_in), "%s%c%s", source, '\0', source_url);
    unsigned char sid_md[CRYPTO_SHA256_LEN];
    crypto_sha256((const unsigned char *)sid_in, (size_t)sid_l, sid_md);
    char source_identity[17];
    static const char *H = "0123456789abcdef";
    for (int i = 0; i < 16; i++) {
        source_identity[i] = H[sid_md[i] >> 4];
        source_identity[i + 1] = H[sid_md[i] & 0xF];
    }
    source_identity[16] = '\0';

    char bare[CRYPTO_SHA256_LEN * 2 + 1];
    const char *colon = strchr(bundle_hash, ':');
    snprintf(bare, sizeof(bare), "%s", colon ? colon + 1 : bundle_hash);

    char cache_file[8192];
    snprintf(cache_file, sizeof(cache_file), "%s/%s-%s.json", cache_root, bare, source_identity);

    /* Try load cached */
    json_t *cached = NULL;
    {
        FILE *f = fopen(cache_file, "r");
        if (f) {
            fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
            if (sz > 0) {
                char *buf = malloc((size_t)sz + 1);
                if (buf) {
                    size_t rd = fread(buf, 1, (size_t)sz, f); buf[rd] = '\0';
                    cached = json_parse(buf, NULL);
                    free(buf);
                }
            }
            fclose(f);
        }
    }

    int hit = 0;
    if (cached && json_get_str(cached, "bundle_hash", NULL) &&
        strcmp(json_get_str(cached, "bundle_hash", ""), bundle_hash) == 0 &&
        strcmp(json_get_str(cached, "scanner_version", ""), "skills-guard-v1") == 0 &&
        strcmp(json_get_str(cached, "source", ""), source) == 0 &&
        strcmp(json_get_str(cached, "source_url", ""), source_url) == 0) {
        hit = 1;
        snprintf(out->skill_name, sizeof(out->skill_name), "%s",
                 strrchr(skill_path, '/') ? strrchr(skill_path, '/') + 1 : skill_path);
        snprintf(out->source, sizeof(out->source), "%s", source);
        snprintf(out->trust_level, sizeof(out->trust_level), "%s",
                 json_get_str(cached, "trust_level", "community"));
        snprintf(out->verdict, sizeof(out->verdict), "%s",
                 json_get_str(cached, "verdict", "safe"));
        snprintf(out->scanned_at, sizeof(out->scanned_at), "%s",
                 json_get_str(cached, "scanned_at", ""));
        snprintf(out->summary, sizeof(out->summary), "%s",
                 json_get_str(cached, "summary", ""));
        out->fresh = 0;
    }
    if (cached) json_free(cached);
    free(bundle_hash);

    if (hit) return 0;

    /* Miss: run the underlying scan (cli_tools_skills_guard_scan_skill fills a
     * JSON report; we materialize a minimal ScanResult from it), then write a
     * fresh cache entry so a repeat call hits (mirrors Python scan_skill_cached
     * which persists the attestation keyed on exact content + source). */
    char report[4096];
    int rc = cli_tools_skills_guard_scan_skill(skill_path, source, report, sizeof(report));
    (void)rc;
    const char *base = strrchr(skill_path, '/') ? strrchr(skill_path, '/') + 1 : skill_path;
    snprintf(out->skill_name, sizeof(out->skill_name), "%s", base);
    snprintf(out->source, sizeof(out->source), "%s", source);
    snprintf(out->trust_level, sizeof(out->trust_level), "%s",
             cli_tools_skills_guard__resolve_trust_level(source, NULL));
    /* verdict from the report is not parsed here; mirror the scan_skill
     * default of safe for a clean skill. */
    snprintf(out->verdict, sizeof(out->verdict), "safe");
    /* Mirror _build_summary: clean scan -> "<name>: clean scan, no threats detected". */
    snprintf(out->summary, sizeof(out->summary), "%s: clean scan, no threats detected", base);
    out->fresh = 1;

    /* Write the cache entry (recompute bundle_hash since we freed it). */
    char *bh = skills_guard_full_content_hash(skill_path);
    if (bh) {
        char bare[CRYPTO_SHA256_LEN * 2 + 1];
        const char *colon = strchr(bh, ':');
        snprintf(bare, sizeof(bare), "%s", colon ? colon + 1 : bh);
        mkdir(cache_root, 0755);
        char cfile[8192];
        snprintf(cfile, sizeof(cfile), "%s/%s-%s.json", cache_root, bare, source_identity);
        FILE *cf = fopen(cfile, "w");
        if (cf) {
            /* provenance mirrors Python: bundle_hash, scanner_version, source,
             * source_url, trust_level, verdict, scanned_at, summary, fresh. */
            fprintf(cf,
                "{\"bundle_hash\":\"%s\",\"scanner_version\":\"skills-guard-v1\","
                "\"source\":\"%s\",\"source_url\":\"%s\",\"trust_level\":\"%s\","
                "\"verdict\":\"%s\",\"scanned_at\":\"%s\",\"summary\":\"%s\",\"fresh\":true}",
                bh, source, source_url, out->trust_level, out->verdict,
                out->scanned_at, out->summary);
            fclose(cf);
        }
        free(bh);
    }
    return 0;

if (!skill_path || !result_buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "skills_guard", "scan_skill: invalid args");
        return -1;
    }
    hermes_log(LOG_DEBUG, "skills_guard", "scan_skill: path=%s source=%s", skill_path, source ? source : "(null)");
    snprintf(result_buf, bufsize, "{\"path\":\"%s\",\"source\":\"%s\",\"findings\":0}",
