    while (fgets(line, sizeof(line), f) && count < max_patterns) {
        char *p = line;
        while (*p && (*p == ' ' || *p == '\t')) p++;
        if (*p == '\0' || *p == '#') continue;
        size_t len = strlen(p);
        while (len > 0 && (p[len - 1] == '\n' || p[len - 1] == '\r')) p[--len] = '\0';
        if (len == 0) continue;
        patterns[count] = strdup(p);
        if (patterns[count]) count++;
