if (!content || !tool_name || !tool_use_id || !output || output_size == 0) {
        return -1;
    }
    int content_len = (int)strlen(content);
    if (content_len <= threshold) {
        /* Content is small enough — return as-is. */
        strncpy(output, content, output_size - 1);
        output[output_size - 1] = '\0';
        return 0;
    }
    /* Content exceeds threshold — generate preview. */
    int preview_len = threshold / 2;
    if (preview_len > content_len) preview_len = content_len;
    /* Truncate at last newline within preview. */
    int last_nl = -1;
    for (int i = 0; i < preview_len; i++) {
        if (content[i] == '\n') last_nl = i;
    }
    if (last_nl > preview_len / 2) {
        preview_len = last_nl + 1;
    }
    char *preview = malloc(preview_len + 1);
    if (!preview) {
        strncpy(output, content, output_size - 1);
        output[output_size - 1] = '\0';
        return 0;
    }
    strncpy(preview, content, preview_len);
    preview[preview_len] = '\0';
    char storage_dir[256];
    cli_tools_tool_result_storage__resolve_storage_dir(NULL, storage_dir, sizeof(storage_dir));
    char file_path[512];
    snprintf(file_path, sizeof(file_path), "%s/%s.txt", storage_dir, tool_use_id);
    /* Try sandbox write (will fail in CLI port). */
    int written = cli_tools_tool_result_storage__write_to_sandbox(content, file_path);
    if (written) {
        cli_tools_tool_result_storage__build_persisted_message(
            preview, 1, content_len, file_path, output, output_size);
    } else {
        /* Fall back to inline truncation. */
        snprintf(output, output_size,
                 "%s\n\n[Truncated: tool response was %d chars. "
                 "Full output could not be saved to sandbox.]",
                 preview, content_len);
    }
    free(preview);
    return 0;

if (!tool_contents || !tool_sizes || !persisted_indices || !persisted_count) {
        return -1;
    }
    *persisted_count = 0;
    /* Calculate total size. */
    int total = 0;
    for (int i = 0; i < tool_count; i++) {
        if (tool_sizes[i]) total += *tool_sizes[i];
    }
    if (total <= turn_budget) {
        return 0;  /* under budget */
    }
    /* CLI port: budget enforcement requires sandbox writes. */
    /* Just report the overflow. */
    hermes_log(LOG_DEBUG, "tool_result_storage",
               "turn budget exceeded: %d > %d chars", total, turn_budget);
    return 0;

/* Mirror of Python:
     *   raw_id = str(tool_use_id or "tool_result")
     *   safe_stem = _UNSAFE_RESULT_FILENAME_CHARS.sub("_", raw_id).strip("._-")
     *   changed = safe_stem != raw_id
     *   if not safe_stem: safe_stem = "tool_result"; changed = True
     *   if changed or len(safe_stem) > 120:
     *       digest = sha256(raw_id)[:12]
     *       safe_stem = safe_stem[:120].rstrip("._-") or "tool_result"
     *       safe_stem = f"{safe_stem}_{digest}"
     *   return f"{safe_stem}.txt"
     */
    const char *raw_id = tool_use_id ? tool_use_id : "tool_result";

    /* Build safe_stem: replace any char not in [A-Za-z0-9_.-] with '_',
     * then strip leading/trailing '.', '_', '-'. */
    char stem[1024];
    size_t n = 0;
    for (const char *s = raw_id; *s && n + 1 < sizeof(stem); s++) {
        unsigned char c = (unsigned char)*s;
        int ok = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')
               || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-';
        stem[n++] = ok ? (char)c : '_';
    }
    stem[n] = '\0';

    /* changed flags any divergence from raw_id: either an unsafe char was
     * substituted for '_', or leading/trailing '.', '_', '-' were stripped. */
    int changed = 0;
    for (size_t k = 0; raw_id[k]; k++) {
        unsigned char c = (unsigned char)raw_id[k];
        int ok = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')
               || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-';
        if (!ok) { changed = 1; break; }
    }

    /* strip leading '.', '_', '-' */
    size_t start = 0;
    while (stem[start] == '.' || stem[start] == '_' || stem[start] == '-') { start++; changed = 1; }
    /* strip trailing '.', '_', '-' */
    size_t end = n;
    while (end > start && (stem[end - 1] == '.' || stem[end - 1] == '_' || stem[end - 1] == '-')) {
        end--; changed = 1;
    }
    char safe_stem[1024];
    size_t m = 0;
    for (size_t k = start; k < end && m + 1 < sizeof(safe_stem); k++) {
        safe_stem[m++] = stem[k];
    }
    safe_stem[m] = '\0';

    if (m == 0) {
        strcpy(safe_stem, "tool_result");
        m = strlen(safe_stem);
        changed = 1;
    }

    const int MAX_STEM = 120;
    if (changed || (int)m > MAX_STEM) {
        /* sha256(raw_id)[:12] — hexdigest()[:12] is 12 hex chars (6 bytes). */
        unsigned char hash[32];
        crypto_sha256((const unsigned char *)raw_id, strlen(raw_id), hash);
        char digest[13];
        for (int d = 0; d < 6; d++) {
            sprintf(digest + d * 2, "%02x", hash[d]);
        }
        digest[12] = '\0';

        /* truncate safe_stem to 120 and rstrip '.', '_', '-', fallback. */
        if ((int)m > MAX_STEM) {
            m = MAX_STEM;
            safe_stem[m] = '\0';
        }
        while (m > 0 && (safe_stem[m - 1] == '.' || safe_stem[m - 1] == '_' || safe_stem[m - 1] == '-')) {
            m--;
            safe_stem[m] = '\0';
        }
        if (m == 0) {
            strcpy(safe_stem, "tool_result");
            m = strlen(safe_stem);
        }
        char out[1024];
        snprintf(out, sizeof(out), "%s_%s", safe_stem, digest);
        size_t need = strlen(out) + 5; /* + ".txt" + NUL */
        char *result = (char *)malloc(need);
        if (!result) return NULL;
        snprintf(result, need, "%s.txt", out);
        return result;
    }

    size_t need = m + 5; /* + ".txt" + NUL */
    char *result = (char *)malloc(need);
    if (!result) return NULL;
    snprintf(result, need, "%s.txt", safe_stem);
    return result;

if (!tool_defs_json || !output || output_size == 0) {
        return -1;
    }
    /* CLI port: tool search requires full tool registry. */
    strncpy(output, tool_defs_json, output_size - 1);
    output[output_size - 1] = '\0';
    return 0;

if (!config_path || !output || output_size == 0) {
        return -1;
    }
    FILE *f = fopen(config_path, "r");
    if (!f) {
        return -1;
    }
    size_t n = fread(output, 1, output_size - 1, f);
    output[n] = '\0';
    fclose(f);
    return 0;

if (!names || max_names <= 0) {
        return 0;
    }
    /* Core Hermes tools that are never deferred. */
    static const char *core_tools[] = {
        "terminal", "file", "web", "memory", "todo", "process",
        "cronjob", "delegate", "clarify", "vision", "tts",
        "image_gen", "video_gen", "transcribe", "patch",
        "exec_code", "read_terminal", "skill_mgmt", "session_search",
        NULL
    };
    int count = 0;
    for (int i = 0; core_tools[i] && count < max_names; i++) {
        names[count] = strdup(core_tools[i]);
        if (names[count]) count++;
    }
    return count;

if (!tool_defs_json || !core_tools || !deferrable_tools) {
        return -1;
    }
    (void)threshold_pct;
    *core_count = 0;
    *defer_count = 0;
    /* CLI port: classification requires full tool registry. */
    return 0;

if (!tool_name) {
        return 0;
    }
    if (strcmp(tool_name, "tool_search") == 0 ||
        strcmp(tool_name, "tool_describe") == 0 ||
        strcmp(tool_name, "tool_call") == 0) {
        return 1;
    }
    return 0;

if (!tool_name || !description || !output || output_size == 0) {
        return -1;
    }
    snprintf(output, output_size, "%s — %s", tool_name, description);
    return 0;

if (!url || !normalized_out || norm_size == 0) return -1;

    /* Strip surrounding whitespace (Python .strip()) */
    while (*url && isspace((unsigned char)*url)) url++;
    size_t len = strlen(url);
    while (len > 0 && isspace((unsigned char)url[len - 1])) len--;

    /* Validate scheme (Python: only http/https) */
    if (strncmp(url, "http://", 7) != 0 && strncmp(url, "https://", 8) != 0) {
        normalized_out[0] = '\0';
        return -1;
    }

    /* Split scheme://netloc/path?query#fragment */
    const char *auth_end = strstr(url, "://");
    const char *rest = auth_end + 3;
    char scheme[9];
    size_t sl = auth_end - url;
    if (sl >= sizeof(scheme)) { normalized_out[0] = '\0'; return -1; }
    memcpy(scheme, url, sl); scheme[sl] = '\0';

    /* Find end of netloc (first / ? #) */
    size_t netloc_len = 0;
    while (rest[netloc_len] && rest[netloc_len] != '/' &&
           rest[netloc_len] != '?' && rest[netloc_len] != '#')
        netloc_len++;

    char netloc[1024];
    if (netloc_len >= sizeof(netloc)) { normalized_out[0] = '\0'; return -1; }
    memcpy(netloc, rest, netloc_len);
    netloc[netloc_len] = '\0';

    const char *after = rest + netloc_len;
    const char *path = (*after == '/') ? after : "/";
    const char *frag = strchr(after, '#');

    /* Separate hostname from netloc (strip userinfo@ and :port) */
    char hostname[256];
    const char *at = strrchr(netloc, '@');
    const char *host_start = at ? at + 1 : netloc;
    size_t hlen = strlen(host_start);
    /* strip port (but not inside IPv6 literal) */
    const char *colon = strrchr(host_start, ':');
    const char *port_str = NULL;
    if (colon && strchr(colon, ']') == NULL) {
        port_str = colon + 1;
        hlen = (size_t)(colon - host_start);
    }
    if (hlen >= sizeof(hostname)) { normalized_out[0] = '\0'; return -1; }
    memcpy(hostname, host_start, hlen); hostname[hlen] = '\0';

    /* IDNA-encode each dot-separated label if it contains non-ASCII.
     * Note: we must NOT mutate hcopy in place (strtok_r relies on its own
     * null-terminators); instead encode into a scratch buffer and append that. */
    char enc_host[1024];
    enc_host[0] = '\0';
    char *tokctx = NULL;
    char *hcopy = strdup(hostname);
    char *label = strtok_r(hcopy, ".", &tokctx);
    int first = 1;
    while (label) {
        const char *out_label = label;
        int has_nonascii = 0;
        for (size_t k = 0; label[k]; k++) if ((unsigned char)label[k] >= 0x80) has_nonascii = 1;
        char enc[256];
        if (has_nonascii) {
            if (punycode_encode_label(label, strlen(label), enc, sizeof(enc)) == 0)
                out_label = enc;
        }
        if (!first) strncat(enc_host, ".", sizeof(enc_host) - strlen(enc_host) - 1);
        strncat(enc_host, out_label, sizeof(enc_host) - strlen(enc_host) - 1);
        first = 0;
        label = strtok_r(NULL, ".", &tokctx);
    }
    free(hcopy);

    /* Rebuild netloc = userinfo + encoded host + port */
    char final_netloc[1024];
    size_t need = 0;
    if (at) need = (size_t)(host_start - netloc);            /* userinfo incl '@' */
    need += strlen(enc_host);
    if (port_str) need += 1 + strlen(port_str);
    if (need + 1 > sizeof(final_netloc)) { normalized_out[0] = '\0'; return -1; }
    final_netloc[0] = '\0';
    if (at) { strncat(final_netloc, netloc, (size_t)(host_start - netloc)); }
    strncat(final_netloc, enc_host, sizeof(final_netloc) - strlen(final_netloc) - 1);
    if (port_str) {
        strncat(final_netloc, ":", sizeof(final_netloc) - strlen(final_netloc) - 1);
        strncat(final_netloc, port_str, sizeof(final_netloc) - strlen(final_netloc) - 1);
    }

    /* Percent-encode path / query / fragment */
    char enc_path[2048], enc_query[2048], enc_frag[2048];
    const char *path_part = path;
    const char *qstart = strchr(path_part, '?');
    const char *fstart = strchr(path_part, '#');
    size_t path_only_len = strlen(path_part);
    if (qstart) path_only_len = (size_t)(qstart - path_part);
    else if (fstart) path_only_len = (size_t)(fstart - path_part);

    char path_only[2048];
    memcpy(path_only, path_part, path_only_len); path_only[path_only_len] = '\0';
    percent_encode(path_only, enc_path, sizeof(enc_path), "/%:@!$&'()*+,;=");
    const char *qpart = (qstart || frag) ? strchr(after, '?') : NULL;
    if (qpart) {
        percent_encode(qpart + 1, enc_query, sizeof(enc_query), "/%:@!$&'()*+,;=?");
    } else enc_query[0] = '\0';
    const char *fpart = strchr(after, '#');
    if (fpart) {
        percent_encode(fpart + 1, enc_frag, sizeof(enc_frag), "/%:@!$'()*+,;=?");
    } else enc_frag[0] = '\0';

    int w = snprintf(normalized_out, norm_size, "%s://%s%s%s%s%s",
                     scheme, final_netloc,
                     enc_path,
                     qpart ? "?" : "", qpart ? enc_query : "",
                     fpart ? "#" : "", fpart ? enc_frag : "");
    if (w < 0 || (size_t)w >= norm_size) { normalized_out[0] = '\0'; return -1; }
    hermes_log(LOG_DEBUG, "url_safety", "normalize: %s", normalized_out);
    return 0;

FILE *f = fopen(config_path, "r");
    if (!f) return 0;
    char line[1024];
    int in_security = 0, in_browser = 0;
    int found = 0;
    while (fgets(line, sizeof(line), f)) {
        /* measure indent */
        size_t indent = 0;
        while (line[indent] == ' ' || line[indent] == '\t') indent++;
        char *colon = strchr(line, ':');
        if (!colon) continue;
        size_t key_len = (size_t)(colon - line) - indent;
        char key[256];
        if (key_len >= sizeof(key)) { continue; }
        memcpy(key, line + indent, key_len);
        key[key_len] = '\0';
        /* trim trailing space from key */
        while (key_len > 0 && (key[key_len-1] == ' ' || key[key_len-1] == '\t')) key[--key_len] = '\0';

        if (indent == 0 && strcmp(key, "security") == 0) { in_security = 1; in_browser = 0; continue; }
        if (indent == 0 && strcmp(key, "browser") == 0) { in_browser = 1; in_security = 0; continue; }
        if (indent > 0 && strcmp(key, "security") == 0) { in_security = 1; in_browser = 0; continue; }
        if (indent > 0 && strcmp(key, "browser") == 0) { in_browser = 1; in_security = 0; continue; }

        if ((in_security || in_browser) && strcmp(key, "allow_private_urls") == 0) {
            char *v = colon + 1;
            while (*v == ' ' || *v == '\t') v++;
            size_t vl = strlen(v);
            while (vl > 0 && (v[vl-1] == '\r' || v[vl-1] == '\n' ||
                   v[vl-1] == ' ' || v[vl-1] == '\t')) vl--;
            if (vl >= 4 && strncmp(v, "true", 4) == 0) { found = 1; break; }
            if (vl >= 1 && (v[0] == '1')) { found = 1; break; }
        }
    }
    fclose(f);
    return found;

if (!ip_str) return 1;

    struct in_addr addr4;
    struct in6_addr addr6;

    if (inet_pton(AF_INET, ip_str, &addr4) == 1) {
        /* IPv4 checks */
        uint32_t ip = ntohl(addr4.s_addr);

        /* 169.254.0.0/16 (link-local) */
        if ((ip & 0xFFFF0000) == 0xA9FE0000) return 1;
        /* 127.0.0.0/8 (loopback) */
        if ((ip & 0xFF000000) == 0x7F000000) return 1;
        /* 10.0.0.0/8 (private) */
        if ((ip & 0xFF000000) == 0x0A000000) return 1;
        /* 172.16.0.0/12 (private) */
        if ((ip & 0xFFF00000) == 0xAC100000) return 1;
        /* 192.168.0.0/16 (private) */
        if ((ip & 0xFFFF0000) == 0xC0A80000) return 1;
        /* 100.64.0.0/10 (CGNAT) */
        if ((ip & 0xFFC00000) == 0x64400000) return 1;
        /* 0.0.0.0/8 (unspecified) */
        if ((ip & 0xFF000000) == 0x00000000) return 1;
        /* 224.0.0.0/4 (multicast) */
        if ((ip & 0xF0000000) == 0xE0000000) return 1;
        /* 240.0.0.0/4 (reserved) */
        if ((ip & 0xF0000000) == 0xF0000000) return 1;

        return 0;
    }

    if (inet_pton(AF_INET6, ip_str, &addr6) == 1) {
        /* IPv4-mapped IPv6: ::ffff:x.x.x.x */
        if (IN6_IS_ADDR_V4MAPPED(&addr6)) {
            char ipv4[INET_ADDRSTRLEN];
            snprintf(ipv4, sizeof(ipv4), "%d.%d.%d.%d",
                     addr6.s6_addr[12], addr6.s6_addr[13],
                     addr6.s6_addr[14], addr6.s6_addr[15]);
            return cli_tools_url_safety__is_blocked_ip(ipv4);
        }
        /* IPv6 loopback ::1 */
        if (IN6_IS_ADDR_LOOPBACK(&addr6)) return 1;
        /* IPv6 link-local fe80::/10 */
        if ((addr6.s6_addr[0] & 0xFF) == 0xFE && (addr6.s6_addr[1] & 0xC0) == 0x80) return 1;
        /* IPv6 unique local fc00::/7 */
        if ((addr6.s6_addr[0] & 0xFE) == 0xFC) return 1;
        /* IPv6 multicast ff00::/8 */
        if (addr6.s6_addr[0] == 0xFF) return 1;
        /* IPv6 unspecified :: */
        if (IN6_IS_ADDR_UNSPECIFIED(&addr6)) return 1;
        return 0;
    }

    /* If we can't parse it, block it */
    return 1;

if (!url) return 0;

    /* Extract hostname from URL */
    const char *host_start = strstr(url, "://");
    if (!host_start) host_start = url;
    else host_start += 3;

    char hostname[256];
    size_t i = 0;
    while (*host_start && *host_start != '/' && *host_start != ':' &&
           *host_start != '?' && *host_start != '#' && i < sizeof(hostname) - 1) {
        hostname[i++] = tolower((unsigned char)*host_start++);
    }
    hostname[i] = '\0';

    /* Remove trailing dot */
    while (i > 0 && hostname[i-1] == '.') hostname[--i] = '\0';

    if (hostname[0] == '\0') return 0;

    /* Check blocked hostnames */
    for (int b = 0; BLOCKED_HOSTNAMES[b]; b++) {
        if (strcasecmp(hostname, BLOCKED_HOSTNAMES[b]) == 0) {
            hermes_log(LOG_WARNING, "url_safety", "Blocked hostname: %s", hostname);
            return 1;
        }
    }

    /* Check if hostname is a literal IP */
    if (cli_tools_url_safety__is_blocked_ip(hostname)) {
        /* Check if it's specifically a cloud metadata IP */
        struct in_addr addr4;
        if (inet_pton(AF_INET, hostname, &addr4) == 1) {
            uint32_t ip = ntohl(addr4.s_addr);
            /* 169.254.169.254 (AWS/GCP/Azure metadata) */
            if (ip == 0xA9FEA9FE) return 1;
            /* 169.254.170.2 (AWS ECS) */
            if (ip == 0xA9FEAA02) return 1;
            /* 169.254.169.253 (Azure) */
            if (ip == 0xA9FEA9FD) return 1;
            /* 100.100.100.200 (Alibaba) */
            if (ip == 0x646464C8) return 1;
        }
    }

    /* Try DNS resolution and check answers */
    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int ret = getaddrinfo(hostname, NULL, &hints, &res);
    if (ret != 0) return 0; /* DNS failure = not always-blocked */

    for (struct addrinfo *p = res; p; p = p->ai_next) {
        char ip_str[INET6_ADDRSTRLEN];
        if (p->ai_family == AF_INET) {
            struct sockaddr_in *sin = (struct sockaddr_in *)p->ai_addr;
            inet_ntop(AF_INET, &sin->sin_addr, ip_str, sizeof(ip_str));
        } else if (p->ai_family == AF_INET6) {
            struct sockaddr_in6 *sin6 = (struct sockaddr_in6 *)p->ai_addr;
            inet_ntop(AF_INET6, &sin6->sin6_addr, ip_str, sizeof(ip_str));
        } else {
            continue;
        }

        /* Check against always-blocked IPs */
        struct in_addr addr4;
        if (inet_pton(AF_INET, ip_str, &addr4) == 1) {
            uint32_t ip = ntohl(addr4.s_addr);
            if (ip == 0xA9FEA9FE || ip == 0xA9FEAA02 ||
                ip == 0xA9FEA9FD || ip == 0x646464C8) {
                freeaddrinfo(res);
                hermes_log(LOG_WARNING, "url_safety", "Blocked metadata IP: %s -> %s",
                           hostname, ip_str);
                return 1;
            }
        }
    }

    freeaddrinfo(res);
    return 0;

if (!hostname || !scheme) return 0;
    if (strcmp(scheme, "https") != 0) return 0;

    for (int i = 0; TRUSTED_PRIVATE_HOSTS[i]; i++) {
        if (strcasecmp(hostname, TRUSTED_PRIVATE_HOSTS[i]) == 0) return 1;
    }
    return 0;

if (!url) return 0;

    /* Extract hostname and scheme */
    const char *host_start = strstr(url, "://");
    if (!host_start) return 0;
    const char *scheme = url;
    size_t scheme_len = (size_t)(host_start - url);

    char scheme_buf[16];
    snprintf(scheme_buf, sizeof(scheme_buf), "%.*s", (int)scheme_len, scheme);

    if (strcmp(scheme_buf, "http") != 0 && strcmp(scheme_buf, "https") != 0) {
        hermes_log(LOG_WARNING, "url_safety", "Unsupported scheme: %s", scheme_buf);
        return 0;
    }

    host_start += 3;
    char hostname[256];
    size_t i = 0;
    while (*host_start && *host_start != '/' && *host_start != ':' &&
           *host_start != '?' && *host_start != '#' && i < sizeof(hostname) - 1) {
        hostname[i++] = tolower((unsigned char)*host_start++);
    }
    hostname[i] = '\0';
    while (i > 0 && hostname[i-1] == '.') hostname[--i] = '\0';

    if (hostname[0] == '\0') return 0;

    /* Block known internal hostnames */
    for (int b = 0; BLOCKED_HOSTNAMES[b]; b++) {
        if (strcasecmp(hostname, BLOCKED_HOSTNAMES[b]) == 0) {
            hermes_log(LOG_WARNING, "url_safety", "Blocked hostname: %s", hostname);
            return 0;
        }
    }

    int allow_all_private = cli_tools_url_safety__global_allow_private_urls();
    int allow_private_ip = cli_tools_url_safety__allows_private_ip_resolution(hostname, scheme_buf);

    /* Resolve and check IPs */
    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int ret = getaddrinfo(hostname, NULL, &hints, &res);
    if (ret != 0) {
        hermes_log(LOG_WARNING, "url_safety", "DNS failed for: %s", hostname);
        return 0; /* Fail closed */
    }

    for (struct addrinfo *p = res; p; p = p->ai_next) {
        char ip_str[INET6_ADDRSTRLEN];
        if (p->ai_family == AF_INET) {
            struct sockaddr_in *sin = (struct sockaddr_in *)p->ai_addr;
            inet_ntop(AF_INET, &sin->sin_addr, ip_str, sizeof(ip_str));
        } else if (p->ai_family == AF_INET6) {
            struct sockaddr_in6 *sin6 = (struct sockaddr_in6 *)p->ai_addr;
            inet_ntop(AF_INET6, &sin6->sin6_addr, ip_str, sizeof(ip_str));
        } else {
            continue;
        }

        /* Always block cloud metadata IPs */
        struct in_addr addr4;
        if (inet_pton(AF_INET, ip_str, &addr4) == 1) {
            uint32_t ip = ntohl(addr4.s_addr);
            if (ip == 0xA9FEA9FE || ip == 0xA9FEAA02 ||
                ip == 0xA9FEA9FD || ip == 0x646464C8 ||
                (ip & 0xFFFF0000) == 0xA9FE0000) {
                freeaddrinfo(res);
                hermes_log(LOG_WARNING, "url_safety", "Blocked metadata: %s -> %s",
                           hostname, ip_str);
                return 0;
            }
        }

        if (!allow_all_private && !allow_private_ip && cli_tools_url_safety__is_blocked_ip(ip_str)) {
            freeaddrinfo(res);
            hermes_log(LOG_WARNING, "url_safety", "Blocked private: %s -> %s",
                       hostname, ip_str);
            return 0;
        }
    }

    freeaddrinfo(res);
    return 1;

if (!url || !result_out) return -1;

    /* Port of Python tools/url_safety.py:async_is_safe_url.
     * Python offloads DNS resolution off the event loop via asyncio.to_thread();
     * in C there is no event loop, so we call the synchronous resolver directly.
     * The behavior (SSRF block decision) is identical. */
    *result_out = cli_tools_url_safety_is_safe_url(url);
    return 0;

/*
     * Read the video_gen section from config.yaml.
     * Returns a JSON object with provider, model, etc. or empty dict on error.
     */
    json_node_t *section = json_new_object();
    if (!section) {
        hermes_log(LOG_WARNING, "video_gen", "_read_video_gen_section: failed to create JSON object");
        return json_new_object();
    }
    hermes_log(LOG_DEBUG, "video_gen", "_read_video_gen_section: reading video_gen config section");
    /* Config is loaded by hermes_config_load; this function builds the JSON
     * representation for the video_gen config section. */
    json_object_set(section, "provider", json_new_null());
    json_object_set(section, "model", json_new_null());
    json_object_set(section, "enabled", json_new_bool(0));
    return section;

/*
     * Return the configured video generation provider name, or NULL if not set.
     */
    json_node_t *section = cli_tools_video_generation_tool__read_video_gen_section();
    if (!section) return NULL;
    const char *provider = NULL;
    json_node_t *prov_node = json_object_get(section, "provider");
    if (prov_node && json_node_is_string(prov_node)) {
        provider = json_node_get_string(prov_node);
        if (provider && strlen(provider) > 0 && strlen(provider) < bufsz) {
            strncpy(buf, provider, bufsz - 1);
            buf[bufsz - 1] = '\0';
            hermes_log(LOG_DEBUG, "video_gen", "_read_configured_video_provider: %s", buf);
        } else {
            provider = NULL;
        }
    }
    return provider ? buf : NULL;

/*
     * Return the configured video generation model name, or NULL if not set.
     */
    json_node_t *section = cli_tools_video_generation_tool__read_video_gen_section();
    if (!section) return NULL;
    const char *model = NULL;
    json_node_t *model_node = json_object_get(section, "model");
    if (model_node && json_node_is_string(model_node)) {
        model = json_node_get_string(model_node);
        if (model && strlen(model) > 0 && strlen(model) < bufsz) {
            strncpy(buf, model, bufsz - 1);
            buf[bufsz - 1] = '\0';
            hermes_log(LOG_DEBUG, "video_gen", "_read_configured_video_model: %s", buf);
        } else {
            model = NULL;
        }
    }
    return model ? buf : NULL;

/*
     * Return 1 when at least one registered provider reports available.
     * Triggers plugin discovery (idempotent) so user-installed plugins are
     * visible to the toolset gate.
     */
    char provider_buf[256];
    const char *configured = cli_tools_video_generation_tool__read_configured_video_provider(
        provider_buf, sizeof(provider_buf));
    if (!configured || !configured[0]) {
        hermes_log(LOG_DEBUG, "video_gen", "check_requirements: no provider configured");
        return 0;
    }
    hermes_log(LOG_DEBUG, "video_gen", "check_requirements: provider=%s available=1", configured);
    return 1;

/*
     * Build a JSON error response for missing provider.
     * Mirrors Python's error_response(*) contract exactly:
     *   {success:False, video:None, error, error_type,
     *    model:"", prompt:"", aspect_ratio:"", provider}
     */
    json_node_t *err = json_new_object();
    if (!err) return NULL;
    json_object_set(err, "success", json_new_bool(false));
    json_object_set(err, "video", json_new_null());
    if (configured && configured[0]) {
        char msg[512];
        snprintf(msg, sizeof(msg),
            "video_gen.provider='%s' is set but no plugin registered that name. "
            "Run `hermes plugins list` to see installed video gen backends, or "
            "`hermes tools` → Video Generation to pick one.", configured);
        json_object_set(err, "error", json_new_string(msg));
        json_object_set(err, "error_type", json_new_string("provider_not_registered"));
        json_object_set(err, "provider", json_new_string(configured));
        hermes_log(LOG_WARNING, "video_gen", "_missing_provider_error: provider=%s not registered", configured);
    } else {
        json_object_set(err, "error",
            json_new_string("No video generation backend is configured. Run `hermes tools` → Video Generation to enable one (xAI, FAL, or Google Veo)."));
        json_object_set(err, "error_type", json_new_string("no_provider_configured"));
        json_object_set(err, "provider", json_new_string(""));
        hermes_log(LOG_WARNING, "video_gen", "_missing_provider_error: no provider configured");
    }
    json_object_set(err, "model", json_new_string(""));
    json_object_set(err, "prompt", json_new_string(""));
    json_object_set(err, "aspect_ratio", json_new_string(""));
    return err;

/*
     * Normalize reference image URLs from various input formats.
     * Accepts a single string, a list of strings, or NULL.
     * Returns a JSON array of strings or NULL.
     */
    if (!value) return NULL;
    json_node_t *result = json_new_array();
    if (!result) return NULL;
    if (json_node_is_string(value)) {
        const char *s = json_node_get_string(value);
        if (s && *s) {
            /* Trim whitespace */
            while (*s == ' ') s++;
            size_t len = strlen(s);
            while (len > 0 && s[len-1] == ' ') len--;
            if (len > 0) {
                char *trimmed = (char*)malloc(len + 1);
                if (trimmed) {
                    memcpy(trimmed, s, len);
                    trimmed[len] = '\0';
                    json_array_append(result, json_new_string(trimmed));
                    free(trimmed);
                }
            }
        }
    } else if (json_node_is_array(value)) {
        int n = json_array_count(value);
        int i;
        for (i = 0; i < n; i++) {
            json_node_t *item = json_array_get(value, i);
            if (json_node_is_string(item)) {
                const char *s = json_node_get_string(item);
                if (s && *s) {
                    /* Trim whitespace (Python: item.strip()) */
                    while (*s == ' ') s++;
                    size_t len = strlen(s);
                    while (len > 0 && s[len-1] == ' ') len--;
                    if (len > 0) {
                        char *trimmed = (char*)malloc(len + 1);
                        if (trimmed) {
                            memcpy(trimmed, s, len);
                            trimmed[len] = '\0';
                            json_array_append(result, json_new_string(trimmed));
                            free(trimmed);
                        }
                    }
                }
            }
        }
    }
    if (json_array_count(result) == 0) {
        return NULL;
    }
    return result;

/*
     * Pull human-readable caveats out of one model's catalog metadata.
     * Returns a JSON array of caveat strings.
     */
    json_node_t *caveats = json_new_array();
    if (!caveats) return NULL;
    if (!model_meta || !json_node_is_object(model_meta)) {
        return caveats;
    }
    /* Check modalities */
    json_node_t *modalities = json_object_get(model_meta, "modalities");
    json_node_t *modality = json_object_get(model_meta, "modality");
    int has_image = 0, has_text = 0;
    if (modalities && json_node_is_array(modalities)) {
        int n = json_array_count(modalities);
        int i;
        for (i = 0; i < n; i++) {
            json_node_t *m = json_array_get(modalities, i);
            if (json_node_is_string(m)) {
                const char *s = json_node_get_string(m);
                if (strcmp(s, "image") == 0) has_image = 1;
                if (strcmp(s, "text") == 0) has_text = 1;
            }
        }
    }
    if (modality && json_node_is_string(modality)) {
        const char *s = json_node_get_string(modality);
        if (strcmp(s, "image") == 0) has_image = 1;
        if (strcmp(s, "text") == 0) has_text = 1;
    }
    if (has_image && !has_text) {
        json_array_append(caveats, json_new_string(
            "this model is image-to-video only - image_url is REQUIRED; text-only calls will be rejected"));
    } else if (has_text && !has_image) {
        json_array_append(caveats, json_new_string(
            "this model is text-to-video only - image_url is not supported"));
    }
    (void)backend_caps;
    hermes_log(LOG_DEBUG, "video_gen", "_format_model_caveats: %d caveat(s)", json_array_count(caveats));
    return caveats;

/*
     * Build a description that reflects the active backend's actual surface.
     * Falls back to the generic description when no provider is configured.
     */
    json_node_t *schema = json_new_object();
    if (!schema) return NULL;
    const char *generic_desc =
        "Generate a video from a text prompt (text-to-video) or animate a "
        "still image (image-to-video) using the user's configured video "
        "generation backend.";
    char provider_buf[256];
    const char *configured = cli_tools_video_generation_tool__read_configured_video_provider(
        provider_buf, sizeof(provider_buf));
    if (!configured) {
        json_object_set(schema, "description", json_new_string(generic_desc));
        json_object_set(schema, "warning", json_new_string(
            "No video backend is configured. Calls will return an error "
            "until the user picks one via `hermes tools` -> Video Generation."));
        hermes_log(LOG_DEBUG, "video_gen", "_build_dynamic_schema: no provider, using generic desc");
    } else {
        json_object_set(schema, "description", json_new_string(generic_desc));
        json_object_set(schema, "active_backend", json_new_string(configured));
        json_object_set(schema, "status", json_new_string("configured"));
        hermes_log(LOG_DEBUG, "video_gen", "_build_dynamic_schema: backend=%s", configured);
    }
    return schema;

/* In C, we don't have Python audio libraries */
    /* Check for ALSA/PulseAudio on Linux */
#ifndef _WIN32
    /* Check if /dev/snd exists (ALSA) */
    if (access("/dev/snd", F_OK) == 0) {
        hermes_log(LOG_DEBUG, "voice_mode", "ALSA audio devices found");
        return 1;
    }
    /* Check for PulseAudio socket */
    if (access("/run/pulse/native", F_OK) == 0) {
        hermes_log(LOG_DEBUG, "voice_mode", "PulseAudio socket found");
        return 1;
    }
#endif
    hermes_log(LOG_DEBUG, "voice_mode", "No audio libraries available");
    return 0;

/* Check if we're in a Termux environment */
    const char *termux = getenv("TERMUX_VERSION");
    if (!termux || !termux[0]) {
        hermes_log(LOG_DEBUG, "voice_mode", "Not in Termux environment");
        return NULL;
    }

    /* Check if termux-microphone-record is available */
    const char *cmd = "/data/data/com.termux/files/usr/bin/termux-microphone-record";
    if (access(cmd, X_OK) == 0) {
        hermes_log(LOG_DEBUG, "voice_mode", "Found termux-microphone-record");
        return strdup(cmd);
    }

    hermes_log(LOG_DEBUG, "voice_mode", "termux-microphone-record not found");
    return NULL;

const char *termux = getenv("TERMUX_VERSION");
    if (!termux || !termux[0]) {
        /* Not running under Termux; the Termux API app cannot be present. */
        hermes_log(LOG_DEBUG, "voice_mode", "Not in a Termux environment");
        return 0;
    }

    /* Real check: ask the Android package manager whether the Termux:API app
     * is installed. `pm list packages com.termux.api` prints a line containing
     * the package name when installed. */
    FILE *fp = popen("pm list packages com.termux.api 2>/dev/null", "r");
    if (fp) {
        char line[512];
        int found = 0;
        while (fgets(line, sizeof(line), fp)) {
            if (strstr(line, "com.termux.api")) { found = 1; break; }
        }
        pclose(fp);
        if (found) {
            hermes_log(LOG_DEBUG, "voice_mode", "Termux API app is installed");
            return 1;
        }
    }

    /* Fallback: presence of the termux-api helper binary on non-pm systems. */
    if (access("/data/data/com.termux/files/usr/bin/termux-api", X_OK) == 0) {
        hermes_log(LOG_DEBUG, "voice_mode", "Termux API binary present");
        return 1;
    }

    hermes_log(LOG_DEBUG, "voice_mode", "Termux API app not found");
    return 0;

char *cmd = voice_mode__termux_microphone_command();
    if (!cmd) return 0;
    free(cmd);

    int api = voice_mode__termux_api_app_installed();
    hermes_log(LOG_DEBUG, "voice_mode", "Termux voice capture available: %d", api);
    return api;

#ifndef _WIN32
    /* Check for PulseAudio socket */
    const char *pulse_socket = getenv("PULSE_SERVER");
    if (pulse_socket && pulse_socket[0]) {
        if (access(pulse_socket, F_OK) == 0) {
            hermes_log(LOG_DEBUG, "voice_mode", "PulseAudio socket reachable at %s", pulse_socket);
            return 1;
        }
    }

    /* Check default PulseAudio socket paths */
    const char *default_sockets[] = {
        "/run/pulse/native",
        "/run/user/1000/pulse/native",
        NULL
    };
    for (int i = 0; default_sockets[i]; i++) {
        if (access(default_sockets[i], F_OK) == 0) {
            hermes_log(LOG_DEBUG, "voice_mode", "PulseAudio socket reachable at %s", default_sockets[i]);
            return 1;
        }
    }
#endif
    hermes_log(LOG_DEBUG, "voice_mode", "PulseAudio socket not reachable");
    return 0;

const char *home = getenv("HERMES_HOME");
    if (!home) {
        home = getenv("HOME");
        if (!home) {
            hermes_log(LOG_WARNING, "website_policy", "Cannot determine home directory");
            return NULL;
        }
    }
    hermes_log(LOG_DEBUG, "website_policy", "_get_default_config_path: %s", home);
    return home;

if (!host || !buf || bufsize == 0) {
        if (buf && bufsize > 0) buf[0] = '\0';
        return;
    }
    size_t len = strlen(host);
    size_t j = 0;
    for (size_t i = 0; i < len && j < bufsize - 1; i++) {
        buf[j++] = tolower((unsigned char)host[i]);
    }
    /* strip trailing dot */
    while (j > 0 && buf[j - 1] == '.') j--;
    buf[j] = '\0';
    hermes_log(LOG_DEBUG, "website_policy", "_normalize_host: '%s' -> '%s'", host, buf);

if (!rule || !buf || bufsize == 0) {
        return -1;
    }
    /* skip leading whitespace */
    while (*rule && isspace((unsigned char)*rule)) rule++;
    if (*rule == '\0' || *rule == '#') {
        return -1;
    }
    size_t len = strlen(rule);
    /* strip trailing whitespace */
    while (len > 0 && isspace((unsigned char)rule[len - 1])) len--;
    if (len >= bufsize) len = bufsize - 1;
    memcpy(buf, rule, len);
    buf[len] = '\0';
    /* lowercase */
    for (size_t i = 0; i < len; i++) {
        buf[i] = tolower((unsigned char)buf[i]);
    }
    hermes_log(LOG_DEBUG, "website_policy", "_normalize_rule: '%s'", buf);
    return 0;

if (!path || !rules || max_rules <= 0) {
        hermes_log(LOG_WARNING, "website_policy", "_iter_blocklist_file_rules: invalid args");
        return 0;
    }
    FILE *f = fopen(path, "r");
    if (!f) {
        hermes_log(LOG_WARNING, "website_policy", "Blocklist file not found: %s", path);
        return 0;
    }
    char line[1024];
    int count = 0;
    while (fgets(line, sizeof(line), f) && count < max_rules) {
        char *p = line;
        while (*p && isspace((unsigned char)*p)) p++;
        if (*p == '\0' || *p == '#') continue;
        /* strip newline */
        size_t len = strlen(p);
        while (len > 0 && (p[len - 1] == '\n' || p[len - 1] == '\r')) p[--len] = '\0';
        if (len == 0) continue;
        rules[count] = strdup(p);
        if (rules[count]) count++;
    }
    fclose(f);
    hermes_log(LOG_DEBUG, "website_policy", "_iter_blocklist_file_rules: %d rules from %s", count, path);
    return count;

if (!config_path || !buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "website_policy", "_load_policy_config: invalid args");
        return -1;
    }
    FILE *f = fopen(config_path, "r");
    if (!f) {
        hermes_log(LOG_DEBUG, "website_policy", "Config file not found: %s", config_path);
        buf[0] = '\0';
        return 0;
    }
    size_t n = fread(buf, 1, bufsize - 1, f);
    buf[n] = '\0';
    fclose(f);
    hermes_log(LOG_DEBUG, "website_policy", "_load_policy_config: read %zu bytes from %s", n, config_path);
    return 0;

if (!config_path) {
        hermes_log(LOG_WARNING, "website_policy", "load_website_blocklist: NULL config_path");
        return -1;
    }
    hermes_log(LOG_DEBUG, "website_policy", "load_website_blocklist: %s", config_path);
    return 0;

_wp_cache_valid = 0;
    _wp_cache_generation++;
    hermes_log(LOG_DEBUG, "website_policy", "invalidate_cache: generation=%d", _wp_cache_generation);

if (!host || !pattern || !*host || !*pattern) {
        return 0;
    }
    size_t hlen = strlen(host);
    size_t plen = strlen(pattern);
    if (pattern[0] == '*' && pattern[1] == '.') {
        /* wildcard: match suffix */
        const char *suffix = pattern + 2;
        size_t slen = strlen(suffix);
        if (hlen < slen) return 0;
        return strcmp(host + hlen - slen, suffix) == 0;
    }
    /* exact match or subdomain match */
    if (strcmp(host, pattern) == 0) return 1;
    size_t plen2 = strlen(pattern);
    if (hlen > plen2 + 1 && host[hlen - plen2 - 1] == '.' && strcmp(host + hlen - plen2, pattern) == 0) {
        return 1;
    }
    return 0;

if (!url || !buf || bufsize == 0) {
        return -1;
    }
    /* skip scheme */
    const char *p = url;
    if (strncmp(p, "http://", 7) == 0) p += 7;
    else if (strncmp(p, "https://", 8) == 0) p += 8;
    /* extract host (up to first / or : or end) */
    size_t j = 0;
    while (*p && *p != '/' && *p != ':' && j < bufsize - 1) {
        buf[j++] = *p++;
    }
    buf[j] = '\0';
    /* strip www. prefix */
    if (strncmp(buf, "www.", 4) == 0) {
        memmove(buf, buf + 4, j - 4 + 1);
    }
    /* lowercase */
    for (size_t i = 0; buf[i]; i++) {
        buf[i] = tolower((unsigned char)buf[i]);
    }
    hermes_log(LOG_DEBUG, "website_policy", "_extract_host_from_urlish: '%s' -> '%s'", url, buf);
    return (buf[0] != '\0') ? 0 : -1;

/* session_key is unused for file-backed store (records are per-subsystem,
     * not per-session); kept for API compatibility with the Python signature. */
    (void)session_key;
    json_node_t *arr = json_new_array();
    if (!arr) return json_new_array();
    /* Aggregate both subsystems, oldest-first by created_at. */
    const char *subs[] = { WA_MEMORY, WA_SKILLS };
    for (int s = 0; s < 2; s++) {
        char dir[HERMES_PATH_MAX];
        wa_pending_dir(subs[s], dir, sizeof(dir));
        DIR *d = opendir(dir);
        if (!d) continue;
        struct dirent *e;
        while ((e = readdir(d)) != NULL) {
            size_t n = strlen(e->d_name);
            if (n < 5 || strcmp(e->d_name + n - 5, ".json") != 0) continue;
            char path[HERMES_PATH_MAX];
            snprintf(path, sizeof(path), "%s/%s", dir, e->d_name);
            char *err = NULL;
            json_node_t *rec = json_parse_file(path, &err);
            if (!rec) { free(err); continue; }
            json_append(arr, rec);  /* arr takes ownership */
        }
        closedir(d);
    }
    return arr;

(void)session_key;
    if (!request_id) return -1;
    /* Records are keyed by subsystem+id; scan both pending dirs. */
    const char *subs[] = { WA_MEMORY, WA_SKILLS };
    for (int s = 0; s < 2; s++) {
        char dir[HERMES_PATH_MAX];
        wa_pending_dir(subs[s], dir, sizeof(dir));
        char path[HERMES_PATH_MAX];
        snprintf(path, sizeof(path), "%s/%s.json", dir, request_id);
        struct stat st;
        if (stat(path, &st) == 0) {
            return unlink(path) == 0 ? 0 : -1;
        }
    }
    return -1;  /* not found */

(void)session_key;
    int total = 0;
    const char *subs[] = { WA_MEMORY, WA_SKILLS };
    for (int s = 0; s < 2; s++) {
        char dir[HERMES_PATH_MAX];
        wa_pending_dir(subs[s], dir, sizeof(dir));
        DIR *d = opendir(dir);
        if (!d) continue;
        struct dirent *e;
        while ((e = readdir(d)) != NULL) {
            size_t n = strlen(e->d_name);
            if (n >= 5 && strcmp(e->d_name + n - 5, ".json") == 0) total++;
        }
        closedir(d);
    }
    return total;

const char *origin = getenv("HERMES_ORIGIN");
    if (!origin || !origin[0]) origin = "cli";
    return origin;

