    if (!c) return;
    for (size_t i = 0; i < c->n_subs; i++) {
        if (c->subs[i].id == sub_id) {
            memmove(&c->subs[i], &c->subs[i + 1],
                    (c->n_subs - i - 1) * sizeof *c->subs);
            c->n_subs--;
            break;
        }
    }
    maybe_evict(reg, c);

