            size_t j = 0;
            int cap = 1;
            for (size_t k = 0; nm[k] && j + 1 < sizeof(titled); k++) {
                char c = nm[k];
                if (c == '_') { titled[j++] = ' '; cap = 1; continue; }
                if (cap && c >= 'a' && c <= 'z') c = (char)(c - 'a' + 'A');
                titled[j++] = c;
