    /* check upper-prefix */
    char up[16];
    int k = 0;
    const char *q = text;
    while (*q && k < 15) {
        char c = *q++;
        if (c >= 'a' && c <= 'z') c = (char)(c - 'a' + 'A');
        up[k++] = c;
    }
    up[k] = '\0';
    if (strncmp(up, "[SILENT]", 8) == 0) return 1;
    return 0;

/* Python: compact one-line failure for chat delivery. */
