            const size_t MAX_CONTEXT_CHARS = 8000;
            if (strlen(text) > MAX_CONTEXT_CHARS) {
                text[MAX_CONTEXT_CHARS] = '\0';
                char *t2 = malloc(MAX_CONTEXT_CHARS + 40);
