    const char *p = message;
    while (*p && (unsigned char)*p <= ' ') p++;
    char norm[256];
    size_t n = 0;
    int last_was_space = 0;
    while (*p && n < sizeof(norm) - 1) {
        if ((unsigned char)*p <= ' ') {
            if (!last_was_space) {
                norm[n++] = ' ';
                last_was_space = 1;
            }
        } else {
            norm[n++] = (char)tolower((unsigned char)*p);
            last_was_space = 0;
        }
        p++;
    }
