        while (name_key[nn] && name_key[nn] != '\n'
               && name_key[nn] != '\r' && nn < name_size - 1) {
            if (name_out) {
                if (name_key[nn] != '"' && name_key[nn] != '\'')
                    name_out[nn] = name_key[nn];
                else {
                    /* Find matching close quote */
                    char q = name_key[nn];
                    nn++;
                    while (name_key[nn] && name_key[nn] != q && name_key[nn] != '\n') nn++;
                    break;
                }
            }
            nn++;
