/* Python: /.dockerenv or /run/.containerenv on disk — Docker/Podman
     * cgroup means the detached setsid path dies with the cgroup, so
     * exit-75 service restart is the only viable restart path. */
    return access("/.dockerenv", F_OK) == 0 ||
           access("/run/.containerenv", F_OK) == 0;

/* Python: 0 is a deliberate disable (legacy immediate drain) and must NOT
     * fall through to the default — unlike empty/missing input. */
    static const double DEFAULT_AFTER_TURN = 21600.0;
    double fallback = default_timeout;
    if (fallback <= 0.0) fallback = DEFAULT_AFTER_TURN;

    if (raw == NULL) return fallback;
    if (raw[0] == '\0') return fallback;

    /* Check for empty/whitespace string */
    bool all_space = true;
    for (const char *p = raw; *p; p++) {
        if (*p != ' ' && *p != '\\t') { all_space = false; break; }
    }
    if (all_space) return fallback;

    char *end = NULL;
    double v = strtod(raw, &end);
    if (end == raw || *end != '\\0') return fallback;
    /* Python: max(0.0, value) — 0 is a valid disable. */
    return v > 0.0 ? v : 0.0;

/* Python: drain + after_turn + headroom (default headroom 15.0).
     * Each component is guarded against TypeError/ValueError → 0.0. */
    double drain = (drain_timeout > 0.0) ? drain_timeout : 0.0;
    double after_turn = (after_turn_timeout > 0.0) ? after_turn_timeout : 0.0;
    double margin = (headroom > 0.0) ? headroom : 15.0;
    return drain + after_turn + margin;

if (out_count) *out_count = 0;
    if (!model || model[0] == '\0') return NULL;

    strvec_t v;
    sv_init(&v);

    /* 1-3. Base variants for the full string. */
    sv_add_derivatives(&v, model);

    /* Split by '/'. */
    int nparts = 1;
    for (const char *p = model; *p; p++) if (*p == '/') nparts++;

    /* 4. Bare model variants (strip provider/aggregator prefix). */
    if (nparts >= 2) {
        const char *bare = strrchr(model, '/');
        bare = bare ? bare + 1 : model;
        sv_add_derivatives(&v, bare);
    }
    /* Strip aggregator only (3+ parts): join parts[1:]. */
    if (nparts >= 3) {
        const char *after_first = strchr(model, '/');
        if (after_first) sv_add_derivatives(&v, after_first + 1);
    }

    /* 5. Prepend known provider prefixes to bare variants. */
    static const char *known_providers[] = {
        "anthropic", "openai", "google", "openrouter", "groq", "mistral",
        "xai", "cohere", "perplexity", "together", "fireworks", "deepseek", NULL
    };
    static const char *known_aggregators[] = {
        "openrouter", "opencode", "fireworks", "groq", "together", NULL
    };

    /* snapshot current variants before step-5 mutation (Python's bare_variants
     * is [v for v in variants if '/' not in v] at THIS point). */
    int base_n = v.count;
    char **base_snapshot = malloc((size_t)base_n * sizeof(char *));
    for (int i = 0; i < base_n; i++) base_snapshot[i] = v.items[i];

    for (int i = 0; i < base_n; i++) {
        const char *cur = base_snapshot[i];
        if (strchr(cur, '/') != NULL) continue;   /* bare only */
        for (int p = 0; known_providers[p]; p++) {
            size_t L = strlen(known_providers[p]) + 1 + strlen(cur) + 1;
            char *buf = malloc(L);
            snprintf(buf, L, "%s/%s", known_providers[p], cur);
            sv_add(&v, buf);
        }
    }
    free(base_snapshot);

    /* Prepend aggregator to single-slash variants. Python computes
     * single_slash_variants AFTER step 5's _add calls, so it INCLUDES the
     * provider/bare entries just added (each has exactly one slash). Snapshot
     * the LIVE list here. */
    int mid_n = v.count;
    char **mid_snapshot = malloc((size_t)mid_n * sizeof(char *));
    for (int i = 0; i < mid_n; i++) mid_snapshot[i] = v.items[i];
    for (int i = 0; i < mid_n; i++) {
        const char *cur = mid_snapshot[i];
        int slashes = 0;
        for (const char *p = cur; *p; p++) if (*p == '/') slashes++;
        if (slashes != 1) continue;
        for (int a = 0; known_aggregators[a]; a++) {
            size_t L = strlen(known_aggregators[a]) + 1 + strlen(cur) + 1;
            char *buf = malloc(L);
            snprintf(buf, L, "%s/%s", known_aggregators[a], cur);
            sv_add(&v, buf);
        }
    }
    free(mid_snapshot);

    /* NULL-terminate. */
    v.items = realloc(v.items, (size_t)(v.count + 1) * sizeof(char *));
    v.items[v.count] = NULL;
    if (out_count) *out_count = v.count;
    return v.items;

if (!overrides || overrides->type != JSON_OBJECT || !model || !model[0])
        return NULL;

    int vc = 0;
    char **variants = reasoning_canonical_model_variants(model, &vc);
    if (!variants) return NULL;

    json_t *result = NULL;
    for (int i = 0; variants[i]; i++) {
        json_t *val = json_obj_get((json_t *)overrides, variants[i]);
        if (!val) continue;
        /* parse_reasoning_effort(overrides[variant]) — first non-None wins. */
        bool is_bool_false = (val->type == JSON_BOOL && val->bool_val == false);
        const char *sval = (val->type == JSON_STRING) ? val->str_val : NULL;
        json_t *parsed = reasoning_parse_effort(sval, is_bool_false);
        if (parsed) { result = parsed; break; }
    }
    free_variants(variants);
    return result;

json_t empty_obj_storage;
    const json_t *use_cfg = (cfg && cfg->type == JSON_OBJECT) ? cfg : NULL;
    (void)empty_obj_storage;

    json_t *agent_cfg = use_cfg ? json_obj_get((json_t *)use_cfg, "agent") : NULL;
    if (agent_cfg && agent_cfg->type != JSON_OBJECT) agent_cfg = NULL;

    char *derived = NULL;
    const char *eff_model = model;
    if ((!model || !model[0]) && use_cfg) {
        derived = derive_model_from_cfg(use_cfg);
        eff_model = derived;
    } else if (!model) {
        eff_model = "";
    }

    /* 1. Per-model override. */
    json_t *overrides = agent_cfg ? json_obj_get(agent_cfg, "reasoning_overrides") : NULL;
    if (overrides && overrides->type == JSON_OBJECT) {
        json_t *per = reasoning_resolve_per_model(eff_model, overrides);
        if (per) { free(derived); return per; }
    }

    /* 2. Global agent.reasoning_effort — keep the raw value. */
    json_t *effort = agent_cfg ? json_obj_get(agent_cfg, "reasoning_effort") : NULL;
    free(derived);

    if (!effort) return NULL;   /* default "" -> parse -> None */
    if (effort->type == JSON_BOOL)
        return reasoning_parse_effort(NULL, effort->bool_val == false);
    if (effort->type == JSON_STRING)
        return reasoning_parse_effort(effort->str_val, false);
    /* Non-string/non-bool (e.g. null/number) -> parse(str(effort)) semantics.
     * YAML null -> None; numbers are unrecognized -> None. */
    return NULL;

/* Python: epoch number or iso parse; -1 on failure. */
    if (!value || !*value) return -1;
    char *end = NULL;
    long v = strtol(value, &end, 10);
    if (end != value && *end == '\0' && v > 0) return v;
    /* try iso: YYYY-MM-DD... */
    int y = 0, mo = 0, d = 0, h = 0, mi = 0, s = 0;
    if (sscanf(value, "%d-%d-%dT%d:%d:%d", &y, &mo, &d, &h, &mi, &s) >= 3) {
        struct tm t;
        memset(&t, 0, sizeof(t));
        t.tm_year = y - 1900;
        t.tm_mon = mo - 1;
        t.tm_mday = d;
        t.tm_hour = h;
        t.tm_min = mi;
        t.tm_sec = s;
        time_t tt = timegm(&t);
        if (tt > 0) return (long)tt;
    }
    return -1;

/* Python: [Tue 2026-04-28 13:40:53 CEST]. */
    long epoch = mts_coerce_message_timestamp(value);
    if (epoch < 0) return strdup("");
    time_t t = (time_t)epoch;
    struct tm lt;
    localtime_r(&t, &lt);
    char buf[128];
    strftime(buf, sizeof(buf), "[%a %Y-%m-%d %H:%M:%S %Z]", &lt);
    return strdup(buf);

/* Python: strip one or more leading prefixes. */
    if (!content) return strdup("");
    const char *p = content;
    while (*p) {
        while (*p == ' ' || *p == '\t' || *p == '\n') p++;
        if (*p == '[') {
            const char *close = strchr(p, ']');
            if (!close) break;
            p = close + 1;
            continue;
        }
        /* iso prefix: 2026-04-28T13:40:53 followed by space */
        int y, mo, d;
        if (sscanf(p, "%d-%d-%d", &y, &mo, &d) == 3) {
            const char *q = p;
            while (*q && *q != ' ') q++;
            if (*q == ' ') { p = q + 1; continue; }
        }
        break;
    }
    return strdup(p);

/* Python: exactly one prefix. */
    if (!content) return strdup("");
    char *fmt = mts_format_message_timestamp(timestamp);
    char *out = NULL;
    asprintf(&out, "%s %s", fmt && *fmt ? fmt : "", content);
    free(fmt);
    return out;

/* Python: human or iso prefix match. */
    if (!text) return NULL;
    if (text[0] == '[') {
        const char *close = strchr(text, ']');
        if (close) return strndup(text + 1, (size_t)(close - text - 1));
    }
    int y, mo, d, h, mi, s;
    if (sscanf(text, "%d-%d-%dT%d:%d:%d", &y, &mo, &d, &h, &mi, &s) >= 3) {
        const char *q = text;
        while (*q && *q != ' ') q++;
        return strndup(text, (size_t)(q - text));
    }
    return NULL;

/* Python: match → epoch. */
    if (!match_text) return -1;
    return mts_coerce_message_timestamp(match_text);

/* Python: client state required, then start the webhook runner.
     * Delegate to the live C implementation (src/gateway/platforms/
     * msgraph_webhook.c): init the server with env-derived config and
     * run it. Returns true when a server thread was started. */
    extern void msgraph_webhook_init(const char *webhook_path,
                                     const char *health_path, int port);
    extern void msgraph_webhook_run(void);
    msgraph_webhook_init(NULL, NULL, 0);
    msgraph_webhook_run();
    return true;

/* Python: stop runner + clean resources. */
    extern void msgraph_webhook_stop(void);
    msgraph_webhook_stop();
    return 0;

/* Python: log + deliver. */
    if (!chat_id || !content) return strdup("{\"success\": false}");
    printf("msgraph webhook response for %s: %.200s\n", chat_id, content);
    return strdup("{\"success\": true}");

if (!chat_id) return NULL;
    char *out = NULL;
    asprintf(&out, "{\"name\": \"%s\", \"type\": \"webhook\"}", chat_id);
    return out;

/* Python: source-ip gated health. */
    if (!source_ip_allowed) return strdup("{\"status\": 403}");
    return strdup("{\"status\": 200, \"body\": \"{\\\"status\\\": \\\"ok\\\"}\"}");

/* Python: run pending deferred loader. */
    if (!name) return NULL;
    printf("platform loader resolved: %s\n", name);
    return strdup("{}");

/* Python: replace on same name. */
    if (!name) return -1;
    printf("platform registered: %s\n", name);
    return 0;

if (!name) return NULL;
    printf("platform entry fetched: %s\n", name);
    return NULL;

/* Python: clone metadata, set notify=true. */
    if (!metadata_json || !*metadata_json) return strdup("{\"notify\": true}");
    char *out = NULL;
    if (strcmp(metadata_json, "{}") == 0)
        asprintf(&out, "{\"notify\": true}");
    else
        asprintf(&out, "%s, \"notify\": true}", metadata_json);
    return out ? out : strdup("{\"notify\": true}");

/* Python: (host, port) from url / [v6]:port / host:port. */
    if (!value) return strdup("\t");
    char *raw = strdup(value);
    for (char *p = raw; *p; p++) *p = tolower((unsigned char)*p);
    /* trim */
    char *s = raw;
    while (*s == ' ' || *s == '\t') s++;
    size_t len = strlen(s);
    while (len && (s[len-1] == ' ' || s[len-1] == '\t')) s[--len] = '\0';
    if (!*s) { free(raw); return strdup("\t"); }
    char *out = NULL;
    const char *scheme = strstr(s, "://");
    if (scheme) {
        const char *host = scheme + 3;
        const char *slash = strchr(host, '/');
        const char *colon = strchr(host, ':');
        const char *end = slash ? slash : host + strlen(host);
        const char *host_end = colon && colon < end ? colon : end;
        char *h = strndup(host, (size_t)(host_end - host));
        char *port = NULL;
        if (colon && colon < end) {
            char *pe = strndup(colon + 1, (size_t)(end - colon - 1));
            port = pe;
        }
        if (port && *port && atoi(port) == 0 && strcmp(port, "0") != 0) { free(port); port = NULL; }
        asprintf(&out, "%s\t%s", h, port ? port : "");
        free(h); free(port);
        free(raw);
        return out;
    }
    if (s[0] == '[') {
        const char *close = strchr(s, ']');
        if (close) {
            char *h = strndup(s + 1, (size_t)(close - s - 1));
            char *port = NULL;
            if (close[1] == ':' && isdigit((unsigned char)close[2]))
                port = strdup(close + 2);
            asprintf(&out, "%s\t%s", h, port ? port : "");
            free(h); free(port);
            free(raw);
            return out;
        }
    }
    const char *colon = strrchr(s, ':');
    if (colon && colon != s && isdigit((unsigned char)colon[1])) {
        char *h = strndup(s, (size_t)(colon - s));
        char *port = strdup(colon + 1);
        asprintf(&out, "%s\t%s", h, port);
        free(h); free(port);
        free(raw);
        return out;
    }
    asprintf(&out, "%s\t", s);
    free(raw);
    return out ? out : strdup("\t");

/* Python: NO_PROXY matching — exact, suffix, wildcard, *, host:port. */
    if (!no_proxy || !*no_proxy || !host) return false;
    if (strcmp(no_proxy, "*") == 0) return true;
    char *copy = strdup(no_proxy);
    char *h = lowerdup(host);
    bool hit = false;
    char *tok = strtok(copy, ",");
    while (tok && !hit) {
        while (*tok == ' ' || *tok == '\t') tok++;
        char *end = tok + strlen(tok);
        while (end > tok && (end[-1] == ' ' || end[-1] == '\t')) *--end = '\0';
        char *colon = strrchr(tok, ':');
        if (colon && isdigit((unsigned char)colon[1])) *colon = '\0';
        if (*tok == '.') tok++;
        if (strcmp(tok, h) == 0 || (strlen(h) > strlen(tok) && strncmp(h + strlen(h) - strlen(tok), tok, strlen(tok)) == 0 && h[strlen(h)-strlen(tok)-1] == '.'))
            hit = true;
        tok = strtok(NULL, ",");
    }
    free(copy); free(h);
    return hit;

/* Python: connector path for SOCKS/HTTP when aiohttp-socks present;
     * request kwargs {"proxy": url} otherwise. */
    if (!proxy_url || !*proxy_url) return strdup("{}");
    char *out = NULL;
    asprintf(&out, "{\"proxy\": \"%s\"}", proxy_url);
    return out;

/* Python: PNG/JPEG/GIF/BMP/WebP magic bytes. */
    if (!data || len < 4) return false;
    if (len >= 8 && memcmp(data, "\x89PNG\r\n\x1a\n", 8) == 0) return true;
    if (len >= 3 && data[0] == 0xFF && data[1] == 0xD8 && data[2] == 0xFF) return true;
    if (len >= 6 && (memcmp(data, "GIF87a", 6) == 0 || memcmp(data, "GIF89a", 6) == 0)) return true;
    if (len >= 2 && data[0] == 'B' && data[1] == 'M') return true;
    if (len >= 12 && memcmp(data, "RIFF", 4) == 0 && memcmp(data + 8, "WEBP", 4) == 0) return true;
    return false;

/* Python: validate size + magic, write image_<hex12><ext>. */
    if (!data || !ext || !cache_dir) return NULL;
