            c->completed = true;
            c->suppress_whole_file = true;
        } else if (c->handle->audible && c->dropped) {
            c->partial = true;
            c->completed = false;
            c->suppress_whole_file = true;
        } else {
            c->completed = false;
            c->suppress_whole_file = false;
        }
