    clock_gettime(CLOCK_MONOTONIC, &ts);
    double now = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
    int r = sd_n_record_tick(now, now);
    printf("systemd watchdog heartbeat (WATCHDOG=1) -> %s\n",
