        w = ((long)buf[16] << 24) | ((long)buf[17] << 16) | ((long)buf[18] << 8) | buf[19];
        h = ((long)buf[20] << 24) | ((long)buf[21] << 16) | ((long)buf[22] << 8) | buf[23];
    } else if (buf[0] == 0xFF && buf[1] == 0xD8) {
