    char *pattern = malloc(needed);
    if (!pattern) return NULL;
    int written = snprintf(pattern, needed,
                           "(?:[\"'](?:%s)[\"']|(?:%s)(?:\\s|$|[\\)`;|&]))",
                           path_alt, path_alt);
