    char *saveptr = NULL;
    char *tok = strtok_r(path_copy, "/\\", &saveptr);
    while (tok && comp_count < 64) {
        components[comp_count++] = tok;
        tok = strtok_r(NULL, "/\\", &saveptr);
    }

    /* Require at least 2 components below root (e.g., /home/alice, C:\Users\alice) */
    if (comp_count < 2) {
        free(path_copy);
        return NULL;
    }

