    size_t body_len = 0;
    for (int i = 0; i < comp_count; i++) {
        body_len += strlen(components[i]);
        if (i > 0) body_len += 5;  /* [/\\]+ */
    }
    char *body = malloc(body_len + 1);
    if (!body) {
        free(path_copy);
        return NULL;
    }
    body[0] = '\0';
    for (int i = 0; i < comp_count; i++) {
        if (i > 0) strcat(body, "[/\\\\]+");
        strcat(body, components[i]);
