    /* _PATH_TAIL = (?P<tail>(?:[/\\][^/\\s'"`;|&<>()])+) */
    const char *path_token_stop = "\\s'\"`;|&<>()";
    size_t pattern_len = 16 + body_len + 64;  /* [/\\]* + body + (?P<tail>...) */
    char *pattern = malloc(pattern_len);
    if (!pattern) {
        free(body);
        return NULL;
    }
    snprintf(pattern, pattern_len,
             "[/\\\\]*(?P<tail>(?:[/\\\\][^/\\\\%s])+)",
