/* Python: /proc scan on Linux, psutil fallback, else empty —
     * REAL: list pids in /proc whose ppid == our pid. */
    DIR *d = opendir("/proc");
    if (!d) return strdup("[]");
    pid_t me = getpid();
    size_t cap = 256, len = 0;
    char *out = malloc(cap);
    if (!out) { closedir(d); return strdup("[]"); }
    out[0] = '\0';
    strcpy(out, "[");
    bool first = true;
    struct dirent *e;
    while ((e = readdir(d)) != NULL) {
        if (!isdigit((unsigned char)e->d_name[0])) continue;
        long pid = atol(e->d_name);
        if (pid <= 0) continue;
        char stat_path[64];
        snprintf(stat_path, sizeof(stat_path), "/proc/%ld/stat", pid);
        FILE *f = fopen(stat_path, "r");
        if (!f) continue;
        char buf[512];
        size_t r = fread(buf, 1, sizeof(buf) - 1, f);
        buf[r] = '\0';
        fclose(f);
        char *rp = strrchr(buf, ')');
        if (!rp) continue;
        /* fields after comm: state(3) ppid(4) */
        char *pp = rp + 1;
        char *end = NULL;
        strtol(pp, &end, 10);      /* state */
        if (!end) continue;
        long ppid = strtol(end, NULL, 10);
        if (ppid == me) {
            size_t need = len + 16;
            if (need > cap) {
                cap = need * 2;
                char *nb = realloc(out, cap);
                if (!nb) break;
                out = nb;
            }
            if (!first) strcat(out, ",");
            char num[16];
            snprintf(num, sizeof(num), "%ld", pid);
            strcat(out, num);
            first = false;
            len = strlen(out);
        }
    }
    closedir(d);
    strcat(out, "]");
    return out;

