    w += snprintf(w, remaining, "(%zu file%s attached)", count, count == 1 ? "" : "s");
    remaining = 1024 - (w - result);

    for (size_t i = 0; i < count && remaining > 10; i++) {
        json_t *m = json_get(media_files, i);
