    /* Parse target */
    char platform[64] = {0};
    char target_ref[256] = {0};
    char *colon = strchr(target, ':');
    if (colon) {
        size_t platform_len = colon - target;
        if (platform_len < sizeof(platform)) {
            strncpy(platform, target, platform_len);
            platform[platform_len] = '\0';
