    if (gethostname(host, sizeof(host) - 1) != 0) host[0] = '\0';
    /* short hostname: drop domain */
    char *dot = strchr(host, '.');
    if (dot) *dot = '\0';
    /* keep only alnum, '-', '_' */
    size_t w = 0;
    for (char *p = host; *p && w < sizeof(host) - 1; p++) {
        if (isalnum((unsigned char)*p) || *p == '-' || *p == '_') host[w++] = *p;
    }
    host[w] = '\0';
