        if (got == 3) snprintf(suffix, sizeof(suffix), "%02x%02x%02x",
                               rb[0], rb[1], rb[2]);
        else snprintf(suffix, sizeof(suffix), "%06lx", (unsigned long)time(NULL) & 0xffffff);
