        }
        const char *kind = (e && e->type == JSON_OBJECT)
            ? json_get_str(e, "kind", "") : "";
        const char *mode = (e && e->type == JSON_OBJECT)
            ? json_get_str(e, "mode", "") : "";
        const char *hash = (e && e->type == JSON_OBJECT)
            ? json_get_str(e, "hash", "") : "";

