            {{0x02}, 7},                               /* 200::/7  */
            {{0x04}, 6},                               /* 400::/6  */
            {{0x08}, 5},                               /* 800::/5  */
            {{0x10}, 4},                               /* 1000::/4 */
            {{0x40}, 3},                               /* 4000::/3 */
            {{0x60}, 3},                               /* 6000::/3 */
            {{0x80}, 3},                               /* 8000::/3 */
            {{0xA0}, 3},                               /* a000::/3 */
