            if (s && (strcmp(s, "STOPPED") == 0 || strcmp(s, "ABORTED") == 0 ||
                      strcmp(s, "FAILED") == 0)) break;
            if ((double)time(NULL) >= deadline) break;
            struct timespec ts;
            ts.tv_sec = 0;
            ts.tv_nsec = VERCEL_STOP_POLL_MS * 1000000L;
            nanosleep(&ts, NULL);
        }
    }
    pthread_mutex_unlock(&g_env.lock);

