    pthread_mutex_lock(&g_env.lock);
    bool attached = g_env.sandbox_attached;
    pthread_mutex_unlock(&g_env.lock);
    if (!attached) return 0;
    if (g_env.persistent && g_env.task_id[0]) {
        char *sid = ve_env_snapshot_sandbox();
        if (sid) free(sid);
    }
    ve_env_stop_sandbox();
    ve_env_close_sandbox_client();
    return 0;

const char *home = getenv("HERMES_HOME");
    if (!home || !home[0]) home = getenv("HOME");
    if (!home || !home[0]) home = "/tmp";
    char *out = NULL;
    asprintf(&out, "%s/%s", home, VERCEL_SNAPSHOT_STORE_NAME);
    return out;

/* Python: read the JSON dict from the store; {} on any failure. */
    char *path = ve_snapshot_store_path();
    if (!path) return strdup("{}");
    FILE *f = fopen(path, "rb");
    free(path);
    if (!f) return strdup("{}");
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = NULL;
    if (sz > 0 && sz < 16 * 1024 * 1024) {
        buf = malloc((size_t)sz + 1);
        if (buf) {
            size_t rd = fread(buf, 1, (size_t)sz, f);
            buf[rd] = '\0';
        }
    }
    fclose(f);
    if (!buf) return strdup("{}");
    json_t *j = json_parse(buf, NULL);
    free(buf);
    if (!j || j->type != JSON_OBJECT) { if (j) json_free(j); return strdup("{}"); }
    char *out = json_dumps(j, 0);
    json_free(j);
    return out ? out : strdup("{}");

/* Python: atomic-ish JSON write of the store. */
    char *path = ve_snapshot_store_path();
    if (!path) return -1;
    FILE *f = fopen(path, "wb");
    if (!f) { free(path); return -1; }
    if (data_json) fwrite(data_json, 1, strlen(data_json), f);
    fclose(f);
    free(path);
    return 0;

/* Python: store.get(task_id) if it's a non-empty string. */
    if (!task_id || !task_id[0]) return NULL;
    char *store = ve_load_snapshots();
    json_t *j = json_parse(store, NULL);
    free(store);
    if (!j) return NULL;
    json_t *v = json_obj_get(j, task_id);
    char *out = NULL;
    if (v && v->type == JSON_STRING && v->str_val && v->str_val[0])
        out = strdup(v->str_val);
    json_free(j);
    return out;

if (!task_id || !task_id[0] || !snapshot_id || !snapshot_id[0]) return -1;
    char *store = ve_load_snapshots();
    json_t *j = json_parse(store, NULL);
    free(store);
    if (!j) { j = json_object(); }
    if (j->type != JSON_OBJECT) { json_free(j); j = json_object(); }
    json_set(j, task_id, json_string(snapshot_id));
    char *dumped = json_dumps(j, 0);
    int rc = dumped ? ve_save_snapshots(dumped) : -1;
    free(dumped);
    json_free(j);
    return rc;

if (!task_id || !task_id[0]) return -1;
    char *store = ve_load_snapshots();
    json_t *j = json_parse(store, NULL);
    free(store);
    if (!j) return -1;
    if (j->type != JSON_OBJECT) { json_free(j); return -1; }
    json_t *existing = json_obj_get(j, task_id);
    if (!existing) { json_free(j); return 0; }
    if (snapshot_id != NULL) {
        if (existing->type != JSON_STRING || !existing->str_val ||
            strcmp(existing->str_val, snapshot_id) != 0) {
            json_free(j);
            return 0;
        }
    }
    json_obj_del(j, task_id);
    char *dumped = json_dumps(j, 0);
    int rc = dumped ? ve_save_snapshots(dumped) : -1;
    free(dumped);
    json_free(j);
    return rc;

/* Python: setdefault VERCEL_TELEMETRY_DISABLED=1 (never override an
     * explicit user value) + lazy-install probe. The C port sets the env
     * default and probes for the vercel binary/sdk marker. Returns 0 when
     * available, -1 otherwise. */
    if (!getenv("VERCEL_TELEMETRY_DISABLED"))
        setenv("VERCEL_TELEMETRY_DISABLED", "1", 0);
    /* Probe: the C port's sandbox client is always compiled in, so the
     * SDK analogue is available. */
    return 0;

/* Python: retry a callback with exponential backoff on transient
     * failures (100ms * 2^attempt), up to *attempts* tries. */
    (void)label;
    if (attempts <= 0) attempts = 1;
    for (int i = 0; i < attempts; i++) {
        char *err = NULL;
        if (fn(ctx, &err)) {
            if (out_err) *out_err = NULL;
            return 0;
        }
        if (out_err) *out_err = err ? err : strdup("vercel call failed");
        if (i < attempts - 1) {
            struct timespec ts;
            ts.tv_sec = 0;
            ts.tv_nsec = (long)(100000000.0 * (1 << (i > 6 ? 6 : i)));
            nanosleep(&ts, NULL);
        }
    }
    return -1;

/* Python: returns the SandboxStatus enum class. The C port maps the
     * status names 1:1 as strings. */
    return "SandboxStatus";

/* Python: frozenset{ABORTED, FAILED, STOPPED} — the states that
     * terminate a sandbox. */
    if (!states_out || max <= 0) return 0;
    const char *states[] = { "ABORTED", "FAILED", "STOPPED" };
    int n = 3 < max ? 3 : max;
    for (int i = 0; i < n; i++) states_out[i] = states[i];
    return n;

/* Python: reject configurable disk (only 0 or default allowed);
     * timeout = max(self.timeout, 5min); vcpus = floor(cpu) if cpu>0 else
     * None; memory_mb = memory if memory>0 else None. Returns 0 on success,
     * -1 when disk is unsupported. */
    int default_disk_mb = 4096;
    if (disk != 0 && disk != default_disk_mb) {
        if (out_err) *out_err = 1;
        return -1;
    }
    double t = timeout_secs > 0 ? timeout_secs : 0;
    if (t < VERCEL_MIN_SANDBOX_TIMEOUT_SECS) t = VERCEL_MIN_SANDBOX_TIMEOUT_SECS;
    if (out_timeout) *out_timeout = t;
    if (out_runtime && rt_sz) snprintf(out_runtime, rt_sz, "%s", runtime ? runtime : "");
    if (out_vcpus) *out_vcpus = cpu > 0 ? (double)(long)cpu : 0;  /* 0 = None */
    if (out_memory_mb) *out_memory_mb = memory > 0 ? memory : 0;
    return 0;

/* Python: sandbox.sandbox.cwd if it starts with "/", else default. */
    if (sandbox_cwd && sandbox_cwd[0] == '/') return strdup(sandbox_cwd);
    return strdup(VERCEL_DEFAULT_CWD);

/* Python: strip the HOME probe output; if it starts with "/" use it,
     * else fall back to workspace_root. */
    if (result_output) {
        const char *p = result_output;
        while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
        const char *end = p + strlen(p);
        while (end > p && (end[-1] == ' ' || end[-1] == '\t' || end[-1] == '\n' || end[-1] == '\r')) end--;
        size_t len = (size_t)(end - p);
        if (len > 0 && p[0] == '/') {
            char *out = malloc(len + 1);
            memcpy(out, p, len);
            out[len] = '\0';
            return out;
        }
    }
    return strdup(workspace_root ? workspace_root : VERCEL_DEFAULT_CWD);

/* Python: run quoted rm; raise when returncode != 0. */
    if (!client || !client->run_command || n <= 0) return -1;
    char *args_json = NULL;
    asprintf(&args_json, "[\"-lc\", \"rm -rf\"]");
    char *cmd = quoted_rm_command(remote_paths, n);
    char *result = client->run_command(client->ctx, "bash", args_json, workspace_root);
    free(args_json);
    free(cmd);
    if (!result) return -1;
    json_t *rj = json_parse(result, NULL);
    free(result);
    int rc = -1;
    if (rj) {
        json_t *code = json_obj_get(rj, "returncode");
        if (code && code->type == JSON_NUMBER) rc = (int)code->num_val == 0 ? 0 : -1;
        json_free(rj);
    }
    return rc;

/* Python: build WriteFile payloads (path + bytes) and retry
     * write_files. The C client handles the byte read; we pass the
     * path pairs as JSON. */
    if (!client || !client->write_files || n <= 0) return 0;
    json_t *arr = json_array();
    for (int i = 0; i < n; i++) {
        json_t *wf = json_object();
        json_set(wf, "path", json_string(remote_paths[i] ? remote_paths[i] : ""));
        json_set(wf, "host_path", json_string(host_paths[i] ? host_paths[i] : ""));
        json_array_append(arr, wf);
    }
    char *files_json = json_dumps(arr, 0);
    json_free(arr);
    if (!files_json) return -1;
    /* Retry with backoff. */
    int rc = -1;
    for (int attempt = 0; attempt < VERCEL_WRITE_RETRY_ATTEMPTS; attempt++) {
        if (client->write_files(client->ctx, files_json) == 0) { rc = 0; break; }
        if (attempt < VERCEL_WRITE_RETRY_ATTEMPTS - 1) {
            struct timespec ts;
            ts.tv_sec = 0;
            ts.tv_nsec = (long)(100000000.0 * (1 << attempt));
            nanosleep(&ts, NULL);
        }
    }
    free(files_json);
    return rc;

if (!host_path || !remote_path) return -1;
    const char *hp[1] = { host_path };
    const char *rp[1] = { remote_path };
    return ve_vercel_bulk_upload(client, hp, rp, 1);

/* Python: tar the remote .hermes dir on the sandbox, download the tar,
     * clean up. */
    if (!client || !client->run_command || !client->download_file) return -1;
    char archive_member[1024];
    if (remote_home && strcmp(remote_home, "/") == 0)
        snprintf(archive_member, sizeof(archive_member), ".hermes");
    else
        snprintf(archive_member, sizeof(archive_member), "%s/.hermes",
                 remote_home ? remote_home : "/root");
    char *archive_member_clean = archive_member;
    if (archive_member[0] == '/') archive_member_clean = archive_member + 1;
    char remote_tar[1024];
    snprintf(remote_tar, sizeof(remote_tar), "/tmp/.hermes_sync.%ld.tar", (long)getpid());
    char cmd[2048];
    snprintf(cmd, sizeof(cmd), "tar cf %s -C / %s", remote_tar, archive_member_clean);
    char *args_json = NULL;
    asprintf(&args_json, "[\"-lc\", \"%s\"]", cmd);
    char *result = client->run_command(client->ctx, "bash", args_json, workspace_root);
    free(args_json);
    if (!result) { return -1; }
    json_t *rj = json_parse(result, NULL);
    free(result);
    int rc = -1;
    if (rj) {
        json_t *code = json_obj_get(rj, "returncode");
        if (code && code->type == JSON_NUMBER && (int)code->num_val == 0)
            rc = client->download_file(client->ctx, remote_tar, dest_tar_path);
        json_free(rj);
    }
    /* Cleanup the remote tar (best-effort). */
    char *cleanup_args = NULL;
    asprintf(&cleanup_args, "[\"-lc\", \"rm -f %s\"]", remote_tar);
    char *cr = client->run_command(client->ctx, "bash", cleanup_args, workspace_root);
    free(cleanup_args);
    if (cr) free(cr);
    return rc;

/* Python: poll sandbox status until RUNNING (default 30s, 250ms poll);
     * treat terminal states as failure. Returns 0 when running. */
    if (!client || !status_fn) return -1;
    double deadline = (double)time(NULL) + (timeout_secs > 0 ? timeout_secs : 30.0);
    for (;;) {
        const char *status = status_fn(status_ctx);
        if (status && strcmp(status, "RUNNING") == 0) return 0;
        if (status) {
            const char *terminal[] = { "ABORTED", "FAILED", "STOPPED" };
            for (int i = 0; i < 3; i++)
                if (strcmp(status, terminal[i]) == 0) return -1;
        }
        if ((double)time(NULL) >= deadline) return -1;
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 250000000L;
        nanosleep(&ts, NULL);
    }

const char *raw = ww_get_str(cfg, "provider");
    if (!raw) raw = WW_DEFAULT_PROVIDER;
    /* strip + lower */
    size_t len = strlen(raw);
    char *out = malloc(len + 1);
    if (!out) return NULL;
    size_t j = 0;
    for (size_t i = 0; i < len; i++) {
        char c = raw[i];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') continue;
        out[j++] = (char)tolower((unsigned char)c);
    }
    out[j] = '\0';
    if (j == 0) {
        free(out);
        return strdup(WW_DEFAULT_PROVIDER);
    }
    return out;

if (out_int) *out_int = 0;
    if (out_str) *out_str = NULL;
    if (!cfg || cfg->type != JSON_OBJECT) return 0; /* None */

    json_t *raw = json_obj_get(cfg, "input_device");
    if (!raw) return 0; /* None */

    /* bool -> None */
    if (raw->type == JSON_BOOL) return 0;

    if (raw->type == JSON_NUMBER) {
        if (out_int) *out_int = (int)raw->num_val;
        return 1; /* int selector */
    }

    if (raw->type == JSON_STRING) {
        const char *s = raw->str_val;
        /* strip */
        while (*s && (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r')) s++;
        size_t len = strlen(s);
        while (len > 0 && (s[len-1] == ' ' || s[len-1] == '\t' ||
                           s[len-1] == '\n' || s[len-1] == '\r')) len--;
        if (len == 0) return 0; /* empty -> None */
        char *name = malloc(len + 1);
        if (!name) return 0;
        memcpy(name, s, len);
        name[len] = '\0';
        if (out_str) *out_str = name;
        else free(name);
        return 2; /* string name */
    }
    return 0; /* other types -> None */

double s = ww_get_num(cfg, "sensitivity", WW_DEFAULT_SENSITIVITY);
    if (s < 0.0) s = 0.0;
    if (s > 1.0) s = 1.0;
    return s;

double n = ww_get_num(cfg, "confirmation_frames", WW_DEFAULT_CONFIRMATION_FRAMES);
    int v = (int)n;
    if (v < 1) v = 1;
    if (v > 10) v = 10;
    return v;

const char *raw = ww_get_str(cfg, "phrase");
    if (!raw || !*raw) return strdup(WW_DEFAULT_PHRASE);
    return strdup(raw);

if (!surface) return false;
    if (!cfg || cfg->type != JSON_OBJECT) return false;
    if (!ww_get_bool(cfg, "enabled", false)) return false;

    const char *want_raw = ww_get_str(cfg, "surface");
    /* strip + lower */
    if (!want_raw) want_raw = "auto";
    size_t len = strlen(want_raw);
    char want[128];
    size_t j = 0;
    for (size_t i = 0; i < len && j < sizeof(want)-1; i++) {
        char c = want_raw[i];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') continue;
        want[j++] = (char)tolower((unsigned char)c);
    }
    want[j] = '\0';
    if (j == 0) return true; /* "auto" */

    if (strcmp(want, "auto") == 0) return true;

    /* surface.strip().lower() */
    const char *s = surface;
    while (*s && (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r')) s++;
    size_t slen = strlen(s);
    while (slen > 0 && (s[slen-1] == ' ' || s[slen-1] == '\t' ||
                        s[slen-1] == '\n' || s[slen-1] == '\r')) slen--;
    if (slen != j) return false;
    for (size_t i = 0; i < slen; i++) {
        if (tolower((unsigned char)s[i]) != want[i]) return false;
    }
    return true;

const char *framework = "onnx";
    if (cfg && cfg->type == JSON_OBJECT) {
        json_t *sub = json_obj_get(cfg, "openwakeword");
        if (sub && sub->type == JSON_OBJECT) {
            const char *f = json_get_str(sub, "inference_framework", NULL);
            if (f && *f) {
                /* strip + lower */
                size_t len = strlen(f);
                char buf[64];
                size_t j = 0;
                for (size_t i = 0; i < len && j < sizeof(buf)-1; i++) {
                    char c = f[i];
                    if (c == ' ' || c == '\t' || c == '\n' || c == '\r') continue;
                    buf[j++] = (char)tolower((unsigned char)c);
                }
                buf[j] = '\0';
                framework = j ? buf : "onnx"; /* empty -> default */
                if (strcmp(framework, "onnx") == 0 && is_macos_arm64) {
                    return strdup("tflite");
                }
                return strdup(framework);
            }
        }
    }
    /* empty -> platform default: tflite on macOS ARM64 else onnx */
    return strdup(is_macos_arm64 ? "tflite" : "onnx");

if (!details || details->type != JSON_OBJECT) return strdup("system default");

    const char *name = json_get_str(details, "name", "");
    while (*name == ' ' || *name == '\t' || *name == '\n' || *name == '\r') name++;
    size_t namelen = strlen(name);
    while (namelen > 0 && (name[namelen-1] == ' ' || name[namelen-1] == '\t' ||
                           name[namelen-1] == '\n' || name[namelen-1] == '\r')) namelen--;

    char *label;
    if (namelen > 0) {
        label = malloc(namelen + 1);
        if (!label) return strdup("system default");
        memcpy(label, name, namelen);
        label[namelen] = '\0';
    } else {
        json_t *sel = json_obj_get(details, "selector");
        if (!sel || sel->type == JSON_NULL) {
            label = strdup("system default");
        } else if (sel->type == JSON_NUMBER) {
            char buf[32];
            snprintf(buf, sizeof(buf), "%d", (int)sel->num_val);
            label = strdup(buf);
        } else if (sel->type == JSON_STRING) {
            label = strdup(sel->str_val);
        } else {
            label = strdup("system default");
        }
        if (!label) return strdup("system default");
    }

    const char *hostapi = json_get_str(details, "hostapi", "");
    while (*hostapi == ' ' || *hostapi == '\t' || *hostapi == '\n' || *hostapi == '\r') hostapi++;
    size_t halen = strlen(hostapi);
    while (halen > 0 && (hostapi[halen-1] == ' ' || hostapi[halen-1] == '\t' ||
                         hostapi[halen-1] == '\n' || hostapi[halen-1] == '\r')) halen--;

    if (halen > 0) {
        size_t need = strlen(label) + halen + 4;
        char *out = malloc(need);
        if (out) {
            snprintf(out, need, "%s (%.*s)", label, (int)halen, hostapi);
            free(label);
            return out;
        }
    }
    return label;

if (!value) return false;
    if (strchr(value, '/') != NULL || strchr(value, '\\') != NULL) return true;
    size_t len = strlen(value);
    if (len >= 5 && strcmp(value + len - 5, ".onnx") == 0) return true;
    if (len >= 7 && strcmp(value + len - 7, ".tflite") == 0) return true;
    if (len >= 4 && strcmp(value + len - 4, ".ppn") == 0) return true;
    return false;

if (!tools_dir) return NULL;
    const char *ext = "onnx";
    if (framework) {
        const char *f = framework;
        while (*f == ' ' || *f == '\t') f++;
        if (strcasecmp(f, "tflite") == 0) ext = "tflite";
    }
    size_t dlen = strlen(tools_dir);
    size_t need = dlen + strlen("/wakewords/") + strlen(WW_BUNDLED_MODEL_NAME) +
                  strlen(ext) + 2;
    char *out = malloc(need);
    if (!out) return NULL;
    if (dlen > 0 && tools_dir[dlen-1] == '/')
        snprintf(out, need, "%swakewords/%s.%s", tools_dir, WW_BUNDLED_MODEL_NAME, ext);
    else
        snprintf(out, need, "%s/wakewords/%s.%s", tools_dir, WW_BUNDLED_MODEL_NAME, ext);
    return out;

#if defined(__APPLE__) && defined(__aarch64__)
    return true;
#else
    return false;
#endif

/* Try the standard tflite_runtime import first. */
    FILE *fp = popen("python3 -c "
                     "\"import tflite_runtime.interpreter\" "
                     "2>/dev/null",
                     "r");
    if (fp) {
        int rc = pclose(fp);
        if (rc == 0) return true;
    }

    /* Bridge ai_edge_litert -> tflite_runtime (macOS). */
    fp = popen("python3 -c "
               "\"from ai_edge_litert import interpreter as _litert; "
               "import types, sys; "
               "pkg = types.ModuleType('tflite_runtime'); "
               "pkg.__path__ = []; "
               "sys.modules.setdefault('tflite_runtime', pkg); "
               "sys.modules['tflite_runtime.interpreter'] = _litert; "
               "print('ok')\" "
               "2>/dev/null",
               "r");
    if (fp) {
        char buf[64];
        if (fgets(buf, sizeof(buf), fp) != NULL) {
            pclose(fp);
            return strstr(buf, "ok") != NULL;
        }
        pclose(fp);
    }
    return false;

/* Delegate to Python to load the config and extract
     * the wake_word section. */
    FILE *fp = popen("python3 -c "
                       "\"import json, sys; "
                       "from hermes_cli.config import load_config; "
                       "cfg = load_config(); "
                       "wake = cfg.get('wake_word', {}); "
                       "print(json.dumps(wake))\" "
                       "2>/dev/null",
                       "r");
    if (!fp) return json_object();

    char buf[4096];
    json_t *result = json_object();
    if (fgets(buf, sizeof(buf), fp) != NULL) {
        char *err = NULL;
        json_t *parsed = json_parse(buf, &err);
        if (parsed && parsed->type == JSON_OBJECT) {
            json_free(result);
            result = parsed;
        }
        if (err) free(err);
    }
    pclose(fp);
    return result;

FILE *fp = popen("python3 -c "
                       "\"from hermes_cli.config import get_active_profile; "
                       "print(get_active_profile() or 'default')\" "
                       "2>/dev/null",
