/* Python: checks if response has callable iter_content or is a
     * requests.Response. In C, we check for a marker field. */
    return response != NULL;

/* Python: call response.close() if callable. Best-effort. */
    if (!response) return;
    /* In C, response is an opaque handle; close is a no-op without
     * a known close function pointer. */

/* Python: read response body with hard byte cap.
     * In C, if response is a memory buffer, copy it; otherwise fail. */
    if (!response) return NULL;
    if (!limit) limit = TTS_RESPONSE_BODY_LIMIT_BYTES;
    /* Assume response is a null-terminated string buffer for the C port.
     * In the Python version, this reads from HTTP response.iter_content. */
    const char *buf = (const char *)response;
    size_t blen = strlen(buf);
    if (blen > limit) {
        tts_close_response((void*)response);
        return NULL;
    }
    if (out_len) *out_len = blen;
    return strdup(buf);

/* Python: parse response bytes as JSON dict. */
    size_t len = 0;
    void *raw = tts_read_tts_response_bytes(response, label, limit ? limit
                                                             : TTS_RESPONSE_BODY_LIMIT_BYTES, &len);
    if (!raw) return strdup("{}");
    json_t *parsed = json_parse((char*)raw, NULL);
    free(raw);
    if (!parsed || parsed->type != JSON_OBJECT) {
        if (parsed) json_free(parsed);
        /* Fallback: try .json() method — not available in C; return empty dict. */
        return strdup("{}");
    }
    char *out = json_serialize(parsed);
    json_free(parsed);
    return out ? out : strdup("{}");

/* Python: read bytes → write to file. */
    size_t len = 0;
    void *data = tts_read_tts_response_bytes(response, label,
                                             limit ? limit : TTS_RESPONSE_BODY_LIMIT_BYTES, &len);
    if (!data) return -1;
    FILE *f = fopen(output_path, "wb");
    if (!f) { free(data); return -1; }
    fwrite(data, 1, len, f);
    fclose(f);
    free(data);
    return 0;

/* Python: delegates to resolve_provider_secret, falls back to get_env_value. */
    if (env_var) {
        const char *e = getenv(env_var);
        if (e && *e) return strdup(e);
    }
    /* No resolve_provider_secret in C; fall back to env. */
    return NULL;

/* Python: build ElevenLabsEnvironment kwargs if base_url set. */
    if (!el_config_json) return strdup("{}");
    json_t *cfg = json_parse(el_config_json, NULL);
    if (!cfg || cfg->type != JSON_OBJECT) {
        if (cfg) json_free(cfg);
        return strdup("{}");
    }
    const char *base_url = json_get_str(cfg, "base_url", NULL);
    if (!base_url || !*base_url) {
        json_free(cfg);
        return strdup("{}");
    }
    /* Strip trailing slash. */
    char *bu = strdup(base_url);
    while (bu && bu[0] && bu[strlen(bu)-1] == '/') bu[strlen(bu)-1] = '\0';
    const char *wss = json_get_str(cfg, "wss_url", NULL);
    char *wss_url = NULL;
    if (wss && *wss) {
        wss_url = strdup(wss);
        while (wss_url && wss_url[0] && wss_url[strlen(wss_url)-1] == '/')
            wss_url[strlen(wss_url)-1] = '\0';
    } else {
        /* wss_url defaults to base_url with ws:// scheme */
        if (bu) {
            const char *p = strstr(bu, "http");
            if (p) {
                wss_url = malloc(strlen(bu) + 16);
                if (wss_url) {
                    memcpy(wss_url, bu, p - bu);
                    sprintf(wss_url + (p - bu), "ws%s", p + 4);
                }
            } else wss_url = strdup(bu);
        }
    }
    json_free(cfg);
    char *out = NULL;
    asprintf(&out, "{\"environment\":{\"base\":\"%s\",\"wss\":\"%s\"}}",
             bu ? bu : "", wss_url ? wss_url : "");
    free(bu);
    free(wss_url);
    return out;

/* Python: select region (global/cn), endpoint, credential. */
    if (!tts_config_json) return strdup("{\"region\":\"global\",\"endpoint\":\"\",\"key\":\"\"}");
    const char *mm_config_ptr = strstr(tts_config_json, "\"minimax\"");
    if (!mm_config_ptr) {
        /* No minimax section — return defaults with global credential. */
        char *key = tts_resolve_provider_key("MINIMAX_API_KEY", "minimax");
        char *out = NULL;
        asprintf(&out, "{\"region\":\"global\",\"endpoint\":\"https://api.minimax.io/v1/t2a_v2\",\"key\":\"%s\"}",
                 key ? key : "");
        free(key);
        return out;
    }
    /* Parse config section for region + credentials. */
    json_t *full = json_parse(tts_config_json, NULL);
    if (!full) return strdup("{\"region\":\"global\",\"endpoint\":\"\",\"key\":\"\"}");
    json_t *mm = json_obj_get(full, "minimax");
    const char *region = "";
    if (mm && mm->type == JSON_OBJECT) {
        const char *r = json_get_str(mm, "region", NULL);
        if (r) region = r;
    }
    char *out = NULL;
    if (strcmp(region, "cn") == 0 || strcmp(region, "global") == 0) {
        char *key = tts_resolve_provider_key(
            strcmp(region, "cn") == 0 ? "MINIMAX_CN_API_KEY" : "MINIMAX_API_KEY",
            "minimax");
        const char *endpoint = strcmp(region, "cn") == 0
            ? "https://api.minimax.cn/v1/text2voice"
            : "https://api.minimax.io/v1/t2a_v2";
        asprintf(&out, "{\"region\":\"%s\",\"endpoint\":\"%s\",\"key\":\"%s\"}",
                 region, endpoint, key ? key : "");
        free(key);
    } else {
        char *key = tts_resolve_provider_key("MINIMAX_API_KEY", "minimax");
        asprintf(&out, "{\"region\":\"global\",\"endpoint\":\"https://api.minimax.io/v1/t2a_v2\",\"key\":\"%s\"}",
                 key ? key : "");
        free(key);
    }
    json_free(full);
    return out;

/* Python: read 12-byte magic from file, delegate to sniff_container. */
    if (!path) return "unknown";
    FILE *f = fopen(path, "rb");
    if (!f) return "unknown";
    unsigned char head[12] = {0};
    size_t n = fread(head, 1, sizeof(head), f);
    fclose(f);
    if (n == 0) return "unknown";
    return sniff_container_magic(head, n);

/* Python: ffmpeg → Ogg/Opus. Safe in-place (temp + replace). */
    if (!input_path || !ogg_path) return NULL;
    if (!tts_has_ffmpeg()) return NULL;
    bool in_place = (strcmp(input_path, ogg_path) == 0);
    char *work_path = in_place ? malloc(strlen(ogg_path) + 8) : NULL;
    if (work_path) sprintf(work_path, "%s.tmp.ogg", ogg_path);
    char *out = in_place ? strdup(ogg_path) : strdup(ogg_path);
    /* In C: invoke ffmpeg via system() with timeout. */
    char cmd[2048];
    snprintf(cmd, sizeof(cmd),
             "ffmpeg -i '%s' -acodec libopus -ac 1 -b:a 48k -vbr on "
             "-application voip -compression_level 10 -f ogg '%s' -y 2>/dev/null",
             input_path, work_path ? work_path : out);
    int rc = system(cmd);
    if (rc != 0) {
        free(work_path);
        free(out);
        return NULL;
    }
    if (work_path) {
        rename(work_path, out);
        free(work_path);
    }
    return out;

/* Python: ensure .ogg actually contains Ogg; transcode or rename. */
    if (!file_str) return NULL;
    size_t flen = strlen(file_str);
    if (flen < 4 || strcmp(file_str + flen - 4, ".ogg") != 0) return strdup(file_str);
    const char *container = tts_sniff_audio_container(file_str);
    if (strcmp(container, "ogg") == 0 || strcmp(container, "unknown") == 0)
        return strdup(file_str);
    /* Transcode to real Ogg/Opus. */
    char *repaired = tts_ffmpeg_transcode_to_opus(file_str, file_str);
    if (repaired) return repaired;
    /* ffmpeg unavailable/failed: rename to honest extension. */
    char *honest = malloc(flen + 16);
    if (!honest) return strdup(file_str);
    strcpy(honest, file_str);
    honest[flen - 4] = '\0';
    strcat(honest, ".");
    strcat(honest, container);
    rename(file_str, honest);
    return honest;

/* Python: LRU-bounded get-or-load. cache is a JSON object (insertion-
     * ordered). On hit: pop+reinsert. On miss: load + evict LRU. */
    if (!cache || !key) return load ? load(load_ctx) : NULL;
    json_t *c = (json_t *)cache;
    if (c->type != JSON_OBJECT) return load ? load(load_ctx) : NULL;
    json_t *existing = json_obj_get(c, key);
    if (existing) {
        /* LRU: pop + reinsert to refresh recency. */
        json_t *copy = json_copy(existing);
        json_obj_del(c, key);
        json_set(c, key, copy);
        return copy;
    }
    void *value = load ? load(load_ctx) : NULL;
    if (value) {
        json_set(c, key, (json_t *)value);
        /* Evict LRU beyond cap. */
        while (c->c.count > TTS_MODEL_CACHE_MAX) {
            json_obj_del(c, c->c.keys[0]);
        }
    }
    return value;

if (!scheme || strcmp(scheme, "https") != 0) return false;
    if (!hostname) return false;
    for (int i = 0; URL_SAFETY_TRUSTED_HOSTS[i]; i++)
        if (strcmp(hostname, URL_SAFETY_TRUSTED_HOSTS[i]) == 0) return true;
    return false;

if (!buf || len < 4) return "application/octet-stream";
    /* PNG */
    if (len >= 4 && buf[0]==0x89 && buf[1]=='P' && buf[2]=='N' && buf[3]=='G')
        return "image/png";
    /* JPEG */
    if (len >= 3 && buf[0]==0xFF && buf[1]==0xD8 && buf[2]==0xFF)
        return "image/jpeg";
    /* GIF */
    if (len >= 6 && buf[0]=='G' && buf[1]=='I' && buf[2]=='F')
        return "image/gif";
    /* WebP (RIFF....WEBP) */
    if (len >= 12 && buf[0]=='R' && buf[1]=='I' && buf[2]=='F' && buf[3]=='F' &&
        buf[8]=='W' && buf[9]=='E' && buf[10]=='B' && buf[11]=='P')
        return "image/webp";
    /* BMP */
    if (len >= 2 && buf[0]=='B' && buf[1]=='M')
        return "image/bmp";
    /* SVG (text-based, starts with <?xml or <svg) */
    if (len >= 5 && (memcmp(buf, "<?xml", 5) == 0 || memcmp(buf, "<svg", 4) == 0))
        return "image/svg+xml";
    return "application/octet-stream";

if (!buf || len < 4) return NULL;
    if (len >= 4 && buf[0]==0x89 && buf[1]=='P' && buf[2]=='N' && buf[3]=='G') return "png";
    if (len >= 3 && buf[0]==0xFF && buf[1]==0xD8 && buf[2]==0xFF) return "jpeg";
    if (len >= 6 && buf[0]=='G' && buf[1]=='I' && buf[2]=='F') return "gif";
    if (len >= 12 && buf[0]=='R' && buf[1]=='I' && buf[2]=='F' && buf[3]=='F' &&
        buf[8]=='W' && buf[9]=='E' && buf[10]=='B' && buf[11]=='P') return "webp";
    if (len >= 2 && buf[0]=='B' && buf[1]=='M') return "bmp";
    if (len >= 5 && (memcmp(buf, "<?xml", 5) == 0 || memcmp(buf, "<svg", 4) == 0)) return "svg";
    /* HEIC/AVIF: ftyp box at offset 4 */
    if (len >= 12 && buf[4]=='f' && buf[5]=='t' && buf[6]=='y' && buf[7]=='p') {
        if (memcmp(buf+8, "avif", 4) == 0) return "avif";
        if (memcmp(buf+8, "heic", 4) == 0 || memcmp(buf+8, "heim", 4) == 0) return "heic";
    }
    return NULL;

if (!path || !path[0]) return NULL;
    /* Try extension first */
    const char *dot = strrchr(path, '.');
    if (dot && dot[1]) {
        const char *exts[] = {"png","jpeg","jpg","gif","webp","bmp","svg","tiff","tif","ico","heic","avif",NULL};
        const char *names[] = {"png","jpeg","jpeg","gif","webp","bmp","svg","tiff","tiff","ico","heic","avif"};
        char lower[16];
        size_t el = strlen(dot + 1);
        if (el < sizeof(lower)) {
            for (size_t i = 0; i <= el; i++) lower[i] = (char)tolower((unsigned char)dot[1+i]);
            for (int i = 0; exts[i]; i++) {
                if (strcmp(lower, exts[i]) == 0) return names[i];
            }
        }
    }
    /* Fall back to magic bytes */
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    unsigned char hdr[16] = {0};
    size_t n = fread(hdr, 1, sizeof(hdr), f);
    fclose(f);
    return vision_detect_image_format_from_bytes(hdr, n);

if (!path || !path[0]) return false;
    /* data: URL */
    if (strncmp(path, "data:", 5) == 0) return true;
    /* http(s):// URL */
    if (strncmp(path, "http://", 7) == 0 || strncmp(path, "https://", 8) == 0) return true;
    /* local file: must exist and be non-empty */
    struct stat st;
    if (stat(path, &st) == 0 && st.st_size > 0) return true;
    return false;

if (!buf || n < 12) return NULL;
    char dims[64] = "";
    unsigned w = 0, h = 0;
    /* PNG */
    if (n >= 24 && buf[0]==0x89 && buf[1]=='P' && buf[2]=='N' && buf[3]=='G') {
        w = ((unsigned)buf[16]<<24)|((unsigned)buf[17]<<16)|((unsigned)buf[18]<<8)|buf[19];
        h = ((unsigned)buf[20]<<24)|((unsigned)buf[21]<<16)|((unsigned)buf[22]<<8)|buf[23];
        snprintf(dims, sizeof(dims), "%ux%u", w, h);
    } else if (n >= 6 && buf[0]=='G' && buf[1]=='I' && buf[2]=='F') {
        w = (unsigned)buf[6] | ((unsigned)buf[7]<<8);
        h = (unsigned)buf[8] | ((unsigned)buf[9]<<8);
        snprintf(dims, sizeof(dims), "%ux%u", w, h);
    } else if (n >= 2 && buf[0]=='B' && buf[1]=='M' && n >= 26) {
        w = (unsigned)buf[18]|((unsigned)buf[19]<<8)|((unsigned)buf[20]<<16)|((unsigned)buf[21]<<24);
        h = (unsigned)buf[22]|((unsigned)buf[23]<<8)|((unsigned)buf[24]<<16)|((unsigned)buf[25]<<24);
        snprintf(dims, sizeof(dims), "%ux%u", w, h);
    } else if (n >= 30 && buf[0]=='R' && buf[1]=='I' && buf[2]=='F' && buf[3]=='F') {
        if (buf[8]=='W' && buf[9]=='E' && buf[10]=='B' && buf[11]=='P') {
            if (buf[12]=='V' && buf[13]=='P' && buf[14]=='8' && buf[15]==' ') {
                w = ((unsigned)(buf[27]&0x3F)<<8)|buf[26];
                h = ((unsigned)(buf[29]&0x3F)<<8)|buf[28];
                snprintf(dims, sizeof(dims), "%ux%u", w+1, h+1);
            } else if (buf[12]=='V' && buf[13]=='P' && buf[14]=='8' && buf[15]=='L') {
                w = ((unsigned)(buf[21]&0x3F)<<8)|(unsigned)(buf[20]&0xFF);
                h = ((unsigned)(buf[23]&0x0F)<<10)|((unsigned)buf[22]<<2)|((unsigned)(buf[21]&0xC0)>>6);
                snprintf(dims, sizeof(dims), "%ux%u", w+1, h+1);
            }
        }
    }
    /* JPEG: need more bytes for SOF scan */
    if (dims[0]) return strdup(dims);
    return NULL;

if (!path) return NULL;
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    unsigned char buf[256];
    size_t n = fread(buf, 1, sizeof(buf), f);
    fclose(f);
    return vision_extract_dimensions_from_bytes(buf, n);

if (!path) return NULL;
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz <= 0 || sz > (50 * 1024 * 1024)) { fclose(f); return NULL; }
    unsigned char *data = malloc((size_t)sz);
    if (!data) { fclose(f); return NULL; }
    size_t rd = fread(data, 1, (size_t)sz, f);
    fclose(f);
    const char *fmt = vision_detect_image_format_from_path(path);
    const char *mime = NULL;
    if (fmt) {
        if (strcmp(fmt,"png")==0) mime="image/png";
        else if (strcmp(fmt,"jpeg")==0) mime="image/jpeg";
        else if (strcmp(fmt,"gif")==0) mime="image/gif";
        else if (strcmp(fmt,"webp")==0) mime="image/webp";
        else if (strcmp(fmt,"bmp")==0) mime="image/bmp";
        else if (strcmp(fmt,"svg")==0) mime="image/svg+xml";
        else if (strcmp(fmt,"tiff")==0) mime="image/tiff";
        else if (strcmp(fmt,"avif")==0) mime="image/avif";
        else if (strcmp(fmt,"heic")==0) mime="image/heic";
    }
    if (!mime) { free(data); return NULL; }
    char *b64 = base64_encode(data, rd);
    free(data);
    if (!b64) return NULL;
    size_t prefix = strlen("data:") + strlen(mime) + strlen(";base64,");
    size_t b64len = strlen(b64);
    char *url = malloc(prefix + b64len + 1);
    if (!url) { free(b64); return NULL; }
    snprintf(url, prefix + b64len + 1, "data:%s;base64,%s", mime, b64);
    free(b64);
    return url;

if (!error_text || !error_text[0]) return false;
    const char *hints[] = {
        "too large", "payload", "413", "content_too_large",
        "request_too_large", "image_url", "invalid_request", NULL
    };
    for (int i = 0; hints[i]; i++) {
        if (strcasestr(error_text, hints[i])) return true;
    }
    return false;

if (!url || !url[0]) return false;
    if (strncmp(url, "data:", 5) == 0) return true;
    if (strncmp(url, "http://", 7) == 0) return true;
    if (strncmp(url, "https://", 8) == 0) return true;
    /* local path */
    struct stat st;
    return stat(url, &st) == 0;

if (!url || !url[0]) return NULL;
    if (strncmp(url, "http://", 7) != 0 && strncmp(url, "https://", 8) != 0)
        return NULL;
    char tmpl[] = "/tmp/slermes-vision-dl-XXXXXX";
    int fd = mkstemp(tmpl);
    if (fd < 0) return NULL;
    close(fd);
    char cmd[8192];
    snprintf(cmd, sizeof(cmd),
             "curl -sS --max-time %d -o %s '%s' 2>/dev/null",
             timeout_sec > 0 ? timeout_sec : 30, tmpl, url);
    int rc = system(cmd);
    if (rc != 0) { unlink(tmpl); return NULL; }
    struct stat st;
    if (stat(tmpl, &st) != 0 || st.st_size == 0) { unlink(tmpl); return NULL; }
    return strdup(tmpl);

if (!path || !path[0] || max_dim <= 0) return NULL;
    struct stat st;
    if (stat(path, &st) != 0) return NULL;
    char out[PATH_MAX];
    snprintf(out, sizeof(out), "/tmp/slermes-vision-resized-XXXXXX");
    int fd = mkstemp(out);
    if (fd < 0) return NULL;
    close(fd);
    unlink(out); /* convert creates the file; mkstemp just reserves the name */
    char cmd[8192];
    snprintf(cmd, sizeof(cmd),
             "convert '%s' -resize '%dx%d>' '%s' 2>/dev/null",
             path, max_dim, max_dim, out);
    int rc = system(cmd);
    if (rc != 0 || stat(out, &st) != 0 || st.st_size == 0) {
        /* try with ffmpeg fallback */
        snprintf(cmd, sizeof(cmd),
                 "ffmpeg -y -i '%s' -vf scale='min(%d,iw)':'min(%d,ih)' '%s' 2>/dev/null",
                 path, max_dim, max_dim, out);
        rc = system(cmd);
        if (rc != 0 || stat(out, &st) != 0 || st.st_size == 0) return NULL;
    }
