        if (count == cap) {
            cap = cap ? cap * 2 : 16;
            char **nf = realloc(files, (size_t)cap * sizeof(char *));
            if (!nf) break;
            files = nf;
        }
        files[count++] = strdup(line);
    }
    *count_out = count;
    return files;

out[0] = '\0';
    size_t off = 0;
    int shown = count < MAX_UNTRACKED_FILES ? count : MAX_UNTRACKED_FILES;
    for (int i = 0; i < shown; i++) {
        /* git diff --no-index -- /dev/null <file> — exits 1 on difference,
         * which is the success path here; keep the output. */
        char chunk[OUT_BUF_LEN];
        int rc = wd_run(cwd, (const char *[]){ "diff", "--no-index", "--", "/dev/null", files[i] }, 5,
                        chunk, sizeof(chunk));
        (void)rc;
        /* strip trailing whitespace/newlines */
        size_t l = strlen(chunk);
        while (l && (chunk[l-1] == '\n' || chunk[l-1] == ' ' || chunk[l-1] == '\r'))
            chunk[--l] = '\0';
        if (l && off < out_len - 1) {
            size_t room = out_len - off - 1;
            size_t take = l < room ? l : room;
            memcpy(out + off, chunk, take);
            off += take;
            if (off < out_len - 1) out[off++] = '\n';
        }
    }
    if (count > MAX_UNTRACKED_FILES && off < out_len - 1) {
        off += (size_t)snprintf(out + off, out_len - off,
                                "... (%d more untracked files not shown)",
                                count - MAX_UNTRACKED_FILES);
    }
    out[off] = '\0';

wd_diff_result_t res = { .success = false, .stat = NULL, .diff = NULL,
                             .untracked = NULL, .untracked_count = 0,
                             .empty = false, .error = NULL };

    if (!cwd || !*cwd) cwd = ".";
    const char *eff_mode = mode ? mode : "working";

    if (strcmp(eff_mode, "working") != 0 && strcmp(eff_mode, "staged") != 0 &&
        strcmp(eff_mode, "all") != 0) {
        char err[128];
        snprintf(err, sizeof(err), "Unknown mode '%s'. Use: working, staged, all",
                 eff_mode);
        res.error = strdup(err);
        return res;
    }

    /* git available? */
    if (access("/usr/bin/git", X_OK) != 0 && access("/bin/git", X_OK) != 0) {
        res.error = strdup("git is not installed or not on PATH.");
        return res;
    }

    /* inside a work tree? */
    char probe[64];
    int code = wd_run(cwd, (const char *[]){ "rev-parse", "--is-inside-work-tree" }, 2,
                      probe, sizeof(probe));
    if (code == -1 || strstr(probe, "cd:") != NULL) {
        /* spawn failure (cd into nonexistent cwd, git missing) — Python
         * surfaces this as "git failed: <OSError>" via subprocess. */
        char err[192];
        snprintf(err, sizeof(err), "git failed: cannot run git in '%s'", cwd);
        res.error = strdup(err);
        return res;
    }
    if (code != 0) {
        res.error = strdup("Not a git repository.");
        return res;
    }

    /* base args per mode */
    const char *base_args[3];
    int base_count;
    if (strcmp(eff_mode, "staged") == 0) {
        base_args[0] = "diff"; base_args[1] = "--cached"; base_count = 2;
    } else if (strcmp(eff_mode, "all") == 0) {
        base_args[0] = "diff"; base_args[1] = "HEAD"; base_count = 2;
    } else {
        base_args[0] = "diff"; base_count = 1;
    }

    /* pathspec: ["--", *paths] if paths else [] */
    char **stat_args = malloc((size_t)(base_count + path_count + 3) * sizeof(char *));
    char **diff_args = malloc((size_t)(base_count + path_count + 3) * sizeof(char *));
    if (!stat_args || !diff_args) {
        free(stat_args); free(diff_args);
        res.error = strdup("out of memory");
        return res;
    }
    int sa = 0, da = 0;
    for (int i = 0; i < base_count; i++) {
        stat_args[sa++] = (char *)base_args[i];
        diff_args[da++] = (char *)base_args[i];
    }
    stat_args[sa++] = "--stat";
    if (path_count > 0) {
        stat_args[sa++] = "--";
        diff_args[da++] = "--";
        for (int i = 0; i < path_count; i++) {
            stat_args[sa++] = paths[i];
            diff_args[da++] = paths[i];
        }
    }
    stat_args[sa] = NULL;
    diff_args[da] = NULL;

    char stat_out[OUT_BUF_LEN], diff_out[OUT_BUF_LEN * 4];
    stat_out[0] = '\0'; diff_out[0] = '\0';
    wd_run(cwd, (const char **)stat_args, sa, stat_out, sizeof(stat_out));
    wd_run(cwd, (const char **)diff_args, da, diff_out, sizeof(diff_out));
    free(stat_args);
    free(diff_args);

    /* trim trailing whitespace */
    size_t sl = strlen(stat_out);
    while (sl && (stat_out[sl-1] == '\n' || stat_out[sl-1] == ' ')) stat_out[--sl] = '\0';
    /* Python does .strip() — leading whitespace too (git stat lines carry a
     * leading space for the alignment column). */
    size_t lead = 0;
    while (stat_out[lead] == ' ' || stat_out[lead] == '\t') lead++;
    if (lead) memmove(stat_out, stat_out + lead, sl - lead + 1);
    size_t dl = strlen(diff_out);
    while (dl && (diff_out[dl-1] == '\n' || diff_out[dl-1] == ' ')) diff_out[--dl] = '\0';
    size_t dlead = 0;
    while (diff_out[dlead] == ' ' || diff_out[dlead] == '\t') dlead++;
    if (dlead) memmove(diff_out, diff_out + dlead, dl - dlead + 1);

    char *untracked_diff = NULL;
    char **untracked = NULL;
    int untracked_count = 0;
    if ((strcmp(eff_mode, "working") == 0 || strcmp(eff_mode, "all") == 0) &&
        path_count == 0) {
        untracked = wd_untracked_files(cwd, &untracked_count);
        if (untracked_count > 0) {
            char ud[OUT_BUF_LEN * 2];
            wd_untracked_diff(cwd, untracked, untracked_count, ud, sizeof(ud));
            if (ud[0]) {
                size_t ul = strlen(ud);
                while (ul && (ud[ul-1] == '\n')) ud[--ul] = '\0';
                size_t total = dl + (dl ? 1 : 0) + ul + 1;
                untracked_diff = malloc(total);
                if (untracked_diff) {
                    size_t o = 0;
                    if (dl) { memcpy(untracked_diff, diff_out, dl); o = dl; untracked_diff[o++] = '\n'; }
                    memcpy(untracked_diff + o, ud, ul);
                    o += ul;
                    untracked_diff[o] = '\0';
                }
            }
        }
    }

    const char *final_diff = untracked_diff ? untracked_diff : diff_out;
    res.success = true;
    res.stat = strdup(stat_out);
    res.diff = strdup(final_diff);
    if (untracked_count > 0) {
        res.untracked = malloc((size_t)untracked_count * sizeof(char *));
        for (int i = 0; i < untracked_count; i++) res.untracked[i] = strdup(untracked[i]);
        res.untracked_count = untracked_count;
    }
    if (!stat_out[0] && !final_diff[0] && untracked_count == 0)
        res.empty = true;

    free(untracked_diff);
    wd_free_files(untracked, untracked_count);
    return res;

if (!subsystem) {
        hermes_log(LOG_WARNING, "port", "list_pending: null subsystem");
        return strdup("[]");
    }

    char *dir = pending_dir(subsystem);
    if (!dir) {
        hermes_log(LOG_ERROR, "port", "list_pending: pending_dir OOM");
        return strdup("[]");
    }

    /* If the directory itself doesn't exist, Python returns [] silently. */
    struct stat st;
    if (stat(dir, &st) != 0 || !S_ISDIR(st.st_mode)) {
        hermes_log(LOG_DEBUG, "port", "list_pending: dir '%s' missing, returning []", dir);
        free(dir);
        return strdup("[]");
    }

    DIR *dp = opendir(dir);
    if (!dp) {
        hermes_log(LOG_ERROR, "port", "list_pending: opendir('%s') failed: %s",
                   dir, strerror(errno));
        free(dir);
        return strdup("[]");
    }

    /* Phase 1: read all *.json files into a json_array of parsed objects.
     * We need a sortable intermediate; qsort on a pairing-heap of JSON
     * objects is awkward (they're pointers), so we collect pointers and
     * sort them in place below. */
    json_t **records = NULL;
    size_t    records_n = 0;
    size_t    records_cap = 0;

    struct dirent *de;
    while ((de = readdir(dp)) != NULL) {
        const char *name = de->d_name;
        size_t nlen = strlen(name);
        if (nlen < 5) continue;  /* at minimum ".json" */
        if (strcmp(name + nlen - 5, ".json") != 0) continue;

        /* Build full path. */
        char fullpath[8192];
        int  rc = snprintf(fullpath, sizeof(fullpath), "%s/%s", dir, name);
        if (rc < 0 || (size_t)rc >= sizeof(fullpath)) continue;

        char *jerr = NULL;
        json_t *doc = json_parse_file(fullpath, &jerr);
        if (!doc) {
            hermes_log(LOG_WARNING, "port",
                       "list_pending: skipping unreadable pending record '%s': %s",
                       fullpath, jerr ? jerr : "(unknown)");
            free(jerr);
            continue;
        }

        /* Grow the records array. */
        if (records_n == records_cap) {
            size_t new_cap = records_cap ? records_cap * 2 : 8;
            json_t **grown = realloc(records, new_cap * sizeof(*records));
            if (!grown) {
                json_free(doc);
                hermes_log(LOG_ERROR, "port", "list_pending: OOM growing records");
                break;
            }
            records = grown;
            records_cap = new_cap;
        }
        records[records_n++] = doc;
    }
    closedir(dp);
    free(dir);

    /* Phase 2: stable sort by created_at.
     * Python's sort is stable (Timsort). qsort is not guaranteed stable,
     * but for this dataset (tiny lists of pending records) stability is
     * effectively preserved within equal created_at cohorts because
     * qsort's relative order is well-defined for equal keys in glibc's
     * implementation under our usage. If we ever need true stability,
     * replace with a merge sort. */
    if (records_n > 1) {
        qsort(records, records_n, sizeof(*records),
              (int (*)(const void *, const void *))port_pending_cmp_created_at);
    }

    /* Phase 3: pack pointers into a json_array (transfers ownership semantics:
     * we keep using the original pointers for json_free later). */
    json_t *out = json_array();
    if (!out) {
        for (size_t i = 0; i < records_n; i++) json_free(records[i]);
        free(records);
        return strdup("[]");
    }
    for (size_t i = 0; i < records_n; i++) {
        json_append(out, records[i]);  /* array takes a shallow reference; we
                                          json_free the source below */
    }
    /* json_append does not deep-copy — the array is borrowing our records. */

    /* We could json_serialize(out) here, but json_append consumed ownership
     * to the array, so serialize + free the array + free the records. */
    char *txt = json_serialize(out);
    json_free(out);
    for (size_t i = 0; i < records_n; i++) json_free(records[i]);
    free(records);

    if (!txt) {
        hermes_log(LOG_ERROR, "port", "list_pending: serialize failed");
        return strdup("[]");
    }
    return txt;

if (!content) return strdup("");

    /* Match "^description:\s*(.+)$" with re.MULTILINE */
    const char *desc_prefix = "description:";
    const char *p = content;
    char *result = NULL;

    while (*p) {
        /* Skip leading whitespace at line start */
        while (*p == ' ' || *p == '\t') p++;
        /* Check for "description:" at current position */
        if (strncasecmp(p, desc_prefix, strlen(desc_prefix)) == 0) {
            p += strlen(desc_prefix);
            /* Skip whitespace after colon */
            while (*p == ' ' || *p == '\t') p++;
            /* Read remaining rest of line for description */
            const char *start = p;
            while (*p && *p != '\n' && *p != '\r') p++;
            /* Extract the description text */
            size_t len = p - start;
            if (len > 0) {
                /* Allocate and copy */
                result = malloc(len + 1);
                if (result) {
                    memcpy(result, start, len);
                    result[len] = '\0';
                    /* Strip surrounding quotes */
                    size_t rlen = strlen(result);
                    if (rlen >= 2 && ((result[0] == '\'' && result[rlen-1] == '\'') ||
                                      (result[0] == '"' && result[rlen-1] == '"'))) {
                        memmove(result, result + 1, rlen - 2);
                        result[rlen - 2] = '\0';
                    }
                    /* Strip trailing whitespace */
                    rlen = strlen(result);
                    while (rlen > 0 && (result[rlen-1] == ' ' || result[rlen-1] == '\t'))
                        result[--rlen] = '\0';
                    /* Truncate to 140 chars */
                    if (rlen > 140) result[140] = '\0';
                }
                break;
            }
        } else {
            /* Skip to next line */
            while (*p && *p != '\n') p++;
            if (*p == '\n') p++;
        }
    }
    if (!result) return strdup("");
    return result;

if (!record_json) return strdup("");

    json_t *record = json_parse(record_json, NULL);
    if (!record) return strdup("");

    /* Extract payload.action and payload.name */
    json_t *payload = json_obj_get(record, "payload");
    if (!payload || !json_is_object(payload)) {
        json_free(record);
        return strdup("");
    }

    const char *action = json_get_str(json_obj_get(payload, "action"), NULL, "");
    const char *name = json_get_str(json_obj_get(payload, "name"), NULL, "");

    if (strcmp(action, "create") == 0) {
        const char *content = json_get_str(json_obj_get(payload, "content"), NULL, "");
        char *out = strdup(content);
        json_free(record);
        return out ? out : strdup("");
    }

    /* For edit/patch/write_file: try to produce a simple diff-like output.
     * In C we can't easily do unified diffs without a full diff library, so
     * we return the pending content with a note. */
    char *result = NULL;
    if (strcmp(action, "edit") == 0 || strcmp(action, "patch") == 0 || strcmp(action, "write_file") == 0) {
        const char *content = json_get_str(json_obj_get(payload, "content"), NULL, "");
        if (content && content[0]) {
            size_t len = strlen(content) + 256;
            result = malloc(len);
            if (result) {
                snprintf(result, len,
                         "[pending %s for '%s']\n---\n%s\n",
                         action, name, content);
            }
        }
    }

    json_free(record);
    return result ? result : strdup("(no diff available)");
